  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface User {
  id: string;
  name: string;
  email: string;
  avatar: string;
}

export interface Message {
  id: string;
  role: 'user' | 'model';
  content: string;
  timestamp: Date;
  sources?: string[];
}

export interface Document {
  id: string;
  name: string;
  content: string;
  type: string;
  uploadDate: Date;
  size: number;
}

export interface MarketData {
  symbol: string;
  name: string;
  price: number;
  change: number;
  history: { date: string; value: number }[];
}

export enum ViewState {
  Dashboard = 'DASHBOARD',
  Chat = 'CHAT',
  Documents = 'DOCUMENTS',
  Reports = 'REPORTS'
}

import { Document, User } from '../types';

const DOCS_KEY = 'finan_gpt_docs';
const USER_KEY = 'finan_gpt_user';

export const StorageService = {
  getDocuments: (): Document[] => {
    const data = localStorage.getItem(DOCS_KEY);
    return data ? JSON.parse(data) : [];
  },

  saveDocument: (doc: Document) => {
    const docs = StorageService.getDocuments();
    docs.push(doc);
    localStorage.setItem(DOCS_KEY, JSON.stringify(docs));
  },

  deleteDocument: (id: string) => {
    const docs = StorageService.getDocuments().filter(d => d.id !== id);
    localStorage.setItem(DOCS_KEY, JSON.stringify(docs));
  },

  getUser: (): User | null => {
    const data = localStorage.getItem(USER_KEY);
    return data ? JSON.parse(data) : null;
  },

  setUser: (user: User) => {
    localStorage.setItem(USER_KEY, JSON.stringify(user));
  },

  clearAll: () => {
    localStorage.removeItem(DOCS_KEY);
    localStorage.removeItem(USER_KEY);
  }
};

import { GoogleGenAI, Type } from "@google/genai";
import { StorageService } from "./storage";

const API_KEY = process.env.API_KEY || '';

export const GeminiService = {
  generateChatResponse: async (prompt: string, history: any[]) => {
    const ai = new GoogleGenAI({ apiKey: API_KEY });

    // RAG Logic: Fetch documents from storage to use as context
    const docs = StorageService.getDocuments();
    const context = docs.length > 0 
      ? `Base de Conhecimento do Usuário:\n${docs.map(d => `--- Documento: ${d.name} ---\n${d.content}`).join('\n\n')}`
      : "Nenhum documento carregado.";

    const systemInstruction = `
      Você é um especialista em Contabilidade e Finanças para empresas brasileiras.
      Suas respostas devem ser precisas, profissionais e baseadas em normas contábeis (IFRS/CPC) e legislação tributária brasileira.

      ${context}

      Se o usuário perguntar algo fora do contexto dos documentos, utilize seus conhecimentos gerais de contabilidade.
      Se o usuário perguntar sobre mercado financeiro, utilize a ferramenta de busca se necessário.
    `;

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          systemInstruction,
          tools: [{ googleSearch: {} }]
        },
      });

      return {
        text: response.text || "Desculpe, não consegui processar sua solicitação.",
        groundingMetadata: response.candidates?.[0]?.groundingMetadata
      };
    } catch (error) {
      console.error("Gemini Error:", error);
      throw error;
    }
  }
};

