import { useState, useEffect } from 'react';
import { LineChart, Line, XAxis, YAxis, Tooltip, ResponsiveContainer } from 'recharts';
import { Button, Card, CardContent } from '@/components/ui/card';
import { signIn, useSession } from 'next-auth/react';
import Joyride, { STATUS } from 'react-joyride';

export default function Home() {
  const { data: session } = useSession();
  const [pergunta, setPergunta] = useState('');
  const [resposta, setResposta] = useState('');
  const [fontes, setFontes] = useState([]);
  const [series, setSeries] = useState([]);
  const [lgpdAceito, setLgpdAceito] = useState(false);
  const [runTour, setRunTour] = useState(false);

  useEffect(() => {
    const consent = localStorage.getItem('lgpd_consent');
    if (consent === 'true') setLgpdAceito(true);
    else setRunTour(true); // ativa tour para novos usuários

    fetchCambio();
  }, []);

  const fetchCambio = async () => {
    try {
      const res = await fetch('/api/indicadores');
      const data = await res.json();
      setSeries([
        { name: 'Selic', valor: data.selic_bcb },
        { name: 'Fed', valor: data.fed_funds }
      ]);
    } catch (e) {
      console.error('Erro ao buscar indicadores', e);
    }
  };

  const enviarPergunta = async () => {
    if (!pergunta) return;
    try {
      const res = await fetch('/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ pergunta })
      });
      const data = await res.json();
      setResposta(data.resposta);
      setFontes(data.fontes);
    } catch (e) {
      console.error('Erro ao enviar pergunta', e);
    }
  };

  const aceitarLGPD = () => {
    localStorage.setItem('lgpd_consent', 'true');
    setLgpdAceito(true);
    setRunTour(true); // inicia tour após consentimento
  };

  const steps = [
    {
      target: 'body',
      content: 'Bem-vindo à IA Educacional de Contabilidade e Finanças! Vamos te guiar pelas funcionalidades.'
    },
    {
      target: '#login-button',
      content: 'Use este botão para fazer login com sua conta Google.'
    },
    {
      target: '#lgpd-consent',
      content: 'Aceite o LGPD para continuar usando a plataforma.'
    },
    {
      target: '#input-pergunta',
      content: 'Digite sua pergunta para o chatbot aqui.'
    },
    {
      target: '#btn-enviar',
      content: 'Clique aqui para enviar sua pergunta e receber respostas educacionais.'
    },
    {
      target: '#resposta-chat',
      content: 'Aqui aparecem as respostas do chatbot com as fontes de informação.'
    },
    {
      target: '#grafico-indicadores',
      content: 'Visualize os indicadores econômicos atualizados em tempo real.'
    }
  ];

  const handleJoyrideCallback = (data) => {
    const { status } = data;
    const finishedStatuses = [STATUS.FINISHED, STATUS.SKIPPED];
    if (finishedStatuses.includes(status)) {
      setRunTour(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#F2EFEA] p-4">
      <Joyride steps={steps} run={runTour} continuous={true} showSkipButton={true} callback={handleJoyrideCallback} />

      {!session && (
        <Button id="login-button" onClick={() => signIn('google')}>Login com Google</Button>
      )}

      {session && !lgpdAceito && (
        <Card id="lgpd-consent" className="p-4 mb-4">
          <CardContent>
            <p>Para usar esta IA, você precisa aceitar o consentimento LGPD.</p>
            <Button onClick={aceitarLGPD}>Aceitar</Button>
          </CardContent>
        </Card>
      )}

      {session && lgpdAceito && (
        <div>
          <Card className="p-4 mb-4">
            <CardContent>
              <input
                id="input-pergunta"
                type="text"
                placeholder="Digite sua pergunta..."
                value={pergunta}
                onChange={(e) => setPergunta(e.target.value)}
                className="border p-2 w-full mb-2 rounded"
              />
              <Button id="btn-enviar" onClick={enviarPergunta}>Enviar</Button>
            </CardContent>
          </Card>

          {resposta && (
            <Card id="resposta-chat" className="p-4 mb-4">
              <CardContent>
                <p>{resposta}</p>
                <ul>
                  {fontes.map((f, i) => (<li key={i}>{f.nome}</li>))}
                </ul>
              </CardContent>
            </Card>
          )}

          <Card id="grafico-indicadores" className="p-4">
            <CardContent>
              <h3 className="mb-2">Indicadores Econômicos</h3>
              <ResponsiveContainer width="100%" height={200}>
                <LineChart data={series}>
                  <XAxis dataKey="name" />
                  <YAxis />
                  <Tooltip />
                  <Line type="monotone" dataKey="valor" stroke="#1A1A1A" />
                </LineChart>
              </ResponsiveContainer>
            </CardContent>
          </Card>
        </div>
      )}
    </div>
  );
}
