import { GoogleGenAI, Type } from "@google/genai";
import { StorageService } from "./storage";

const API_KEY = process.env.API_KEY || '';

export const GeminiService = {
  generateChatResponse: async (prompt: string, history: any[]) => {
    const ai = new GoogleGenAI({ apiKey: API_KEY });

    // RAG Logic: Fetch documents from storage to use as context
    const docs = StorageService.getDocuments();
    const context = docs.length > 0 
      ? `Base de Conhecimento do Usuário (Documentos Privados):\n${docs.map(d => `--- Documento: ${d.name} ---\n${d.content}`).join('\n\n')}`
      : "O usuário ainda não carregou documentos para análise.";

    const systemInstruction = `
      Você é o "FinanGPT", um especialista de elite em Contabilidade, Finanças e Direito Tributário Brasileiro (ênfase em Simples Nacional, Lucro Presumido e Lucro Real).

      MISSÃO:
      1. Fornecer respostas precisas baseadas em normas (IFRS/CPC).
      2. Agir como um tutor educacional, explicando conceitos financeiros complexos de forma simples.
      3. Analisar os documentos privados fornecidos no contexto (RAG) para responder perguntas específicas sobre a empresa do usuário.

      CONTEXTO DO USUÁRIO:
      ${context}

      DIRETRIZES:
      - Se a pergunta for sobre indicadores econômicos (Selic, Inflação, Câmbio), use a ferramenta 'googleSearch' para dados atualizados.
      - Sempre cite a base legal (ex: Lei Complementar 123/06) quando aplicável.
      - Formate as respostas em Markdown para clareza (tópicos, negrito, tabelas).
      - Caso a resposta dependa de informações não presentes nos documentos, informe ao usuário o que falta.
    `;

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: {
          systemInstruction,
          tools: [{ googleSearch: {} }]
        },
      });

      return {
        text: response.text || "Desculpe, não consegui processar sua solicitação no momento.",
        groundingMetadata: response.candidates?.[0]?.groundingMetadata
      };
    } catch (error) {
      console.error("Gemini Error:", error);
      throw error;
    }
  }
};

