import React, { useState, useRef, useEffect } from 'react';
import { Message } from '../types';
import { GeminiService } from '../services/geminiService';

const ChatInterface: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([
    {
      id: 'welcome',
      role: 'model',
      content: 'FINANGPT ATIVO. Como posso auxiliar em sua análise técnica hoje?',
      timestamp: new Date()
    }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsTyping(true);

    try {
      const response = await GeminiService.generateChatResponse(input, messages);
      const sources: string[] = [];
      if (response.groundingMetadata?.groundingChunks) {
        response.groundingMetadata.groundingChunks.forEach((chunk: any) => {
          if (chunk.web?.uri) sources.push(chunk.web.uri);
          if (chunk.maps?.uri) sources.push(chunk.maps.uri);
        });
      }

      const modelMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: response.text,
        timestamp: new Date(),
        sources: sources.length > 0 ? sources : undefined
      };

      setMessages(prev => [...prev, modelMessage]);
    } catch (error) {
      const errorMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: 'ERRO NO SISTEMA. TENTE NOVAMENTE.',
        timestamp: new Date()
      };
      setMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="h-full flex flex-col bg-white">
      <header className="px-10 py-8 border-b-2 border-[#1A1A1A] flex items-center justify-between">
        <div className="flex items-center gap-6">
          <div className="w-14 h-14 bg-[#1A1A1A] flex items-center justify-center text-[#F2EFEA] font-bold italic">
            IA
          </div>
          <div>
            <h2 className="text-xl font-bold text-[#1A1A1A] uppercase tracking-tighter">MÓDULO DE CONSULTA IA</h2>
            <div className="flex items-center gap-2">
              <span className="w-2 h-2 bg-[#1A1A1A] rounded-full"></span>
              <span className="text-[10px] text-[#7A7A7A] font-bold uppercase tracking-widest">ESTADO: PROCESSANDO</span>
            </div>
          </div>
        </div>
      </header>

      <div 
        ref={scrollRef}
        className="flex-1 overflow-y-auto p-10 space-y-10 bg-[#F2EFEA]/30"
      >
        {messages.map((msg) => (
          <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[75%] flex gap-6 ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
              <div className={`w-10 h-10 flex-shrink-0 flex items-center justify-center text-[10px] font-bold border-2 ${
                msg.role === 'user' ? 'bg-white border-[#1A1A1A] text-[#1A1A1A]' : 'bg-[#1A1A1A] border-[#1A1A1A] text-[#F2EFEA]'
              }`}>
                {msg.role === 'user' ? 'USR' : 'SYS'}
              </div>
              <div className={`p-6 sketch-border ${
                msg.role === 'user' 
                  ? 'bg-white text-[#1A1A1A]' 
                  : 'bg-[#F2EFEA] text-[#1A1A1A]'
              }`}>
                <div className="whitespace-pre-wrap leading-relaxed text-sm font-medium">{msg.content}</div>
                {msg.sources && (
                  <div className="mt-6 pt-6 border-t border-[#B5B5B5]">
                    <p className="text-[8px] font-bold uppercase tracking-widest text-[#7A7A7A] mb-3">REF. TÉCNICAS:</p>
                    <div className="flex flex-wrap gap-4">
                      {msg.sources.map((url, i) => (
                        <a key={i} href={url} target="_blank" rel="noopener noreferrer" className="text-[10px] text-[#1A1A1A] hover:underline font-bold underline-offset-4">
                          [LINK_{i + 1}]
                        </a>
                      ))}
                    </div>
                  </div>
                )}
                <p className="text-[8px] mt-4 font-bold text-[#B5B5B5]">
                  {msg.timestamp.toLocaleTimeString()}
                </p>
              </div>
            </div>
          </div>
        ))}
        {isTyping && (
          <div className="flex justify-start">
             <div className="flex gap-6 items-center">
              <div className="w-10 h-10 bg-[#1A1A1A] text-white flex items-center justify-center text-[10px] font-bold">SYS</div>
              <div className="text-[10px] font-bold animate-pulse tracking-widest uppercase">Processando resposta...</div>
            </div>
          </div>
        )}
      </div>

      <div className="p-10 bg-white border-t-2 border-[#1A1A1A]">
        <div className="max-w-4xl mx-auto flex gap-6">
          <input 
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="ENTRADA DE COMANDO..."
            className="flex-1 bg-[#F2EFEA] border-2 border-[#1A1A1A] px-6 py-4 outline-none font-bold uppercase text-xs tracking-widest placeholder-[#B5B5B5]"
          />
          <button 
            onClick={handleSend}
            disabled={!input.trim() || isTyping}
            className="sketch-button px-10 font-bold uppercase tracking-widest text-xs"
          >
            ENVIAR
          </button>
        </div>
      </div>
    </div>
  );
};

export default ChatInterface;

