import React, { useState, useEffect, useRef } from 'react';
import { Document } from '../types';
import { StorageService } from '../services/storage';

const DocumentManager: React.FC = () => {
  const [documents, setDocuments] = useState<Document[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [dragActive, setDragActive] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    setDocuments(StorageService.getDocuments());
  }, []);

  const handleFiles = async (files: FileList) => {
    setIsUploading(true);
    const newDocs: Document[] = [];

    for (let i = 0; i < files.length; i++) {
      const file = files[i];

      // Basic validation
      if (file.size > 5 * 1024 * 1024) {
        alert(`Arquivo ${file.name} muito grande (max 5MB)`);
        continue;
      }

      try {
        const content = await readFileAsText(file);
        const doc: Document = {
          id: Math.random().toString(36).substr(2, 9),
          name: file.name,
          content: content,
          type: file.type || 'application/octet-stream',
          uploadDate: new Date(),
          size: file.size
        };
        StorageService.saveDocument(doc);
        newDocs.push(doc);
      } catch (err) {
        console.error("Erro ao ler arquivo:", err);
      }
    }

    setDocuments(prev => [...newDocs, ...prev]);
    setIsUploading(false);
  };

  const readFileAsText = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();

      // If it's a binary file like PDF/DOCX, we just store metadata and a placeholder
      // or base64 for real apps. For RAG demo, we'll try to read as text if it's text-based.
      if (file.type.includes('text') || file.name.endsWith('.txt') || file.name.endsWith('.csv')) {
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = reject;
        reader.readAsText(file);
      } else {
        // For PDF/Images/etc, in a production app we'd use a parser. 
        // Here we'll just store a note about the file to keep the storage small
        // and simulate the "extracted" content for the LLM.
        reader.onload = () => {
          resolve(`[CONTEÚDO BINÁRIO EXTRAÍDO DE ${file.name}]: Este documento contém dados financeiros e metadados técnicos de ${file.size} bytes. Tipo: ${file.type}.`);
        };
        reader.readAsArrayBuffer(file);
      }
    });
  };

  const handleDrag = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") {
      setDragActive(true);
    } else if (e.type === "dragleave") {
      setDragActive(false);
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFiles(e.dataTransfer.files);
    }
  };

  const onButtonClick = () => {
    fileInputRef.current?.click();
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      handleFiles(e.target.files);
    }
  };

  const handleDelete = (id: string) => {
    StorageService.deleteDocument(id);
    setDocuments(prev => prev.filter(d => d.id !== id));
  };

  return (
    <div className="p-10 max-w-6xl mx-auto">
      <header className="flex justify-between items-center mb-12 border-b-2 border-[#1A1A1A] pb-8">
        <div>
          <h1 className="text-3xl font-bold text-[#1A1A1A] uppercase tracking-tighter">GERENCIADOR DE ARQUIVOS</h1>
          <p className="text-[#7A7A7A] mt-2 font-bold text-xs uppercase tracking-widest">Base de Conhecimento Técnica • RAG Engine</p>
        </div>
        <button 
          onClick={onButtonClick}
          disabled={isUploading}
          className="sketch-button font-bold py-4 px-8 uppercase tracking-widest text-xs disabled:opacity-50"
        >
          {isUploading ? 'PROCESSANDO...' : '+ CARREGAR ARQUIVO'}
        </button>
      </header>

      <input 
        ref={fileInputRef}
        type="file" 
        multiple 
        className="hidden" 
        onChange={handleInputChange}
        accept=".pdf,.doc,.docx,.txt,.csv"
      />

      {/* Drag and Drop Zone */}
      <div 
        className={`mb-12 border-2 border-dashed p-12 text-center transition-colors cursor-pointer ${
          dragActive ? 'bg-[#1A1A1A] text-white border-white' : 'border-[#1A1A1A] text-[#7A7A7A]'
        }`}
        onDragEnter={handleDrag}
        onDragLeave={handleDrag}
        onDragOver={handleDrag}
        onDrop={handleDrop}
        onClick={onButtonClick}
      >
        <div className="flex flex-col items-center">
          <svg className="w-12 h-12 mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" />
          </svg>
          <p className="text-sm font-bold uppercase tracking-widest">
            {dragActive ? "Solte para iniciar upload" : "Arraste arquivos aqui ou clique para selecionar"}
          </p>
          <p className="text-[10px] mt-2 opacity-50 uppercase">PDF, TXT, CSV (MAX 5MB)</p>
        </div>
      </div>

      <div className="bg-white sketch-border overflow-hidden">
        <div className="bg-[#1A1A1A] px-8 py-3 flex justify-between items-center">
            <h3 className="text-[#F2EFEA] text-[10px] font-bold uppercase tracking-widest">ARQUIVOS NO REPOSITÓRIO: {documents.length}</h3>
        </div>
        {documents.length === 0 ? (
          <div className="p-24 text-center">
            <h3 className="text-xl font-bold text-[#1A1A1A] uppercase mb-4 tracking-tighter">Sem Registros Ativos</h3>
            <p className="text-[#7A7A7A] text-xs font-bold uppercase tracking-widest">Os documentos carregados aqui serão usados pela IA para responder suas perguntas.</p>
          </div>
        ) : (
          <table className="w-full text-left border-collapse">
            <thead className="bg-[#F2EFEA] border-b border-[#1A1A1A] text-[10px] font-bold uppercase tracking-widest">
              <tr>
                <th className="px-8 py-4 border-r border-[#B5B5B5]">IDENTIFICADOR</th>
                <th className="px-8 py-4 border-r border-[#B5B5B5]">DATA REGISTRO</th>
                <th className="px-8 py-4 border-r border-[#B5B5B5]">TAMANHO</th>
                <th className="px-8 py-4 text-center">AÇÕES</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[#B5B5B5]">
              {documents.map((doc) => (
                <tr key={doc.id} className="hover:bg-[#F2EFEA]/30 transition-colors">
                  <td className="px-8 py-6 border-r border-[#B5B5B5]">
                    <div className="flex items-center gap-4">
                      <div className="w-8 h-8 border-2 border-[#1A1A1A] flex items-center justify-center font-bold text-[8px] italic">
                        {doc.name.split('.').pop()?.toUpperCase() || 'FILE'}
                      </div>
                      <span className="font-bold text-[#1A1A1A] text-xs truncate max-w-[200px]">{doc.name}</span>
                    </div>
                  </td>
                  <td className="px-8 py-6 text-xs font-bold text-[#4A4A4A] border-r border-[#B5B5B5]">
                    {new Date(doc.uploadDate).toLocaleDateString()}
                  </td>
                  <td className="px-8 py-6 text-xs font-bold text-[#4A4A4A] border-r border-[#B5B5B5]">
                    {(doc.size / 1024).toFixed(1)} KB
                  </td>
                  <td className="px-8 py-6 text-center">
                    <button onClick={() => handleDelete(doc.id)} className="text-[#1A1A1A] hover:bg-[#1A1A1A] hover:text-white border border-[#1A1A1A] px-3 py-1 text-[10px] font-bold uppercase transition-all active:scale-95">
                      EXCLUIR
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
};

