import React, { useState, useEffect, useRef } from 'react';
import { Document } from '../types';
import { StorageService } from '../services/storage';

const DocumentManager: React.FC = () => {
  const [documents, setDocuments] = useState<Document[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [dragActive, setDragActive] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    setDocuments(StorageService.getDocuments());
  }, []);

  const handleFiles = async (files: FileList) => {
    setIsUploading(true);
    const newDocs: Document[] = [];

    for (let i = 0; i < files.length; i++) {
      const file = files[i];

      // Basic validation
      if (file.size > 5 * 1024 * 1024) {
        alert(`Arquivo ${file.name} muito grande (max 5MB)`);
        continue;
      }

      try {
        const content = await readFileAsText(file);
        const doc: Document = {
          id: Math.random().toString(36).substr(2, 9),
          name: file.name,
          content: content,
          type: file.type || 'application/octet-stream',
          uploadDate: new Date(),
          size: file.size
        };
        StorageService.saveDocument(doc);
        newDocs.push(doc);
      } catch (err) {
        console.error("Erro ao ler arquivo:", err);
      }
    }

    setDocuments(prev => [...newDocs, ...prev]);
    setIsUploading(false);
  };

  const readFileAsText = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();

      if (file.type.includes('text') || file.name.endsWith('.txt') || file.name.endsWith('.csv')) {
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = reject;
        reader.readAsText(file);
      } else {
        reader.onload = () => {
          resolve(`[CONTEÚDO BINÁRIO EXTRAÍDO DE ${file.name}]: Este documento contém dados financeiros e metadados técnicos de ${file.size} bytes. Tipo: ${file.type}.`);
        };
        reader.readAsArrayBuffer(file);
      }
    });
  };

  const handleDrag = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") {
      setDragActive(true);
    } else if (e.type === "dragleave") {
      setDragActive(false);
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFiles(e.dataTransfer.files);
    }
  };

  const onButtonClick = () => {
    fileInputRef.current?.click();
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      handleFiles(e.target.files);
    }
  };

  const handleDelete = (id: string) => {
    StorageService.deleteDocument(id);
    setDocuments(prev => prev.filter(d => d.id !== id));
  };

  const filteredDocuments = documents.filter(doc => 
    doc.name.toUpperCase().includes(searchTerm.toUpperCase()) || 
    doc.content.toUpperCase().includes(searchTerm.toUpperCase())
  );

  return (
    <div className="p-10 max-w-6xl mx-auto">
      <header className="flex flex-col md:flex-row justify-between items-start md:items-center mb-12 border-b-2 border-[#1A1A1A] pb-8 gap-6">
        <div>
          <h1 className="text-3xl font-bold text-[#1A1A1A] uppercase tracking-tighter">GERENCIADOR DE ARQUIVOS</h1>
          <p className="text-[#7A7A7A] mt-2 font-bold text-xs uppercase tracking-widest">Base de Conhecimento Técnica • RAG Engine</p>
        </div>
        <button 
          onClick={onButtonClick}
          disabled={isUploading}
          className="sketch-button font-bold py-4 px-8 uppercase tracking-widest text-xs disabled:opacity-50 whitespace-nowrap"
        >
          {isUploading ? 'PROCESSANDO...' : '+ CARREGAR ARQUIVO'}
        </button>
      </header>

      <input 
        ref={fileInputRef}
        type="file" 
        multiple 
        className="hidden" 
        onChange={handleInputChange}
        accept=".pdf,.doc,.docx,.txt,.csv"
      />

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 mb-12">
        {/* Search Bar */}
        <div className="lg:col-span-2">
          <div className="relative">
            <input 
              type="text"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              placeholder="PESQUISAR POR NOME OU CONTEÚDO..."
              className="w-full bg-white sketch-border px-6 py-4 outline-none font-bold uppercase text-xs tracking-widest placeholder-[#B5B5B5] focus:bg-[#F2EFEA] transition-colors"
            />
            <div className="absolute right-4 top-1/2 -translate-y-1/2 text-[#1A1A1A]">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
              </svg>
            </div>
          </div>
        </div>

        {/* Info Card */}
        <div className="bg-[#1A1A1A] p-4 text-[#F2EFEA] flex items-center justify-between sketch-border shadow-none">
          <div className="flex flex-col">
            <span className="text-[8px] font-bold uppercase tracking-widest text-[#B5B5B5]">STATUS FILTRO</span>
            <span className="text-xs font-bold uppercase">
              {searchTerm ? `MOSTRANDO ${filteredDocuments.length}` : `TOTAL: ${documents.length}`}
            </span>
          </div>
          {searchTerm && (
            <button 
              onClick={() => setSearchTerm('')}
              className="text-[8px] font-bold border border-[#F2EFEA] px-2 py-1 hover:bg-[#F2EFEA] hover:text-[#1A1A1A] transition-colors"
            >
              LIMPAR
            </button>
          )}
        </div>
      </div>

      {/* Drag and Drop Zone */}
      <div 
        className={`mb-12 border-2 border-dashed p-12 text-center transition-colors cursor-pointer ${
          dragActive ? 'bg-[#1A1A1A] text-white border-white' : 'border-[#1A1A1A] text-[#7A7A7A]'
        }`}
        onDragEnter={handleDrag}
        onDragLeave={handleDrag}
        onDragOver={handleDrag}
        onDrop={handleDrop}
