            <h3 className="text-[#F2EFEA] text-[10px] font-bold uppercase tracking-widest">ARQUIVOS NO REPOSITÓRIO: {filteredDocuments.length}</h3>
        </div>
        {filteredDocuments.length === 0 ? (
          <div className="p-24 text-center">
