import React, { useState, useEffect, useRef } from 'react';
import { Document } from '../types';
import { StorageService } from '../services/storage';

const DocumentManager: React.FC = () => {
  const [documents, setDocuments] = useState<Document[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [parsingStatus, setParsingStatus] = useState<string>('');
  const [dragActive, setDragActive] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    setDocuments(StorageService.getDocuments());
  }, []);

  const handleFiles = async (files: FileList) => {
    setIsUploading(true);
    const newDocs: Document[] = [];

    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      setParsingStatus(`Processando ${file.name}...`);

      // LocalStorage has limits (~5MB total), keep files small for this demo
      if (file.size > 2 * 1024 * 1024) {
        alert(`Arquivo ${file.name} muito grande. O limite recomendado para armazenamento local é 2MB.`);
        continue;
      }

      try {
        const content = await extractContent(file);

        if (!content || content.trim().length === 0) {
          throw new Error("Nenhum texto extraído do documento.");
        }

        const doc: Document = {
          id: Math.random().toString(36).substr(2, 9),
          name: file.name,
          content: content,
          type: file.type || 'application/octet-stream',
          uploadDate: new Date(),
          size: file.size
        };

        StorageService.saveDocument(doc);
        newDocs.push(doc);
      } catch (err) {
        console.error("Erro ao processar arquivo:", err);
        alert(`Falha ao processar ${file.name}: ${err instanceof Error ? err.message : 'Erro desconhecido'}`);
      }
    }

    setDocuments(prev => [...newDocs, ...prev]);
    setIsUploading(false);
    setParsingStatus('');
  };

  const extractContent = async (file: File): Promise<string> => {
    const extension = file.name.split('.').pop()?.toLowerCase();

    if (extension === 'pdf') {
      return await extractTextFromPDF(file);
    }

    if (extension === 'docx') {
      return await extractTextFromDOCX(file);
    }

    if (file.type.includes('text') || extension === 'txt' || extension === 'csv' || extension === 'json') {
      return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = () => reject(new Error("Erro ao ler arquivo de texto."));
        reader.readAsText(file);
      });
    }

    throw new Error("Formato de arquivo não suportado.");
  };

  const extractTextFromPDF = async (file: File): Promise<string> => {
    const arrayBuffer = await file.arrayBuffer();
    // @ts-ignore
    const pdfjsLib = window['pdfjs-dist/build/pdf'];
    pdfjsLib.GlobalWorkerOptions.workerSrc = '//cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';

    try {
      const loadingTask = pdfjsLib.getDocument({ data: arrayBuffer });
      const pdf = await loadingTask.promise;
      let fullText = "";

      for (let i = 1; i <= pdf.numPages; i++) {
        const page = await pdf.getPage(i);
        const textContent = await page.getTextContent();
        // @ts-ignore
        const pageText = textContent.items.map((item: any) => item.str).join(" ");
        fullText += pageText + "\n";
      }
      return fullText;
    } catch (e) {
      throw new Error("Erro ao decodificar PDF.");
    }
  };

  const extractTextFromDOCX = async (file: File): Promise<string> => {
    const arrayBuffer = await file.arrayBuffer();
    // @ts-ignore
    const mammoth = window.mammoth;

    try {
      const result = await mammoth.extractRawText({ arrayBuffer });
      return result.value;
    } catch (e) {
      throw new Error("Erro ao processar arquivo DOCX.");
    }
  };

  const handleDrag = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") {
      setDragActive(true);
    } else if (e.type === "dragleave") {
      setDragActive(false);
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFiles(e.dataTransfer.files);
    }
  };

  const onButtonClick = () => {
    fileInputRef.current?.click();
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      handleFiles(e.target.files);
    }
  };

  const handleDelete = (id: string) => {
    StorageService.deleteDocument(id);
    setDocuments(prev => prev.filter(d => d.id !== id));
  };

  const filteredDocuments = documents.filter(doc => 
    doc.name.toUpperCase().includes(searchTerm.toUpperCase()) || 
    doc.content.toUpperCase().includes(searchTerm.toUpperCase())
  );

  return (
    <div className="p-10 max-w-6xl mx-auto">
      <header className="flex flex-col md:flex-row justify-between items-start md:items-center mb-12 border-b-2 border-[#1A1A1A] pb-8 gap-6">
        <div>
          <h1 className="text-3xl font-bold text-[#1A1A1A] uppercase tracking-tighter">GERENCIADOR DE ARQUIVOS</h1>
          <p className="text-[#7A7A7A] mt-2 font-bold text-xs uppercase tracking-widest">Base de Conhecimento RAG • Extração Real</p>
        </div>
        <button 
          onClick={onButtonClick}
          disabled={isUploading}
          className="sketch-button font-bold py-4 px-8 uppercase tracking-widest text-xs disabled:opacity-50 whitespace-nowrap"
        >
          {isUploading ? 'PROCESSANDO...' : '+ CARREGAR ARQUIVO'}
        </button>
      </header>

      <input 
        ref={fileInputRef}
        type="file" 
        multiple 
        className="hidden" 
        onChange={handleInputChange}
        accept=".pdf,.docx,.txt,.csv"
      />

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 mb-12">
        <div className="lg:col-span-2">
          <input 
            type="text"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="PESQUISAR DOCUMENTOS..."
            className="w-full bg-white sketch-border px-6 py-4 outline-none font-bold uppercase text-xs tracking-widest placeholder-[#B5B5B5] focus:bg-[#F2EFEA] transition-colors"
          />
        </div>
        <div className="bg-[#1A1A1A] p-4 text-[#F2EFEA] flex items-center justify-between sketch-border shadow-none">
          <div className="flex flex-col">
            <span className="text-[8px] font-bold uppercase tracking-widest text-[#B5B5B5]">STATUS REPOSITÓRIO</span>
            <span className="text-xs font-bold uppercase">{documents.length} ARQUIVOS</span>
          </div>
          {isUploading && (
            <div className="flex items-center gap-2">
              <div className="w-2 h-2 bg-emerald-500 rounded-full animate-ping"></div>
              <span className="text-[10px] font-bold uppercase">UPDATING</span>
            </div>
          )}
        </div>
      </div>

      <div 
        className={`mb-12 border-2 border-dashed p-12 text-center transition-colors cursor-pointer ${
          dragActive ? 'bg-[#1A1A1A] text-white border-white' : 'border-[#1A1A1A] text-[#7A7A7A]'
        }`}
        onDragEnter={handleDrag}
        onDragLeave={handleDrag}
        onDragOver={handleDrag}
