import React, { useState, useRef, useEffect } from 'react';
import { Message } from '../types';
import { GeminiService } from '../services/geminiService';

const ChatInterface: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([
    {
      id: 'welcome',
      role: 'model',
      content: '### FINANGPT ATIVO\n\nAnalista técnico pronto para processamento. Como posso auxiliar em sua análise contábil ou financeira hoje?\n\n- **RAG Engine:** On\n- **Web Grounding:** On\n- **Compliance:** CPC/IFRS',
      timestamp: new Date()
    }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsTyping(true);

    try {
      const response = await GeminiService.generateChatResponse(input, messages);
      const sources: string[] = [];
      if (response.groundingMetadata?.groundingChunks) {
        response.groundingMetadata.groundingChunks.forEach((chunk: any) => {
          if (chunk.web?.uri) sources.push(chunk.web.uri);
          if (chunk.maps?.uri) sources.push(chunk.maps.uri);
        });
      }

      const modelMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: response.text,
        timestamp: new Date(),
        sources: sources.length > 0 ? sources : undefined
      };

      setMessages(prev => [...prev, modelMessage]);
    } catch (error) {
      const errorMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: '### ERRO CRÍTICO NO SISTEMA\n\nFalha na comunicação com o motor de inferência. Por favor, tente novamente.',
        timestamp: new Date()
      };
      setMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsTyping(false);
    }
  };

  // Simple Markdown-ish parser for lists, bold, and tables
  const renderFormattedContent = (content: string) => {
    const lines = content.split('\n');
    let inTable = false;
    let tableRows: string[][] = [];

    return lines.map((line, idx) => {
      // Bold rendering
      const formatBold = (text: string) => {
        return text.split('**').map((part, i) => i % 2 === 1 ? <strong key={i} className="font-black text-[#1A1A1A]">{part}</strong> : part);
      };

      // Table detection
      if (line.trim().startsWith('|') && line.trim().endsWith('|')) {
        const cells = line.split('|').map(c => c.trim()).filter(c => c !== '');
        if (line.includes('---')) return null; // Skip divider line

        if (!inTable) {
          inTable = true;
          tableRows = [cells];
          return null;
        } else {
          tableRows.push(cells);

          // Check if next line is also a table line, if not, render the whole table
          const nextLine = lines[idx + 1];
          if (!nextLine || !nextLine.trim().startsWith('|')) {
            inTable = false;
            const currentTable = [...tableRows];
            tableRows = [];
            return (
              <div key={`table-${idx}`} className="my-6 overflow-x-auto sketch-border bg-white">
                <table className="w-full text-left border-collapse text-[11px] uppercase tracking-tighter">
                  <thead className="bg-[#1A1A1A] text-white font-black">
                    <tr>
                      {currentTable[0].map((cell, cIdx) => (
                        <th key={cIdx} className="px-4 py-2 border-r border-[#4A4A4A]">{cell}</th>
                      ))}
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-[#B5B5B5]">
                    {currentTable.slice(1).map((row, rIdx) => (
                      <tr key={rIdx} className="hover:bg-[#F2EFEA] transition-colors">
                        {row.map((cell, cIdx) => (
                          <td key={cIdx} className="px-4 py-2 border-r border-[#B5B5B5] font-medium">{formatBold(cell)}</td>
                        ))}
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            );
          }
          return null;
        }
      }

      // Headers
      if (line.startsWith('###')) {
        return <h3 key={idx} className="text-lg font-black mt-6 mb-2 text-[#1A1A1A] border-b-2 border-[#1A1A1A] pb-1 uppercase tracking-tighter">{formatBold(line.replace('###', ''))}</h3>;
      }

      // Lists
      if (line.trim().startsWith('- ') || line.trim().startsWith('* ')) {
        return (
          <div key={idx} className="flex gap-2 items-start ml-2 my-1">
            <span className="mt-1.5 w-1.5 h-1.5 bg-[#1A1A1A] flex-shrink-0"></span>
            <p className="text-sm font-medium leading-relaxed">{formatBold(line.substring(2))}</p>
          </div>
        );
      }

      // Paragraph
      if (line.trim() === '') return <div key={idx} className="h-4" />;

      return <p key={idx} className="text-sm leading-relaxed font-medium mb-2">{formatBold(line)}</p>;
    });
  };

  return (
    <div className="h-full flex flex-col bg-white">
      <header className="px-10 py-6 border-b-2 border-[#1A1A1A] flex items-center justify-between bg-white z-10 sticky top-0">
        <div className="flex items-center gap-6">
          <div className="w-12 h-12 bg-[#1A1A1A] flex items-center justify-center text-[#F2EFEA] font-bold italic text-xl sketch-border">
            F
          </div>
          <div>
            <h2 className="text-xl font-black text-[#1A1A1A] uppercase tracking-tighter leading-none">TERMINAL DE CONSULTA IA</h2>
            <div className="flex items-center gap-2 mt-1">
              <span className={`w-2 h-2 rounded-full ${isTyping ? 'bg-amber-500 animate-pulse' : 'bg-emerald-500'}`}></span>
              <span className="text-[9px] text-[#7A7A7A] font-bold uppercase tracking-widest">MOTOR: GEMINI-3-FLASH / RAG_ACTIVE</span>
            </div>
          </div>
        </div>
        <button 
          onClick={() => setMessages([{ id: 'reset', role: 'model', content: 'MEMÓRIA LIMPA. AGUARDANDO COMANDOS.', timestamp: new Date() }])}
          className="text-[9px] font-bold border-2 border-[#1A1A1A] px-3 py-1 uppercase hover:bg-[#1A1A1A] hover:text-white transition-all"
        >
          LIMPAR SESSÃO
        </button>
      </header>

      <div 
        ref={scrollRef}
        className="flex-1 overflow-y-auto p-10 space-y-12 bg-[#F2EFEA]/20"
      >
        {messages.map((msg) => (
          <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] flex gap-4 ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
              <div className={`w-10 h-10 flex-shrink-0 flex items-center justify-center text-[9px] font-black border-2 transition-transform duration-300 hover:rotate-6 ${
                msg.role === 'user' ? 'bg-white border-[#1A1A1A] text-[#1A1A1A]' : 'bg-[#1A1A1A] border-[#1A1A1A] text-[#F2EFEA]'
              }`}>
                {msg.role === 'user' ? 'USER' : 'GPT'}
              </div>

              <div className="flex flex-col gap-2">
                <div className={`p-8 sketch-border relative ${
                  msg.role === 'user' 
                    ? 'bg-white text-[#1A1A1A]' 
                    : 'bg-white text-[#1A1A1A]'
                }`}>
                  {/* Watermark for system messages */}
                  {msg.role === 'model' && (
                    <div className="absolute top-2 right-4 opacity-5 pointer-events-none select-none">
                      <span className="text-4xl font-black italic">CONFIDENTIAL</span>
                    </div>
                  )}

                  <div className="relative z-10">
                    {renderFormattedContent(msg.content)}
                  </div>

                  {msg.sources && (
                    <div className="mt-8 pt-6 border-t-2 border-dashed border-[#B5B5B5]">
                      <div className="flex items-center gap-2 mb-3">
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13.828 10.172a4 4 0 00-5.656 0l-4 4a4 4 0 105.656 5.656l1.102-1.101m-.758-4.899a4 4 0 005.656 0l4-4a4 4 0 00-5.656-5.656l-1.1 1.1"></path></svg>
                        <p className="text-[10px] font-black uppercase tracking-widest text-[#1A1A1A]">EVIDÊNCIAS DE MERCADO:</p>
                      </div>
                      <div className="flex flex-wrap gap-2">
                        {msg.sources.map((url, i) => (
                          <a 
