                      </div>
                    </div>
                  )}
                </div>
                <span className="text-[8px] font-black text-[#B5B5B5] px-2 uppercase tracking-widest">
                  {msg.timestamp.toLocaleTimeString()} • {msg.role === 'user' ? 'LOCAL_AUTH' : 'REMOTE_SYNC'}
