              <div className="flex flex-col gap-1">
                <div className="text-[10px] font-black tracking-widest uppercase text-[#1A1A1A]">Inferência em curso...</div>
                <div className="w-32 h-1 bg-[#B5B5B5] overflow-hidden">
                  <div className="h-full bg-[#1A1A1A] animate-[progress_1s_infinite_linear]"></div>
                </div>
              </div>
            </div>
          </div>
