import { GoogleGenAI } from "@google/genai";
import { StorageService } from "./storage";

export const GeminiService = {
  generateChatResponse: async (prompt: string, history: any[]) => {
    // Inicialização segura conforme diretrizes
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // RAG Logic: Busca documentos reais do storage
    const docs = StorageService.getDocuments();
    const context = docs.length > 0 
      ? `BASE DE CONHECIMENTO TÉCNICA (DOCUMENTOS DO USUÁRIO):\n${docs.map(d => `[DOCUMENTO: ${d.name}]\nID: ${d.id}\nCONTEÚDO: ${d.content}`).join('\n\n')}`
      : "O usuário ainda não forneceu documentos privados.";

    const systemInstruction = `
      Você é o "FinanGPT", consultor sênior em Contabilidade e Finanças.

      CONTEXTO ATUAL DA EMPRESA (RAG):
      ${context}

      DIRETRIZES DE RESPOSTA:
      1. Use o contexto acima para responder perguntas específicas.
      2. REQUISITO CRÍTICO: Se você usar informações de um documento interno, cite-o obrigatoriamente usando o formato [[NOME_DO_DOCUMENTO]]. Exemplo: "Segundo o balanço patrimonial [[Balanço_2023.pdf]], o lucro aumentou...".
      3. Se a informação não estiver nos documentos, use seus conhecimentos gerais e Google Search para dados de mercado.
      4. Formate respostas com Markdown, use tabelas para comparações numéricas.
      5. Mantenha um tom profissional, técnico e conciso.
      6. Sempre cite leis brasileiras (ex: LC 123/06, CPCs) quando tratar de contabilidade.
    `;

    // Formatação do histórico para o padrão da API
    const formattedHistory = history
      .filter(msg => msg.id !== 'welcome' && msg.id !== 'reset') // Filtra mensagens de sistema iniciais
      .map(msg => ({
        role: msg.role === 'user' ? 'user' : 'model',
        parts: [{ text: msg.content }]
      }));

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [
          ...formattedHistory,
          { role: 'user', parts: [{ text: prompt }] }
        ],
        config: {
          systemInstruction,
          tools: [{ googleSearch: {} }]
        },
      });

      return {
        text: response.text || "Ocorreu um erro ao processar a resposta.",
        groundingMetadata: response.candidates?.[0]?.groundingMetadata
      };
    } catch (error) {
      console.error("Gemini Error:", error);
      throw error;
    }
  }
};

import React, { useState, useRef, useEffect } from 'react';
