export const MarketService = {
  /**
   * Obtém taxas de câmbio e cripto de múltiplas fontes confiáveis.
   * Utiliza ExchangeRate-API para moedas fiduciárias e Binance para Cripto.
   */
  fetchExchangeRates: async (): Promise<MarketRates> => {
    try {
      // 1. Fetch taxas de moedas tradicionais (Fiat)
      const fiatResponse = await fetch('https://open.er-api.com/v6/latest/USD');
      if (!fiatResponse.ok) throw new Error('Falha ao obter taxas fiduciárias');
      const fiatData = await fiatResponse.json();
      const brl = fiatData.rates.BRL;

      // 2. Fetch Cripto em tempo real da Binance (Fonte mais confiável para tickers de 24h)
      // Buscamos BTCBRL e ETHBRL diretamente para maior precisão de mercado no Brasil
      const [btcRes, ethRes] = await Promise.all([
        fetch('https://api.binance.com/api/v3/ticker/price?symbol=BTCBRL').catch(() => null),
        fetch('https://api.binance.com/api/v3/ticker/price?symbol=ETHBRL').catch(() => null)
      ]);

      let btc_brl = brl / fiatData.rates.BTC; // Fallback inicial via taxa global USD
      let eth_brl = (brl / fiatData.rates.ETH) || (brl / fiatData.rates.BTC * 0.05); // Fallback secundário

      if (btcRes?.ok) {
        const btcData = await btcRes.json();
        if (btcData.price) btc_brl = parseFloat(btcData.price);
      }

      if (ethRes?.ok) {
        const ethData = await ethRes.json();
        if (ethData.price) eth_brl = parseFloat(ethData.price);
      }

      return {
        usd_brl: brl,
        eur_brl: brl / fiatData.rates.EUR,
        gbp_brl: brl / fiatData.rates.GBP,
        btc_brl: btc_brl,
        eth_brl: eth_brl,
        last_update: new Date().toISOString()
      };
    } catch (error) {
      console.error("Erro crítico ao buscar dados de mercado:", error);
      // Valores de contingência baseados em médias de mercado recentes para evitar Dashboard vazio
      return {
        usd_brl: 5.65,
        eur_brl: 6.12,
        gbp_brl: 7.32,
        btc_brl: 545000,
        eth_brl: 18750,
        last_update: new Date().toISOString()
      };
    }
  },

  /**
   * Simula dados de ações para o monitor de mercado.
   */
  fetchStockData: async (): Promise<StockInfo[]> => {
    const getVariation = (base: number) => (base + (Math.random() - 0.5) * (base * 0.008)).toLocaleString('pt-BR', { minimumFractionDigits: 2 });
    const getChange = () => ((Math.random() - 0.45) * 1.5).toFixed(2);

    return [
      { symbol: 'IBOV', name: 'IBOVESPA', price: '128.942', change: getChange() + '%', isPositive: Math.random() > 0.4 },
      { symbol: 'PETR4', name: 'PETROBRAS PN', price: getVariation(37.45), change: getChange() + '%', isPositive: Math.random() > 0.5 },
      { symbol: 'VALE3', name: 'VALE ON', price: getVariation(69.80), change: getChange() + '%', isPositive: Math.random() > 0.5 },
      { symbol: 'ITUB4', name: 'ITAÚ UNIBANCO', price: getVariation(33.95), change: getChange() + '%', isPositive: Math.random() > 0.5 },
      { symbol: 'SPX', name: 'S&P 500', price: '5.912,40', change: getChange() + '%', isPositive: Math.random() > 0.3 },
      { symbol: 'WDO', name: 'DÓLAR FUTURO', price: getVariation(5.66), change: getChange() + '%', isPositive: Math.random() > 0.5 },
    ];
  }
};

