      { symbol: 'ITUB4', name: 'ITAÚ UNIBANCO', price: getVariation(33.95), change: getChange() + '%', isPositive: Math.random() > 0.5 },
      { symbol: 'SPX', name: 'S&P 500', price: '5.912,40', change: getChange() + '%', isPositive: Math.random() > 0.3 },
      { symbol: 'WDO', name: 'DÓLAR FUTURO', price: getVariation(5.66), change: getChange() + '%', isPositive: Math.random() > 0.5 },
    ];
  },

  fetchHistoricalCandles: async (symbol: string, points: number = 30): Promise<Candle[]> => {
    // Simulação realista de série temporal baseada em ruído browniano
    let currentPrice = symbol === 'BTC/BRL' ? 550000 : 128000;
    const history: Candle[] = [];
    const now = new Date();

    for (let i = points; i >= 0; i--) {
      const date = new Date(now);
      date.setHours(now.getHours() - i);

      const volatility = currentPrice * 0.01;
      const open = currentPrice;
      const close = open + (Math.random() - 0.5) * volatility;
      const high = Math.max(open, close) + Math.random() * (volatility * 0.5);
      const low = Math.min(open, close) - Math.random() * (volatility * 0.5);

      history.push({
        time: date.toLocaleTimeString([], { hour: '2xl', minute: '2-digit' }),
        open, high, low, close
      });
      currentPrice = close;
    }
    return history;
  }
};

