                      className={`px-3 py-1.5 text-[9px] font-black uppercase border-r-2 last:border-0 border-[#1A1A1A] transition-colors ${timeframe === tf ? 'bg-[#1A1A1A] text-white' : 'hover:bg-[#B5B5B5]'}`}
                    >
                      {tf}
