                <span>MACD: NEUTRAL</span>
              </div>
              <span>DADOS: API BINANCE / B3 ENGINE • {new Date().toLocaleTimeString()}</span>
            </div>
          </div>
        </section>

        {/* Dashboard Cards Grid */}
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-8 mb-12">
          {stats.map((stat, idx) => (
            <div key={idx} className="bg-white p-6 sketch-border group hover:translate-y-[-4px] transition-all">
