              <p className="text-[8px] font-black text-gray-500 uppercase">Sistema Operacional</p>
              <p className="text-sm font-black text-emerald-400 uppercase tracking-tighter">FINAN_GPT OK</p>
            </div>
            <button className="mt-4 px-6 py-2 bg-white text-[#1A1A1A] text-[9px] font-black uppercase tracking-widest hover:bg-gray-200 transition-colors">
