import React, { useState, useRef, useEffect } from 'react';
import { Message, ChatSession } from '../types';
import { GeminiService } from '../services/geminiService';
import { StorageService } from '../services/storage';

const ChatInterface: React.FC = () => {
  const [currentSessionId, setCurrentSessionId] = useState<string>(Date.now().toString());
  const [messages, setMessages] = useState<Message[]>([
    {
      id: 'welcome',
      role: 'model',
      content: '### TERMINAL FINANGPT INICIALIZADO\n\nPronto para processamento de dados contábeis e análise de mercado.\n\n- **RAG Engine:** Ativa (Acesse "Documentos" para carregar sua base)\n- **Grounding:** Ativo via Google Search\n- **Modo:** Consultoria Técnica Especializada',
      timestamp: new Date()
    }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [copyStatus, setCopyStatus] = useState<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Carrega última sessão ativa (se houver) ou cria nova
  useEffect(() => {
    const activeSessions = StorageService.getChatSessions();
    if (activeSessions.length > 0) {
      // Por simplicidade, pega a mais recente para o modo "continuar"
      const last = activeSessions[activeSessions.length - 1];
      setCurrentSessionId(last.id);
      setMessages(last.messages);
    }
  }, []);

  // Salva automaticamente ao mudar mensagens
  useEffect(() => {
    if (messages.length > 1 || (messages.length === 1 && messages[0].id !== 'welcome')) {
      const session: ChatSession = {
        id: currentSessionId,
        title: messages.find(m => m.role === 'user')?.content.substring(0, 30) || 'Nova Conversa',
        messages,
        lastUpdate: new Date()
      };
      StorageService.saveChatSession(session);
    }
  }, [messages, currentSessionId]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsTyping(true);

    try {
      const response = await GeminiService.generateChatResponse(input, messages);
      const sources: string[] = [];

      if (response.groundingMetadata?.groundingChunks) {
        response.groundingMetadata.groundingChunks.forEach((chunk: any) => {
          if (chunk.web?.uri) sources.push(chunk.web.uri);
          if (chunk.maps?.uri) sources.push(chunk.maps.uri);
        });
      }

      const modelMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: response.text,
        timestamp: new Date(),
        sources: sources.length > 0 ? Array.from(new Set(sources)) : undefined
      };

      setMessages(prev => [...prev, modelMessage]);
    } catch (error) {
      const errorMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: '### FALHA TÉCNICA NO MOTOR DE IA\n\nOcorreu um erro ao processar a requisição. Verifique sua conexão ou tente novamente mais tarde.',
        timestamp: new Date()
      };
      setMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsTyping(false);
    }
  };

  const handleShare = async (content: string, id: string) => {
    const shareData = {
      title: 'Relatório FinanGPT',
      text: content,
      url: window.location.href
    };

    if (navigator.share && navigator.canShare && navigator.canShare(shareData)) {
      try {
        await navigator.share(shareData);
        return;
      } catch (err) {
        console.warn("Share failed, falling back to copy", err);
      }
    }

    try {
      await navigator.clipboard.writeText(content);
      setCopyStatus(id);
      setTimeout(() => setCopyStatus(null), 2000);
    } catch (err) {
      console.error("Failed to copy", err);
    }
  };

  const handleDeleteChat = () => {
    if (window.confirm("Deseja mover esta conversa para a lixeira? Ela ficará disponível por 30 dias.")) {
      StorageService.moveToTrash(currentSessionId);
      // Reseta para uma nova sessão
      setCurrentSessionId(Date.now().toString());
      setMessages([{
        id: 'welcome',
        role: 'model',
        content: '### TERMINAL REINICIADO\nSessão anterior movida para a lixeira.',
        timestamp: new Date()
      }]);
    }
  };

  const renderFormattedContent = (content: string) => {
    const processedContent = content.replace(/\[\[(.*?)\]\]/g, (match, p1) => `**[Fonte: ${p1}]**`);

    const lines = processedContent.split('\n');
    let inTable = false;
    let tableRows: string[][] = [];

    const formatBold = (text: string) => {
      const parts = text.split('**');
      return parts.map((part, i) => i % 2 === 1 ? <strong key={i} className="font-black text-[#1A1A1A]">{part}</strong> : part);
    };

    const elements: React.ReactNode[] = [];

    lines.forEach((line, idx) => {
      if (line.trim().startsWith('|') && line.trim().endsWith('|')) {
        const cells = line.split('|').map(c => c.trim()).filter(c => c !== '');
        if (line.includes('---')) return;

        if (!inTable) {
          inTable = true;
          tableRows = [cells];
        } else {
          tableRows.push(cells);
        }

        const nextLine = lines[idx + 1];
        if (!nextLine || !nextLine.trim().startsWith('|')) {
          inTable = false;
          const currentTable = [...tableRows];
          tableRows = [];
          elements.push(
            <div key={`table-${idx}`} className="my-6 overflow-x-auto sketch-border bg-white">
              <table className="w-full text-left border-collapse text-[11px] uppercase tracking-tighter">
                <thead className="bg-[#1A1A1A] text-white font-black">
                  <tr>
                    {currentTable[0]?.map((cell, cIdx) => (
                      <th key={cIdx} className="px-4 py-2 border-r border-[#4A4A4A]">{cell}</th>
                    ))}
                  </tr>
                </thead>
                <tbody className="divide-y divide-[#B5B5B5]">
                  {currentTable.slice(1).map((row, rIdx) => (
                    <tr key={rIdx} className="hover:bg-[#F2EFEA] transition-colors">
                      {row.map((cell, cIdx) => (
                        <td key={cIdx} className="px-4 py-2 border-r border-[#B5B5B5] font-medium">{formatBold(cell)}</td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          );
        }
        return;
      }

      if (line.startsWith('###')) {
        elements.push(<h3 key={idx} className="text-lg font-black mt-6 mb-2 text-[#1A1A1A] border-b-2 border-[#1A1A1A] pb-1 uppercase tracking-tighter">{formatBold(line.replace('###', ''))}</h3>);
        return;
      }

      if (line.trim().startsWith('- ') || line.trim().startsWith('* ')) {
        elements.push(
          <div key={idx} className="flex gap-2 items-start ml-2 my-1">
            <span className="mt-1.5 w-1.5 h-1.5 bg-[#1A1A1A] flex-shrink-0"></span>
            <p className="text-sm font-medium leading-relaxed">{formatBold(line.trim().substring(2))}</p>
          </div>
        );
        return;
      }

      if (line.trim() === '') {
        elements.push(<div key={idx} className="h-4" />);
      } else {
        elements.push(<p key={idx} className="text-sm leading-relaxed font-medium mb-2">{formatBold(line)}</p>);
      }
    });

    return <div className="space-y-1">{elements}</div>;
  };

  return (
    <div className="flex flex-col h-full bg-[#F2EFEA]">
      <header className="p-8 border-b-2 border-[#1A1A1A] flex justify-between items-center bg-white">
        <div>
          <h2 className="text-2xl font-black text-[#1A1A1A] tracking-tighter uppercase leading-none">ASSISTENTE FINANGPT</h2>
          <p className="text-[10px] font-bold text-[#7A7A7A] uppercase tracking-widest mt-2">Protocolo de Comunicação Seguro</p>
        </div>
        <div className="flex gap-4">
          <button 
            onClick={() => {
              setCurrentSessionId(Date.now().toString());
              setMessages([{ id: 'new', role: 'model', content: '### NOVA CONVERSA INICIADA\nComo posso ajudar hoje?', timestamp: new Date() }]);
            }}
            className="text-[10px] font-bold uppercase border-2 border-[#1A1A1A] px-4 py-2 hover:bg-[#1A1A1A] hover:text-white transition-all shadow-[2px_2px_0px_0px_#1A1A1A] bg-white"
          >
            Novo Chat
          </button>
          <button 
            onClick={handleDeleteChat}
            className="text-[10px] font-bold uppercase border-2 border-[#EF4444] text-[#EF4444] px-4 py-2 hover:bg-[#EF4444] hover:text-white transition-all shadow-[2px_2px_0px_0px_#EF4444] bg-white"
          >
            Deletar Chat
          </button>
        </div>
      </header>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-8 space-y-8 scroll-smooth">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] ${msg.role === 'user' ? 'bg-[#1A1A1A] text-white' : 'bg-white text-[#1A1A1A]'} sketch-border p-6 relative group transition-all`}>
              <div className="flex justify-between items-start mb-4 gap-4 border-b border-[#B5B5B5]/30 pb-2">
                <span className={`text-[8px] font-black uppercase tracking-widest ${msg.role === 'user' ? 'text-gray-400' : 'text-[#7A7A7A]'}`}>
                  {msg.role === 'user' ? 'ANALISTA_ID:01' : 'CORE_ENGINE_AI'}
                </span>
                <span className="text-[8px] font-bold text-[#7A7A7A]">{msg.timestamp.toLocaleTimeString()}</span>
              </div>

              <div className="prose prose-sm max-w-none">
                {renderFormattedContent(msg.content)}
              </div>

              {msg.role === 'model' && msg.sources && (
                <div className="mt-6 pt-4 border-t border-[#B5B5B5] space-y-2">
                  <p className="text-[9px] font-black text-[#7A7A7A] uppercase tracking-widest">Fontes de Grounding:</p>
                  <div className="flex flex-wrap gap-2">
                    {msg.sources.map((url, i) => (
                      <a key={i} href={url} target="_blank" rel="noopener noreferrer" className="text-[9px] font-bold text-blue-600 underline truncate max-w-[250px] hover:text-blue-800">
                        {new URL(url).hostname}
                      </a>
                    ))}
                  </div>
                </div>
              )}

              {msg.role === 'model' && (
                <div className="mt-6 flex justify-end border-t border-[#B5B5B5]/20 pt-4">
                  <button 
                    onClick={() => handleShare(msg.content, msg.id)}
                    className={`flex items-center gap-2 text-[9px] font-black uppercase tracking-widest transition-all px-3 py-1.5 border border-[#1A1A1A] hover:bg-[#1A1A1A] hover:text-white ${copyStatus === msg.id ? 'bg-emerald-500 text-white border-emerald-500' : ''}`}
                  >
                    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8.684 13.342C8.886 12.938 9 12.482 9 12c0-.482-.114-.938-.316-1.342m0 2.684a3 3 0 110-2.684m0 2.684l6.632 3.316m-6.632-6l6.632-3.316m0 0a3 3 0 100-2.684 3 3 0 000 2.684zm0 12.684a3 3 0 100-2.684 3 3 0 000 2.684z" />
                    </svg>
                    {copyStatus === msg.id ? 'COPIADO!' : 'COMPARTILHAR RESPOSTA'}
                  </button>
                </div>
              )}
            </div>
          </div>
        ))}
        {isTyping && (
          <div className="flex justify-start">
            <div className="bg-white sketch-border p-4 flex gap-2">
              <div className="w-1.5 h-1.5 bg-[#1A1A1A] animate-bounce"></div>
