import { GoogleGenAI } from "@google/genai";
import { StorageService } from "./storage";

export const GeminiService = {
  generateChatResponse: async (prompt: string, history: any[]) => {
    // Inicialização segura conforme diretrizes
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // RAG Logic: Busca documentos reais do storage
    const docs = StorageService.getDocuments();
    const context = docs.length > 0 
      ? `BASE DE CONHECIMENTO TÉCNICA (DOCUMENTOS DO USUÁRIO):\n${docs.map(d => `[DOCUMENTO: ${d.name}]\nID: ${d.id}\nCONTEÚDO: ${d.content}`).join('\n\n')}`
      : "O usuário ainda não forneceu documentos privados.";

    const systemInstruction = `
      Você é o "FinanGPT", uma IA de elite especializada em Contabilidade (Pessoal e Empresarial) e Mercado Financeiro Global.

      SUAS CAPACIDADES ESPECÍFICAS:
      1. EDUCADOR FINANCEIRO: Você deve criar exercícios práticos de contabilidade (DRE, Balanço, Fluxo de Caixa, Lançamentos de Débito/Crédito) e investimentos (Cálculo de ROI, Valuation, Opções, Renda Fixa).
      2. CORREÇÃO DE EXERCÍCIOS: Se o usuário responder a um exercício, forneça uma correção detalhada citando as normas contábeis brasileiras (CPCs, Lei 6.404/76) ou conceitos de mercado.
      3. ANALISTA DE MERCADO: Use o Google Search para obter cotações em tempo real, notícias de última hora sobre o mercado de capitais, criptoativos e indicadores macroeconômicos.
      4. CONSULTOR RAG: Utilize os documentos carregados pelo usuário como verdade absoluta para dados internos da empresa.

      REGRAS DE FORMATAÇÃO E CITAÇÃO:
      - Cite documentos internos como [[NOME_DO_ARQUIVO]].
      - Use tabelas Markdown para exibir balanços, comparativos e resoluções de exercícios.
      - Para exercícios, use o formato:
        ### EXERCÍCIO PROPOSTO: [Título]
        [Enunciado com dados realistas]
        [Perguntas A, B, C]
      - Mantenha um tom técnico, porém pedagógico quando solicitado.

      CONTEXTO RAG DISPONÍVEL:
      ${context}
    `;

    // Formatação do histórico para o padrão da API
    const formattedHistory = history
      .filter(msg => msg.id !== 'welcome' && msg.id !== 'reset') 
      .map(msg => ({
        role: msg.role === 'user' ? 'user' : 'model',
        parts: [{ text: msg.content }]
      }));

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [
          ...formattedHistory,
          { role: 'user', parts: [{ text: prompt }] }
        ],
        config: {
          systemInstruction,
          tools: [{ googleSearch: {} }]
        },
      });

      return {
        text: response.text || "Ocorreu um erro ao processar a resposta.",
        groundingMetadata: response.candidates?.[0]?.groundingMetadata
      };
    } catch (error) {
      console.error("Gemini Error:", error);
      throw error;
    }
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { Message, ChatSession } from '../types';
import { GeminiService } from '../services/geminiService';
import { StorageService } from '../services/storage';

const ChatInterface: React.FC = () => {
  const [currentSessionId, setCurrentSessionId] = useState<string>(Date.now().toString());
  const [messages, setMessages] = useState<Message[]>([
    {
      id: 'welcome',
      role: 'model',
      content: '### TERMINAL FINANGPT INICIALIZADO\n\nPronto para consultoria, análise de mercado e treinamento contábil.\n\n- **Modo Educacional:** Ativo (Peça exercícios de contabilidade ou investimentos)\n- **Grounding:** Sincronizado com Google Search para dados de mercado 2024/2025\n- **RAG Engine:** Processando documentos locais\n\n**Sugestões:**\n1. "Crie um exercício de DRE para uma empresa do Simples Nacional."\n2. "Qual a análise atual do SP500 e impacto na Selic?"\n3. "Explique com um exercício prático como funciona o hedge com opções."',
      timestamp: new Date()
    }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [copyStatus, setCopyStatus] = useState<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const activeSessions = StorageService.getChatSessions();
    if (activeSessions.length > 0) {
      const last = activeSessions[activeSessions.length - 1];
      setCurrentSessionId(last.id);
      setMessages(last.messages);
    }
  }, []);

  useEffect(() => {
    if (messages.length > 1 || (messages.length === 1 && messages[0].id !== 'welcome')) {
      const session: ChatSession = {
        id: currentSessionId,
        title: messages.find(m => m.role === 'user')?.content.substring(0, 30) || 'Nova Conversa',
        messages,
        lastUpdate: new Date()
      };
      StorageService.saveChatSession(session);
    }
  }, [messages, currentSessionId]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsTyping(true);

    try {
      const response = await GeminiService.generateChatResponse(input, messages);
      const sources: string[] = [];

      if (response.groundingMetadata?.groundingChunks) {
        response.groundingMetadata.groundingChunks.forEach((chunk: any) => {
          if (chunk.web?.uri) sources.push(chunk.web.uri);
          if (chunk.maps?.uri) sources.push(chunk.maps.uri);
        });
      }

      const modelMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: response.text,
        timestamp: new Date(),
        sources: sources.length > 0 ? Array.from(new Set(sources)) : undefined
      };

      setMessages(prev => [...prev, modelMessage]);
    } catch (error) {
      const errorMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: '### FALHA TÉCNICA NO MOTOR DE IA\n\nOcorreu um erro ao processar a requisição. Verifique sua conexão ou tente novamente mais tarde.',
        timestamp: new Date()
      };
      setMessages(prev => [...prev, errorMessage]);
    } finally {
      setIsTyping(false);
    }
  };

  const handleShare = async (content: string, id: string) => {
    const shareData = { title: 'Relatório FinanGPT', text: content, url: window.location.href };
    if (navigator.share && navigator.canShare && navigator.canShare(shareData)) {
      try { await navigator.share(shareData); return; } catch (err) { console.warn("Share failed", err); }
    }
    try {
      await navigator.clipboard.writeText(content);
      setCopyStatus(id);
      setTimeout(() => setCopyStatus(null), 2000);
    } catch (err) { console.error("Failed to copy", err); }
  };

  const handleDeleteChat = () => {
    if (window.confirm("Deseja mover esta conversa para a lixeira?")) {
      StorageService.moveToTrash(currentSessionId);
      setCurrentSessionId(Date.now().toString());
      setMessages([{
        id: 'welcome',
        role: 'model',
        content: '### TERMINAL REINICIADO\nSessão anterior arquivada.',
        timestamp: new Date()
      }]);
    }
  };

  const renderFormattedContent = (content: string) => {
    const processedContent = content.replace(/\[\[(.*?)\]\]/g, (match, p1) => `**[Fonte: ${p1}]**`);
    const lines = processedContent.split('\n');
    let inTable = false;
    let tableRows: string[][] = [];

    const formatBold = (text: string) => {
      const parts = text.split('**');
      return parts.map((part, i) => i % 2 === 1 ? <strong key={i} className="font-black text-[#1A1A1A]">{part}</strong> : part);
    };

    const elements: React.ReactNode[] = [];

    lines.forEach((line, idx) => {
      if (line.trim().startsWith('|') && line.trim().endsWith('|')) {
        const cells = line.split('|').map(c => c.trim()).filter(c => c !== '');
        if (line.includes('---')) return;
        if (!inTable) { inTable = true; tableRows = [cells]; } else { tableRows.push(cells); }
        const nextLine = lines[idx + 1];
        if (!nextLine || !nextLine.trim().startsWith('|')) {
          inTable = false;
          const currentTable = [...tableRows];
          tableRows = [];
          elements.push(
            <div key={`table-${idx}`} className="my-6 overflow-x-auto sketch-border bg-white">
              <table className="w-full text-left border-collapse text-[11px] uppercase tracking-tighter">
                <thead className="bg-[#1A1A1A] text-white font-black">
                  <tr>{currentTable[0]?.map((cell, cIdx) => (<th key={cIdx} className="px-4 py-2 border-r border-[#4A4A4A]">{cell}</th>))}</tr>
                </thead>
                <tbody className="divide-y divide-[#B5B5B5]">
                  {currentTable.slice(1).map((row, rIdx) => (
                    <tr key={rIdx} className="hover:bg-[#F2EFEA] transition-colors">
                      {row.map((cell, cIdx) => (<td key={cIdx} className="px-4 py-2 border-r border-[#B5B5B5] font-medium">{formatBold(cell)}</td>))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          );
        }
        return;
      }

      if (line.startsWith('###')) {
        elements.push(<h3 key={idx} className="text-lg font-black mt-6 mb-2 text-[#1A1A1A] border-b-2 border-[#1A1A1A] pb-1 uppercase tracking-tighter">{formatBold(line.replace('###', ''))}</h3>);
        return;
      }
      if (line.trim().startsWith('- ') || line.trim().startsWith('* ')) {
        elements.push(<div key={idx} className="flex gap-2 items-start ml-2 my-1"><span className="mt-1.5 w-1.5 h-1.5 bg-[#1A1A1A] flex-shrink-0"></span><p className="text-sm font-medium leading-relaxed">{formatBold(line.trim().substring(2))}</p></div>);
        return;
      }
      if (line.trim() === '') { elements.push(<div key={idx} className="h-4" />); } 
      else { elements.push(<p key={idx} className="text-sm leading-relaxed font-medium mb-2">{formatBold(line)}</p>); }
    });

    return <div className="space-y-1">{elements}</div>;
  };

  return (
    <div className="flex flex-col h-full bg-[#F2EFEA]">
      <header className="p-8 border-b-2 border-[#1A1A1A] flex justify-between items-center bg-white">
        <div>
          <h2 className="text-2xl font-black text-[#1A1A1A] tracking-tighter uppercase leading-none">ASSISTENTE FINANGPT</h2>
          <p className="text-[10px] font-bold text-[#7A7A7A] uppercase tracking-widest mt-2">Educação, Auditoria e Análise de Mercado</p>
        </div>
        <div className="flex gap-4">
          <button onClick={() => { setCurrentSessionId(Date.now().toString()); setMessages([{ id: 'new', role: 'model', content: '### NOVA SESSÃO\nPronto para novos desafios contábeis e financeiros.', timestamp: new Date() }]); }} className="text-[10px] font-bold uppercase border-2 border-[#1A1A1A] px-4 py-2 hover:bg-[#1A1A1A] hover:text-white transition-all shadow-[2px_2px_0px_0px_#1A1A1A] bg-white">Novo Chat</button>
          <button onClick={handleDeleteChat} className="text-[10px] font-bold uppercase border-2 border-[#EF4444] text-[#EF4444] px-4 py-2 hover:bg-[#EF4444] hover:text-white transition-all shadow-[2px_2px_0px_0px_#EF4444] bg-white">Deletar</button>
        </div>
      </header>

      <div ref={scrollRef} className="flex-1 overflow-y-auto p-8 space-y-8 scroll-smooth">
        {messages.map((msg) => (
          <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[85%] ${msg.role === 'user' ? 'bg-[#1A1A1A] text-white' : 'bg-white text-[#1A1A1A]'} sketch-border p-6 relative group transition-all`}>
              <div className="flex justify-between items-start mb-4 gap-4 border-b border-[#B5B5B5]/30 pb-2">
                <span className={`text-[8px] font-black uppercase tracking-widest ${msg.role === 'user' ? 'text-gray-400' : 'text-[#7A7A7A]'}`}>{msg.role === 'user' ? 'ESTUDANTE_ID:01' : 'CORE_ENGINE_AI'}</span>
                <span className="text-[8px] font-bold text-[#7A7A7A]">{msg.timestamp.toLocaleTimeString()}</span>
              </div>
              <div className="prose prose-sm max-w-none">{renderFormattedContent(msg.content)}</div>
              {msg.role === 'model' && msg.sources && (
