import React, { useState, useEffect, useMemo } from 'react';
import { MarketService, MarketRates, StockInfo } from '../services/marketService';
import { Candle } from '../types';

const Dashboard: React.FC = () => {
  const [rates, setRates] = useState<MarketRates | null>(null);
  const [stocks, setStocks] = useState<StockInfo[]>([]);
  const [candles, setCandles] = useState<Candle[]>([]);
  const [selectedAsset, setSelectedAsset] = useState('BTC');
  const [timeframe, setTimeframe] = useState('1h');
  const [hoveredCandle, setHoveredCandle] = useState<Candle | null>(null);
  const [loadingMarket, setLoadingMarket] = useState(true);
  const [showSMA, setShowSMA] = useState(false);

  useEffect(() => {
    const loadMarketData = async () => {
      setLoadingMarket(true);
      try {
        const rateData = await MarketService.fetchExchangeRates();
        const [stockData, candleData] = await Promise.all([
          MarketService.fetchStockData(rateData),
          MarketService.fetchHistoricalCandles(selectedAsset, timeframe)
        ]);
        setRates(rateData);
        setStocks(stockData);
        setCandles(candleData);
      } catch (e) {
        console.error("Error updating dashboard data", e);
      } finally {
        setLoadingMarket(false);
      }
    };

    loadMarketData();
    const interval = setInterval(loadMarketData, timeframe === '1m' ? 5000 : 30000); 
    return () => clearInterval(interval);
  }, [selectedAsset, timeframe]);

  const stats = [
    { label: 'RECEITA ESTIMADA', value: 'R$ 45.230', trend: '+12%', isPositive: true },
    { label: 'OPEX ATUAL', value: 'R$ 21.050', trend: '-2%', isPositive: true },
    { label: 'LUCRO PROJETADO', value: 'R$ 24.180', trend: '+18%', isPositive: true },
    { label: 'RISCO CAMBIAL', value: 'BAIXO', trend: 'STABLE', isPositive: true },
  ];

  const chartMetrics = useMemo(() => {
    if (candles.length === 0) return null;
    const lows = candles.map(c => c.low);
    const highs = candles.map(c => c.high);
    const minLow = Math.min(...lows);
    const maxHigh = Math.max(...highs);
    const range = maxHigh - minLow;

    const sma = candles.map((_, i) => {
      if (i < 9) return null;
      const slice = candles.slice(i - 9, i + 1);
      const sum = slice.reduce((acc, curr) => acc + curr.close, 0);
      return sum / 10;
    });

    // Cálculos de Suporte e Resistência Estimados
    const estimatedSupport = minLow;
    const estimatedResistance = maxHigh;

    return { minLow, maxHigh, range, sma, estimatedSupport, estimatedResistance };
  }, [candles]);

  const renderCandleChart = () => {
    if (!chartMetrics || candles.length === 0) return (
      <div className="h-[350px] flex flex-col items-center justify-center gap-4 bg-[#F9F9F9] sketch-border">
        <div className="w-8 h-8 border-4 border-[#1A1A1A] border-t-transparent rounded-full animate-spin"></div>
        <span className="text-[10px] font-black uppercase tracking-widest text-[#7A7A7A]">Sincronizando Ordens...</span>
      </div>
    );

    const width = 1000;
    const height = 350;
    const padding = 40;
    const candleSpace = (width - padding * 2) / candles.length;
    const candleWidth = candleSpace * 0.7;

    const getY = (price: number) => {
      return height - padding - ((price - chartMetrics.minLow) / chartMetrics.range) * (height - padding * 2);
    };

    return (
      <div className="relative group cursor-crosshair select-none bg-white p-2">
        <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-[350px] overflow-visible" preserveAspectRatio="none">
          {[0, 0.25, 0.5, 0.75, 1].map((p, i) => {
            const y = padding + p * (height - padding * 2);
            const price = chartMetrics.maxHigh - p * chartMetrics.range;
            return (
              <g key={i}>
                <line x1={padding} y1={y} x2={width - padding} y2={y} stroke="#F2F2F2" strokeWidth="1" />
                <text x={width - padding + 5} y={y + 4} className="text-[9px] fill-[#B5B5B5] font-bold font-mono">
                  {price.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL', minimumFractionDigits: 0 })}
                </text>
              </g>
            );
          })}

          {candles.filter((_, i) => i % 10 === 0).map((candle, i) => {
            const x = padding + (i * 10) * candleSpace;
            return (
              <text key={i} x={x} y={height - 5} className="text-[8px] fill-[#7A7A7A] font-bold text-center" textAnchor="middle">
                {candle.time}
              </text>
            );
          })}

          {showSMA && chartMetrics.sma.map((val, i) => {
            if (val === null || i === 0 || chartMetrics.sma[i-1] === null) return null;
            const x1 = padding + (i - 1) * candleSpace + candleSpace/2;
            const y1 = getY(chartMetrics.sma[i-1]!);
            const x2 = padding + i * candleSpace + candleSpace/2;
            const y2 = getY(val);
            return (
              <line key={i} x1={x1} y1={y1} x2={x2} y2={y2} stroke="#3B82F6" strokeWidth="1.5" strokeDasharray="2 2" />
            );
          })}

          {candles.map((candle, i) => {
            const x = padding + i * candleSpace;
            const openY = getY(candle.open);
            const closeY = getY(candle.close);
            const highY = getY(candle.high);
            const lowY = getY(candle.low);
            const isBullish = candle.close >= candle.open;
            const color = isBullish ? '#10B981' : '#EF4444';

            return (
              <g key={i} onMouseEnter={() => setHoveredCandle(candle)} onMouseLeave={() => setHoveredCandle(null)}>
                <line x1={x + candleSpace/2} y1={highY} x2={x + candleSpace/2} y2={lowY} stroke={color} strokeWidth="1.5" />
                <rect 
                  x={x + (candleSpace - candleWidth)/2} 
                  y={Math.min(openY, closeY)} 
                  width={candleWidth} 
                  height={Math.max(1.5, Math.abs(openY - closeY))} 
                  fill={color}
                  className="transition-all duration-200 hover:opacity-80"
                />
                <rect x={x} y={0} width={candleSpace} height={height} fill="transparent" />
              </g>
            );
          })}
        </svg>

        {hoveredCandle && (
          <div className="absolute bottom-2 left-2 bg-[#1A1A1A] text-white p-4 text-[9px] font-black sketch-border shadow-2xl z-50 space-y-2 min-w-[150px]">
            <div className="border-b border-white/20 pb-2 flex justify-between">
              <span>TIMESTAMP</span>
              <span className="text-emerald-400 font-mono">{hoveredCandle.time}</span>
            </div>
            <div className="space-y-1 font-mono">
              <div className="flex justify-between"><span>OPEN:</span> <span>{hoveredCandle.open.toFixed(2)}</span></div>
              <div className="flex justify-between"><span>HIGH:</span> <span>{hoveredCandle.high.toFixed(2)}</span></div>
              <div className="flex justify-between"><span>LOW:</span> <span>{hoveredCandle.low.toFixed(2)}</span></div>
              <div className="flex justify-between"><span>CLOSE:</span> <span>{hoveredCandle.close.toFixed(2)}</span></div>
            </div>
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full bg-[#F2EFEA] overflow-hidden">
      {/* Ticker Tape */}
      <div className="bg-[#1A1A1A] h-10 flex items-center overflow-hidden border-b-2 border-[#1A1A1A] relative">
        <div className="flex animate-[ticker_60s_linear_infinite] whitespace-nowrap gap-12 px-4 items-center">
          {[...stocks, ...stocks].map((stock, i) => (
            <div key={i} className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest">
              <span className="text-white">{stock.symbol}</span>
              <span className="text-gray-400 font-mono">{stock.price}</span>
              <span className={stock.isPositive ? 'text-emerald-400' : 'text-rose-400'}>{stock.change}</span>
            </div>
          ))}
        </div>
        <style>{`
          @keyframes ticker {
            0% { transform: translateX(0); }
            100% { transform: translateX(-50%); }
          }
        `}</style>
      </div>

      <div className="flex-1 overflow-y-auto p-8 space-y-8">
        <header className="flex justify-between items-end border-b-2 border-[#1A1A1A] pb-8">
          <div>
            <h1 className="text-4xl font-black text-[#1A1A1A] tracking-tighter uppercase leading-none">TERMINAL ANALÍTICO</h1>
            <div className="flex gap-4 mt-4">
              <div className="flex items-center gap-2">
                <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></div>
