  const chartMetrics = useMemo(() => {
    if (candles.length === 0) return null;
    const lows = candles.map(c => c.low);
    const highs = candles.map(c => c.high);
    const minLow = Math.min(...lows);
    const maxHigh = Math.max(...highs);
    const range = maxHigh - minLow;

    const sma = candles.map((_, i) => {
      if (i < 9) return null;
      const slice = candles.slice(i - 9, i + 1);
      const sum = slice.reduce((acc, curr) => acc + curr.close, 0);
      return sum / 10;
    });

    const estimatedSupport = minLow;
    const estimatedResistance = maxHigh;

    return { minLow, maxHigh, range, sma, estimatedSupport, estimatedResistance };
  }, [candles]);

  const renderCandleChart = () => {
    if (!chartMetrics || candles.length === 0) return (
      <div className="h-[350px] flex flex-col items-center justify-center gap-4 bg-[#F9F9F9] sketch-border">
