    const width = 1000;
    const height = 350;
    const padding = 40;
    const candleSpace = (width - padding * 2) / candles.length;
    const candleWidth = candleSpace * 0.7;

    const getY = (price: number) => {
      return height - padding - ((price - chartMetrics.minLow) / chartMetrics.range) * (height - padding * 2);
    };

    return (
      <div className="relative group cursor-crosshair select-none bg-white p-2">
        <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-[350px] overflow-visible" preserveAspectRatio="none">
          {[0, 0.25, 0.5, 0.75, 1].map((p, i) => {
            const y = padding + p * (height - padding * 2);
            const price = chartMetrics.maxHigh - p * chartMetrics.range;
            return (
              <g key={i}>
                <line x1={padding} y1={y} x2={width - padding} y2={y} stroke="#F2F2F2" strokeWidth="1" />
                <text x={width - padding + 5} y={y + 4} className="text-[9px] fill-[#B5B5B5] font-bold font-mono">
                  {price.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL', minimumFractionDigits: 0 })}
                </text>
              </g>
            );
          })}

          {candles.filter((_, i) => i % 10 === 0).map((candle, i) => {
            const x = padding + (i * 10) * candleSpace;
            return (
              <text key={i} x={x} y={height - 5} className="text-[8px] fill-[#7A7A7A] font-bold text-center" textAnchor="middle">
                {candle.time}
              </text>
            );
          })}

          {showSMA && chartMetrics.sma.map((val, i) => {
            if (val === null || i === 0 || chartMetrics.sma[i-1] === null) return null;
            const x1 = padding + (i - 1) * candleSpace + candleSpace/2;
            const y1 = getY(chartMetrics.sma[i-1]!);
            const x2 = padding + i * candleSpace + candleSpace/2;
            const y2 = getY(val);
            return (
              <line key={i} x1={x1} y1={y1} x2={x2} y2={y2} stroke="#3B82F6" strokeWidth="1.5" strokeDasharray="2 2" />
            );
          })}

          {candles.map((candle, i) => {
            const x = padding + i * candleSpace;
            const openY = getY(candle.open);
            const closeY = getY(candle.close);
            const highY = getY(candle.high);
            const lowY = getY(candle.low);
            const isBullish = candle.close >= candle.open;
            const color = isBullish ? '#10B981' : '#EF4444';

            return (
              <g key={i} onMouseEnter={() => setHoveredCandle(candle)} onMouseLeave={() => setHoveredCandle(null)}>
                <line x1={x + candleSpace/2} y1={highY} x2={x + candleSpace/2} y2={lowY} stroke={color} strokeWidth="1.5" />
                <rect 
                  x={x + (candleSpace - candleWidth)/2} 
                  y={Math.min(openY, closeY)} 
                  width={candleWidth} 
                  height={Math.max(1.5, Math.abs(openY - closeY))} 
                  fill={color}
                  className="transition-all duration-200 hover:opacity-80"
                />
                <rect x={x} y={0} width={candleSpace} height={height} fill="transparent" />
              </g>
            );
          })}
        </svg>

        {hoveredCandle && (
          <div className="absolute bottom-2 left-2 bg-[#1A1A1A] text-white p-4 text-[9px] font-black sketch-border shadow-2xl z-50 space-y-2 min-w-[150px]">
            <div className="border-b border-white/20 pb-2 flex justify-between">
              <span>TIMESTAMP</span>
              <span className="text-emerald-400 font-mono">{hoveredCandle.time}</span>
            </div>
            <div className="space-y-1 font-mono">
              <div className="flex justify-between"><span>OPEN:</span> <span>{hoveredCandle.open.toFixed(2)}</span></div>
              <div className="flex justify-between"><span>HIGH:</span> <span>{hoveredCandle.high.toFixed(2)}</span></div>
              <div className="flex justify-between"><span>LOW:</span> <span>{hoveredCandle.low.toFixed(2)}</span></div>
              <div className="flex justify-between"><span>CLOSE:</span> <span>{hoveredCandle.close.toFixed(2)}</span></div>
            </div>
          </div>
        )}
      </div>
    );
  };

