              <div className="h-4 w-[1px] bg-[#B5B5B5]"></div>
              <span className="text-[10px] font-black uppercase tracking-widest text-[#7A7A7A]">Sincronizado: {new Date().toLocaleTimeString()}</span>
            </div>
          </div>

          <div className="flex gap-4">
            <select 
              value={selectedAsset}
              onChange={(e) => setSelectedAsset(e.target.value)}
              className="bg-white sketch-border px-4 py-2 font-black text-[10px] uppercase outline-none"
            >
              {stocks.map(s => <option key={s.symbol} value={s.symbol}>{s.symbol} - {s.name}</option>)}
            </select>
            <div className="flex sketch-border bg-white overflow-hidden">
              {['1m', '1h', '1d'].map(t => (
                <button 
                  key={t}
                  onClick={() => setTimeframe(t)}
                  className={`px-4 py-2 text-[10px] font-black uppercase transition-colors ${timeframe === t ? 'bg-[#1A1A1A] text-white' : 'hover:bg-[#F2EFEA]'}`}
                >
                  {t}
