          ))}
        </div>

        <div className="bg-white sketch-border p-8">
          <div className="flex justify-between items-center mb-8">
            <div className="flex items-center gap-4">
              <h3 className="text-lg font-black uppercase tracking-tighter">Performance {selectedAsset}</h3>
              <div className="bg-[#F2EFEA] px-3 py-1 text-[9px] font-black uppercase">{timeframe} Interval</div>
            </div>
            <div className="flex items-center gap-6">
              <label className="flex items-center gap-2 cursor-pointer group">
                <input 
                  type="checkbox" 
