import React, { useState, useEffect, useRef } from 'react';
import { Document, DocumentSource } from '../types';
import { StorageService } from '../services/storage';

const DocumentManager: React.FC = () => {
  const [documents, setDocuments] = useState<Document[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [activeTab, setActiveTab] = useState<'local' | 'cloud'>('local');
  const [parsingStatus, setParsingStatus] = useState<string>('');
  const [searchTerm, setSearchTerm] = useState('');
  const [externalUrl, setExternalUrl] = useState('');
  const [selectedProvider, setSelectedProvider] = useState<DocumentSource>('google_docs');

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    setDocuments(StorageService.getDocuments());
  }, []);

  const handleFiles = async (files: FileList) => {
    setIsUploading(true);
    const newDocs: Document[] = [];

    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      setParsingStatus(`Processando ${file.name}...`);

      try {
        const content = await extractContent(file);
        const doc: Document = {
          id: Math.random().toString(36).substr(2, 9),
          name: file.name,
          content: content,
          type: file.type || 'application/octet-stream',
          uploadDate: new Date(),
          size: file.size,
          sourceType: 'local'
        };
        StorageService.saveDocument(doc);
        newDocs.push(doc);
      } catch (err) {
        alert(`Falha ao processar ${file.name}`);
      }
    }

    setDocuments(prev => [...newDocs, ...prev]);
    setIsUploading(false);
    setParsingStatus('');
  };

  const handleAddExternal = async () => {
    if (!externalUrl) return;
    setIsUploading(true);
    setParsingStatus('Sincronizando com Google Cloud...');

    // Lógica para transformar URLs do Google em links de exportação
    let processedUrl = externalUrl;
    let name = "Novo Conector";

    if (selectedProvider === 'google_docs') {
      name = "Google Doc Imported";
      // Simulação de fetch de conteúdo via export link (txt)
    } else if (selectedProvider === 'google_sheets') {
      name = "Google Sheet Data";
      // Simulação de fetch via export link (csv)
    }

    const doc: Document = {
      id: Math.random().toString(36).substr(2, 9),
      name: name,
      content: `[DATA_LINK: ${externalUrl}]\nConteúdo sincronizado via ${selectedProvider.replace('_', ' ').toUpperCase()}. Dados carregados em tempo real pelo FinanGPT Engine.`,
      type: 'external/link',
      uploadDate: new Date(),
      size: 0,
      sourceType: selectedProvider,
      externalUrl: externalUrl
    };

    StorageService.saveDocument(doc);
    setDocuments(prev => [doc, ...prev]);
    setExternalUrl('');
    setIsUploading(false);
    setParsingStatus('');
  };

  const extractContent = async (file: File): Promise<string> => {
    // Reutilizando lógica de extração existente...
    return new Promise((resolve) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result as string);
      reader.readAsText(file);
    });
  };

  const exportToNotebookLM = () => {
    const fullContent = documents
      .map(d => `SOURCE: ${d.name}\nTYPE: ${d.sourceType}\nCONTENT:\n${d.content}\n---\n`)
      .join('\n');

    const blob = new Blob([fullContent], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `FinanGPT_NotebookLM_Bundle_${new Date().toISOString().split('T')[0]}.txt`;
    a.click();
  };

  const filteredDocuments = documents.filter(doc => 
    doc.name.toUpperCase().includes(searchTerm.toUpperCase()) || 
    doc.content.toUpperCase().includes(searchTerm.toUpperCase())
  );

  return (
    <div className="p-10 max-w-6xl mx-auto">
