import { GoogleGenAI } from "@google/genai";
import { StorageService } from "./storage";

export const GeminiService = {
  generateChatResponse: async (prompt: string, history: any[]) => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const docs = StorageService.getDocuments();
    const context = docs.length > 0 
      ? `BASE DE CONHECIMENTO INTEGRADA (GOOGLE + LOCAL):\n${docs.map(d => `[PROVEDOR: ${d.sourceType.toUpperCase()}] [ARQUIVO: ${d.name}]\nCONTEÚDO: ${d.content}`).join('\n\n')}`
      : "O usuário ainda não conectou documentos ou serviços Google.";

    const systemInstruction = `
      Você é o "FinanGPT", uma IA de elite especializada em Finanças, Contabilidade e Análise de Dados Digitais.

      CAPACIDADES DE INTEGRAÇÃO:
      1. GOOGLE DOCS/SHEETS: Você tem acesso a dados sincronizados de planilhas e documentos. Analise tendências em tabelas de Sheets como se fossem bancos de dados vivos.
      2. GOOGLE ANALYTICS: Se houver dados de analytics no contexto, ajude o usuário a calcular ROI de campanhas, taxa de conversão e comportamento de usuários para previsões financeiras.
      3. NOTEBOOKLM SYNC: Você foi treinado para organizar respostas que podem ser facilmente importadas como "fontes" no NotebookLM do Google.

      SUAS TAREFAS:
      - Cruze dados contábeis (DRE/Balanço) com métricas de tráfego do Analytics quando solicitado.
      - Para Google Sheets, identifique anomalias em lançamentos financeiros.
      - Use o Google Search para validar cotações de mercado que impactam os documentos internos.

      CONTEXTO RAG DISPONÍVEL:
      ${context}
    `;

    const formattedHistory = history
      .filter(msg => msg.id !== 'welcome' && msg.id !== 'reset') 
      .map(msg => ({
        role: msg.role === 'user' ? 'user' : 'model',
        parts: [{ text: msg.content }]
      }));

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [
          ...formattedHistory,
          { role: 'user', parts: [{ text: prompt }] }
        ],
        config: {
          systemInstruction,
          tools: [{ googleSearch: {} }]
        },
      });

      return {
        text: response.text || "Erro no processamento.",
        groundingMetadata: response.candidates?.[0]?.groundingMetadata
      };
    } catch (error) {
      console.error("Gemini Error:", error);
      throw error;
    }
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { MarketService, MarketRates, StockInfo } from '../services/marketService';
import { Candle } from '../types';
import { StorageService } from '../services/storage';

const Dashboard: React.FC = () => {
  const [rates, setRates] = useState<MarketRates | null>(null);
  const [stocks, setStocks] = useState<StockInfo[]>([]);
  const [candles, setCandles] = useState<Candle[]>([]);
  const [selectedAsset, setSelectedAsset] = useState('BTC');
  const [timeframe, setTimeframe] = useState('1h');
  const [hoveredCandle, setHoveredCandle] = useState<Candle | null>(null);
  const [loadingMarket, setLoadingMarket] = useState(true);
  const [showSMA, setShowSMA] = useState(false);
  const [connectedServices, setConnectedServices] = useState<string[]>([]);

  useEffect(() => {
    const docs = StorageService.getDocuments();
    const services = Array.from(new Set(docs.map(d => d.sourceType))).filter(s => s !== 'local');
    setConnectedServices(services);

    const loadMarketData = async () => {
      setLoadingMarket(true);
      try {
        const rateData = await MarketService.fetchExchangeRates();
        const [stockData, candleData] = await Promise.all([
          MarketService.fetchStockData(rateData),
          MarketService.fetchHistoricalCandles(selectedAsset, timeframe)
        ]);
        setRates(rateData);
        setStocks(stockData);
        setCandles(candleData);
      } catch (e) {
        console.error("Error updating dashboard data", e);
      } finally {
        setLoadingMarket(false);
      }
    };

    loadMarketData();
    const interval = setInterval(loadMarketData, timeframe === '1m' ? 5000 : 30000); 
    return () => clearInterval(interval);
  }, [selectedAsset, timeframe]);

  const stats = [
    { label: 'RECEITA ESTIMADA', value: 'R$ 45.230', trend: '+12%', isPositive: true },
    { label: 'OPEX ATUAL', value: 'R$ 21.050', trend: '-2%', isPositive: true },
    { label: 'LUCRO PROJETADO', value: 'R$ 24.180', trend: '+18%', isPositive: true },
    { label: 'RISCO CAMBIAL', value: 'BAIXO', trend: 'STABLE', isPositive: true },
  ];

  const chartMetrics = useMemo(() => {
    if (candles.length === 0) return null;
    const lows = candles.map(c => c.low);
    const highs = candles.map(c => c.high);
    const minLow = Math.min(...lows);
    const maxHigh = Math.max(...highs);
    const range = maxHigh - minLow;
    const sma = candles.map((_, i) => {
      if (i < 9) return null;
      const slice = candles.slice(i - 9, i + 1);
      const sum = slice.reduce((acc, curr) => acc + curr.close, 0);
      return sum / 10;
    });
    return { minLow, maxHigh, range, sma, estimatedSupport: minLow, estimatedResistance: maxHigh };
  }, [candles]);

  const renderCandleChart = () => {
    if (!chartMetrics || candles.length === 0) return (
      <div className="h-[350px] flex flex-col items-center justify-center gap-4 bg-[#F9F9F9] sketch-border">
        <div className="w-8 h-8 border-4 border-[#1A1A1A] border-t-transparent rounded-full animate-spin"></div>
        <span className="text-[10px] font-black uppercase tracking-widest text-[#7A7A7A]">Sincronizando Ordens...</span>
      </div>
    );

    const width = 1000;
    const height = 350;
    const padding = 40;
    const candleSpace = (width - padding * 2) / candles.length;
    const candleWidth = candleSpace * 0.7;
    const getY = (price: number) => height - padding - ((price - chartMetrics.minLow) / chartMetrics.range) * (height - padding * 2);

    return (
      <div className="relative group cursor-crosshair select-none bg-white p-2">
        <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-[350px] overflow-visible" preserveAspectRatio="none">
          {[0, 0.25, 0.5, 0.75, 1].map((p, i) => {
            const y = padding + p * (height - padding * 2);
            const price = chartMetrics.maxHigh - p * chartMetrics.range;
            return (
              <g key={i}>
                <line x1={padding} y1={y} x2={width - padding} y2={y} stroke="#F2F2F2" strokeWidth="1" />
                <text x={width - padding + 5} y={y + 4} className="text-[9px] fill-[#B5B5B5] font-bold font-mono">
                  {price.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL', minimumFractionDigits: 0 })}
                </text>
              </g>
            );
          })}
          {candles.map((candle, i) => {
            const x = padding + i * candleSpace;
            const openY = getY(candle.open);
            const closeY = getY(candle.close);
            const highY = getY(candle.high);
            const lowY = getY(candle.low);
            const isBullish = candle.close >= candle.open;
            const color = isBullish ? '#10B981' : '#EF4444';
            return (
              <g key={i} onMouseEnter={() => setHoveredCandle(candle)} onMouseLeave={() => setHoveredCandle(null)}>
                <line x1={x + candleSpace/2} y1={highY} x2={x + candleSpace/2} y2={lowY} stroke={color} strokeWidth="1.5" />
                <rect x={x + (candleSpace - candleWidth)/2} y={Math.min(openY, closeY)} width={candleWidth} height={Math.max(1.5, Math.abs(openY - closeY))} fill={color}/>
                <rect x={x} y={0} width={candleSpace} height={height} fill="transparent" />
              </g>
            );
          })}
        </svg>
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full bg-[#F2EFEA] overflow-hidden">
      {/* Ticker Tape */}
      <div className="bg-[#1A1A1A] h-10 flex items-center overflow-hidden border-b-2 border-[#1A1A1A] relative">
        <div className="flex animate-[ticker_60s_linear_infinite] whitespace-nowrap gap-12 px-4 items-center">
          {stocks.map((stock, i) => (
            <div key={i} className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-white">
              <span>{stock.symbol}</span>
              <span className="text-gray-400 font-mono">{stock.price}</span>
              <span className={stock.isPositive ? 'text-emerald-400' : 'text-rose-400'}>{stock.change}</span>
            </div>
          ))}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-8 space-y-8">
        <header className="flex justify-between items-end border-b-2 border-[#1A1A1A] pb-8">
          <div>
            <h1 className="text-4xl font-black text-[#1A1A1A] tracking-tighter uppercase leading-none">TERMINAL ANALÍTICO</h1>
            <div className="flex gap-6 mt-4 items-center">
              <div className="flex items-center gap-2">
                <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></div>
                <span className="text-[10px] font-black uppercase tracking-widest text-[#7A7A7A]">Live Feed</span>
              </div>
              <div className="flex gap-2">
                {connectedServices.map(s => (
                  <span key={s} className="bg-[#4285F4] text-white text-[8px] font-black px-2 py-0.5 uppercase tracking-widest">
                    {s.replace('_', ' ')} ACTIVE
                  </span>
                ))}
                {connectedServices.length === 0 && (
                  <span className="border border-[#B5B5B5] text-[#B5B5B5] text-[8px] font-black px-2 py-0.5 uppercase tracking-widest">
                    NO CLOUD SOURCE
                  </span>
                )}
              </div>
            </div>
          </div>

          <div className="flex gap-4">
            <select value={selectedAsset} onChange={(e) => setSelectedAsset(e.target.value)} className="bg-white sketch-border px-4 py-2 font-black text-[10px] uppercase outline-none">
              {stocks.map(s => <option key={s.symbol} value={s.symbol}>{s.symbol}</option>)}
            </select>
          </div>
        </header>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          {stats.map((stat, i) => (
            <div key={i} className="bg-white sketch-border p-6 hover:translate-y-[-4px] transition-all">
              <p className="text-[10px] font-black text-[#7A7A7A] uppercase tracking-[0.2em] mb-4">{stat.label}</p>
              <div className="flex justify-between items-end">
                <span className="text-2xl font-black text-[#1A1A1A] tracking-tighter">{stat.value}</span>
                <span className={`text-[10px] font-bold px-2 py-0.5 border-2 border-[#1A1A1A] ${stat.isPositive ? 'bg-emerald-100 text-emerald-800' : 'bg-rose-100 text-rose-800'}`}>
                  {stat.trend}
                </span>
              </div>
            </div>
          ))}
        </div>

        <div className="bg-white sketch-border p-8">
          <div className="flex justify-between items-center mb-8">
            <h3 className="text-lg font-black uppercase tracking-tighter">Performance {selectedAsset}</h3>
            <div className="flex gap-2">
              <button onClick={() => setShowSMA(!showSMA)} className={`text-[10px] font-black uppercase px-4 py-1 border-2 border-[#1A1A1A] ${showSMA ? 'bg-[#1A1A1A] text-white' : 'bg-white'}`}>SMA(10)</button>
            </div>
          </div>
          {renderCandleChart()}

          <div className="mt-8 grid grid-cols-1 md:grid-cols-3 gap-8 pt-8 border-t border-[#F2F2F2]">
             <div className="md:col-span-3 bg-[#1A1A1A] text-white p-6 sketch-border shadow-none">
              <div className="flex items-center gap-4 mb-4">
                <div className="w-8 h-8 border-2 border-white flex items-center justify-center font-bold text-xs italic">AI</div>
                <h4 className="text-[10px] font-black uppercase tracking-widest">Análise Preditiva FinanGPT</h4>
              </div>
              <p className="text-[11px] font-medium leading-relaxed uppercase tracking-tight text-gray-300">
                {connectedServices.includes('google_analytics') 
                  ? "Sincronização com Analytics detectada. Tendência de conversão alinhada com projeção de receita. Picos de tráfego coincidem com volatilidade do ativo selecionado."
                  : "Monitorando dados de mercado. Para análises de correlação com seu negócio, conecte Google Analytics ou Planilhas de Vendas no Gerenciador de Documentos."
                }
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

