      3. CONTABILIDADE GERENCIAL: Análise de demonstrações financeiras (Vertical e Horizontal), EBITDA (Lajida), ROI, ROE, WACC e Fluxo de Caixa Descontado (DCF). Análise de solvência e liquidez.

      MÓDULO EDUCACIONAL E CORREÇÃO DE EXERCÍCIOS:
      - Atue como um professor universitário rigoroso, porém didático.
      - Ao receber uma resposta de exercício de um estudante:
        1. Valide cada passo do cálculo.
        2. Se houver erro, identifique se foi erro de CLASSIFICAÇÃO (ex: confundir custo com despesa) ou erro ARITMÉTICO.
        3. Forneça o gabarito detalhado em tabelas Markdown.
        4. Atribua uma nota de 0 a 10 baseada na precisão técnica.
      - SEMPRE use tabelas Markdown para DRE, Balanço Patrimonial e Mapas de Custos.

      CONEXÃO COM GOOGLE WORKSPACE:
      - Interprete dados de links do Google Docs como manuais de normas.
      - Interprete dados do Google Sheets como bancos de dados de lançamentos.
      - Interprete Google Analytics para calcular ROI de marketing e CAC.
      - Suas respostas devem ser otimizadas para serem salvas como "Fontes" no NotebookLM.

      CONTEXTO RAG DISPONÍVEL:
      ${context}
    `;

    const formattedHistory = history
      .filter(msg => msg.id !== 'welcome' && msg.id !== 'reset') 
      .map(msg => ({
        role: msg.role === 'user' ? 'user' : 'model',
        parts: [{ text: msg.content }]
      }));

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [
          ...formattedHistory,
          { role: 'user', parts: [{ text: prompt }] }
        ],
        config: {
          systemInstruction,
          tools: [{ googleSearch: {} }]
        },
      });

      return {
        text: response.text || "Erro no processamento da IA.",
        groundingMetadata: response.candidates?.[0]?.groundingMetadata
      };
    } catch (error) {
      console.error("Gemini Error:", error);
      throw error;
    }
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { Document, DocumentSource } from '../types';
import { StorageService } from '../services/storage';

const DocumentManager: React.FC = () => {
  const [documents, setDocuments] = useState<Document[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [activeTab, setActiveTab] = useState<'local' | 'cloud'>('local');
  const [parsingStatus, setParsingStatus] = useState<string>('');
  const [searchTerm, setSearchTerm] = useState('');
  const [externalUrl, setExternalUrl] = useState('');
  const [selectedProvider, setSelectedProvider] = useState<DocumentSource>('google_docs');
  const [selectedCategory, setSelectedCategory] = useState<'cost' | 'tax' | 'management' | 'general' | 'exercise'>('general');

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    setDocuments(StorageService.getDocuments());
  }, []);

  const handleFiles = async (files: FileList) => {
    setIsUploading(true);
    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      setParsingStatus(`Processando ${file.name}...`);

      const reader = new FileReader();
      reader.onload = (e) => {
        const content = e.target?.result as string;
        const doc: Document = {
          id: Math.random().toString(36).substr(2, 9),
          name: file.name,
          content,
          type: file.type,
          uploadDate: new Date(),
          size: file.size,
          sourceType: 'local',
          metadata: {
            category: selectedCategory,
            lastSync: new Date()
          }
        };
        StorageService.saveDocument(doc);
        setDocuments(prev => [doc, ...prev]);
      };
      reader.readAsText(file);
    }
    setIsUploading(false);
    setParsingStatus('');
  };

  const handleAddExternal = async () => {
    if (!externalUrl) return;
    setIsUploading(true);
    setParsingStatus('Sincronizando com Google Cloud API...');

    // Simulador de dados externos para o contexto RAG
    let content = "";
    let name = "";

    switch(selectedProvider) {
      case 'google_docs':
        name = `Manual: ${externalUrl.split('/').pop()?.substring(0, 15) || 'Google Doc'}`;
        content = `[CONTEÚDO_SINC_GOOGLE_DOCS]\nReferência: ${externalUrl}\nCategoria: ${selectedCategory}\nEste documento contém normas contábeis extraídas via Google Docs API.`;
        break;
      case 'google_sheets':
        name = `Planilha: Lançamentos Financeiros`;
        content = `[CONTEÚDO_SINC_GOOGLE_SHEETS]\nID: ${externalUrl}\nEstrutura: CSV\nLançamentos de ${selectedCategory.toUpperCase()} sincronizados em tempo real.`;
        break;
      case 'google_analytics':
        name = `GA4: Propriedade ${externalUrl}`;
        content = `[CONTEÚDO_SINC_GOOGLE_ANALYTICS]\nID: ${externalUrl}\nMétricas de tráfego para análise de ROI e previsões orçamentárias.`;
        break;
    }

    const doc: Document = {
      id: Math.random().toString(36).substr(2, 9),
      name: name,
      content: content,
      type: 'external/link',
      uploadDate: new Date(),
      size: 0,
      sourceType: selectedProvider,
      externalUrl: externalUrl,
      metadata: {
        category: selectedCategory,
        lastSync: new Date()
      }
    };

    StorageService.saveDocument(doc);
    setDocuments(prev => [doc, ...prev]);
    setExternalUrl('');
    setIsUploading(false);
    setParsingStatus('');
  };

  const exportToNotebookLM = () => {
    const bundle = documents.map(d => (
      `========================================\n` +
      `FONTE: ${d.name}\n` +
      `ORIGEM: ${d.sourceType.toUpperCase()}\n` +
      `CATEGORIA: ${d.metadata?.category?.toUpperCase() || 'GERAL'}\n` +
      `DATA: ${d.uploadDate.toISOString()}\n` +
      `----------------------------------------\n` +
      `${d.content}\n` +
      `========================================\n\n`
    )).join('');

    const blob = new Blob([bundle], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = window.document.createElement('a');
    a.href = url;
    a.download = `FinanGPT_NotebookLM_Source_Bundle_${new Date().toISOString().split('T')[0]}.txt`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const deleteDoc = (id: string) => {
    StorageService.deleteDocument(id);
    setDocuments(prev => prev.filter(d => d.id !== id));
  };

  const filteredDocs = documents.filter(d => 
    d.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    d.metadata?.category?.includes(searchTerm.toLowerCase())
  );

