          <button 
            onClick={() => setActiveTab('local')}
            className={`flex-1 px-4 py-3 font-black text-[10px] uppercase border-2 border-[#1A1A1A] transition-all ${activeTab === 'local' ? 'bg-[#1A1A1A] text-white' : 'bg-white text-[#1A1A1A]'}`}
          >
            Arquivos Locais
          </button>
          <button 
            onClick={() => setActiveTab('cloud')}
            className={`flex-1 px-4 py-3 font-black text-[10px] uppercase border-2 border-[#1A1A1A] transition-all ${activeTab === 'cloud' ? 'bg-[#4285F4] text-white border-[#4285F4]' : 'bg-white text-[#1A1A1A]'}`}
          >
