        </div>
      </div>

      {activeTab === 'cloud' && (
        <div className="bg-white sketch-border p-8 mb-12 animate-in fade-in slide-in-from-top-4 duration-300">
          <div className="flex items-center gap-4 mb-6 border-b border-gray-100 pb-4">
