import React, { useState, useEffect, useRef } from 'react';
import { Document, DocumentSource } from '../types';
import { StorageService } from '../services/storage';

const DocumentManager: React.FC = () => {
  const [documents, setDocuments] = useState<Document[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [activeTab, setActiveTab] = useState<'local' | 'cloud'>('local');
  const [parsingStatus, setParsingStatus] = useState<string>('');
  const [searchTerm, setSearchTerm] = useState('');
  const [externalUrl, setExternalUrl] = useState('');
  const [selectedProvider, setSelectedProvider] = useState<DocumentSource>('google_docs');
  const [selectedCategory, setSelectedCategory] = useState<'cost' | 'tax' | 'management' | 'general' | 'exercise'>('general');

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    setDocuments(StorageService.getDocuments());
  }, []);

  const handleFiles = async (files: FileList) => {
    setIsUploading(true);
    const filesArray = Array.from(files);

    const uploadPromises = filesArray.map((file) => {
      return new Promise<Document>((resolve) => {
        setParsingStatus(`Processando ${file.name}...`);
        const reader = new FileReader();
        reader.onload = (e) => {
          const content = e.target?.result as string;
          const doc: Document = {
            id: Math.random().toString(36).substr(2, 9),
            name: file.name,
            content,
            type: file.type || 'text/plain',
            uploadDate: new Date(),
            size: file.size,
            sourceType: 'local',
            metadata: {
              category: selectedCategory,
              lastSync: new Date()
            }
          };
          StorageService.saveDocument(doc);
          resolve(doc);
        };
        reader.readAsText(file);
      });
    });

    const newDocs = await Promise.all(uploadPromises);
    setDocuments(prev => [...newDocs, ...prev]);
    setIsUploading(false);
    setParsingStatus('');
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleAddExternal = async () => {
    if (!externalUrl) return;
    setIsUploading(true);
    setParsingStatus('Sincronizando com Google Workspace API...');

    // Simulador de integração Cloud
    let content = "";
    let name = "";

    switch(selectedProvider) {
      case 'google_docs':
        name = `Doc: ${externalUrl.split('/').pop()?.substring(0, 15) || 'Google Doc'}`;
        content = `[CLOUD_DOC]\nURL: ${externalUrl}\nCategoria: ${selectedCategory}\nSincronizado via Google Docs API.`;
        break;
      case 'google_sheets':
        name = `Sheet: Dados Financeiros`;
        content = `[CLOUD_SHEET]\nID: ${externalUrl}\nCategoria: ${selectedCategory}\nDados de planilhas sincronizados em tempo real.`;
        break;
      case 'google_analytics':
        name = `GA4: Property ID ${externalUrl}`;
        content = `[CLOUD_ANALYTICS]\nID: ${externalUrl}\nMétricas de ROI e Tráfego para análise financeira.`;
        break;
      default:
        name = "Conector Externo";
        content = "Conteúdo não especificado.";
    }

    const doc: Document = {
      id: Math.random().toString(36).substr(2, 9),
      name: name,
      content: content,
      type: 'external/link',
      uploadDate: new Date(),
      size: 0,
      sourceType: selectedProvider,
      externalUrl: externalUrl,
      metadata: {
        category: selectedCategory,
        lastSync: new Date()
      }
    };

    StorageService.saveDocument(doc);
    setDocuments(prev => [doc, ...prev]);
    setExternalUrl('');
    setIsUploading(false);
    setParsingStatus('');
  };

  const exportToNotebookLM = () => {
    const bundle = documents.map(d => (
      `========================================\n` +
      `FONTE: ${d.name}\n` +
      `ORIGEM: ${d.sourceType.toUpperCase()}\n` +
      `CATEGORIA: ${d.metadata?.category?.toUpperCase() || 'GERAL'}\n` +
      `----------------------------------------\n` +
      `${d.content}\n` +
      `========================================\n\n`
    )).join('');

    const blob = new Blob([bundle], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = window.document.createElement('a');
    a.href = url;
    a.download = `FinanGPT_RAG_Bundle_${new Date().toISOString().split('T')[0]}.txt`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const deleteDoc = (id: string) => {
    if (window.confirm("Remover este documento da base de conhecimento?")) {
      StorageService.deleteDocument(id);
      setDocuments(prev => prev.filter(d => d.id !== id));
    }
  };

  const filteredDocs = documents.filter(d => 
    d.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    d.metadata?.category?.includes(searchTerm.toLowerCase())
  );

  return (
    <div className="p-10 max-w-6xl mx-auto">
      <header className="flex flex-col md:flex-row justify-between items-start md:items-center mb-12 border-b-2 border-[#1A1A1A] pb-8 gap-6">
        <div>
          <h1 className="text-3xl font-bold text-[#1A1A1A] uppercase tracking-tighter leading-none">BASE DE DADOS RAG</h1>
          <p className="text-[#7A7A7A] mt-2 font-bold text-xs uppercase tracking-widest">Contabilidade • Google Workspace • Analytics</p>
        </div>
        <div className="flex gap-4">
          <button 
            onClick={exportToNotebookLM}
            className="border-2 border-[#1A1A1A] bg-[#1A1A1A] text-white font-bold py-3 px-6 uppercase tracking-widest text-[9px] flex items-center gap-2 hover:bg-[#4A4A4A] transition-all"
          >
            Exportar p/ NotebookLM
          </button>
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="sketch-button font-bold py-3 px-6 uppercase tracking-widest text-[9px]"
          >
            + Upload Local
          </button>
        </div>
      </header>

      <input ref={fileInputRef} type="file" multiple className="hidden" onChange={(e) => e.target.files && handleFiles(e.target.files)} />

      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-8">
        <div className="md:col-span-1">
          <label className="text-[8px] font-black text-[#7A7A7A] uppercase mb-2 block">Vincular a Categoria</label>
          <select 
            value={selectedCategory}
            onChange={(e) => setSelectedCategory(e.target.value as any)}
            className="w-full bg-white border-2 border-[#1A1A1A] p-3 text-[10px] font-bold uppercase outline-none"
          >
            <option value="general">Geral / Normas</option>
            <option value="cost">Custos / DRE</option>
            <option value="tax">Fiscal / Tributário</option>
            <option value="management">Gerencial / KPIs</option>
            <option value="exercise">Exercícios / Alunos</option>
          </select>
        </div>
        <div className="md:col-span-3 flex gap-1 items-end">
          <button 
            onClick={() => setActiveTab('local')}
            className={`flex-1 px-4 py-3 font-black text-[10px] uppercase border-2 border-[#1A1A1A] transition-all ${activeTab === 'local' ? 'bg-[#1A1A1A] text-white' : 'bg-white text-[#1A1A1A]'}`}
          >
            Arquivos Locais
          </button>
          <button 
            onClick={() => setActiveTab('cloud')}
            className={`flex-1 px-4 py-3 font-black text-[10px] uppercase border-2 border-[#1A1A1A] transition-all ${activeTab === 'cloud' ? 'bg-[#4285F4] text-white border-[#4285F4]' : 'bg-white text-[#1A1A1A]'}`}
          >
            Google Cloud Sync
          </button>
        </div>
      </div>

      {activeTab === 'cloud' && (
        <div className="bg-white sketch-border p-8 mb-12 animate-in fade-in slide-in-from-top-4">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div>
              <label className="text-[9px] font-black text-[#7A7A7A] uppercase block mb-2">Provedor</label>
              <select 
                value={selectedProvider}
                onChange={(e) => setSelectedProvider(e.target.value as DocumentSource)}
                className="w-full bg-[#F2EFEA] border-2 border-[#1A1A1A] p-3 text-xs font-bold uppercase outline-none"
              >
                <option value="google_docs">Google Docs</option>
                <option value="google_sheets">Google Sheets</option>
                <option value="google_analytics">Google Analytics</option>
              </select>
            </div>
            <div>
              <label className="text-[9px] font-black text-[#7A7A7A] uppercase block mb-2">URL / ID da Propriedade</label>
              <input 
                type="text"
                value={externalUrl}
                onChange={(e) => setExternalUrl(e.target.value)}
                placeholder="https://..."
                className="w-full bg-white border-2 border-[#1A1A1A] p-3 text-xs font-bold outline-none placeholder-[#B5B5B5]"
              />
            </div>
            <div className="flex items-end">
              <button 
                onClick={handleAddExternal}
                disabled={isUploading}
                className="w-full sketch-button py-3 font-black text-[10px] uppercase disabled:opacity-50"
              >
                {isUploading ? 'CONECTANDO...' : 'Sincronizar Canal'}
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="bg-white sketch-border overflow-hidden">
        <div className="p-4 bg-[#1A1A1A] flex justify-between items-center">
          <input 
            type="text"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="PESQUISAR NA BASE..."
            className="bg-transparent border-b border-[#4A4A4A] text-white text-[10px] uppercase font-bold outline-none w-64 placeholder-gray-500"
          />
          <span className="text-[9px] font-bold text-gray-400 uppercase tracking-widest">{documents.length} ATIVOS</span>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead className="bg-[#F2EFEA] text-[9px] font-black uppercase tracking-widest text-[#7A7A7A]">
              <tr>
                <th className="px-8 py-4 border-b-2 border-[#1A1A1A]">ORIGEM</th>
                <th className="px-8 py-4 border-b-2 border-[#1A1A1A]">CATEGORIA</th>
                <th className="px-8 py-4 border-b-2 border-[#1A1A1A]">NOME / ENDEREÇO</th>
                <th className="px-8 py-4 border-b-2 border-[#1A1A1A] text-center">AÇÃO</th>
