import { Document, User, ChatSession } from '../types';

const DOCS_KEY = 'finan_gpt_docs';
const USER_KEY = 'finan_gpt_user';
const CHATS_KEY = 'finan_gpt_chats';

export const StorageService = {
  // Documentos
  getDocuments: (): Document[] => {
    const data = localStorage.getItem(DOCS_KEY);
    return data ? JSON.parse(data) : [];
  },

  saveDocument: (doc: Document) => {
    const docs = StorageService.getDocuments();
    docs.push(doc);
    localStorage.setItem(DOCS_KEY, JSON.stringify(docs));
  },

  deleteDocument: (id: string) => {
    const docs = StorageService.getDocuments().filter(d => d.id !== id);
    localStorage.setItem(DOCS_KEY, JSON.stringify(docs));
  },

  // Usuário
  getUser: (): User | null => {
    const data = localStorage.getItem(USER_KEY);
    return data ? JSON.parse(data) : null;
  },

  setUser: (user: User) => {
    localStorage.setItem(USER_KEY, JSON.stringify(user));
  },

  // Sessões de Chat & Lixeira
  getChatSessions: (includeDeleted = false): ChatSession[] => {
    const data = localStorage.getItem(CHATS_KEY);
    if (!data) return [];

    const sessions: ChatSession[] = JSON.parse(data).map((s: any) => ({
      ...s,
      lastUpdate: new Date(s.lastUpdate),
      deletedAt: s.deletedAt ? new Date(s.deletedAt) : undefined,
      messages: s.messages.map((m: any) => ({ ...m, timestamp: new Date(m.timestamp) }))
    }));

    // Auto-limpeza: Remove chats deletados há mais de 30 dias
    const now = new Date();
    const cleanSessions = sessions.filter(s => {
      if (!s.deletedAt) return true;
      const diffTime = Math.abs(now.getTime() - s.deletedAt.getTime());
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      return diffDays <= 30;
    });

    if (cleanSessions.length !== sessions.length) {
      localStorage.setItem(CHATS_KEY, JSON.stringify(cleanSessions));
    }

    // Correção: includeDeleted deve significar "incluir os deletados na lista", não "retornar apenas os deletados"
    return includeDeleted 
      ? cleanSessions
      : cleanSessions.filter(s => !s.deletedAt);
  },

  saveChatSession: (session: ChatSession) => {
    const sessions = StorageService.getChatSessions(true);
    const index = sessions.findIndex(s => s.id === session.id);
    if (index >= 0) {
      sessions[index] = session;
    } else {
      sessions.push(session);
    }
    localStorage.setItem(CHATS_KEY, JSON.stringify(sessions));
  },

  moveToTrash: (id: string) => {
    const sessions = StorageService.getChatSessions(true);
    const index = sessions.findIndex(s => s.id === id);
    if (index >= 0) {
      sessions[index].deletedAt = new Date();
      localStorage.setItem(CHATS_KEY, JSON.stringify(sessions));
    }
  },

  restoreFromTrash: (id: string) => {
    const sessions = StorageService.getChatSessions(true);
    const index = sessions.findIndex(s => s.id === id);
    if (index >= 0) {
      sessions[index].deletedAt = undefined;
      localStorage.setItem(CHATS_KEY, JSON.stringify(sessions));
    }
  },

  deletePermanently: (id: string) => {
    const sessions = StorageService.getChatSessions(true).filter(s => s.id !== id);
    localStorage.setItem(CHATS_KEY, JSON.stringify(sessions));
  },

  clearAll: () => {
    localStorage.removeItem(DOCS_KEY);
    localStorage.removeItem(USER_KEY);
    localStorage.removeItem(CHATS_KEY);
  }
};

import React, { useState, useEffect } from 'react';
import { ChatSession } from '../types';
import { StorageService } from '../services/storage';

const TrashBin: React.FC = () => {
  const [deletedSessions, setDeletedSessions] = useState<ChatSession[]>([]);

  useEffect(() => {
    // Filtrando apenas os que possuem data de exclusão
    const allSessions = StorageService.getChatSessions(true);
    setDeletedSessions(allSessions.filter(s => !!s.deletedAt));
  }, []);

  const handleRestore = (id: string) => {
    StorageService.restoreFromTrash(id);
    setDeletedSessions(prev => prev.filter(s => s.id !== id));
  };

  const handlePermanentDelete = (id: string) => {
    if (window.confirm("Tem certeza que deseja excluir permanentemente este chat? Esta ação não pode ser desfeita.")) {
      StorageService.deletePermanently(id);
      setDeletedSessions(prev => prev.filter(s => s.id !== id));
    }
  };

  const getDaysLeft = (deletedAt?: Date) => {
    if (!deletedAt) return 0;
    const now = new Date();
    const diffTime = Math.abs(now.getTime() - deletedAt.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return Math.max(0, 30 - diffDays);
  };

  return (
    <div className="p-10 max-w-6xl mx-auto">
      <header className="mb-12 border-b-2 border-[#1A1A1A] pb-8">
        <h1 className="text-3xl font-bold text-[#1A1A1A] uppercase tracking-tighter">LIXEIRA DE CHATS</h1>
        <p className="text-[#7A7A7A] mt-2 font-bold text-xs uppercase tracking-widest">Recuperação de Conversas • Expiração em 30 Dias</p>
      </header>

      {deletedSessions.length === 0 ? (
        <div className="bg-white sketch-border p-20 text-center">
          <svg className="w-16 h-16 mx-auto mb-6 text-[#B5B5B5]" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
          </svg>
          <h3 className="text-xl font-bold uppercase mb-2">Lixeira Vazia</h3>
          <p className="text-[#7A7A7A] text-[10px] font-bold uppercase tracking-widest">Nenhuma conversa deletada recentemente.</p>
        </div>
      ) : (
        <div className="space-y-6">
          <div className="flex items-center gap-4 p-4 bg-[#F2EFEA] border-2 border-[#1A1A1A] mb-8">
            <div className="w-8 h-8 bg-[#1A1A1A] text-white flex items-center justify-center font-bold">i</div>
            <p className="text-[10px] font-bold uppercase tracking-widest leading-relaxed">
              Mensagens nesta área serão excluídas permanentemente após 30 dias de sua exclusão original.
            </p>
          </div>

          <div className="grid grid-cols-1 gap-4">
            {deletedSessions.map((session) => {
              const daysLeft = getDaysLeft(session.deletedAt);
              return (
                <div key={session.id} className="bg-white p-6 sketch-border flex flex-col md:flex-row items-start md:items-center justify-between hover:bg-[#F2EFEA] transition-colors group gap-6">
                  <div className="flex items-center gap-6">
                    <div className="w-12 h-12 bg-[#B5B5B5] text-[#1A1A1A] flex items-center justify-center font-bold text-xs sketch-border shadow-none">
                      {session.messages.length}
                    </div>
                    <div>
                      <h4 className="font-bold text-[#1A1A1A] text-sm uppercase tracking-tight truncate max-w-[300px]">
                        {session.title}
                      </h4>
                      <p className="text-[#7A7A7A] text-[8px] font-bold uppercase tracking-widest mt-1">
                        Deletado em: {session.deletedAt?.toLocaleDateString()} • {daysLeft} dias restantes
                      </p>
                    </div>
                  </div>

                  <div className="flex items-center gap-4 w-full md:w-auto">
                    <button 
                      onClick={() => handleRestore(session.id)}
                      className="flex-1 md:flex-none sketch-button px-6 py-2 text-[10px] font-black uppercase tracking-widest"
                    >
                      Restaurar
                    </button>
                    <button 
                      onClick={() => handlePermanentDelete(session.id)}
                      className="flex-1 md:flex-none border-2 border-[#EF4444] text-[#EF4444] px-6 py-2 text-[10px] font-black uppercase tracking-widest hover:bg-[#EF4444] hover:text-white transition-all"
                    >
                      Excluir
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
};

