import React, { useState, useRef, useEffect } from 'react';
import { Message, ChatSession } from '../types';
import { GeminiService } from '../services/geminiService';
import { StorageService } from '../services/storage';

const ChatInterface: React.FC = () => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string>('');
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [copyStatus, setCopyStatus] = useState<string | null>(null);
  const [showHistory, setShowHistory] = useState(true);
  const scrollRef = useRef<HTMLDivElement>(null);

  const WELCOME_MESSAGE: Message = {
    id: 'welcome',
    role: 'model',
    content: '### TERMINAL FINANGPT INICIALIZADO\n\nPronto para consultoria, análise de mercado e treinamento contábil.\n\n- **Modo Educacional:** Ativo\n- **RAG Engine:** Processando documentos\n\n**Sugestões:**\n1. "Crie um exercício de DRE."\n2. "Explique o impacto da Selic no varejo."',
    timestamp: new Date()
  };

  // Carregar sessões e inicializar
  useEffect(() => {
    const activeSessions = StorageService.getChatSessions();
    setSessions(activeSessions);

    if (activeSessions.length > 0) {
      const last = activeSessions[0]; // Most recent first usually
      setCurrentSessionId(last.id);
      setMessages(last.messages);
    } else {
      createNewChat();
    }
  }, []);

  // Sincronizar mensagens com o Storage
  useEffect(() => {
    if (currentSessionId && messages.length > 0) {
      const session: ChatSession = {
        id: currentSessionId,
        title: messages.find(m => m.role === 'user')?.content.substring(0, 30) || 'Nova Conversa',
        messages,
        lastUpdate: new Date()
      };
      StorageService.saveChatSession(session);

      // Atualizar lista de sessões sem recarregar tudo
      setSessions(prev => {
        const index = prev.findIndex(s => s.id === currentSessionId);
        if (index >= 0) {
          const updated = [...prev];
          updated[index] = session;
          return updated;
        }
        return [session, ...prev];
      });
    }
  }, [messages, currentSessionId]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const createNewChat = () => {
    const newId = Date.now().toString();
    setCurrentSessionId(newId);
    setMessages([WELCOME_MESSAGE]);
  };

  const switchSession = (id: string) => {
    const session = sessions.find(s => s.id === id);
    if (session) {
      setCurrentSessionId(session.id);
      setMessages(session.messages);
    }
  };

  const handleDeleteSession = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm("Mover esta conversa para a lixeira?")) {
      StorageService.moveToTrash(id);
      const remaining = sessions.filter(s => s.id !== id);
      setSessions(remaining);
      if (currentSessionId === id) {
        if (remaining.length > 0) {
          switchSession(remaining[0].id);
        } else {
          createNewChat();
        }
      }
    }
  };

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsTyping(true);

    try {
      const response = await GeminiService.generateChatResponse(input, messages);
      const sources: string[] = [];

      if (response.groundingMetadata?.groundingChunks) {
        response.groundingMetadata.groundingChunks.forEach((chunk: any) => {
          if (chunk.web?.uri) sources.push(chunk.web.uri);
        });
      }

      const modelMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: response.text,
        timestamp: new Date(),
        sources: sources.length > 0 ? Array.from(new Set(sources)) : undefined
      };

      setMessages(prev => [...prev, modelMessage]);
    } catch (error) {
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'model',
        content: '### ERRO DE COMUNICAÇÃO\nFalha ao processar resposta.',
        timestamp: new Date()
      }]);
    } finally {
      setIsTyping(false);
    }
  };

  const renderFormattedContent = (content: string) => {
    const lines = content.split('\n');
    let elements: React.ReactNode[] = [];

    lines.forEach((line, idx) => {
      if (line.startsWith('###')) {
        elements.push(<h3 key={idx} className="text-sm font-black mt-4 mb-2 uppercase border-b border-[#1A1A1A]">{line.replace('###', '')}</h3>);
      } else if (line.trim().startsWith('- ')) {
        elements.push(<li key={idx} className="ml-4 text-xs font-medium list-disc">{line.trim().substring(2)}</li>);
      } else if (line.trim() === '') {
        elements.push(<div key={idx} className="h-2" />);
      } else {
        elements.push(<p key={idx} className="text-xs leading-relaxed mb-1">{line}</p>);
      }
    });
    return elements;
  };

  return (
    <div className="flex h-full bg-[#F2EFEA] overflow-hidden">
      {/* Sidebar de Histórico de Chats */}
      {showHistory && (
        <div className="w-72 bg-white border-r-2 border-[#1A1A1A] flex flex-col h-full animate-in slide-in-from-left duration-300">
          <div className="p-6 border-b-2 border-[#1A1A1A] flex flex-col gap-4">
            <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-[#7A7A7A]">Histórico de Threads</h3>
            <button 
              onClick={createNewChat}
              className="w-full sketch-button py-3 text-[10px] font-black uppercase tracking-widest"
            >
              + Novo Chat
            </button>
          </div>
          <div className="flex-1 overflow-y-auto p-4 space-y-3">
            {sessions.length === 0 ? (
              <p className="text-[9px] font-bold text-center text-[#B5B5B5] mt-10 uppercase">Sem conversas ativas</p>
            ) : (
              sessions.map((s) => (
                <div
                  key={s.id}
                  onClick={() => switchSession(s.id)}
                  className={`group relative p-4 sketch-border cursor-pointer transition-all ${
                    currentSessionId === s.id ? 'bg-[#1A1A1A] text-white' : 'bg-white hover:bg-[#F2EFEA]'
                  }`}
                >
                  <p className="text-[10px] font-black uppercase truncate pr-6">{s.title || 'Nova Conversa'}</p>
                  <p className={`text-[8px] font-bold mt-1 ${currentSessionId === s.id ? 'text-gray-400' : 'text-[#7A7A7A]'}`}>
                    {s.lastUpdate.toLocaleDateString()} • {s.messages.length} msg
                  </p>
                  <button 
                    onClick={(e) => handleDeleteSession(s.id, e)}
                    className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity p-1 hover:text-rose-500"
                  >
                    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
                    </svg>
                  </button>
                </div>
              ))
            )}
          </div>
        </div>
      )}

      {/* Área de Chat Principal */}
      <div className="flex-1 flex flex-col h-full relative">
        <header className="p-6 border-b-2 border-[#1A1A1A] bg-white flex justify-between items-center z-10">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => setShowHistory(!showHistory)}
              className="p-2 border-2 border-[#1A1A1A] hover:bg-[#1A1A1A] hover:text-white transition-colors"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
              </svg>
            </button>
            <div>
              <h2 className="text-xl font-black text-[#1A1A1A] uppercase tracking-tighter leading-none">
                {sessions.find(s => s.id === currentSessionId)?.title || 'NOVA CONVERSA'}
              </h2>
