              <div className={`max-w-[80%] sketch-border p-6 ${msg.role === 'user' ? 'bg-[#1A1A1A] text-white' : 'bg-white text-[#1A1A1A]'}`}>
                <div className="flex justify-between items-center mb-4 border-b border-[#B5B5B5]/30 pb-2">
                  <span className="text-[8px] font-black uppercase tracking-widest opacity-60">
                    {msg.role === 'user' ? 'USUÁRIO_REQ' : 'FINANGPT_CORE'}
                  </span>
                  <span className="text-[8px] font-bold opacity-40">{msg.timestamp.toLocaleTimeString()}</span>
                </div>
                <div className="prose-sm">{renderFormattedContent(msg.content)}</div>
                {msg.sources && (
                  <div className="mt-4 pt-2 border-t border-[#B5B5B5]/30">
                    <p className="text-[7px] font-black uppercase text-[#7A7A7A] mb-1">Fontes:</p>
