import React, { useState, useRef, useEffect } from 'react';
import { Message, ChatSession } from '../types';
import { GeminiService } from '../services/geminiService';
import { StorageService } from '../services/storage';

const ChatInterface: React.FC = () => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string>('');
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [copyStatus, setCopyStatus] = useState<string | null>(null);
  const [showHistory, setShowHistory] = useState(true);
  const scrollRef = useRef<HTMLDivElement>(null);

  const WELCOME_MESSAGE: Message = {
    id: 'welcome',
    role: 'model',
    content: '### TERMINAL FINANGPT INICIALIZADO\n\nPronto para consultoria, análise de mercado e treinamento contábil.\n\n- **Modo Educacional:** Ativo\n- **RAG Engine:** Processando documentos\n\n**Sugestões:**\n1. "Crie um exercício de DRE."\n2. "Explique o impacto da Selic no varejo."',
    timestamp: new Date()
  };

  useEffect(() => {
    const activeSessions = StorageService.getChatSessions();
    setSessions(activeSessions);

    if (activeSessions.length > 0) {
      const last = activeSessions[0];
      setCurrentSessionId(last.id);
      setMessages(last.messages);
    } else {
      createNewChat();
    }
  }, []);

  useEffect(() => {
    if (currentSessionId && messages.length > 0) {
      const currentSession = sessions.find(s => s.id === currentSessionId);
      const existingTitle = currentSession?.title;

      const needsTitle = !existingTitle || existingTitle === 'Nova Conversa' || existingTitle.length > 50;
      const fallbackTitle = messages.find(m => m.role === 'user')?.content.substring(0, 30) || 'Nova Conversa';

      const session: ChatSession = {
        id: currentSessionId,
        title: needsTitle ? fallbackTitle : existingTitle,
        messages,
        lastUpdate: new Date()
      };

      StorageService.saveChatSession(session);

      setSessions(prev => {
        const index = prev.findIndex(s => s.id === currentSessionId);
        if (index >= 0) {
          const updated = [...prev];
          updated[index] = session;
          return updated;
        }
        return [session, ...prev];
      });
    }
  }, [messages, currentSessionId]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const createNewChat = () => {
    const newId = Date.now().toString();
    setCurrentSessionId(newId);
    setMessages([WELCOME_MESSAGE]);
  };

  const switchSession = (id: string) => {
    const session = sessions.find(s => s.id === id);
    if (session) {
      setCurrentSessionId(session.id);
      setMessages(session.messages);
    }
  };

  const handleDeleteSession = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm("ATENÇÃO: Deseja excluir permanentemente este chat? Esta ação não pode ser desfeita.")) {
      StorageService.deleteChatSession(id);
      const remaining = sessions.filter(s => s.id !== id);
      setSessions(remaining);
      if (currentSessionId === id) {
        if (remaining.length > 0) {
          switchSession(remaining[0].id);
        } else {
          createNewChat();
        }
      }
    }
  };

  const handleCopy = (content: string, id: string) => {
    navigator.clipboard.writeText(content);
    setCopyStatus(id);
    setTimeout(() => setCopyStatus(null), 2000);
  };

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      timestamp: new Date()
    };

    const isFirstMessage = messages.filter(m => m.role === 'user').length === 0;

    setMessages(prev => [...prev, userMessage]);
    const currentInput = input;
    setInput('');
    setIsTyping(true);

    if (isFirstMessage) {
      GeminiService.generateTitle(currentInput).then(generatedTitle => {
        setSessions(prev => prev.map(s => 
          s.id === currentSessionId ? { ...s, title: generatedTitle } : s
        ));
      });
    }

    try {
      const response = await GeminiService.generateChatResponse(currentInput, messages);
      const sources: string[] = [];

      if (response.groundingMetadata?.groundingChunks) {
        response.groundingMetadata.groundingChunks.forEach((chunk: any) => {
          if (chunk.web?.uri) sources.push(chunk.web.uri);
          else if (chunk.maps?.uri) sources.push(chunk.maps.uri);
        });
      }

      const modelMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: response.text,
        timestamp: new Date(),
        sources: sources.length > 0 ? Array.from(new Set(sources)) : undefined
      };

      setMessages(prev => [...prev, modelMessage]);
    } catch (error) {
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'model',
        content: '### ERRO CRÍTICO\nNão foi possível processar a consulta. Verifique sua conexão ou API Key.',
        timestamp: new Date()
      }]);
    } finally {
      setIsTyping(false);
    }
  };

  const parseInlineStyles = (text: string) => {
    const parts = text.split(/(\*\*.*?\*\*|\*.*?\*)/g);
    return parts.map((part, i) => {
      if (part.startsWith('**') && part.endsWith('**')) {
        return <strong key={i} className="font-black text-[#1A1A1A]">{part.slice(2, -2)}</strong>;
      }
      if (part.startsWith('*') && part.endsWith('*')) {
        return <em key={i} className="italic font-medium">{part.slice(1, -1)}</em>;
      }
      return part;
    });
  };

  const renderFormattedContent = (content: string) => {
    const lines = content.split('\n');
    let elements: React.ReactNode[] = [];
    let currentTable: string[][] = [];

    const flushTable = (key: number) => {
      if (currentTable.length === 0) return null;

      const isSeparator = (row: string[]) => row.every(cell => cell.trim().match(/^-+$/));
      const hasHeader = currentTable.length > 1 && isSeparator(currentTable[1]);

      const headerRow = hasHeader ? currentTable[0] : null;
      const dataRows = hasHeader ? currentTable.slice(2) : currentTable;

      const tableEl = (
        <div key={`table-${key}`} className="my-6 overflow-x-auto sketch-border p-1 bg-white">
          <table className="w-full border-collapse text-[10px] text-[#1A1A1A]">
            {headerRow && (
              <thead>
                <tr className="bg-[#1A1A1A] text-white">
                  {headerRow.map((cell, i) => (
                    <th key={i} className="px-4 py-3 border-2 border-[#1A1A1A] text-left uppercase font-black tracking-widest">{cell.trim()}</th>
                  ))}
                </tr>
              </thead>
            )}
            <tbody>
              {dataRows.map((row, i) => (
                <tr key={i} className="bg-white hover:bg-[#F2EFEA] transition-colors">
                  {row.map((cell, j) => (
                    <td key={j} className="px-4 py-3 border-2 border-[#1A1A1A] font-bold uppercase">{parseInlineStyles(cell.trim())}</td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      );
      currentTable = [];
      return tableEl;
    };

    lines.forEach((line, idx) => {
      const isTableRow = line.trim().startsWith('|') && line.trim().includes('|');

      if (isTableRow) {
        const cells = line.trim().split('|').filter((_, i, arr) => i > 0 && i < arr.length - 1);
        currentTable.push(cells);
      } else {
        const table = flushTable(idx);
        if (table) elements.push(table);

        if (line.startsWith('###')) {
          elements.push(<h3 key={idx} className="text-sm font-black mt-6 mb-3 uppercase border-b-2 border-[#1A1A1A] pb-1">{line.replace('###', '')}</h3>);
        } else if (line.trim().startsWith('- ') || line.trim().startsWith('* ')) {
          elements.push(
            <li key={idx} className="ml-4 mb-2 text-[11px] font-bold uppercase tracking-tight list-none flex items-start gap-3">
              <span className="mt-1 w-1.5 h-1.5 bg-[#1A1A1A] flex-shrink-0"></span>
              <span>{parseInlineStyles(line.trim().substring(2))}</span>
            </li>
          );
        } else if (line.trim().match(/^\d+\./)) {
           elements.push(
            <li key={idx} className="ml-4 mb-2 text-[11px] font-bold uppercase tracking-tight list-none flex items-start gap-3">
              <span className="text-[#7A7A7A] font-black">{line.trim().split('.')[0]}.</span>
              <span>{parseInlineStyles(line.trim().split('.').slice(1).join('.').trim())}</span>
            </li>
          );
        } else if (line.trim() === '') {
          elements.push(<div key={idx} className="h-4" />);
        } else {
          elements.push(<p key={idx} className="text-[11px] font-medium leading-relaxed mb-3 text-[#333]">{parseInlineStyles(line)}</p>);
        }
      }
    });

    const finalTable = flushTable(lines.length);
    if (finalTable) elements.push(finalTable);

    return elements;
  };

  return (
    <div className="flex h-full bg-[#F2EFEA] overflow-hidden">
      {showHistory && (
        <div className="w-72 bg-white border-r-2 border-[#1A1A1A] flex flex-col h-full animate-in slide-in-from-left duration-300">
          <div className="p-6 border-b-2 border-[#1A1A1A] flex flex-col gap-4">
            <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-[#7A7A7A]">Histórico de Threads</h3>
            <button 
              onClick={createNewChat}
              className="w-full sketch-button py-3 text-[10px] font-black uppercase tracking-widest"
            >
              + Novo Chat
            </button>
          </div>
          <div className="flex-1 overflow-y-auto p-4 space-y-3">
            {sessions.length === 0 ? (
              <p className="text-[9px] font-bold text-center text-[#B5B5B5] mt-10 uppercase">Sem conversas ativas</p>
            ) : (
              sessions.map((s) => (
                <div
                  key={s.id}
                  onClick={() => switchSession(s.id)}
                  className={`group relative p-4 sketch-border cursor-pointer transition-all ${
                    currentSessionId === s.id 
                      ? 'bg-[#1A1A1A] text-white shadow-[0_0_15px_rgba(26,26,26,0.2)]' 
                      : 'bg-white hover:bg-[#F2EFEA]'
                  }`}
                >
                  <p className="text-[10px] font-black uppercase truncate pr-6">{s.title || 'Nova Conversa'}</p>
                  <p className={`text-[8px] font-bold mt-1 ${currentSessionId === s.id ? 'text-gray-400' : 'text-[#7A7A7A]'}`}>
                    {s.lastUpdate.toLocaleDateString()} • {s.messages.length} msg
                  </p>
                  <button 
                    onClick={(e) => handleDeleteSession(s.id, e)}
                    className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity p-1 hover:text-rose-500"
                  >
                    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
                    </svg>
                  </button>
                </div>
              ))
            )}
          </div>
        </div>
      )}

      <div className="flex-1 flex flex-col h-full relative">
        <header className="p-6 border-b-2 border-[#1A1A1A] bg-white flex justify-between items-center z-10">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => setShowHistory(!showHistory)}
              className="p-2 border-2 border-[#1A1A1A] hover:bg-[#1A1A1A] hover:text-white transition-colors"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
              </svg>
            </button>
            <div>
              <h2 className="text-xl font-black text-[#1A1A1A] uppercase tracking-tighter leading-none">
                {sessions.find(s => s.id === currentSessionId)?.title || 'NOVA CONVERSA'}
              </h2>
              <p className="text-[8px] font-black text-[#7A7A7A] uppercase tracking-widest mt-1">Sessão Ativa • Protocolo FinanGPT</p>
            </div>
          </div>
        </header>

        <div ref={scrollRef} className="flex-1 overflow-y-auto p-8 space-y-8 pb-32">
          {messages.map((msg) => (
            <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[85%] sketch-border p-6 relative group ${msg.role === 'user' ? 'bg-[#1A1A1A] text-white' : 'bg-white text-[#1A1A1A]'}`}>
                <div className="flex justify-between items-center mb-6 border-b border-[#B5B5B5]/30 pb-2">
                  <span className={`text-[8px] font-black uppercase tracking-widest ${msg.role === 'user' ? 'text-[#7A7A7A]' : 'text-[#1A1A1A]'}`}>
                    {msg.role === 'user' ? 'AUTENTICADO_USER' : 'FINANGPT_CORE'}
                  </span>
                  <div className="flex items-center gap-4">
                    <span className="text-[8px] font-bold opacity-40 uppercase">{msg.timestamp.toLocaleTimeString()}</span>
                    <button 
                      onClick={() => handleCopy(msg.content, msg.id)}
                      className="text-[8px] font-black hover:underline uppercase transition-opacity opacity-0 group-hover:opacity-100"
                    >
                      {copyStatus === msg.id ? 'COPIADO' : 'COPIAR'}
                    </button>
                  </div>
                </div>

                <div className="chat-content">
                  {renderFormattedContent(msg.content)}
                </div>

                {msg.sources && msg.sources.length > 0 && (
                  <div className="mt-8 pt-4 border-t-2 border-[#1A1A1A]/10">
                    <div className="flex items-center gap-2 mb-3">
                      <svg className="w-3 h-3 text-[#4285F4]" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1 17.93c-3.95-.49-7-3.85-7-7.93 0-.62.08-1.21.21-1.79L9 15v1c0 1.1.9 2 2 2h1v1.93zM17.01 19c-.39-.33-.79-.66-1.18-1-.31-.26-.64-.51-.97-.75C12.44 15.68 11 13 11 11v-1l4 2 2-1V9l-5-2-4 2v2l-1.6 1.6C5.07 11.25 5 10.14 5 9c0-3.86 3.14-7 7-7s7 3.14 7 7c0 1.92-.77 3.66-2.02 4.93-.01.01-.01.02-.02.03-.64.65-1.37 1.19-2.18 1.61-.1.05-.2.09-.3.14-.14.07-.28.14-.42.21-.01.01-.02.01-.03.02-.01.01-.02.01-.03.02L17.01 19z"/></svg>
                      <p className="text-[7px] font-black uppercase text-[#4285F4] tracking-widest">Fontes de Grounding Detectadas ({msg.sources.length}):</p>
                    </div>
                    <div className="flex flex-wrap gap-2">
                      {msg.sources.map((url, i) => (
                        <a 
                          key={i} 
                          href={url} 
                          target="_blank" 
                          rel="noopener noreferrer" 
                          className="bg-gray-50 border border-gray-200 px-3 py-1 text-[8px] font-bold text-blue-600 hover:bg-blue-50 transition-colors flex items-center gap-2"
                        >
                          <span className="w-1.5 h-1.5 bg-blue-500"></span>
                          {new URL(url).hostname.replace('www.', '')}
                        </a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          ))}
          {isTyping && (
            <div className="flex justify-start">
              <div className="bg-white sketch-border p-3 flex gap-2">
                <div className="w-1 h-1 bg-[#1A1A1A] animate-bounce"></div>
                <div className="w-1 h-1 bg-[#1A1A1A] animate-bounce [animation-delay:0.2s]"></div>
                <div className="w-1 h-1 bg-[#1A1A1A] animate-bounce [animation-delay:0.4s]"></div>
              </div>
            </div>
          )}
        </div>

        <div className="absolute bottom-0 left-0 right-0 p-8 bg-gradient-to-t from-[#F2EFEA] via-[#F2EFEA] to-transparent">
          <div className="max-w-4xl mx-auto flex gap-4">
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Digite sua consulta contábil ou financeira..."
              className="flex-1 bg-white sketch-border px-6 py-4 outline-none font-bold text-xs uppercase tracking-widest focus:ring-2 focus:ring-[#1A1A1A]/10 transition-all"
            />
            <button 
              onClick={handleSend}
              disabled={isTyping}
              className="sketch-button px-10 py-4 font-black uppercase tracking-widest text-xs disabled:opacity-50 flex items-center gap-3"
            >
              {isTyping ? 'PROCESSANDO' : 'ENVIAR'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

