  uploadDate: Date;
  size: number;
  sourceType: DocumentSource;
  externalUrl?: string;
  metadata?: {
    propertyId?: string;
    lastSync?: Date;
    category?: 'cost' | 'tax' | 'management' | 'general' | 'exercise';
  };
}

