import { Document, User, ChatSession } from '../types';

const DOCS_KEY = 'finan_gpt_docs';
const USER_KEY = 'finan_gpt_user';
const CHATS_KEY = 'finan_gpt_chats';

export const StorageService = {
  // Documentos
  getDocuments: (): Document[] => {
    try {
      const data = localStorage.getItem(DOCS_KEY);
      return data ? JSON.parse(data) : [];
    } catch (e) {
      console.error("Error reading documents", e);
      return [];
    }
  },

  saveDocument: (doc: Document) => {
    const docs = StorageService.getDocuments();
    docs.push(doc);
    localStorage.setItem(DOCS_KEY, JSON.stringify(docs));
  },

  deleteDocument: (id: string) => {
    const docs = StorageService.getDocuments().filter(d => d.id !== id);
    localStorage.setItem(DOCS_KEY, JSON.stringify(docs));
  },

  // Usuário
  getUser: (): User | null => {
    try {
      const data = localStorage.getItem(USER_KEY);
      return data ? JSON.parse(data) : null;
    } catch (e) {
      return null;
    }
  },

  setUser: (user: User) => {
    localStorage.setItem(USER_KEY, JSON.stringify(user));
  },

  // Sessões de Chat
  // Added optional includeDeleted flag to support trash bin logic
  getChatSessions: (includeDeleted: boolean = false): ChatSession[] => {
    const data = localStorage.getItem(CHATS_KEY);
    if (!data) return [];

    try {
      const parsed = JSON.parse(data);
      if (!Array.isArray(parsed)) return [];

      const sessions = parsed.map((s: any) => ({
        ...s,
        lastUpdate: new Date(s.lastUpdate),
        // Inflate deletedAt date if present
        deletedAt: s.deletedAt ? new Date(s.deletedAt) : undefined,
        messages: (s.messages || []).map((m: any) => ({ 
          ...m, 
          timestamp: new Date(m.timestamp) 
        }))
      }));

      return includeDeleted ? sessions : sessions.filter(s => !s.deletedAt);
    } catch (e) {
      console.error("Failed to parse chat sessions", e);
      return [];
    }
  },

  saveChatSession: (session: ChatSession) => {
    const sessions = StorageService.getChatSessions(true);
    const index = sessions.findIndex(s => s.id === session.id);
    if (index >= 0) {
      sessions[index] = session;
    } else {
      sessions.push(session);
    }
    localStorage.setItem(CHATS_KEY, JSON.stringify(sessions));
  },

  // Updated to perform a soft delete by setting deletedAt timestamp
  deleteChatSession: (id: string) => {
    const sessions = StorageService.getChatSessions(true);
    const index = sessions.findIndex(s => s.id === id);
    if (index >= 0) {
      sessions[index].deletedAt = new Date();
      localStorage.setItem(CHATS_KEY, JSON.stringify(sessions));
    }
  },

  // Added method to restore a session from trash
  restoreFromTrash: (id: string) => {
    const sessions = StorageService.getChatSessions(true);
    const index = sessions.findIndex(s => s.id === id);
    if (index >= 0) {
      delete sessions[index].deletedAt;
      localStorage.setItem(CHATS_KEY, JSON.stringify(sessions));
    }
  },

  // Added method for final hard deletion of a session
  deletePermanently: (id: string) => {
    const sessions = StorageService.getChatSessions(true);
    const updatedSessions = sessions.filter(s => s.id !== id);
    localStorage.setItem(CHATS_KEY, JSON.stringify(updatedSessions));
  },

  clearAll: () => {
    localStorage.removeItem(DOCS_KEY);
    localStorage.removeItem(USER_KEY);
    localStorage.removeItem(CHATS_KEY);
  }
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Message, ChatSession } from '../types';
import { GeminiService } from '../services/geminiService';
import { StorageService } from '../services/storage';

const ChatInterface: React.FC = () => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string>('');
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [copyStatus, setCopyStatus] = useState<string | null>(null);
  const [showHistory, setShowHistory] = useState(true);
  const scrollRef = useRef<HTMLDivElement>(null);

  const WELCOME_MESSAGE: Message = {
    id: 'welcome',
    role: 'model',
    content: '### TERMINAL FINANGPT INICIALIZADO\n\nPronto para consultoria, análise de mercado e treinamento contábil.\n\n- **Modo Educacional:** Ativo\n- **RAG Engine:** Processando documentos\n\n**Sugestões:**\n1. "Crie um exercício de DRE."\n2. "Explique o impacto da Selic no varejo."',
    timestamp: new Date()
  };

  // Load initial data
  useEffect(() => {
    const activeSessions = StorageService.getChatSessions();
    setSessions(activeSessions);

    if (activeSessions.length > 0) {
      const last = activeSessions[0];
      setCurrentSessionId(last.id);
      setMessages(last.messages);
    } else {
      const newId = Date.now().toString();
      setCurrentSessionId(newId);
      setMessages([WELCOME_MESSAGE]);
    }
  }, []);

  // Helper to persist current session
  const persistSession = useCallback((id: string, msgs: Message[], title?: string) => {
    if (!id || msgs.length === 0) return;

    const existingSession = StorageService.getChatSessions().find(s => s.id === id);
    const newTitle = title || existingSession?.title || (msgs.find(m => m.role === 'user')?.content.substring(0, 30)) || 'Nova Conversa';

    const session: ChatSession = {
      id,
      title: newTitle,
      messages: msgs,
      lastUpdate: new Date()
    };

    StorageService.saveChatSession(session);
    setSessions(StorageService.getChatSessions());
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const createNewChat = () => {
    const newId = Date.now().toString();
    setCurrentSessionId(newId);
    setMessages([WELCOME_MESSAGE]);
    // Optionally persist it immediately or wait for first message
  };

  const switchSession = (id: string) => {
    const session = sessions.find(s => s.id === id);
    if (session) {
      setCurrentSessionId(session.id);
      setMessages(session.messages);
    }
  };

  const handleDeleteSession = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    // Updated confirmation text to match soft delete functionality
    if (window.confirm("Deseja mover este chat para a lixeira?")) {
      // 1. Move to Trash (Soft Delete)
      StorageService.deleteChatSession(id);

      // 2. Refresh local sessions list
      const remaining = StorageService.getChatSessions();
      setSessions(remaining);

      // 3. If we deleted the active one, pivot
      if (currentSessionId === id) {
        if (remaining.length > 0) {
          const next = remaining[0];
          setCurrentSessionId(next.id);
          setMessages(next.messages);
        } else {
          createNewChat();
        }
      }
    }
  };

  const handleCopy = (content: string, id: string) => {
    navigator.clipboard.writeText(content);
    setCopyStatus(id);
    setTimeout(() => setCopyStatus(null), 2000);
  };

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      timestamp: new Date()
    };

    const newMessages = [...messages, userMessage];
    setMessages(newMessages);
    const currentInput = input;
    setInput('');
    setIsTyping(true);

    // Initial save of the user's turn
    persistSession(currentSessionId, newMessages);

    // Auto-generate title for new sessions
    const isFirstUserMessage = messages.filter(m => m.role === 'user').length === 0;
    if (isFirstUserMessage) {
      GeminiService.generateTitle(currentInput).then(generatedTitle => {
        persistSession(currentSessionId, newMessages, generatedTitle);
      });
    }

    try {
      const response = await GeminiService.generateChatResponse(currentInput, messages);
      const sources: string[] = [];

      if (response.groundingMetadata?.groundingChunks) {
        response.groundingMetadata.groundingChunks.forEach((chunk: any) => {
          if (chunk.web?.uri) sources.push(chunk.web.uri);
          else if (chunk.maps?.uri) sources.push(chunk.maps.uri);
        });
      }

      const modelMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: response.text,
        timestamp: new Date(),
        sources: sources.length > 0 ? Array.from(new Set(sources)) : undefined
      };

      const finalMessages = [...newMessages, modelMessage];
      setMessages(finalMessages);
      persistSession(currentSessionId, finalMessages);
    } catch (error) {
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'model',
        content: '### ERRO CRÍTICO\nNão foi possível processar a consulta. Verifique sua conexão ou API Key.',
        timestamp: new Date()
      }]);
    } finally {
      setIsTyping(false);
    }
  };

  const parseInlineStyles = (text: string) => {
    const parts = text.split(/(\*\*.*?\*\*|\*.*?\*)/g);
    return parts.map((part, i) => {
      if (part.startsWith('**') && part.endsWith('**')) {
        return <strong key={i} className="font-black text-[#1A1A1A]">{part.slice(2, -2)}</strong>;
      }
      if (part.startsWith('*') && part.endsWith('*')) {
        return <em key={i} className="italic font-medium">{part.slice(1, -1)}</em>;
      }
      return part;
    });
  };

  const renderFormattedContent = (content: string) => {
    const lines = content.split('\n');
    let elements: React.ReactNode[] = [];
    let currentTable: string[][] = [];

    const flushTable = (key: number) => {
      if (currentTable.length === 0) return null;

      const isSeparator = (row: string[]) => row.every(cell => cell.trim().match(/^-+$/));
      const hasHeader = currentTable.length > 1 && isSeparator(currentTable[1]);

      const headerRow = hasHeader ? currentTable[0] : null;
      const dataRows = hasHeader ? currentTable.slice(2) : currentTable;

      const tableEl = (
        <div key={`table-${key}`} className="my-6 overflow-x-auto sketch-border p-1 bg-white">
          <table className="w-full border-collapse text-[10px] text-[#1A1A1A]">
            {headerRow && (
              <thead>
                <tr className="bg-[#1A1A1A] text-white">
                  {headerRow.map((cell, i) => (
                    <th key={i} className="px-4 py-3 border-2 border-[#1A1A1A] text-left uppercase font-black tracking-widest">{cell.trim()}</th>
                  ))}
                </tr>
              </thead>
            )}
            <tbody>
              {dataRows.map((row, i) => (
                <tr key={i} className="bg-white hover:bg-[#F2EFEA] transition-colors">
                  {row.map((cell, j) => (
                    <td key={j} className="px-4 py-3 border-2 border-[#1A1A1A] font-bold uppercase">{parseInlineStyles(cell.trim())}</td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      );
      currentTable = [];
      return tableEl;
    };

    lines.forEach((line, idx) => {
      const isTableRow = line.trim().startsWith('|') && line.trim().includes('|');

      if (isTableRow) {
        const cells = line.trim().split('|').filter((_, i, arr) => i > 0 && i < arr.length - 1);
        currentTable.push(cells);
      } else {
        const table = flushTable(idx);
        if (table) elements.push(table);

        if (line.startsWith('###')) {
          elements.push(<h3 key={idx} className="text-sm font-black mt-6 mb-3 uppercase border-b-2 border-[#1A1A1A] pb-1">{line.replace('###', '')}</h3>);
        } else if (line.trim().startsWith('- ') || line.trim().startsWith('* ')) {
          elements.push(
            <li key={idx} className="ml-4 mb-2 text-[11px] font-bold uppercase tracking-tight list-none flex items-start gap-3">
              <span className="mt-1 w-1.5 h-1.5 bg-[#1A1A1A] flex-shrink-0"></span>
              <span>{parseInlineStyles(line.trim().substring(2))}</span>
            </li>
          );
        } else if (line.trim().match(/^\d+\./)) {
           elements.push(
            <li key={idx} className="ml-4 mb-2 text-[11px] font-bold uppercase tracking-tight list-none flex items-start gap-3">
              <span className="text-[#7A7A7A] font-black">{line.trim().split('.')[0]}.</span>
              <span>{parseInlineStyles(line.trim().split('.').slice(1).join('.').trim())}</span>
            </li>
          );
        } else if (line.trim() === '') {
          elements.push(<div key={idx} className="h-4" />);
        } else {
          elements.push(<p key={idx} className="text-[11px] font-medium leading-relaxed mb-3 text-[#333]">{parseInlineStyles(line)}</p>);
        }
      }
    });

    const finalTable = flushTable(lines.length);
    if (finalTable) elements.push(finalTable);

    return elements;
  };

  return (
    <div className="flex h-full bg-[#F2EFEA] overflow-hidden">
      {showHistory && (
        <div className="w-72 bg-white border-r-2 border-[#1A1A1A] flex flex-col h-full animate-in slide-in-from-left duration-300">
          <div className="p-6 border-b-2 border-[#1A1A1A] flex flex-col gap-4">
            <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-[#7A7A7A]">Histórico de Threads</h3>
            <button 
              onClick={createNewChat}
              className="w-full sketch-button py-3 text-[10px] font-black uppercase tracking-widest"
            >
              + Novo Chat
            </button>
          </div>
          <div className="flex-1 overflow-y-auto p-4 space-y-3">
            {sessions.length === 0 ? (
              <p className="text-[9px] font-bold text-center text-[#B5B5B5] mt-10 uppercase">Sem conversas ativas</p>
            ) : (
              sessions.map((s) => (
                <div
                  key={s.id}
                  onClick={() => switchSession(s.id)}
                  className={`group relative p-4 sketch-border cursor-pointer transition-all ${
                    currentSessionId === s.id 
                      ? 'bg-[#1A1A1A] text-white shadow-[0_0_15px_rgba(26,26,26,0.2)]' 
                      : 'bg-white hover:bg-[#F2EFEA]'
                  }`}
                >
                  <div className="flex justify-between items-start gap-2">
                    <p className="text-[10px] font-black uppercase truncate flex-1">{s.title || 'Nova Conversa'}</p>
                    <button 
                      onClick={(e) => handleDeleteSession(s.id, e)}
                      className="opacity-0 group-hover:opacity-100 transition-opacity p-1 text-[#7A7A7A] hover:text-rose-500"
                      title="Mover para Lixeira"
                    >
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                      </svg>
                    </button>
                  </div>
                  <p className={`text-[8px] font-bold mt-1 ${currentSessionId === s.id ? 'text-gray-400' : 'text-[#7A7A7A]'}`}>
                    {s.lastUpdate.toLocaleDateString()} • {s.messages?.length || 0} msg
                  </p>
                </div>
              ))
            )}
          </div>
        </div>
      )}

      <div className="flex-1 flex flex-col h-full relative">
        <header className="p-6 border-b-2 border-[#1A1A1A] bg-white flex justify-between items-center z-10">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => setShowHistory(!showHistory)}
              className="p-2 border-2 border-[#1A1A1A] hover:bg-[#1A1A1A] hover:text-white transition-colors"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
              </svg>
            </button>
            <div>
              <h2 className="text-xl font-black text-[#1A1A1A] uppercase tracking-tighter leading-none">
                {sessions.find(s => s.id === currentSessionId)?.title || 'NOVA CONVERSA'}
              </h2>
              <p className="text-[8px] font-black text-[#7A7A7A] uppercase tracking-widest mt-1">Sessão Ativa • Protocolo FinanGPT</p>
            </div>
          </div>
        </header>

        <div ref={scrollRef} className="flex-1 overflow-y-auto p-8 space-y-8 pb-32">
          {messages.map((msg) => (
            <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[85%] sketch-border p-6 relative group ${msg.role === 'user' ? 'bg-[#1A1A1A] text-white' : 'bg-white text-[#1A1A1A]'}`}>
                <div className="flex justify-between items-center mb-6 border-b border-[#B5B5B5]/30 pb-2">
                  <span className={`text-[8px] font-black uppercase tracking-widest ${msg.role === 'user' ? 'text-[#7A7A7A]' : 'text-[#1A1A1A]'}`}>
                    {msg.role === 'user' ? 'AUTENTICADO_USER' : 'FINANGPT_CORE'}
                  </span>
                  <div className="flex items-center gap-4">
                    <span className="text-[8px] font-bold opacity-40 uppercase">{msg.timestamp.toLocaleTimeString()}</span>
                    <button 
                      onClick={() => handleCopy(msg.content, msg.id)}
                      className="text-[8px] font-black hover:underline uppercase transition-opacity opacity-0 group-hover:opacity-100"
                    >
                      {copyStatus === msg.id ? 'COPIADO' : 'COPIAR'}
                    </button>
                  </div>
                </div>

                <div className="chat-content">
                  {renderFormattedContent(msg.content)}
                </div>

                {msg.sources && msg.sources.length > 0 && (
                  <div className="mt-8 pt-4 border-t-2 border-[#1A1A1A]/10">
                    <div className="flex items-center gap-2 mb-3">
                      <svg className="w-3 h-3 text-[#4285F4]" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1 17.93c-3.95-.49-7-3.85-7-7.93 0-.62.08-1.21.21-1.79L9 15v1c0 1.1.9 2 2 2h1v1.93zM17.01 19c-.39-.33-.79-.66-1.18-1-.31-.26-.64-.51-.97-.75C12.44 15.68 11 13 11 11v-1l4 2 2-1V9l-5-2-4 2v2l-1.6 1.6C5.07 11.25 5 10.14 5 9c0-3.86 3.14-7 7-7s7 3.14 7 7c0 1.92-.77 3.66-2.02 4.93-.01.01-.01.02-.02.03-.64.65-1.37 1.19-2.18 1.61-.1.05-.2.09-.3.14-.14.07-.28.14-.42.21-.01.01-.02.01-.03.02-.01.01-.02.01-.03.02L17.01 19z"/></svg>
                      <p className="text-[7px] font-black uppercase text-[#4285F4] tracking-widest">Fontes de Grounding Detectadas ({msg.sources.length}):</p>
                    </div>
                    <div className="flex flex-wrap gap-2">
                      {msg.sources.map((url, i) => (
                        <a 
                          key={i} 
                          href={url} 
                          target="_blank" 
                          rel="noopener noreferrer" 
                          className="bg-gray-50 border border-gray-200 px-3 py-1 text-[8px] font-bold text-blue-600 hover:bg-blue-50 transition-colors flex items-center gap-2"
                        >
                          <span className="w-1.5 h-1.5 bg-blue-500"></span>
                          {new URL(url).hostname.replace('www.', '')}
                        </a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          ))}
          {isTyping && (
            <div className="flex justify-start">
              <div className="bg-white sketch-border p-3 flex gap-2">
                <div className="w-1 h-1 bg-[#1A1A1A] animate-bounce"></div>
                <div className="w-1 h-1 bg-[#1A1A1A] animate-bounce [animation-delay:0.2s]"></div>
                <div className="w-1 h-1 bg-[#1A1A1A] animate-bounce [animation-delay:0.4s]"></div>
              </div>
            </div>
          )}
        </div>

        <div className="absolute bottom-0 left-0 right-0 p-8 bg-gradient-to-t from-[#F2EFEA] via-[#F2EFEA] to-transparent">
          <div className="max-w-4xl mx-auto flex gap-4">
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Digite sua consulta contábil ou financeira..."
              className="flex-1 bg-white sketch-border px-6 py-4 outline-none font-bold text-xs uppercase tracking-widest focus:ring-2 focus:ring-[#1A1A1A]/10 transition-all"
            />
            <button 
              onClick={handleSend}
              disabled={isTyping}
              className="sketch-button px-10 py-4 font-black uppercase tracking-widest text-xs disabled:opacity-50 flex items-center gap-3"
            >
              {isTyping ? 'PROCESSANDO' : 'ENVIAR'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ChatInterface;

import React, { useState, useEffect, useMemo } from 'react';
import { MarketService, MarketRates, StockInfo } from '../services/marketService';
import { Candle } from '../types';
import { StorageService } from '../services/storage';

const Dashboard: React.FC = () => {
  const [rates, setRates] = useState<MarketRates | null>(null);
  const [stocks, setStocks] = useState<StockInfo[]>([]);
  const [candles, setCandles] = useState<Candle[]>([]);
  const [selectedAsset, setSelectedAsset] = useState('BTC');
  const [timeframe, setTimeframe] = useState('1h');
  const [hoveredCandle, setHoveredCandle] = useState<Candle | null>(null);
  const [loadingMarket, setLoadingMarket] = useState(true);
  const [showSMA, setShowSMA] = useState(false);
  const [connectedServices, setConnectedServices] = useState<string[]>([]);

  useEffect(() => {
    const docs = StorageService.getDocuments();
    const services = Array.from(new Set(docs.map(d => d.sourceType))).filter(s => s !== 'local');
    setConnectedServices(services);

    const loadMarketData = async () => {
      setLoadingMarket(true);
      try {
        const rateData = await MarketService.fetchExchangeRates();
        const [stockData, candleData] = await Promise.all([
          MarketService.fetchStockData(rateData),
          MarketService.fetchHistoricalCandles(selectedAsset, timeframe)
        ]);
        setRates(rateData);
        setStocks(stockData);
        setCandles(candleData);
      } catch (e) {
        console.error("Error updating dashboard data", e);
      } finally {
        setLoadingMarket(false);
      }
    };

    loadMarketData();
    const interval = setInterval(loadMarketData, timeframe === '1m' ? 5000 : 60000); 
    return () => clearInterval(interval);
  }, [selectedAsset, timeframe]);

  const chartMetrics = useMemo(() => {
    if (candles.length === 0) return null;
    const lows = candles.map(c => c.low);
    const highs = candles.map(c => c.high);
    const minLow = Math.min(...lows);
    const maxHigh = Math.max(...highs);
    const range = maxHigh - minLow;

    // Proteção contra range zero (preço estático)
    const effectiveRange = range === 0 ? 1 : range;

    const sma = candles.map((_, i) => {
      if (i < 9) return null;
      const slice = candles.slice(i - 9, i + 1);
      const sum = slice.reduce((acc, curr) => acc + curr.close, 0);
      return sum / 10;
    });

    return { 
      minLow, 
      maxHigh, 
      range: effectiveRange, 
      sma, 
      estimatedSupport: minLow, 
      estimatedResistance: maxHigh 
    };
  }, [candles]);

  const renderCandleChart = () => {
    if (!chartMetrics || candles.length === 0) return (
      <div className="h-[350px] flex flex-col items-center justify-center gap-4 bg-[#F9F9F9] sketch-border">
        <div className="w-8 h-8 border-4 border-[#1A1A1A] border-t-transparent rounded-full animate-spin"></div>
        <span className="text-[10px] font-black uppercase tracking-widest text-[#7A7A7A]">Sincronizando Dados...</span>
      </div>
    );

    const width = 1000;
    const height = 350;
    const padding = 40;
    const candleSpace = (width - padding * 2) / candles.length;
    const candleWidth = candleSpace * 0.7;
    const getY = (price: number) => height - padding - ((price - chartMetrics.minLow) / chartMetrics.range) * (height - padding * 2);

    return (
      <div className="relative group cursor-crosshair select-none bg-white p-2">
        <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-[350px] overflow-visible" preserveAspectRatio="none">
          {/* Linhas de Grade e Preços */}
          {[0, 0.25, 0.5, 0.75, 1].map((p, i) => {
            const y = padding + p * (height - padding * 2);
            const price = chartMetrics.maxHigh - p * (chartMetrics.maxHigh - chartMetrics.minLow);
            return (
              <g key={i}>
                <line x1={padding} y1={y} x2={width - padding} y2={y} stroke="#F2F2F2" strokeWidth="1" />
                <text x={width - padding + 5} y={y + 4} className="text-[9px] fill-[#B5B5B5] font-bold font-mono">
                  {price.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                </text>
              </g>
            );
          })}

          {/* SMA Line */}
          {showSMA && (
            <path
              d={chartMetrics.sma.map((val, i) => {
                if (val === null) return '';
                const x = padding + i * candleSpace + candleSpace/2;
                const y = getY(val);
                return `${i === 9 ? 'M' : 'L'} ${x} ${y}`;
              }).join(' ')}
              fill="none"
              stroke="#4285F4"
              strokeWidth="2"
              strokeDasharray="4 2"
            />
          )}

          {/* Candlesticks */}
          {candles.map((candle, i) => {
            const x = padding + i * candleSpace;
            const openY = getY(candle.open);
            const closeY = getY(candle.close);
            const highY = getY(candle.high);
            const lowY = getY(candle.low);
            const isBullish = candle.close >= candle.open;
            const color = isBullish ? '#10B981' : '#EF4444';

            return (
              <g key={i} onMouseEnter={() => setHoveredCandle(candle)} onMouseLeave={() => setHoveredCandle(null)}>
                <line x1={x + candleSpace/2} y1={highY} x2={x + candleSpace/2} y2={lowY} stroke={color} strokeWidth="1.5" />
                <rect 
                  x={x + (candleSpace - candleWidth)/2} 
                  y={Math.min(openY, closeY)} 
                  width={candleWidth} 
                  height={Math.max(1, Math.abs(openY - closeY))} 
                  fill={color}
                  className="transition-all duration-300"
                />
                <rect x={x} y={0} width={candleSpace} height={height} fill="transparent" />
              </g>
            );
          })}
        </svg>

        {/* Tooltip */}
        {hoveredCandle && (
          <div className="absolute top-4 left-10 bg-[#1A1A1A] text-white p-3 text-[9px] font-bold uppercase tracking-widest z-10 sketch-border shadow-none border-white">
            <div className="grid grid-cols-2 gap-x-4 gap-y-1">
              <span className="text-[#7A7A7A]">Abertura:</span> <span>{hoveredCandle.open.toFixed(2)}</span>
              <span className="text-[#7A7A7A]">Fechamento:</span> <span>{hoveredCandle.close.toFixed(2)}</span>
              <span className="text-[#7A7A7A]">Máxima:</span> <span>{hoveredCandle.high.toFixed(2)}</span>
              <span className="text-[#7A7A7A]">Mínima:</span> <span>{hoveredCandle.low.toFixed(2)}</span>
            </div>
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full bg-[#F2EFEA] overflow-hidden">
      {/* Ticker Tape */}
      <div className="bg-[#1A1A1A] h-10 flex items-center overflow-hidden border-b-2 border-[#1A1A1A] relative">
        <div className="flex animate-[ticker_60s_linear_infinite] whitespace-nowrap gap-12 px-4 items-center">
          {stocks.concat(stocks).map((stock, i) => (
            <div key={i} className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-white">
              <span>{stock.symbol}</span>
              <span className="text-gray-400 font-mono">{stock.price}</span>
              <span className={stock.isPositive ? 'text-emerald-400' : 'text-rose-400'}>{stock.change}</span>
            </div>
          ))}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-8 space-y-8">
        <header className="flex flex-col lg:flex-row justify-between lg:items-end border-b-2 border-[#1A1A1A] pb-8 gap-6">
          <div>
            <h1 className="text-4xl font-black text-[#1A1A1A] tracking-tighter uppercase leading-none">CENTRO DE OPERAÇÕES</h1>
            <div className="flex flex-wrap gap-4 mt-4 items-center">
              <div className="flex items-center gap-2">
                <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></div>
                <span className="text-[10px] font-black uppercase tracking-widest text-[#7A7A7A]">Mercado Aberto</span>
              </div>
              <div className="flex gap-2">
                {connectedServices.map(s => (
                  <span key={s} className="bg-[#4285F4] text-white text-[8px] font-black px-2 py-1 uppercase tracking-widest">
                    {s.replace('_', ' ')} CONECTADO
                  </span>
                ))}
                {connectedServices.length === 0 && (
                  <span className="border border-[#1A1A1A] text-[#7A7A7A] text-[8px] font-black px-2 py-1 uppercase tracking-widest">
                    BASE LOCAL ATIVA
                  </span>
                )}
              </div>
            </div>
          </div>

          <div className="flex gap-4">
            <select 
              value={selectedAsset} 
              onChange={(e) => setSelectedAsset(e.target.value)} 
