import { GoogleGenAI } from "@google/genai";
import { StorageService } from "./storage";

export const GeminiService = {
  generateChatResponse: async (prompt: string, history: any[]) => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const docs = StorageService.getDocuments();
    const context = docs.length > 0 
      ? `BASE DE CONHECIMENTO INTEGRADA (GOOGLE + LOCAL):\n${docs.map(d => `[PROVEDOR: ${d.sourceType.toUpperCase()}] [CATEGORIA: ${d.metadata?.category || 'GERAL'}] [ARQUIVO: ${d.name}]\nCONTEÚDO: ${d.content}`).join('\n\n')}`
      : "O usuário ainda não conectou documentos ou serviços Google.";

    const systemInstruction = `
      Você é o "FinaIGPT", uma IA de elite especializada em Finanças, Contabilidade e Análise de Dados Digitais no Brasil.

      DIRETRIZES TÉCNICAS (CONFORMIDADE IFRS/CPC):
      1. CONTABILIDADE DE CUSTOS: Realize cálculos de Custo de Mercadorias Vendidas (CMV), Margem de Contribuição e Ponto de Equilíbrio (Contábil, Econômico e Financeiro). Diferencie claramente Custo Direto, Indireto, Fixo e Variável.
      2. CONTABILIDADE TRIBUTÁRIA: Responda sobre Simples Nacional (Anexos), Lucro Presumido e Lucro Real. Explique a não-cumulatividade do PIS/COFINS e créditos de ICMS.
      3. CONTABILIDADE GERENCIAL: Calcule e analise EBITDA, ROI, ROE, Liquidez Corrente e Seca.

      MÓDULO DE ENSINO E CORREÇÃO DE EXERCÍCIOS:
      - Quando um usuário enviar uma resposta de exercício:
        - Analise criticamente.
        - Identifique erros de classificação (ex: classificou frete de venda como custo, quando é despesa).
        - Forneça a correção em formato de tabela Markdown.
        - Dê uma nota final (0-10) justificando cada ponto deduzido.
      - Quando solicitado um exercício novo:
        - Gere enunciados com dados realistas.
        - Peça para o aluno montar a DRE ou Balanço.

      REGRAS DE FORMATAÇÃO:
      - Use tabelas Markdown para DRE e Balanço Patrimonial.
      - Destaque fórmulas matemáticas em blocos de código ou negrito.
      - Para dados de mercado, use o Google Search tool para obter cotações atualizadas (Selic, IPCA, Dólar, etc).

      CONTEXTO RAG ATUAL:
      ${context}
    `;

    const formattedHistory = history
      .filter(msg => msg.id !== 'welcome' && msg.id !== 'reset') 
      .map(msg => ({
        role: msg.role === 'user' ? 'user' : 'model',
        parts: [{ text: msg.content }]
      }));

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [
          ...formattedHistory,
          { role: 'user', parts: [{ text: prompt }] }
        ],
        config: {
          systemInstruction,
          tools: [{ googleSearch: {} }]
        },
      });

      return {
        text: response.text || "Erro no processamento da IA.",
        groundingMetadata: response.candidates?.[0]?.groundingMetadata
      };
    } catch (error) {
      console.error("Gemini Error:", error);
      throw error;
    }
  },

  generateTitle: async (firstPrompt: string): Promise<string> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Analise a intenção e palavras-chave desta consulta e crie um título curto (máximo 5 palavras) em português. Retorne APENAS o título: "${firstPrompt}"`,
        config: {
          temperature: 0.5,
          maxOutputTokens: 20
        }
      });
      return response.text?.replace(/["']/g, '').trim() || firstPrompt.substring(0, 30);
    } catch (e) {
      return firstPrompt.substring(0, 30);
    }
  }
};

