import { GoogleGenAI } from "@google/genai";
import { StorageService } from "./storage.ts";

export const GeminiService = {
  generateChatResponse: async (prompt: string, history: any[]) => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const docs = StorageService.getDocuments();
    const context = docs.length > 0 
      ? `BASE DE CONHECIMENTO INTEGRADA (GOOGLE + LOCAL):\n${docs.map(d => `[PROVEDOR: ${d.sourceType.toUpperCase()}] [CATEGORIA: ${d.metadata?.category || 'GERAL'}] [ARQUIVO: ${d.name}]\nCONTEÚDO: ${d.content}`).join('\n\n')}`
      : "O usuário ainda não conectou documentos ou serviços Google.";

    const systemInstruction = `
      Você é o "FinaIGPT", uma IA de elite especializada em Finanças, Contabilidade e Análise de Dados Digitais no Brasil.

      DIRETRIZES TÉCNICAS (CONFORMIDADE IFRS/CPC):
      1. CONTABILIDADE DE CUSTOS: Realize cálculos de Custo de Mercadorias Vendidas (CMV), Margem de Contribuição e Ponto de Equilíbrio (Contábil, Econômico e Financeiro). Diferencie claramente Custo Direto, Indireto, Fixo e Variável.
      2. CONTABILIDADE TRIBUTÁRIA: Responda sobre Simples Nacional (Anexos), Lucro Presumido e Lucro Real. Explique a não-cumulatividade do PIS/COFINS e créditos de ICMS.
      3. CONTABILIDADE GERENCIAL: Calcule e analise EBITDA, ROI, ROE, Liquidez Corrente e Seca.

      MÓDULO DE ENSINO E CORREÇÃO DE EXERCÍCIOS:
      - Quando um usuário enviar uma resposta de exercício:
        - Analise criticamente.
        - Identifique erros de classificação (ex: classificou frete de venda como custo, quando é despesa).
        - Forneça a correção em formato de tabela Markdown.
        - Dê uma nota final (0-10) justificando cada ponto deduzido.
      - Quando solicitado um exercício novo:
        - Gere enunciados com dados realistas.
        - Peça para o aluno montar a DRE ou Balanço.

      REGRAS DE FORMATAÇÃO:
      - Use tabelas Markdown para DRE e Balanço Patrimonial.
      - Destaque fórmulas matemáticas em blocos de código ou negrito.
      - Para dados de mercado, use o Google Search tool para obter cotações atualizadas (Selic, IPCA, Dólar, etc).

      CONTEXTO RAG ATUAL:
      ${context}
    `;

    const formattedHistory = history
      .filter(msg => msg.id !== 'welcome' && msg.id !== 'reset') 
      .map(msg => ({
        role: msg.role === 'user' ? 'user' : 'model',
        parts: [{ text: msg.content }]
      }));

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [
          ...formattedHistory,
          { role: 'user', parts: [{ text: prompt }] }
        ],
        config: {
          systemInstruction,
          tools: [{ googleSearch: {} }]
        },
      });

      return {
        text: response.text || "Erro no processamento da IA.",
        groundingMetadata: response.candidates?.[0]?.groundingMetadata
      };
    } catch (error) {
      console.error("Gemini Error:", error);
      throw error;
    }
  },

  generateTitle: async (firstPrompt: string): Promise<string> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Analise a intenção e palavras-chave desta consulta e crie um título curto (máximo 5 palavras) em português. Retorne APENAS o título: "${firstPrompt}"`,
        config: {
          temperature: 0.5,
          maxOutputTokens: 20
        }
      });
      return response.text?.replace(/["']/g, '').trim() || firstPrompt.substring(0, 30);
    } catch (e) {
      return firstPrompt.substring(0, 30);
    }
  }
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Message, ChatSession } from '../types.ts';
import { GeminiService } from '../services/geminiService.ts';
import { StorageService } from '../services/storage.ts';

const ChatInterface: React.FC = () => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string>('');
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [copyStatus, setCopyStatus] = useState<string | null>(null);
  const [showHistory, setShowHistory] = useState(true);
  const scrollRef = useRef<HTMLDivElement>(null);

  const WELCOME_MESSAGE: Message = {
    id: 'welcome',
    role: 'model',
    content: '### TERMINAL FINAIGPT INICIALIZADO\n\nPronto para consultoria, análise de mercado e treinamento contábil.\n\n- **Modo Educacional:** Ativo\n- **RAG Engine:** Processando documentos\n\n**Sugestões:**\n1. "Crie um exercício de DRE."\n2. "Explique o impacto da Selic no varejo."',
    timestamp: new Date()
  };

  // Load initial data
  useEffect(() => {
    const activeSessions = StorageService.getChatSessions();
    setSessions(activeSessions);

    if (activeSessions.length > 0) {
      const last = activeSessions[0];
      setCurrentSessionId(last.id);
      setMessages(last.messages);
    } else {
      const newId = Date.now().toString();
      setCurrentSessionId(newId);
      setMessages([WELCOME_MESSAGE]);
    }
  }, []);

  // Helper to persist current session
  const persistSession = useCallback((id: string, msgs: Message[], title?: string) => {
    if (!id || msgs.length === 0) return;

    const existingSession = StorageService.getChatSessions().find(s => s.id === id);
    const newTitle = title || existingSession?.title || (msgs.find(m => m.role === 'user')?.content.substring(0, 30)) || 'Nova Conversa';

    const session: ChatSession = {
      id,
      title: newTitle,
      messages: msgs,
      lastUpdate: new Date()
    };

    StorageService.saveChatSession(session);
    setSessions(StorageService.getChatSessions());
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const createNewChat = () => {
    const newId = Date.now().toString();
    setCurrentSessionId(newId);
    setMessages([WELCOME_MESSAGE]);
    // Optionally persist it immediately or wait for first message
  };

  const switchSession = (id: string) => {
    const session = sessions.find(s => s.id === id);
    if (session) {
      setCurrentSessionId(session.id);
      setMessages(session.messages);
    }
  };

  const handleDeleteSession = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    // Updated confirmation text to match soft delete functionality
    if (window.confirm("Deseja mover este chat para a lixeira?")) {
      // 1. Move to Trash (Soft Delete)
      StorageService.deleteChatSession(id);

      // 2. Refresh local sessions list
      const remaining = StorageService.getChatSessions();
      setSessions(remaining);

      // 3. If we deleted the active one, pivot
      if (currentSessionId === id) {
        if (remaining.length > 0) {
          const next = remaining[0];
          setCurrentSessionId(next.id);
          setMessages(next.messages);
        } else {
          createNewChat();
        }
      }
    }
  };

  const handleCopy = (content: string, id: string) => {
    navigator.clipboard.writeText(content);
    setCopyStatus(id);
    setTimeout(() => setCopyStatus(null), 2000);
  };

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      timestamp: new Date()
    };

    const newMessages = [...messages, userMessage];
    setMessages(newMessages);
    const currentInput = input;
    setInput('');
    setIsTyping(true);

    // Initial save of the user's turn
    persistSession(currentSessionId, newMessages);

    // Auto-generate title for new sessions
    const isFirstUserMessage = messages.filter(m => m.role === 'user').length === 0;
    if (isFirstUserMessage) {
      GeminiService.generateTitle(currentInput).then(generatedTitle => {
        persistSession(currentSessionId, newMessages, generatedTitle);
      });
    }

    try {
      const response = await GeminiService.generateChatResponse(currentInput, messages);
      const sources: string[] = [];

      if (response.groundingMetadata?.groundingChunks) {
        response.groundingMetadata.groundingChunks.forEach((chunk: any) => {
          if (chunk.web?.uri) sources.push(chunk.web.uri);
          else if (chunk.maps?.uri) sources.push(chunk.maps.uri);
        });
      }

      const modelMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: response.text,
        timestamp: new Date(),
        sources: sources.length > 0 ? Array.from(new Set(sources)) : undefined
      };

      const finalMessages = [...newMessages, modelMessage];
      setMessages(finalMessages);
      persistSession(currentSessionId, finalMessages);
    } catch (error) {
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'model',
        content: '### ERRO CRÍTICO\nNão foi possível processar a consulta. Verifique sua conexão ou API Key.',
        timestamp: new Date()
      }]);
    } finally {
      setIsTyping(false);
    }
  };

  const parseInlineStyles = (text: string) => {
    const parts = text.split(/(\*\*.*?\*\*|\*.*?\*)/g);
    return parts.map((part, i) => {
      if (part.startsWith('**') && part.endsWith('**')) {
        return <strong key={i} className="font-black text-[#1A1A1A]">{part.slice(2, -2)}</strong>;
      }
      if (part.startsWith('*') && part.endsWith('*')) {
        return <em key={i} className="italic font-medium">{part.slice(1, -1)}</em>;
      }
      return part;
    });
  };

  const renderFormattedContent = (content: string) => {
    const lines = content.split('\n');
    let elements: React.ReactNode[] = [];
    let currentTable: string[][] = [];

    const flushTable = (key: number) => {
      if (currentTable.length === 0) return null;

      const isSeparator = (row: string[]) => row.every(cell => cell.trim().match(/^-+$/));
      const hasHeader = currentTable.length > 1 && isSeparator(currentTable[1]);

      const headerRow = hasHeader ? currentTable[0] : null;
      const dataRows = hasHeader ? currentTable.slice(2) : currentTable;

      const tableEl = (
        <div key={`table-${key}`} className="my-6 overflow-x-auto sketch-border p-1 bg-white">
          <table className="w-full border-collapse text-[10px] text-[#1A1A1A]">
            {headerRow && (
              <thead>
                <tr className="bg-[#1A1A1A] text-white">
                  {headerRow.map((cell, i) => (
                    <th key={i} className="px-4 py-3 border-2 border-[#1A1A1A] text-left uppercase font-black tracking-widest">{cell.trim()}</th>
                  ))}
                </tr>
              </thead>
            )}
            <tbody>
              {dataRows.map((row, i) => (
                <tr key={i} className="bg-white hover:bg-[#F2EFEA] transition-colors">
                  {row.map((cell, j) => (
                    <td key={j} className="px-4 py-3 border-2 border-[#1A1A1A] font-bold uppercase">{parseInlineStyles(cell.trim())}</td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      );
      currentTable = [];
      return tableEl;
    };

    lines.forEach((line, idx) => {
      const isTableRow = line.trim().startsWith('|') && line.trim().includes('|');

      if (isTableRow) {
        const cells = line.trim().split('|').filter((_, i, arr) => i > 0 && i < arr.length - 1);
        currentTable.push(cells);
      } else {
        const table = flushTable(idx);
        if (table) elements.push(table);

        if (line.startsWith('###')) {
          elements.push(<h3 key={idx} className="text-sm font-black mt-6 mb-3 uppercase border-b-2 border-[#1A1A1A] pb-1">{line.replace('###', '')}</h3>);
        } else if (line.trim().startsWith('- ') || line.trim().startsWith('* ')) {
          elements.push(
            <li key={idx} className="ml-4 mb-2 text-[11px] font-bold uppercase tracking-tight list-none flex items-start gap-3">
              <span className="mt-1 w-1.5 h-1.5 bg-[#1A1A1A] flex-shrink-0"></span>
              <span>{parseInlineStyles(line.trim().substring(2))}</span>
            </li>
          );
        } else if (line.trim().match(/^\d+\./)) {
           elements.push(
            <li key={idx} className="ml-4 mb-2 text-[11px] font-bold uppercase tracking-tight list-none flex items-start gap-3">
              <span className="text-[#7A7A7A] font-black">{line.trim().split('.')[0]}.</span>
              <span>{parseInlineStyles(line.trim().split('.').slice(1).join('.').trim())}</span>
            </li>
          );
        } else if (line.trim() === '') {
          elements.push(<div key={idx} className="h-4" />);
        } else {
          elements.push(<p key={idx} className="text-[11px] font-medium leading-relaxed mb-3 text-[#333]">{parseInlineStyles(line)}</p>);
        }
      }
    });

    const finalTable = flushTable(lines.length);
    if (finalTable) elements.push(finalTable);

    return elements;
  };

  return (
    <div className="flex h-full bg-[#F2EFEA] overflow-hidden">
      {showHistory && (
        <div className="w-72 bg-white border-r-2 border-[#1A1A1A] flex flex-col h-full animate-in slide-in-from-left duration-300">
          <div className="p-6 border-b-2 border-[#1A1A1A] flex flex-col gap-4">
            <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-[#7A7A7A]">Histórico de Threads</h3>
            <button 
              onClick={createNewChat}
              className="w-full sketch-button py-3 text-[10px] font-black uppercase tracking-widest"
            >
              + Novo Chat
            </button>
          </div>
          <div className="flex-1 overflow-y-auto p-4 space-y-3">
            {sessions.length === 0 ? (
              <p className="text-[9px] font-bold text-center text-[#B5B5B5] mt-10 uppercase">Sem conversas ativas</p>
            ) : (
              sessions.map((s) => (
                <div
                  key={s.id}
                  onClick={() => switchSession(s.id)}
                  className={`group relative p-4 sketch-border cursor-pointer transition-all ${
                    currentSessionId === s.id 
                      ? 'bg-[#1A1A1A] text-white shadow-[0_0_15px_rgba(26,26,26,0.2)]' 
                      : 'bg-white hover:bg-[#F2EFEA]'
                  }`}
                >
                  <div className="flex justify-between items-start gap-2">
                    <p className="text-[10px] font-black uppercase truncate flex-1">{s.title || 'Nova Conversa'}</p>
                    <button 
                      onClick={(e) => handleDeleteSession(s.id, e)}
                      className="opacity-0 group-hover:opacity-100 transition-opacity p-1 text-[#7A7A7A] hover:text-rose-500"
                      title="Mover para Lixeira"
                    >
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                      </svg>
                    </button>
                  </div>
                  <p className={`text-[8px] font-bold mt-1 ${currentSessionId === s.id ? 'text-gray-400' : 'text-[#7A7A7A]'}`}>
                    {s.lastUpdate.toLocaleDateString()} • {s.messages?.length || 0} msg
                  </p>
                </div>
              ))
            )}
          </div>
        </div>
      )}

      <div className="flex-1 flex flex-col h-full relative">
        <header className="p-6 border-b-2 border-[#1A1A1A] bg-white flex justify-between items-center z-10">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => setShowHistory(!showHistory)}
              className="p-2 border-2 border-[#1A1A1A] hover:bg-[#1A1A1A] hover:text-white transition-colors"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
              </svg>
            </button>
            <div>
              <h2 className="text-xl font-black text-[#1A1A1A] uppercase tracking-tighter leading-none">
                {sessions.find(s => s.id === currentSessionId)?.title || 'NOVA CONVERSA'}
              </h2>
              <p className="text-[8px] font-black text-[#7A7A7A] uppercase tracking-widest mt-1">Sessão Ativa • Protocolo FinaIGPT</p>
            </div>
          </div>
        </header>

        <div ref={scrollRef} className="flex-1 overflow-y-auto p-8 space-y-8 pb-32">
          {messages.map((msg) => (
            <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[85%] sketch-border p-6 relative group ${msg.role === 'user' ? 'bg-[#1A1A1A] text-white' : 'bg-white text-[#1A1A1A]'}`}>
                <div className="flex justify-between items-center mb-6 border-b border-[#B5B5B5]/30 pb-2">
                  <span className={`text-[8px] font-black uppercase tracking-widest ${msg.role === 'user' ? 'text-[#7A7A7A]' : 'text-[#1A1A1A]'}`}>
                    {msg.role === 'user' ? 'AUTENTICADO_USER' : 'FINAIGPT_CORE'}
                  </span>
                  <div className="flex items-center gap-4">
                    <span className="text-[8px] font-bold opacity-40 uppercase">{msg.timestamp.toLocaleTimeString()}</span>
                    <button 
                      onClick={() => handleCopy(msg.content, msg.id)}
                      className="text-[8px] font-black hover:underline uppercase transition-opacity opacity-0 group-hover:opacity-100"
                    >
                      {copyStatus === msg.id ? 'COPIADO' : 'COPIAR'}
                    </button>
                  </div>
                </div>

                <div className="chat-content">
                  {renderFormattedContent(msg.content)}
                </div>

                {msg.sources && msg.sources.length > 0 && (
                  <div className="mt-8 pt-4 border-t-2 border-[#1A1A1A]/10">
                    <div className="flex items-center gap-2 mb-3">
                      <svg className="w-3 h-3 text-[#4285F4]" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1 17.93c-3.95-.49-7-3.85-7-7.93 0-.62.08-1.21.21-1.79L9 15v1c0 1.1.9 2 2 2h1v1.93zM17.01 19c-.39-.33-.79-.66-1.18-1-.31-.26-.64-.51-.97-.75C12.44 15.68 11 13 11 11v-1l4 2 2-1V9l-5-2-4 2v2l-1.6 1.6C5.07 11.25 5 10.14 5 9c0-3.86 3.14-7 7-7s7 3.14 7 7c0 1.92-.77 3.66-2.02 4.93-.01.01-.01.02-.02.03-.64.65-1.37 1.19-2.18 1.61-.1.05-.2.09-.3.14-.14.07-.28.14-.42.21-.01.01-.02.01-.03.02-.01.01-.02.01-.03.02L17.01 19z"/></svg>
                      <p className="text-[7px] font-black uppercase text-[#4285F4] tracking-widest">Fontes de Grounding Detectadas ({msg.sources.length}):</p>
                    </div>
                    <div className="flex flex-wrap gap-2">
                      {msg.sources.map((url, i) => (
                        <a 
                          key={i} 
                          href={url} 
                          target="_blank" 
                          rel="noopener noreferrer" 
                          className="bg-gray-50 border border-gray-200 px-3 py-1 text-[8px] font-bold text-blue-600 hover:bg-blue-50 transition-colors flex items-center gap-2"
                        >
                          <span className="w-1.5 h-1.5 bg-blue-500"></span>
                          {new URL(url).hostname.replace('www.', '')}
                        </a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          ))}
          {isTyping && (
            <div className="flex justify-start">
              <div className="bg-white sketch-border p-3 flex gap-2">
                <div className="w-1 h-1 bg-[#1A1A1A] animate-bounce"></div>
                <div className="w-1 h-1 bg-[#1A1A1A] animate-bounce [animation-delay:0.2s]"></div>
                <div className="w-1 h-1 bg-[#1A1A1A] animate-bounce [animation-delay:0.4s]"></div>
              </div>
            </div>
          )}
        </div>

        <div className="absolute bottom-0 left-0 right-0 p-8 bg-gradient-to-t from-[#F2EFEA] via-[#F2EFEA] to-transparent">
          <div className="max-w-4xl mx-auto flex gap-4">
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Digite sua consulta contábil ou financeira..."
              className="flex-1 bg-white sketch-border px-6 py-4 outline-none font-bold text-xs uppercase tracking-widest focus:ring-2 focus:ring-[#1A1A1A]/10 transition-all"
            />
            <button 
              onClick={handleSend}
              disabled={isTyping}
              className="sketch-button px-10 py-4 font-black uppercase tracking-widest text-xs disabled:opacity-50 flex items-center gap-3"
            >
              {isTyping ? 'PROCESSANDO' : 'ENVIAR'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ChatInterface;

export interface User {
  id: string;
  name: string;
  email: string;
  avatar: string;
}

export interface Message {
  id: string;
  role: 'user' | 'model';
  content: string;
  timestamp: Date;
  sources?: string[];
}

export type SyncStatus = 'synced' | 'pending' | 'local';

export interface ChatSession {
  id: string;
  title: string;
  messages: Message[];
  lastUpdate: Date;
  deletedAt?: Date;
  // Sync fields
  syncStatus?: SyncStatus;
  syncedAt?: Date;
}

export type DocumentSource = 'local' | 'google_docs' | 'google_sheets' | 'google_analytics';

export interface Document {
  id: string;
  name: string;
  content: string;
  type: string;
  uploadDate: Date;
  size: number;
  sourceType: DocumentSource;
  externalUrl?: string;
  metadata?: {
    propertyId?: string;
    lastSync?: Date;
    category?: 'cost' | 'tax' | 'management' | 'general' | 'exercise';
  };
}

export interface Candle {
  time: string;
  open: number;
  high: number;
  low: number;
  close: number;
}

export interface MarketData {
  symbol: string;
  name: string;
  price: number;
  change: number;
  history: Candle[];
}

export enum ViewState {
  Dashboard = 'DASHBOARD',
  Chat = 'CHAT',
  Documents = 'DOCUMENTS',
  Reports = 'REPORTS',
  Trash = 'TRASH'
}

import { Document, User, ChatSession, SyncStatus } from '../types';

const DOCS_KEY = 'finan_gpt_docs';
const USER_KEY = 'finan_gpt_user';
const CHATS_KEY = 'finan_gpt_chats';

export const StorageService = {
  // Documentos
  getDocuments: (): Document[] => {
    try {
      const data = localStorage.getItem(DOCS_KEY);
      return data ? JSON.parse(data) : [];
    } catch (e) {
      console.error("Error reading documents", e);
      return [];
    }
  },

  saveDocument: (doc: Document) => {
    const docs = StorageService.getDocuments();
    docs.push(doc);
    localStorage.setItem(DOCS_KEY, JSON.stringify(docs));
  },

  deleteDocument: (id: string) => {
    const docs = StorageService.getDocuments().filter(d => d.id !== id);
    localStorage.setItem(DOCS_KEY, JSON.stringify(docs));
  },

  // Usuário
  getUser: (): User | null => {
    try {
      const data = localStorage.getItem(USER_KEY);
      return data ? JSON.parse(data) : null;
    } catch (e) {
      return null;
    }
  },

  setUser: (user: User) => {
    localStorage.setItem(USER_KEY, JSON.stringify(user));
  },

  // Sessões de Chat
  getChatSessions: (includeDeleted: boolean = false): ChatSession[] => {
    const data = localStorage.getItem(CHATS_KEY);
    if (!data) return [];

    try {
      const parsed = JSON.parse(data);
      if (!Array.isArray(parsed)) return [];

      const sessions = parsed.map((s: any) => ({
        ...s,
        lastUpdate: new Date(s.lastUpdate),
        deletedAt: s.deletedAt ? new Date(s.deletedAt) : undefined,
        syncedAt: s.syncedAt ? new Date(s.syncedAt) : undefined,
        messages: (s.messages || []).map((m: any) => ({ 
          ...m, 
          timestamp: new Date(m.timestamp) 
        }))
      }));

      return includeDeleted ? sessions : sessions.filter(s => !s.deletedAt);
    } catch (e) {
      console.error("Failed to parse chat sessions", e);
      return [];
    }
  },

  saveChatSession: (session: ChatSession) => {
    const sessions = StorageService.getChatSessions(true);
    const index = sessions.findIndex(s => s.id === session.id);

    // Flag as pending sync if it's being updated and we have a user
    const user = StorageService.getUser();
    const updatedSession = { 
      ...session, 
      syncStatus: user ? 'pending' : 'local' as SyncStatus 
    };

    if (index >= 0) {
      sessions[index] = updatedSession;
    } else {
      sessions.push(updatedSession);
    }

    localStorage.setItem(CHATS_KEY, JSON.stringify(sessions));

    // Simulate background sync if user is logged in
    if (user) {
      StorageService.syncSessionWithCloud(updatedSession.id);
    }
  },

  syncSessionWithCloud: async (sessionId: string) => {
    // Artificial delay to simulate network latency
    setTimeout(() => {
      const sessions = StorageService.getChatSessions(true);
      const index = sessions.findIndex(s => s.id === sessionId);
      if (index >= 0 && sessions[index].syncStatus === 'pending') {
        sessions[index].syncStatus = 'synced';
        sessions[index].syncedAt = new Date();
        localStorage.setItem(CHATS_KEY, JSON.stringify(sessions));

        // Dispatch custom event to notify UI of sync completion
        window.dispatchEvent(new CustomEvent('session_synced', { detail: sessionId }));
      }
    }, 2000);
  },

  deleteChatSession: (id: string) => {
    const sessions = StorageService.getChatSessions(true);
    const index = sessions.findIndex(s => s.id === id);
    if (index >= 0) {
      sessions[index].deletedAt = new Date();
      sessions[index].syncStatus = 'pending';
      localStorage.setItem(CHATS_KEY, JSON.stringify(sessions));
      StorageService.syncSessionWithCloud(id);
    }
  },

  restoreFromTrash: (id: string) => {
    const sessions = StorageService.getChatSessions(true);
    const index = sessions.findIndex(s => s.id === id);
    if (index >= 0) {
      delete sessions[index].deletedAt;
      sessions[index].syncStatus = 'pending';
      localStorage.setItem(CHATS_KEY, JSON.stringify(sessions));
      StorageService.syncSessionWithCloud(id);
    }
  },

  deletePermanently: (id: string) => {
    const sessions = StorageService.getChatSessions(true);
    const updatedSessions = sessions.filter(s => s.id !== id);
    localStorage.setItem(CHATS_KEY, JSON.stringify(updatedSessions));
  },

  clearAll: () => {
    localStorage.removeItem(DOCS_KEY);
    localStorage.removeItem(USER_KEY);
    localStorage.removeItem(CHATS_KEY);
  }
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Message, ChatSession, SyncStatus } from '../types.ts';
import { GeminiService } from '../services/geminiService.ts';
import { StorageService } from '../services/storage.ts';

const ChatInterface: React.FC = () => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string>('');
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [copyStatus, setCopyStatus] = useState<string | null>(null);
  const [showHistory, setShowHistory] = useState(true);
  const scrollRef = useRef<HTMLDivElement>(null);

  const WELCOME_MESSAGE: Message = {
    id: 'welcome',
    role: 'model',
    content: '### TERMINAL FINAIGPT INICIALIZADO\n\nPronto para consultoria, análise de mercado e treinamento contábil.\n\n- **Modo Educacional:** Ativo\n- **RAG Engine:** Processando documentos\n- **Cloud Sync:** Sincronizado com sua Google Account\n\n**Sugestões:**\n1. "Crie um exercício de DRE."\n2. "Explique o impacto da Selic no varejo."',
    timestamp: new Date()
  };

  const loadData = useCallback(() => {
    const activeSessions = StorageService.getChatSessions();
    setSessions(activeSessions);

    if (currentSessionId) {
      const current = activeSessions.find(s => s.id === currentSessionId);
      if (current) setMessages(current.messages);
    } else if (activeSessions.length > 0) {
      const last = activeSessions[0];
      setCurrentSessionId(last.id);
      setMessages(last.messages);
    } else {
      const newId = Date.now().toString();
      setCurrentSessionId(newId);
      setMessages([WELCOME_MESSAGE]);
    }
  }, [currentSessionId]);

  useEffect(() => {
    loadData();

    const handleSyncEvent = (e: any) => {
      // Refresh session list to show updated cloud icons
      setSessions(StorageService.getChatSessions());
    };

    window.addEventListener('session_synced', handleSyncEvent);
    return () => window.removeEventListener('session_synced', handleSyncEvent);
  }, [loadData]);

  const persistSession = useCallback((id: string, msgs: Message[], title?: string) => {
    if (!id || msgs.length === 0) return;

    const existingSession = StorageService.getChatSessions().find(s => s.id === id);
    const newTitle = title || existingSession?.title || (msgs.find(m => m.role === 'user')?.content.substring(0, 30)) || 'Nova Conversa';

    const session: ChatSession = {
      id,
      title: newTitle,
      messages: msgs,
      lastUpdate: new Date()
    };

    StorageService.saveChatSession(session);
    setSessions(StorageService.getChatSessions());
  }, []);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const createNewChat = () => {
    const newId = Date.now().toString();
    setCurrentSessionId(newId);
    setMessages([WELCOME_MESSAGE]);
  };

  const switchSession = (id: string) => {
    const session = sessions.find(s => s.id === id);
    if (session) {
      setCurrentSessionId(session.id);
      setMessages(session.messages);
    }
  };

  const handleDeleteSession = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (window.confirm("Deseja mover este chat para a lixeira?")) {
      StorageService.deleteChatSession(id);
      const remaining = StorageService.getChatSessions();
      setSessions(remaining);

      if (currentSessionId === id) {
        if (remaining.length > 0) {
          const next = remaining[0];
          setCurrentSessionId(next.id);
          setMessages(next.messages);
        } else {
          createNewChat();
        }
      }
    }
  };

  const handleCopy = (content: string, id: string) => {
    navigator.clipboard.writeText(content);
    setCopyStatus(id);
    setTimeout(() => setCopyStatus(null), 2000);
  };

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      timestamp: new Date()
    };

    const newMessages = [...messages, userMessage];
    setMessages(newMessages);
    const currentInput = input;
    setInput('');
    setIsTyping(true);

    persistSession(currentSessionId, newMessages);

    const isFirstUserMessage = messages.filter(m => m.role === 'user').length === 0;
    if (isFirstUserMessage) {
      GeminiService.generateTitle(currentInput).then(generatedTitle => {
        persistSession(currentSessionId, newMessages, generatedTitle);
      });
    }

    try {
      const response = await GeminiService.generateChatResponse(currentInput, messages);
      const sources: string[] = [];

      if (response.groundingMetadata?.groundingChunks) {
        response.groundingMetadata.groundingChunks.forEach((chunk: any) => {
          if (chunk.web?.uri) sources.push(chunk.web.uri);
          else if (chunk.maps?.uri) sources.push(chunk.maps.uri);
        });
      }

      const modelMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: response.text,
        timestamp: new Date(),
        sources: sources.length > 0 ? Array.from(new Set(sources)) : undefined
      };

      const finalMessages = [...newMessages, modelMessage];
      setMessages(finalMessages);
      persistSession(currentSessionId, finalMessages);
    } catch (error) {
      setMessages(prev => [...prev, {
        id: Date.now().toString(),
        role: 'model',
        content: '### ERRO CRÍTICO\nNão foi possível processar a consulta.',
        timestamp: new Date()
      }]);
    } finally {
      setIsTyping(false);
    }
  };

  const renderSyncIcon = (status?: SyncStatus) => {
    switch (status) {
      case 'synced':
        return (
          <svg className="w-3 h-3 text-emerald-500" fill="currentColor" viewBox="0 0 24 24">
            <path d="M17.5 19c2.5 0 4.5-2 4.5-4.5 0-2-1.3-3.7-3.2-4.2-.3-2.7-2.6-4.8-5.3-4.8-2.1 0-3.9 1.2-4.8 3-2.1.2-3.7 2-3.7 4.1C5 17 6.8 19 9 19h8.5z" />
            <path className="text-white" d="M10 13l2 2 4-4" fill="none" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
        );
      case 'pending':
        return (
          <svg className="w-3 h-3 text-blue-500 animate-pulse" fill="currentColor" viewBox="0 0 24 24">
            <path d="M17.5 19c2.5 0 4.5-2 4.5-4.5 0-2-1.3-3.7-3.2-4.2-.3-2.7-2.6-4.8-5.3-4.8-2.1 0-3.9 1.2-4.8 3-2.1.2-3.7 2-3.7 4.1C5 17 6.8 19 9 19h8.5z" />
          </svg>
        );
      default:
        return (
          <svg className="w-3 h-3 text-gray-300" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 15a4 4 0 004 4h9a5 5 0 10-.1-9.999 5.002 5.002 0 10-9.78 2.096A4.001 4.001 0 003 15z" />
          </svg>
        );
    }
  };

  const parseInlineStyles = (text: string) => {
    const parts = text.split(/(\*\*.*?\*\*|\*.*?\*)/g);
    return parts.map((part, i) => {
      if (part.startsWith('**') && part.endsWith('**')) {
        return <strong key={i} className="font-black text-[#1A1A1A]">{part.slice(2, -2)}</strong>;
      }
      if (part.startsWith('*') && part.endsWith('*')) {
        return <em key={i} className="italic font-medium">{part.slice(1, -1)}</em>;
      }
      return part;
    });
  };

  const renderFormattedContent = (content: string) => {
    const lines = content.split('\n');
    let elements: React.ReactNode[] = [];
    let currentTable: string[][] = [];

    const flushTable = (key: number) => {
      if (currentTable.length === 0) return null;
      const hasHeader = currentTable.length > 1 && currentTable[1].every(cell => cell.trim().match(/^-+$/));
      const headerRow = hasHeader ? currentTable[0] : null;
      const dataRows = hasHeader ? currentTable.slice(2) : currentTable;

      const tableEl = (
        <div key={`table-${key}`} className="my-6 overflow-x-auto sketch-border p-1 bg-white">
          <table className="w-full border-collapse text-[10px] text-[#1A1A1A]">
            {headerRow && (
              <thead>
                <tr className="bg-[#1A1A1A] text-white">
                  {headerRow.map((cell, i) => (
                    <th key={i} className="px-4 py-3 border-2 border-[#1A1A1A] text-left uppercase font-black tracking-widest">{cell.trim()}</th>
                  ))}
                </tr>
              </thead>
            )}
            <tbody>
              {dataRows.map((row, i) => (
                <tr key={i} className="bg-white hover:bg-[#F2EFEA] transition-colors">
                  {row.map((cell, j) => (
                    <td key={j} className="px-4 py-3 border-2 border-[#1A1A1A] font-bold uppercase">{parseInlineStyles(cell.trim())}</td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      );
      currentTable = [];
      return tableEl;
    };

    lines.forEach((line, idx) => {
      const isTableRow = line.trim().startsWith('|') && line.trim().includes('|');
      if (isTableRow) {
        const cells = line.trim().split('|').filter((_, i, arr) => i > 0 && i < arr.length - 1);
        currentTable.push(cells);
      } else {
        const table = flushTable(idx);
        if (table) elements.push(table);
        if (line.startsWith('###')) {
          elements.push(<h3 key={idx} className="text-sm font-black mt-6 mb-3 uppercase border-b-2 border-[#1A1A1A] pb-1">{line.replace('###', '')}</h3>);
        } else if (line.trim().startsWith('- ') || line.trim().startsWith('* ')) {
          elements.push(
            <li key={idx} className="ml-4 mb-2 text-[11px] font-bold uppercase tracking-tight flex items-start gap-3 list-none">
              <span className="mt-1 w-1.5 h-1.5 bg-[#1A1A1A] flex-shrink-0"></span>
              <span>{parseInlineStyles(line.trim().substring(2))}</span>
            </li>
          );
        } else if (line.trim() === '') {
          elements.push(<div key={idx} className="h-4" />);
        } else {
          elements.push(<p key={idx} className="text-[11px] font-medium leading-relaxed mb-3 text-[#333]">{parseInlineStyles(line)}</p>);
        }
      }
    });
    const finalTable = flushTable(lines.length);
    if (finalTable) elements.push(finalTable);
    return elements;
  };

  return (
    <div className="flex h-full bg-[#F2EFEA] overflow-hidden">
      {showHistory && (
        <div className="w-72 bg-white border-r-2 border-[#1A1A1A] flex flex-col h-full animate-in slide-in-from-left duration-300">
          <div className="p-6 border-b-2 border-[#1A1A1A] flex flex-col gap-4">
            <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-[#7A7A7A]">Histórico de Threads</h3>
            <button onClick={createNewChat} className="w-full sketch-button py-3 text-[10px] font-black uppercase tracking-widest">+ Novo Chat</button>
          </div>
          <div className="flex-1 overflow-y-auto p-4 space-y-3">
            {sessions.map((s) => (
              <div key={s.id} onClick={() => switchSession(s.id)} className={`group relative p-4 sketch-border cursor-pointer transition-all ${currentSessionId === s.id ? 'bg-[#1A1A1A] text-white shadow-[0_0_15px_rgba(26,26,26,0.2)]' : 'bg-white hover:bg-[#F2EFEA]'}`}>
                <div className="flex justify-between items-start gap-2">
                  <p className="text-[10px] font-black uppercase truncate flex-1">{s.title || 'Nova Conversa'}</p>
                  <div className="flex items-center gap-1">
                    {renderSyncIcon(s.syncStatus)}
                    <button onClick={(e) => handleDeleteSession(s.id, e)} className="opacity-0 group-hover:opacity-100 transition-opacity p-1 text-[#7A7A7A] hover:text-rose-500">
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                      </svg>
                    </button>
                  </div>
                </div>
                <p className={`text-[8px] font-bold mt-1 ${currentSessionId === s.id ? 'text-gray-400' : 'text-[#7A7A7A]'}`}>{s.lastUpdate.toLocaleDateString()} • {s.messages?.length || 0} msg</p>
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="flex-1 flex flex-col h-full relative">
        <header className="p-6 border-b-2 border-[#1A1A1A] bg-white flex justify-between items-center z-10">
          <div className="flex items-center gap-4">
            <button onClick={() => setShowHistory(!showHistory)} className="p-2 border-2 border-[#1A1A1A] hover:bg-[#1A1A1A] hover:text-white transition-colors">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg>
            </button>
            <div>
              <h2 className="text-xl font-black text-[#1A1A1A] uppercase tracking-tighter leading-none">{sessions.find(s => s.id === currentSessionId)?.title || 'NOVA CONVERSA'}</h2>
              <div className="flex items-center gap-2 mt-1">
                <p className="text-[8px] font-black text-[#7A7A7A] uppercase tracking-widest">Sessão Ativa • Protocolo FinaIGPT</p>
                <div className="h-1 w-1 bg-emerald-500 rounded-full"></div>
                <span className="text-[7px] font-black text-emerald-600 uppercase tracking-widest">Sincronizado com Google Account</span>
              </div>
            </div>
          </div>
        </header>

        <div ref={scrollRef} className="flex-1 overflow-y-auto p-8 space-y-8 pb-32">
          {messages.map((msg) => (
            <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[85%] sketch-border p-6 relative group ${msg.role === 'user' ? 'bg-[#1A1A1A] text-white' : 'bg-white text-[#1A1A1A]'}`}>
                <div className="flex justify-between items-center mb-6 border-b border-[#B5B5B5]/30 pb-2">
                  <span className={`text-[8px] font-black uppercase tracking-widest ${msg.role === 'user' ? 'text-[#7A7A7A]' : 'text-[#1A1A1A]'}`}>
                    {msg.role === 'user' ? 'AUTENTICADO_USER' : 'FINAIGPT_CORE'}
                  </span>
                  <div className="flex items-center gap-4">
                    <span className="text-[8px] font-bold opacity-40 uppercase">{msg.timestamp.toLocaleTimeString()}</span>
                    <button onClick={() => handleCopy(msg.content, msg.id)} className="text-[8px] font-black hover:underline uppercase transition-opacity opacity-0 group-hover:opacity-100">{copyStatus === msg.id ? 'COPIADO' : 'COPIAR'}</button>
                  </div>
                </div>
                <div className="chat-content">{renderFormattedContent(msg.content)}</div>
                {msg.sources && msg.sources.length > 0 && (
                  <div className="mt-8 pt-4 border-t-2 border-[#1A1A1A]/10">
                    <p className="text-[7px] font-black uppercase text-[#4285F4] tracking-widest mb-3">Fontes de Grounding ({msg.sources.length}):</p>
                    <div className="flex flex-wrap gap-2">
                      {msg.sources.map((url, i) => (
                        <a key={i} href={url} target="_blank" rel="noopener noreferrer" className="bg-gray-50 border border-gray-200 px-3 py-1 text-[8px] font-bold text-blue-600 hover:bg-blue-50 transition-colors flex items-center gap-2">
                          <span className="w-1.5 h-1.5 bg-blue-500"></span>
                          {new URL(url).hostname.replace('www.', '')}
                        </a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          ))}
          {isTyping && (
            <div className="flex justify-start">
              <div className="bg-white sketch-border p-3 flex gap-2">
                <div className="w-1 h-1 bg-[#1A1A1A] animate-bounce"></div>
                <div className="w-1 h-1 bg-[#1A1A1A] animate-bounce [animation-delay:0.2s]"></div>
                <div className="w-1 h-1 bg-[#1A1A1A] animate-bounce [animation-delay:0.4s]"></div>
              </div>
            </div>
          )}
        </div>

        <div className="absolute bottom-0 left-0 right-0 p-8 bg-gradient-to-t from-[#F2EFEA] via-[#F2EFEA] to-transparent">
          <div className="max-w-4xl mx-auto flex gap-4">
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Digite sua consulta contábil ou financeira..."
              className="flex-1 bg-white sketch-border px-6 py-4 outline-none font-bold text-xs uppercase tracking-widest focus:ring-2 focus:ring-[#1A1A1A]/10 transition-all"
            />
            <button onClick={handleSend} disabled={isTyping} className="sketch-button px-10 py-4 font-black uppercase tracking-widest text-xs disabled:opacity-50 flex items-center gap-3">
              {isTyping ? 'PROCESSANDO' : 'ENVIAR'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

