        else if (line.trim() !== '') elements.push(<p key={idx} className="text-[11px] font-medium leading-relaxed mb-3">{parseInlineStyles(line)}</p>);
      }
    });
    const finalTable = flushTable(lines.length);
    if (finalTable) elements.push(finalTable);
    return elements;
  };

  return (
    <div className="flex h-full bg-[#F2EFEA] overflow-hidden">
      {showHistory && (
        <div className="w-72 bg-white border-r-2 border-[#1A1A1A] flex flex-col h-full animate-in slide-in-from-left duration-300">
          <div className="p-6 border-b-2 border-[#1A1A1A] flex flex-col gap-4">
            <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-[#7A7A7A]">Histórico Sync</h3>
            <button onClick={createNewChat} className="w-full sketch-button py-3 text-[10px] font-black uppercase tracking-widest">+ Novo Chat</button>
          </div>
          <div className="flex-1 overflow-y-auto p-4 space-y-3">
            {sessions.map((s) => (
