import { Document, User, ChatSession, SyncStatus } from '../types.ts';

const DOCS_KEY = 'finan_gpt_docs';
const USER_KEY = 'finan_gpt_user';
const CHATS_KEY = 'finan_gpt_chats';

export const StorageService = {
  // Documentos
  getDocuments: (): Document[] => {
    try {
      const data = localStorage.getItem(DOCS_KEY);
      if (!data) return [];
      const docs = JSON.parse(data);
      return docs.map((d: any) => ({
        ...d,
        uploadDate: new Date(d.uploadDate),
        metadata: {
          ...d.metadata,
          lastSync: d.metadata?.lastSync ? new Date(d.metadata.lastSync) : undefined
        }
      }));
    } catch (e) {
      console.error("Error reading documents", e);
      return [];
    }
  },

  saveDocument: (doc: Document) => {
    const docs = StorageService.getDocuments();
    docs.push(doc);
    localStorage.setItem(DOCS_KEY, JSON.stringify(docs));
  },

  deleteDocument: (id: string) => {
    const docs = StorageService.getDocuments().filter(d => d.id !== id);
    localStorage.setItem(DOCS_KEY, JSON.stringify(docs));
  },

  // Usuário
  getUser: (): User | null => {
    try {
      const data = localStorage.getItem(USER_KEY);
      return data ? JSON.parse(data) : null;
    } catch (e) {
      return null;
    }
  },

  setUser: (user: User) => {
    localStorage.setItem(USER_KEY, JSON.stringify(user));
  },

  // Sessões de Chat
  getChatSessions: (includeDeleted: boolean = false): ChatSession[] => {
    const data = localStorage.getItem(CHATS_KEY);
    if (!data) return [];

    try {
      const parsed = JSON.parse(data);
      if (!Array.isArray(parsed)) return [];

      const sessions = parsed.map((s: any) => ({
        ...s,
        lastUpdate: new Date(s.lastUpdate),
        deletedAt: s.deletedAt ? new Date(s.deletedAt) : undefined,
        syncedAt: s.syncedAt ? new Date(s.syncedAt) : undefined,
        messages: (s.messages || []).map((m: any) => ({ 
          ...m, 
          timestamp: new Date(m.timestamp) 
        }))
      }));

      return includeDeleted ? sessions : sessions.filter(s => !s.deletedAt);
    } catch (e) {
      console.error("Failed to parse chat sessions", e);
      return [];
    }
  },

  saveChatSession: (session: ChatSession) => {
    const sessions = StorageService.getChatSessions(true);
    const index = sessions.findIndex(s => s.id === session.id);

    const user = StorageService.getUser();
    const updatedSession = { 
      ...session, 
      syncStatus: user ? 'pending' : 'local' as SyncStatus 
    };

    if (index >= 0) {
      sessions[index] = updatedSession;
    } else {
      sessions.unshift(updatedSession); // New sessions at top
    }

    localStorage.setItem(CHATS_KEY, JSON.stringify(sessions));

    if (user) {
      StorageService.syncSessionWithCloud(updatedSession.id);
    }
  },

  syncSessionWithCloud: async (sessionId: string) => {
    setTimeout(() => {
      const sessions = StorageService.getChatSessions(true);
      const index = sessions.findIndex(s => s.id === sessionId);
      if (index >= 0 && sessions[index].syncStatus === 'pending') {
        sessions[index].syncStatus = 'synced';
        sessions[index].syncedAt = new Date();
        localStorage.setItem(CHATS_KEY, JSON.stringify(sessions));
        window.dispatchEvent(new CustomEvent('session_synced', { detail: sessionId }));
      }
    }, 1500);
  },

  deleteChatSession: (id: string) => {
    const sessions = StorageService.getChatSessions(true);
    const index = sessions.findIndex(s => s.id === id);
    if (index >= 0) {
      sessions[index].deletedAt = new Date();
      sessions[index].syncStatus = 'pending';
      localStorage.setItem(CHATS_KEY, JSON.stringify(sessions));
      StorageService.syncSessionWithCloud(id);
    }
  },

  restoreFromTrash: (id: string) => {
    const sessions = StorageService.getChatSessions(true);
    const index = sessions.findIndex(s => s.id === id);
    if (index >= 0) {
      delete sessions[index].deletedAt;
      sessions[index].syncStatus = 'pending';
      localStorage.setItem(CHATS_KEY, JSON.stringify(sessions));
      StorageService.syncSessionWithCloud(id);
    }
  },

  deletePermanently: (id: string) => {
    const sessions = StorageService.getChatSessions(true);
    const updatedSessions = sessions.filter(s => s.id !== id);
    localStorage.setItem(CHATS_KEY, JSON.stringify(updatedSessions));
  },

  clearAll: () => {
    localStorage.clear();
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { Document, DocumentSource } from '../types.ts';
import { StorageService } from '../services/storage.ts';

// Declare external libs for TypeScript
declare const pdfjsLib: any;
declare const mammoth: any;

const DocumentManager: React.FC = () => {
  const [documents, setDocuments] = useState<Document[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [activeTab, setActiveTab] = useState<'local' | 'cloud'>('local');
  const [parsingStatus, setParsingStatus] = useState<string>('');
  const [searchTerm, setSearchTerm] = useState('');
  const [externalUrl, setExternalUrl] = useState('');
  const [selectedProvider, setSelectedProvider] = useState<DocumentSource>('google_docs');
  const [selectedCategory, setSelectedCategory] = useState<'cost' | 'tax' | 'management' | 'general' | 'exercise'>('general');

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    setDocuments(StorageService.getDocuments());
    // Configure PDF.js worker
    if (typeof pdfjsLib !== 'undefined') {
      pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
    }
  }, []);

  const parsePDF = async (file: File): Promise<string> => {
    const arrayBuffer = await file.arrayBuffer();
    const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
    let fullText = "";
    for (let i = 1; i <= pdf.numPages; i++) {
      const page = await pdf.getPage(i);
      const textContent = await page.getTextContent();
      const pageText = textContent.items.map((item: any) => item.str).join(" ");
      fullText += pageText + "\n";
    }
    return fullText;
  };

  const parseDOCX = async (file: File): Promise<string> => {
    const arrayBuffer = await file.arrayBuffer();
    const result = await mammoth.extractRawText({ arrayBuffer });
    return result.value;
  };

  const handleFiles = async (files: FileList) => {
    setIsUploading(true);
    const filesArray = Array.from(files);

    for (const file of filesArray) {
      try {
        setParsingStatus(`Processando ${file.name}...`);
        let content = "";

        if (file.type === "application/pdf") {
          content = await parsePDF(file);
        } else if (file.type === "application/vnd.openxmlformats-officedocument.wordprocessingml.document") {
          content = await parseDOCX(file);
        } else {
          content = await file.text();
        }

        const doc: Document = {
          id: Math.random().toString(36).substr(2, 9),
          name: file.name,
          content: content,
          type: file.type || 'text/plain',
          uploadDate: new Date(),
          size: file.size,
          sourceType: 'local',
          metadata: {
            category: selectedCategory,
            lastSync: new Date()
          }
        };

        StorageService.saveDocument(doc);
        setDocuments(prev => [doc, ...prev]);
      } catch (e) {
        console.error(`Falha ao ler ${file.name}:`, e);
      }
    }

    setIsUploading(false);
    setParsingStatus('');
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleAddExternal = async () => {
    if (!externalUrl) return;
    setIsUploading(true);
    setParsingStatus('Sincronizando com Google Workspace API...');

