export interface MarketRates {
  usd_brl: number;
  eur_brl: number;
  gbp_brl: number;
  btc_brl: number;
  eth_brl: number;
  last_update: string;
}

export interface StockInfo {
  symbol: string;
  name: string;
  price: string;
  change: string;
  isPositive: boolean;
}

export const MarketService = {
  fetchExchangeRates: async (): Promise<MarketRates> => {
    try {
      const fiatResponse = await fetch('https://open.er-api.com/v6/latest/USD');
      if (!fiatResponse.ok) throw new Error('API Fiduciária Down');
      const fiatData = await fiatResponse.json();
      const brl = fiatData.rates.BRL || 5.65;

      const [btcRes, ethRes] = await Promise.all([
        fetch('https://api.binance.com/api/v3/ticker/price?symbol=BTCBRL').catch(() => null),
        fetch('https://api.binance.com/api/v3/ticker/price?symbol=ETHBRL').catch(() => null)
      ]);

      let btc_brl = brl / (fiatData.rates.BTC || 0.00001);
      let eth_brl = (brl / (fiatData.rates.ETH || 0.0001));

      if (btcRes?.ok) {
        const btcData = await btcRes.json();
        if (btcData.price) btc_brl = parseFloat(btcData.price);
      }

      if (ethRes?.ok) {
        const ethData = await ethRes.json();
        if (ethData.price) eth_brl = parseFloat(ethData.price);
      }

      return {
        usd_brl: brl,
        eur_brl: brl / (fiatData.rates.EUR || 1),
        gbp_brl: brl / (fiatData.rates.GBP || 1),
        btc_brl,
        eth_brl,
        last_update: new Date().toISOString()
      };
    } catch (error) {
      console.error("Using Fallback Market Data:", error);
      return {
        usd_brl: 5.68, eur_brl: 6.15, gbp_brl: 7.35, btc_brl: 548000, eth_brl: 18950,
        last_update: new Date().toISOString()
      };
    }
  },

  fetchStockData: async (rates?: MarketRates): Promise<StockInfo[]> => {
    const getChange = () => ((Math.random() - 0.48) * 2.2).toFixed(2);

    const tickers = [
      { symbol: 'PETR4', name: 'PETROBRAS PN', base: 37.82 },
      { symbol: 'VALE3', name: 'VALE ON', base: 68.45 },
      { symbol: 'IBOV', name: 'IBOVESPA', base: 129450 },
      { symbol: 'BTC/BRL', name: 'BITCOIN', base: rates?.btc_brl || 545000 },
      { symbol: 'USD/BRL', name: 'DÓLAR', base: rates?.usd_brl || 5.68 },
      { symbol: 'WDO', name: 'WDO FUTURO', base: 5.69 },
      { symbol: 'SPX', name: 'S&P 500', base: 5918.20 },
      { symbol: 'US30', name: 'DOW JONES', base: 43820 },
    ];

    return tickers.map(t => {
      const change = getChange();
      const currentPrice = t.base * (1 + parseFloat(change)/100);
      return {
        symbol: t.symbol,
        name: t.name,
        price: t.symbol.includes('IBOV') || t.symbol === 'US30'
          ? currentPrice.toLocaleString('pt-BR', { maximumFractionDigits: 0 })
          : currentPrice.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 3 }),
        change: change + '%',
        isPositive: parseFloat(change) >= 0
      };
    });
  },

  fetchHistoricalCandles: async (symbol: string, interval: string = '1h'): Promise<Candle[]> => {
    const isCrypto = symbol.includes('BTC') || symbol.includes('ETH');

    if (isCrypto) {
      const binanceSymbol = symbol.replace('/', '').replace('BTCBRL', 'BTCBRL');
      const cleanSymbol = binanceSymbol === 'BTC' ? 'BTCBRL' : binanceSymbol;
      try {
        const res = await fetch(`https://api.binance.com/api/v3/klines?symbol=${cleanSymbol}&interval=${interval}&limit=60`);
        if (res.ok) {
          const data = await res.json();
          return data.map((item: any) => ({
            time: new Date(item[0]).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
            open: parseFloat(item[1]),
            high: parseFloat(item[2]),
            low: parseFloat(item[3]),
            close: parseFloat(item[4]),
          }));
        }
      } catch (e) {}
    }

    // High-fidelity simulation for indices/stocks
    let currentPrice = symbol === 'IBOV' ? 129000 : (symbol.includes('PETR') ? 37.5 : 100);
    const history: Candle[] = [];
    const now = new Date();

    for (let i = 60; i >= 0; i--) {
      const date = new Date(now);
      date.setMinutes(now.getMinutes() - i * (interval === '1h' ? 60 : 5));

      const vol = currentPrice * 0.006;
      const open = currentPrice;
      const close = open + (Math.random() - 0.5) * vol;
      history.push({
        time: date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        open,
        high: Math.max(open, close) + Math.random() * (vol * 0.4),
        low: Math.min(open, close) - Math.random() * (vol * 0.4),
        close
      });
      currentPrice = close;
    }
    return history;
  }
};

