import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Message, ChatSession, SyncStatus } from '../types.ts';
import { GeminiService } from '../services/geminiService.ts';
import { StorageService } from '../services/storage.ts';

const ChatInterface: React.FC = () => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string>('');
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [showHistory, setShowHistory] = useState(true);
  const scrollRef = useRef<HTMLDivElement>(null);

  const WELCOME_MESSAGE: Message = {
    id: 'welcome',
    role: 'model',
    content: '### TERMINAL FINAIGPT INICIALIZADO\n\nPronto para cálculos financeiros avançados e geração de planilhas.\n\n- **Cálculos Ativos:** DRE, WACC, ROI, Tributos\n- **Exportação:** Google Sheets / CSV disponível\n- **Cloud Sync:** Drive Integration Ativa\n\n**Sugestões:**\n1. "Calcule o EBITDA desta empresa: Receita 500k, Custos 300k, Depreciação 20k."\n2. "Monte uma tabela de Simples Nacional Anexo III."',
    timestamp: new Date()
  };

  const loadData = useCallback(() => {
    const activeSessions = StorageService.getChatSessions();
    setSessions(activeSessions);

    if (currentSessionId) {
      const current = activeSessions.find(s => s.id === currentSessionId);
      if (current) {
        setMessages(current.messages);
      } else if (activeSessions.length > 0) {
        // Fallback if current was deleted
        const last = activeSessions[0];
        setCurrentSessionId(last.id);
        setMessages(last.messages);
      } else {
        createNewChat();
      }
    } else if (activeSessions.length > 0) {
      const last = activeSessions[0];
      setCurrentSessionId(last.id);
      setMessages(last.messages);
    } else {
      createNewChat();
    }
  }, [currentSessionId]);

  useEffect(() => {
    loadData();
    const handleSyncEvent = () => setSessions(StorageService.getChatSessions());
    window.addEventListener('session_synced', handleSyncEvent);
    return () => window.removeEventListener('session_synced', handleSyncEvent);
  }, [loadData]);

  const createNewChat = () => {
    const newId = Date.now().toString();
    setCurrentSessionId(newId);
    setMessages([WELCOME_MESSAGE]);
  };

  const switchSession = (id: string) => {
    setCurrentSessionId(id);
    const session = sessions.find(s => s.id === id);
    if (session) {
      setMessages(session.messages);
    }
  };

  const handleDeleteSession = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (window.confirm("Tem certeza que deseja excluir permanentemente este chat? Esta ação não pode ser desfeita.")) {
      StorageService.deleteChatSession(id);
      const remaining = StorageService.getChatSessions();
      setSessions(remaining);
      if (id === currentSessionId) {
        if (remaining.length > 0) {
          switchSession(remaining[0].id);
        } else {
          createNewChat();
        }
      }
    }
  };

  const persistSession = useCallback((id: string, msgs: Message[], title?: string) => {
    if (!id || msgs.length === 0) return;
    const existingSession = StorageService.getChatSessions().find(s => s.id === id);
    const newTitle = title || existingSession?.title || (msgs.find(m => m.role === 'user')?.content.substring(0, 30)) || 'Nova Conversa';
    const session: ChatSession = { id, title: newTitle, messages: msgs, lastUpdate: new Date() };
    StorageService.saveChatSession(session);
    setSessions(StorageService.getChatSessions());
  }, []);

  const exportTableToCSV = (tableData: string[][], fileName: string) => {
    const csvContent = tableData.map(row => row.join(',')).join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `${fileName.replace(/\s+/g, '_')}_FinaIGPT.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;
    const userMessage: Message = { id: Date.now().toString(), role: 'user', content: input, timestamp: new Date() };
    const newMessages = [...messages, userMessage];
    setMessages(newMessages);
    const currentInput = input;
    setInput('');
    setIsTyping(true);
    persistSession(currentSessionId, newMessages);

    if (messages.filter(m => m.role === 'user').length === 0) {
      GeminiService.generateTitle(currentInput).then(title => persistSession(currentSessionId, newMessages, title));
    }

    try {
      const response = await GeminiService.generateChatResponse(currentInput, messages);
      const sources: string[] = [];
      if (response.groundingMetadata?.groundingChunks) {
        response.groundingMetadata.groundingChunks.forEach((chunk: any) => {
          if (chunk.web?.uri) sources.push(chunk.web.uri);
        });
      }
      const modelMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: response.text,
        timestamp: new Date(),
        sources: sources.length > 0 ? Array.from(new Set(sources)) : undefined
      };
      const finalMessages = [...newMessages, modelMessage];
      setMessages(finalMessages);
      persistSession(currentSessionId, finalMessages);
    } catch (error) {
      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'model', content: '### ERRO\nFalha na comunicação IA.', timestamp: new Date() }]);
    } finally {
      setIsTyping(false);
    }
  };

  const parseInlineStyles = (text: string) => {
    const parts = text.split(/(\*\*.*?\*\*|\*.*?\*)/g);
    return parts.map((part, i) => {
      if (part.startsWith('**') && part.endsWith('**')) return <strong key={i} className="font-black">{part.slice(2, -2)}</strong>;
      if (part.startsWith('*') && part.endsWith('*')) return <em key={i} className="italic">{part.slice(1, -1)}</em>;
      return part;
    });
  };

  const renderFormattedContent = (content: string) => {
    const lines = content.split('\n');
    let elements: React.ReactNode[] = [];
    let currentTable: string[][] = [];

    const flushTable = (key: number) => {
      if (currentTable.length === 0) return null;
      const cleanTable = currentTable.filter(row => !row.every(cell => cell.trim().match(/^-+$/)));
      const tableDataForExport = [...cleanTable];

      const tableEl = (
        <div key={`table-${key}`} className="my-6">
          <div className="flex justify-end mb-2">
            <button 
              onClick={() => exportTableToCSV(tableDataForExport, "Calculo_Financeiro")}
              className="text-[8px] font-black bg-emerald-600 text-white px-3 py-1 flex items-center gap-2 hover:bg-emerald-700 transition-colors sketch-border shadow-none"
            >
              <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 24 24"><path d="M14 2H6c-1.1 0-1.99.9-1.99 2L4 20c0 1.1.89 2 1.99 2H18c1.1 0 2-.9 2-2V8l-6-6zm2 16H8v-2h8v2zm0-4H8v-2h8v2zm-3-5V3.5L18.5 9H13z"/></svg>
              EXPORTAR PARA GOOGLE SHEETS
            </button>
          </div>
          <div className="overflow-x-auto sketch-border p-1 bg-white">
            <table className="w-full border-collapse text-[10px] text-[#1A1A1A]">
              <tbody>
                {cleanTable.map((row, i) => (
                  <tr key={i} className={i === 0 ? "bg-[#1A1A1A] text-white" : "hover:bg-[#F2EFEA]"}>
                    {row.map((cell, j) => (
                      <td key={j} className="px-4 py-3 border border-[#1A1A1A] font-bold uppercase truncate">{parseInlineStyles(cell.trim())}</td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      );
      currentTable = [];
      return tableEl;
    };

    lines.forEach((line, idx) => {
      if (line.trim().startsWith('|') && line.trim().includes('|')) {
        currentTable.push(line.trim().split('|').filter((_, i, arr) => i > 0 && i < arr.length - 1));
      } else {
        const table = flushTable(idx);
        if (table) elements.push(table);
        if (line.startsWith('###')) elements.push(<h3 key={idx} className="text-sm font-black mt-6 mb-3 uppercase border-b-2 border-[#1A1A1A] pb-1">{line.replace('###', '')}</h3>);
        else if (line.trim().startsWith('- ')) elements.push(<li key={idx} className="ml-4 mb-2 text-[11px] font-bold uppercase flex gap-3"><span className="mt-1 w-1 h-1 bg-[#1A1A1A]"></span>{parseInlineStyles(line.trim().substring(2))}</li>);
        else if (line.trim() !== '') elements.push(<p key={idx} className="text-[11px] font-medium leading-relaxed mb-3">{parseInlineStyles(line)}</p>);
      }
    });
    const finalTable = flushTable(lines.length);
    if (finalTable) elements.push(finalTable);
    return elements;
  };

  return (
    <div className="flex h-full bg-[#F2EFEA] overflow-hidden">
      {showHistory && (
        <div className="w-72 bg-white border-r-2 border-[#1A1A1A] flex flex-col h-full animate-in slide-in-from-left duration-300">
          <div className="p-6 border-b-2 border-[#1A1A1A] flex flex-col gap-4">
            <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-[#7A7A7A]">Histórico Sync</h3>
            <button onClick={createNewChat} className="w-full sketch-button py-3 text-[10px] font-black uppercase tracking-widest">+ Novo Chat</button>
          </div>
          <div className="flex-1 overflow-y-auto p-4 space-y-3">
            {sessions.map((s) => (
              <div key={s.id} onClick={() => switchSession(s.id)} className={`p-4 sketch-border cursor-pointer relative group ${currentSessionId === s.id ? 'bg-[#1A1A1A] text-white' : 'bg-white hover:bg-[#F2EFEA]'}`}>
                <div className="pr-6">
                  <p className="text-[10px] font-black uppercase truncate">{s.title || 'Nova Conversa'}</p>
                  <div className="flex justify-between mt-2">
                     <p className="text-[8px] font-bold opacity-50">{s.lastUpdate.toLocaleDateString()}</p>
                     {s.syncStatus === 'synced' && <svg className="w-2 h-2 text-emerald-500" fill="currentColor" viewBox="0 0 24 24"><path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 15l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z"/></svg>}
                  </div>
                </div>
                <button 
                  onClick={(e) => handleDeleteSession(e, s.id)}
                  className="absolute right-2 top-2 p-1 text-gray-400 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-opacity"
                  title="Excluir Chat"
                >
                  <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                </button>
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="flex-1 flex flex-col h-full relative">
        <header className="p-6 border-b-2 border-[#1A1A1A] bg-white flex justify-between items-center z-10">
          <div className="flex items-center gap-4">
            <button onClick={() => setShowHistory(!showHistory)} className="p-2 border-2 border-[#1A1A1A] hover:bg-[#1A1A1A] hover:text-white"><svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M4 6h16M4 12h16M4 18h16" /></svg></button>
            <div>
              <h2 className="text-xl font-black uppercase tracking-tighter leading-none">{sessions.find(s => s.id === currentSessionId)?.title || 'NOVA CONVERSA'}</h2>
              <p className="text-[8px] font-black text-emerald-600 uppercase tracking-widest mt-1">Google Drive Sync Ativo</p>
            </div>
          </div>
        </header>

        <div ref={scrollRef} className="flex-1 overflow-y-auto p-8 space-y-8 pb-32">
          {messages.map((msg) => (
            <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[85%] sketch-border p-6 relative ${msg.role === 'user' ? 'bg-[#1A1A1A] text-white' : 'bg-white'}`}>
                <div className="flex justify-between items-center mb-4 border-b border-[#B5B5B5]/30 pb-2">
                  <span className="text-[8px] font-black uppercase">{msg.role === 'user' ? 'USER' : 'FINAIGPT_ENGINE'}</span>
                </div>
                <div className="chat-content">{renderFormattedContent(msg.content)}</div>
              </div>
            </div>
          ))}
          {isTyping && <div className="flex gap-2 p-4 animate-pulse"><div className="w-1 h-1 bg-[#1A1A1A]"></div><div className="w-1 h-1 bg-[#1A1A1A]"></div></div>}
        </div>

        <div className="absolute bottom-0 left-0 right-0 p-8 bg-gradient-to-t from-[#F2EFEA]">
          <div className="max-w-4xl mx-auto flex gap-4">
            <input type="text" value={input} onChange={(e) => setInput(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && handleSend()} placeholder="Insira dados financeiros para cálculo e exportação..." className="flex-1 bg-white sketch-border px-6 py-4 outline-none font-bold text-xs uppercase" />
            <button onClick={handleSend} disabled={isTyping} className="sketch-button px-10 py-4 font-black uppercase text-xs">PROCESSAR</button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ChatInterface;

export interface User {
  id: string;
  name: string;
  email: string;
  avatar: string;
}

export interface Message {
  id: string;
  role: 'user' | 'model';
  content: string;
  timestamp: Date;
  sources?: string[];
}

export type SyncStatus = 'synced' | 'pending' | 'local';

export interface ChatSession {
  id: string;
  title: string;
  messages: Message[];
  lastUpdate: Date;
  deletedAt?: Date;
  // Sync fields
  syncStatus?: SyncStatus;
  syncedAt?: Date;
}

export type DocumentSource = 'local' | 'google_docs' | 'google_sheets' | 'google_analytics';

export interface Document {
  id: string;
  name: string;
  content: string;
  type: string;
  uploadDate: Date;
  size: number;
  sourceType: DocumentSource;
  externalUrl?: string;
  metadata?: {
    propertyId?: string;
    lastSync?: Date;
    category?: 'cost' | 'tax' | 'management' | 'general' | 'exercise';
  };
}

export interface Candle {
  time: string;
  open: number;
  high: number;
  low: number;
  close: number;
}

export interface MarketData {
  symbol: string;
  name: string;
  price: number;
  change: number;
  history: Candle[];
}

export enum ViewState {
  Dashboard = 'DASHBOARD',
  Chat = 'CHAT',
  Documents = 'DOCUMENTS',
  Reports = 'REPORTS'
}

import { Document, User, ChatSession, SyncStatus } from '../types.ts';

const DOCS_KEY = 'finan_gpt_docs';
const USER_KEY = 'finan_gpt_user';
const CHATS_KEY = 'finan_gpt_chats';

export const StorageService = {
  // Documentos
  getDocuments: (): Document[] => {
    try {
      const data = localStorage.getItem(DOCS_KEY);
      if (!data) return [];
      const docs = JSON.parse(data);
      return docs.map((d: any) => ({
        ...d,
        uploadDate: new Date(d.uploadDate),
        metadata: {
          ...d.metadata,
          lastSync: d.metadata?.lastSync ? new Date(d.metadata.lastSync) : undefined
        }
      }));
    } catch (e) {
      console.error("Error reading documents", e);
      return [];
    }
  },

  saveDocument: (doc: Document) => {
    const docs = StorageService.getDocuments();
    docs.push(doc);
    localStorage.setItem(DOCS_KEY, JSON.stringify(docs));
  },

  deleteDocument: (id: string) => {
    const docs = StorageService.getDocuments().filter(d => d.id !== id);
    localStorage.setItem(DOCS_KEY, JSON.stringify(docs));
  },

  // Usuário
  getUser: (): User | null => {
    try {
      const data = localStorage.getItem(USER_KEY);
      return data ? JSON.parse(data) : null;
    } catch (e) {
      return null;
    }
  },

  setUser: (user: User) => {
    localStorage.setItem(USER_KEY, JSON.stringify(user));
  },

  // Sessões de Chat
  // Added includeDeleted parameter to handle trash bin logic
  getChatSessions: (includeDeleted: boolean = false): ChatSession[] => {
    const data = localStorage.getItem(CHATS_KEY);
    if (!data) return [];

    try {
      const parsed = JSON.parse(data);
      if (!Array.isArray(parsed)) return [];

      const sessions = parsed.map((s: any) => ({
        ...s,
        lastUpdate: new Date(s.lastUpdate),
        syncedAt: s.syncedAt ? new Date(s.syncedAt) : undefined,
        deletedAt: s.deletedAt ? new Date(s.deletedAt) : undefined,
        messages: (s.messages || []).map((m: any) => ({ 
          ...m, 
          timestamp: new Date(m.timestamp) 
        }))
      }));

      if (includeDeleted) return sessions;
      return sessions.filter(s => !s.deletedAt);
    } catch (e) {
      console.error("Failed to parse chat sessions", e);
      return [];
    }
  },

  saveChatSession: (session: ChatSession) => {
    // Must include deleted sessions to avoid overwriting them in storage
    const sessions = StorageService.getChatSessions(true);
    const index = sessions.findIndex(s => s.id === session.id);

    const user = StorageService.getUser();
    const updatedSession = { 
      ...session, 
      syncStatus: user ? 'pending' : 'local' as SyncStatus 
    };

    if (index >= 0) {
      sessions[index] = updatedSession;
    } else {
      sessions.unshift(updatedSession);
    }

    localStorage.setItem(CHATS_KEY, JSON.stringify(sessions));

    if (user) {
      StorageService.syncSessionWithCloud(updatedSession.id);
    }
  },

  syncSessionWithCloud: async (sessionId: string) => {
    setTimeout(() => {
      // Must include deleted sessions to maintain storage integrity
      const sessions = StorageService.getChatSessions(true);
      const index = sessions.findIndex(s => s.id === sessionId);
      if (index >= 0 && sessions[index].syncStatus === 'pending') {
        sessions[index].syncStatus = 'synced';
        sessions[index].syncedAt = new Date();
        localStorage.setItem(CHATS_KEY, JSON.stringify(sessions));
        window.dispatchEvent(new CustomEvent('session_synced', { detail: sessionId }));
      }
    }, 1500);
  },

  // Updated to soft delete by setting deletedAt
  deleteChatSession: (id: string) => {
    const sessions = StorageService.getChatSessions(true);
    const index = sessions.findIndex(s => s.id === id);
    if (index >= 0) {
      sessions[index].deletedAt = new Date();
      localStorage.setItem(CHATS_KEY, JSON.stringify(sessions));
    }
  },

  // Restores a session from the trash
  restoreFromTrash: (id: string) => {
    const sessions = StorageService.getChatSessions(true);
    const index = sessions.findIndex(s => s.id === id);
    if (index >= 0) {
      delete sessions[index].deletedAt;
      localStorage.setItem(CHATS_KEY, JSON.stringify(sessions));
    }
  },

  // Permanently removes a session from storage
  deletePermanently: (id: string) => {
    const sessions = StorageService.getChatSessions(true);
    const updatedSessions = sessions.filter(s => s.id !== id);
    localStorage.setItem(CHATS_KEY, JSON.stringify(updatedSessions));
  },

  clearAll: () => {
    localStorage.clear();
  }
};

