import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Message, ChatSession, SyncStatus } from '../types.ts';
import { GeminiService } from '../services/geminiService.ts';
import { StorageService } from '../services/storage.ts';

const ChatInterface: React.FC = () => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string>('');
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [showHistory, setShowHistory] = useState(false); // Default false on mobile
  const scrollRef = useRef<HTMLDivElement>(null);

  const WELCOME_MESSAGE: Message = {
    id: 'welcome',
    role: 'model',
    content: '### TERMINAL FINAIGPT INICIALIZADO\n\nPronto para cálculos financeiros avançados e geração de planilhas.\n\n- **Cálculos Ativos:** DRE, WACC, ROI, Tributos\n- **Exportação:** CSV disponível\n- **Cloud Sync:** Drive Ativo\n\n**Sugestões:**\n1. "Calcule o EBITDA desta empresa: Receita 500k, Custos 300k, Depreciação 20k."\n2. "Monte uma tabela de Simples Nacional Anexo III."',
    timestamp: new Date()
  };

  const loadData = useCallback(() => {
    const activeSessions = StorageService.getChatSessions();
    setSessions(activeSessions);

    if (currentSessionId) {
      const current = activeSessions.find(s => s.id === currentSessionId);
      if (current) {
        setMessages(current.messages);
      } else if (activeSessions.length > 0) {
        const last = activeSessions[0];
        setCurrentSessionId(last.id);
        setMessages(last.messages);
      } else {
        createNewChat();
      }
    } else if (activeSessions.length > 0) {
      const last = activeSessions[0];
      setCurrentSessionId(last.id);
      setMessages(last.messages);
    } else {
      createNewChat();
    }
  }, [currentSessionId]);

  useEffect(() => {
    loadData();
    const handleSyncEvent = () => setSessions(StorageService.getChatSessions());
    window.addEventListener('session_synced', handleSyncEvent);
    return () => window.removeEventListener('session_synced', handleSyncEvent);
  }, [loadData]);

  // Handle auto-scroll
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const createNewChat = () => {
    const newId = Date.now().toString();
    setCurrentSessionId(newId);
    setMessages([WELCOME_MESSAGE]);
  };

  const switchSession = (id: string) => {
    setCurrentSessionId(id);
    const session = sessions.find(s => s.id === id);
    if (session) {
      setMessages(session.messages);
    }
    if (window.innerWidth < 1024) setShowHistory(false);
  };

  const handleDeleteSession = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (window.confirm("Excluir chat permanentemente?")) {
      StorageService.deleteChatSession(id);
      const remaining = StorageService.getChatSessions();
      setSessions(remaining);
      if (id === currentSessionId) {
        if (remaining.length > 0) switchSession(remaining[0].id);
        else createNewChat();
      }
    }
  };

  const persistSession = useCallback((id: string, msgs: Message[], title?: string) => {
    if (!id || msgs.length === 0) return;
    const existingSession = StorageService.getChatSessions().find(s => s.id === id);
    const newTitle = title || existingSession?.title || (msgs.find(m => m.role === 'user')?.content.substring(0, 30)) || 'Nova Conversa';
    const session: ChatSession = { id, title: newTitle, messages: msgs, lastUpdate: new Date() };
    StorageService.saveChatSession(session);
    setSessions(StorageService.getChatSessions());
  }, []);

  const exportTableToCSV = (tableData: string[][], fileName: string) => {
    const csvContent = tableData.map(row => row.join(',')).join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `${fileName.replace(/\s+/g, '_')}_FinaIGPT.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;
    const userMessage: Message = { id: Date.now().toString(), role: 'user', content: input, timestamp: new Date() };
    const newMessages = [...messages, userMessage];
    setMessages(newMessages);
    const currentInput = input;
    setInput('');
    setIsTyping(true);
    persistSession(currentSessionId, newMessages);

    if (messages.filter(m => m.role === 'user').length === 0) {
      GeminiService.generateTitle(currentInput).then(title => persistSession(currentSessionId, newMessages, title));
    }

    try {
      const response = await GeminiService.generateChatResponse(currentInput, messages);
      const sources: string[] = [];
      if (response.groundingMetadata?.groundingChunks) {
        response.groundingMetadata.groundingChunks.forEach((chunk: any) => {
          if (chunk.web?.uri) sources.push(chunk.web.uri);
        });
      }
      const modelMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: response.text,
        timestamp: new Date(),
        sources: sources.length > 0 ? Array.from(new Set(sources)) : undefined
      };
      const finalMessages = [...newMessages, modelMessage];
      setMessages(finalMessages);
      persistSession(currentSessionId, finalMessages);
    } catch (error) {
      setMessages(prev => [...prev, { id: Date.now().toString(), role: 'model', content: '### ERRO\nFalha na comunicação IA.', timestamp: new Date() }]);
    } finally {
      setIsTyping(false);
    }
  };

  const renderFormattedContent = (content: string) => {
    const lines = content.split('\n');
    let elements: React.ReactNode[] = [];
    let currentTable: string[][] = [];

    const flushTable = (key: number) => {
      if (currentTable.length === 0) return null;
      const cleanTable = currentTable.filter(row => !row.every(cell => cell.trim().match(/^-+$/)));

      const tableEl = (
        <div key={`table-${key}`} className="my-4 overflow-x-auto w-full">
          <div className="flex justify-end mb-2">
            <button 
              onClick={() => exportTableToCSV(cleanTable, "Calculo_Financeiro")}
              className="text-[8px] font-black bg-emerald-600 text-white px-2 py-1 flex items-center gap-1 sketch-border shadow-none"
            >
              CSV
            </button>
          </div>
          <table className="min-w-full border-collapse text-[10px] text-[#1A1A1A] bg-white sketch-border">
            <tbody>
              {cleanTable.map((row, i) => (
                <tr key={i} className={i === 0 ? "bg-[#1A1A1A] text-white" : ""}>
                  {row.map((cell, j) => (
                    <td key={j} className="px-2 py-2 border border-[#1A1A1A] font-bold uppercase whitespace-nowrap">{cell.trim()}</td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      );
      currentTable = [];
      return tableEl;
    };

    lines.forEach((line, idx) => {
      if (line.trim().startsWith('|') && line.trim().includes('|')) {
        currentTable.push(line.trim().split('|').filter((_, i, arr) => i > 0 && i < arr.length - 1));
      } else {
        const table = flushTable(idx);
        if (table) elements.push(table);
        if (line.startsWith('###')) elements.push(<h3 key={idx} className="text-xs font-black mt-4 mb-2 uppercase border-b border-[#1A1A1A]">{line.replace('###', '')}</h3>);
        else if (line.trim() !== '') elements.push(<p key={idx} className="text-[10px] font-medium leading-relaxed mb-2">{line}</p>);
      }
    });
    const finalTable = flushTable(lines.length);
    if (finalTable) elements.push(finalTable);
    return elements;
  };

  return (
    <div className="flex h-full bg-[#F2EFEA] overflow-hidden relative">
      {/* History Sidebar - Toggleable on mobile */}
      <div className={`
        fixed inset-y-0 left-0 z-30 w-72 bg-white border-r-2 border-[#1A1A1A] flex flex-col transition-transform duration-300
        ${showHistory ? 'translate-x-0' : '-translate-x-full'}
        lg:relative lg:translate-x-0 lg:z-0
      `}>
        <div className="p-4 border-b-2 border-[#1A1A1A] flex flex-col gap-2">
          <h3 className="text-[9px] font-black uppercase text-[#7A7A7A]">Histórico</h3>
          <button onClick={createNewChat} className="w-full sketch-button py-2 text-[9px] font-black uppercase tracking-widest">+ Novo Chat</button>
        </div>
        <div className="flex-1 overflow-y-auto p-4 space-y-2">
          {sessions.map((s) => (
            <div key={s.id} onClick={() => switchSession(s.id)} className={`p-3 sketch-border cursor-pointer relative group ${currentSessionId === s.id ? 'bg-[#1A1A1A] text-white' : 'bg-white'}`}>
              <p className="text-[9px] font-black uppercase truncate pr-4">{s.title || 'Nova Conversa'}</p>
              <button onClick={(e) => handleDeleteSession(e, s.id)} className="absolute right-1 top-1 text-rose-500 opacity-0 group-hover:opacity-100 lg:opacity-100">
                <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>
          ))}
        </div>
      </div>

      <div className="flex-1 flex flex-col h-full relative min-w-0">
        <header className="p-4 border-b-2 border-[#1A1A1A] bg-white flex justify-between items-center z-10">
          <div className="flex items-center gap-3">
            <button onClick={() => setShowHistory(!showHistory)} className="p-2 border-2 border-[#1A1A1A] hover:bg-[#1A1A1A] hover:text-white">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg>
            </button>
            <h2 className="text-sm font-black uppercase truncate max-w-[150px]">{sessions.find(s => s.id === currentSessionId)?.title || 'CHAT'}</h2>
          </div>
        </header>

        <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 md:p-8 space-y-6 pb-24">
          {messages.map((msg) => (
            <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[95%] md:max-w-[80%] sketch-border p-4 ${msg.role === 'user' ? 'bg-[#1A1A1A] text-white' : 'bg-white'}`}>
                <div className="text-[7px] font-black uppercase mb-2 opacity-50">{msg.role === 'user' ? 'USER' : 'FINAIGPT'}</div>
                <div className="chat-content">{renderFormattedContent(msg.content)}</div>
              </div>
            </div>
          ))}
          {isTyping && <div className="flex gap-1 p-2"><div className="w-1 h-1 bg-[#1A1A1A] animate-bounce"></div><div className="w-1 h-1 bg-[#1A1A1A] animate-bounce delay-75"></div></div>}
        </div>

        <div className="absolute bottom-0 left-0 right-0 p-4 bg-gradient-to-t from-[#F2EFEA] via-[#F2EFEA] to-transparent pt-8">
