import React, { useState, useEffect, useMemo } from 'react';
import { MarketService, MarketRates, StockInfo } from '../services/marketService';
import { Candle } from '../types';
import { StorageService } from '../services/storage';

const Dashboard: React.FC = () => {
  const [rates, setRates] = useState<MarketRates | null>(null);
  const [stocks, setStocks] = useState<StockInfo[]>([]);
  const [candles, setCandles] = useState<Candle[]>([]);
  const [selectedAsset, setSelectedAsset] = useState('BTC');
  const [timeframe, setTimeframe] = useState('1h');
  const [hoveredCandle, setHoveredCandle] = useState<Candle | null>(null);
  const [loadingMarket, setLoadingMarket] = useState(true);
  const [showSMA, setShowSMA] = useState(false);
  const [connectedServices, setConnectedServices] = useState<string[]>([]);

  useEffect(() => {
    const docs = StorageService.getDocuments();
    const services = Array.from(new Set(docs.map(d => d.sourceType))).filter(s => s !== 'local');
    setConnectedServices(services);

    const loadMarketData = async () => {
      setLoadingMarket(true);
      try {
        const rateData = await MarketService.fetchExchangeRates();
        const [stockData, candleData] = await Promise.all([
          MarketService.fetchStockData(rateData),
          MarketService.fetchHistoricalCandles(selectedAsset, timeframe)
        ]);
        setRates(rateData);
        setStocks(stockData);
        setCandles(candleData);
      } catch (e) {
        console.error("Error updating dashboard data", e);
      } finally {
        setLoadingMarket(false);
      }
    };

    loadMarketData();
    const interval = setInterval(loadMarketData, timeframe === '1m' ? 10000 : 60000); 
    return () => clearInterval(interval);
  }, [selectedAsset, timeframe]);

  const chartMetrics = useMemo(() => {
    if (candles.length === 0) return null;
    const lows = candles.map(c => c.low);
    const highs = candles.map(c => c.high);
    const minLow = Math.min(...lows);
    const maxHigh = Math.max(...highs);
    const range = Math.max(0.1, maxHigh - minLow);

    const sma = candles.map((_, i) => {
      if (i < 9) return null;
      const slice = candles.slice(i - 9, i + 1);
      const sum = slice.reduce((acc, curr) => acc + curr.close, 0);
      return sum / 10;
    });

    return { minLow, maxHigh, range, sma };
  }, [candles]);

  const renderCandleChart = () => {
    if (!chartMetrics || candles.length === 0) return (
      <div className="h-[250px] md:h-[350px] flex flex-col items-center justify-center gap-4 bg-white sketch-border">
        <div className="w-6 h-6 border-4 border-[#1A1A1A] border-t-transparent rounded-full animate-spin"></div>
        <span className="text-[8px] font-black uppercase tracking-widest text-[#7A7A7A]">Sincronizando...</span>
      </div>
    );

    const width = 1000;
    const height = 350;
    const padding = 20;
    const candleSpace = (width - padding * 2) / candles.length;
    const candleWidth = candleSpace * 0.7;
    const getY = (price: number) => height - padding - ((price - chartMetrics.minLow) / chartMetrics.range) * (height - padding * 2);

    return (
      <div className="relative cursor-crosshair bg-white p-2 w-full overflow-hidden">
        <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-full min-h-[250px] md:min-h-[350px]" preserveAspectRatio="none">
          {[0, 0.5, 1].map((p, i) => {
            const y = padding + p * (height - padding * 2);
            const price = chartMetrics.maxHigh - p * chartMetrics.range;
            return (
              <g key={i}>
                <line x1={0} y1={y} x2={width} y2={y} stroke="#F2F2F2" strokeWidth="1" />
                <text x={2} y={y - 2} className="text-[12px] fill-[#B5B5B5] font-black">{price.toFixed(2)}</text>
              </g>
            );
          })}

          {candles.map((candle, i) => {
            const x = padding + i * candleSpace;
            const openY = getY(candle.open);
            const closeY = getY(candle.close);
            const highY = getY(candle.high);
            const lowY = getY(candle.low);
            const color = candle.close >= candle.open ? '#10B981' : '#EF4444';

            return (
              <g key={i} onMouseEnter={() => setHoveredCandle(candle)} onMouseLeave={() => setHoveredCandle(null)}>
                <line x1={x + candleSpace/2} y1={highY} x2={x + candleSpace/2} y2={lowY} stroke={color} strokeWidth="2" />
                <rect 
                  x={x + (candleSpace - candleWidth)/2} 
                  y={Math.min(openY, closeY)} 
                  width={candleWidth} 
                  height={Math.max(2, Math.abs(openY - closeY))} 
                  fill={color}
                />
              </g>
            );
          })}
        </svg>
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full bg-[#F2EFEA]">
      <div className="bg-[#1A1A1A] h-8 flex items-center overflow-hidden border-b-2 border-[#1A1A1A] relative shrink-0">
        <div className="flex animate-[ticker_30s_linear_infinite] whitespace-nowrap gap-12 px-4 items-center min-w-full">
          {stocks.concat(stocks).map((stock, i) => (
            <div key={i} className="flex items-center gap-2 text-[9px] font-black uppercase text-white">
              <span>{stock.symbol}</span>
              <span className="text-gray-400">{stock.price}</span>
              <span className={stock.isPositive ? 'text-emerald-400' : 'text-rose-400'}>{stock.change}</span>
            </div>
          ))}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 md:p-8 space-y-6">
        <header className="flex flex-col gap-4 border-b-2 border-[#1A1A1A] pb-4">
          <div>
            <h1 className="text-2xl md:text-4xl font-black text-[#1A1A1A] uppercase tracking-tighter">OPERACIONAL</h1>
            <p className="text-[8px] font-black uppercase text-emerald-600">Sincronização em Tempo Real</p>
          </div>

          <div className="flex gap-2">
            <select value={selectedAsset} onChange={(e) => setSelectedAsset(e.target.value)} className="flex-1 bg-white border-2 border-[#1A1A1A] px-2 py-2 font-black text-[9px] uppercase outline-none">
              {stocks.map(s => <option key={s.symbol} value={s.symbol}>{s.symbol}</option>)}
            </select>
            <select value={timeframe} onChange={(e) => setTimeframe(e.target.value)} className="flex-1 bg-white border-2 border-[#1A1A1A] px-2 py-2 font-black text-[9px] uppercase outline-none">
              <option value="5m">5m</option>
              <option value="1h">1h</option>
              <option value="1d">1d</option>
            </select>
          </div>
        </header>

        <div className="bg-white sketch-border p-4">
          <h3 className="text-xs font-black uppercase mb-4">MERCADO: {selectedAsset}</h3>
          <div className="w-full overflow-hidden">
            {renderCandleChart()}
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pb-8 safe-pb">
          <div className="bg-white sketch-border p-4">
            <h4 className="text-[10px] font-black uppercase mb-2">IA Preditiva</h4>
            <p className="text-[9px] font-bold text-[#4A4A4A] leading-relaxed uppercase">Projeção mensal baseada em RAG indica estabilidade fiscal com margem de erro de 1.2%.</p>
          </div>
          <div className="bg-[#1A1A1A] text-white p-4 sketch-border">
            <h4 className="text-[10px] font-black uppercase mb-2">Audit Status</h4>
            <p className="text-[9px] font-bold text-emerald-400 uppercase">Todos os documentos em conformidade.</p>
          </div>
        </div>
      </div>
    </div>
  );
};

