import { GoogleGenAI } from "@google/genai";
import { StorageService } from "./storage.ts";

export const GeminiService = {
  generateChatResponse: async (prompt: string, history: any[], marketContext?: string) => {
    // Initializing inside the call to ensure fresh API key if changed by system
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const docs = StorageService.getDocuments();
    const docContext = docs.length > 0 
      ? `BASE DE CONHECIMENTO INTEGRADA (GOOGLE + LOCAL):\n${docs.map(d => `[FONTE: ${d.sourceType.toUpperCase()}] [CATEGORIA: ${d.metadata?.category || 'GERAL'}] [ARQUIVO: ${d.name}]\nCONTEÚDO: ${d.content.substring(0, 2000)}...`).join('\n\n')}`
      : "Nenhum documento carregado na base RAG.";

    const systemInstruction = `
      Você é o "FinaIGPT", um Terminal de Inteligência Artificial de Elite especializado em Contabilidade, Fiscalidade e Finanças Corporativas.

      OBJETIVO: Atuar como um analista sênior, capaz de realizar auditorias, cálculos complexos e estruturação de dados.

      CONTEXTO DE MERCADO ATUAL:
      ${marketContext || 'Dados de mercado não disponíveis no momento.'}

      CONTEXTO RAG (DOCUMENTOS):
      ${docContext}

      DIRETRIZES DE RESPOSTA:
      1. PRECISÃO TÉCNICA: Siga rigorosamente as normas IFRS e CPC.
      2. CÁLCULOS: Explique a lógica. Use tabelas Markdown para resultados financeiros.
      3. PRONTIDÃO PARA PLANILHA: Lembre o usuário que tabelas geradas podem ser exportadas para CSV/Sheets.
      4. TOM DE VOZ: Profissional, conciso, brutalista e eficiente.
      5. PESQUISA: Se necessário, use a ferramenta de busca para verificar leis tributárias recentes (2024/2025).

      ESTRUTURA DE DADOS:
      - Use | Coluna 1 | Coluna 2 | para tabelas.
      - Não use formatação excessiva, mantenha o foco nos dados.
    `;

    const formattedHistory = history
      .filter(msg => msg.id !== 'welcome' && msg.id !== 'reset') 
      .map(msg => ({
        role: msg.role === 'user' ? 'user' : 'model',
        parts: [{ text: msg.content }]
      }));

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview', // Pro model for complex finance reasoning
        contents: [
          ...formattedHistory,
          { role: 'user', parts: [{ text: prompt }] }
        ],
        config: {
          systemInstruction,
          tools: [{ googleSearch: {} }]
        },
      });

      return {
        text: response.text || "Erro no processamento da IA.",
        groundingMetadata: response.candidates?.[0]?.groundingMetadata
      };
    } catch (error) {
      console.error("Gemini Error:", error);
      throw error;
    }
  },

  generateTitle: async (firstPrompt: string): Promise<string> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview', // Flash is enough for title generation
        contents: `Analise a intenção e palavras-chave desta consulta e crie um título curto (máximo 5 palavras) em português. Retorne APENAS o título: "${firstPrompt}"`,
        config: {
          temperature: 0.5,
          maxOutputTokens: 20
        }
      });
      return response.text?.replace(/["']/g, '').trim() || firstPrompt.substring(0, 30);
    } catch (e) {
      return firstPrompt.substring(0, 30);
    }
  }
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Message, ChatSession } from '../types.ts';
import { GeminiService } from '../services/geminiService.ts';
import { StorageService } from '../services/storage.ts';

const ChatInterface: React.FC = () => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string>('');
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  const WELCOME_MESSAGE: Message = {
    id: 'welcome',
    role: 'model',
    content: '### TERMINAL FINAIGPT INICIALIZADO\n\nPronto para cálculos financeiros avançados e análise técnica.\n\n- **Cálculos Ativos:** DRE, WACC, ROI, Tributos\n- **Exportação:** CSV disponível\n- **Cloud Sync:** Drive Ativo\n\n**Sugestões:**\n1. "Calcule o EBITDA desta empresa: Receita 500k, Custos 300k, Depreciação 20k."\n2. "Monte uma tabela de Simples Nacional Anexo III."',
    timestamp: new Date()
  };

  const loadData = useCallback(() => {
    const activeSessions = StorageService.getChatSessions();
    setSessions(activeSessions);

    // If we have a current session, refresh it from storage
    if (currentSessionId) {
      const current = activeSessions.find(s => s.id === currentSessionId);
      if (current) {
        setMessages(current.messages);
      } else if (activeSessions.length > 0) {
        switchSession(activeSessions[0].id);
      } else {
        createNewChat();
      }
    } else if (activeSessions.length > 0) {
      // Auto-load last session on mount
      switchSession(activeSessions[0].id);
    } else {
      createNewChat();
    }
  }, [currentSessionId]);

  useEffect(() => {
    loadData();
    const handleSyncEvent = () => {
      const updated = StorageService.getChatSessions();
      setSessions(updated);
    };
    window.addEventListener('session_synced', handleSyncEvent);
    return () => window.removeEventListener('session_synced', handleSyncEvent);
  }, [loadData]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({
        top: scrollRef.current.scrollHeight,
        behavior: 'smooth'
      });
    }
  }, [messages, isTyping]);

  const createNewChat = () => {
    const newId = Date.now().toString();
    setCurrentSessionId(newId);
    setMessages([WELCOME_MESSAGE]);
    if (window.innerWidth < 1024) setShowHistory(false);
  };

  const switchSession = (id: string) => {
    const session = StorageService.getChatSessions().find(s => s.id === id);
    if (session) {
      setCurrentSessionId(id);
      setMessages(session.messages);
    }
    if (window.innerWidth < 1024) setShowHistory(false);
  };

  const handleDeleteSession = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (window.confirm("Excluir chat permanentemente?")) {
      StorageService.deleteChatSession(id);
      const remaining = StorageService.getChatSessions();
      setSessions(remaining);
      if (id === currentSessionId) {
        if (remaining.length > 0) switchSession(remaining[0].id);
        else createNewChat();
      }
    }
  };

  const persistSession = useCallback((id: string, msgs: Message[], title?: string) => {
    if (!id || msgs.length === 0) return;
    const existingSessions = StorageService.getChatSessions();
    const existingSession = existingSessions.find(s => s.id === id);

    // Don't persist empty welcome state unless there are user messages
    const hasUserContent = msgs.some(m => m.role === 'user');
    if (!hasUserContent) return;

    const firstUserMsg = msgs.find(m => m.role === 'user')?.content.substring(0, 30);
    const newTitle = title || existingSession?.title || firstUserMsg || 'Nova Conversa';

    const session: ChatSession = { 
      id, 
      title: newTitle, 
      messages: msgs, 
      lastUpdate: new Date(),
      updatedAt: new Date().toISOString(),
      version: existingSession ? existingSession.version + 1 : 1
    };

    StorageService.saveChatSession(session);
    setSessions(StorageService.getChatSessions());
  }, []);

  const exportTableToCSV = (tableData: string[][], fileName: string) => {
    const csvContent = tableData
      .map(row => row.map(cell => `"${cell.trim().replace(/"/g, '""')}"`).join(','))
      .join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `${fileName.replace(/\s+/g, '_')}_FinaIGPT.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;

    const userMessage: Message = { 
      id: Date.now().toString(), 
      role: 'user', 
      content: input, 
      timestamp: new Date() 
    };

    const updatedMessages = [...messages, userMessage];
    setMessages(updatedMessages);
    const currentInput = input;
    setInput('');
    setIsTyping(true);

    // Initial persistence of user message
    persistSession(currentSessionId, updatedMessages);

    // Auto-generate title if it's the first message
    if (messages.filter(m => m.role === 'user').length === 0) {
      GeminiService.generateTitle(currentInput).then(title => {
        persistSession(currentSessionId, updatedMessages, title);
      });
    }

    try {
      // FIXED: Passing updatedMessages instead of messages to include the current prompt in context
      const response = await GeminiService.generateChatResponse(currentInput, updatedMessages);

      const sources: string[] = [];
      if (response.groundingMetadata?.groundingChunks) {
        response.groundingMetadata.groundingChunks.forEach((chunk: any) => {
          if (chunk.web?.uri) sources.push(chunk.web.uri);
        });
      }

      const modelMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: response.text,
        timestamp: new Date(),
        sources: sources.length > 0 ? Array.from(new Set(sources)) : undefined
      };

      const finalMessages = [...updatedMessages, modelMessage];
      setMessages(finalMessages);
      persistSession(currentSessionId, finalMessages);
    } catch (error) {
      setMessages(prev => [...prev, { 
        id: Date.now().toString(), 
        role: 'model', 
        content: '### ERRO CRÍTICO\nFalha na comunicação com o processador de IA. Verifique sua conexão ou tente novamente.', 
        timestamp: new Date() 
      }]);
    } finally {
      setIsTyping(false);
    }
  };

  const renderFormattedContent = (content: string) => {
    const lines = content.split('\n');
    let elements: React.ReactNode[] = [];
    let currentTable: string[][] = [];

    const parseText = (text: string) => {
      // Very basic support for bold **text**
      const parts = text.split(/(\*\*.*?\*\*)/g);
      return parts.map((part, i) => {
        if (part.startsWith('**') && part.endsWith('**')) {
          return <strong key={i}>{part.slice(2, -2)}</strong>;
        }
        return part;
      });
    };

    const flushTable = (key: number) => {
      if (currentTable.length === 0) return null;
      // Filter out markdown separator rows (---|---|---)
      const cleanTable = currentTable.filter(row => !row.every(cell => cell.trim().match(/^-+$/)));

      if (cleanTable.length === 0) {
        currentTable = [];
        return null;
      }

      const tableEl = (
        <div key={`table-${key}`} className="my-6 overflow-x-auto w-full group/table">
          <div className="flex justify-between items-center mb-2">
            <span className="text-[7px] font-black uppercase tracking-widest text-[#7A7A7A]">Planilha Gerada</span>
            <button 
              onClick={() => exportTableToCSV(cleanTable, "Calculo_Financeiro")}
              className="text-[8px] font-black bg-emerald-600 text-white px-2 py-1 flex items-center gap-1 sketch-border shadow-none hover:bg-emerald-700 active:translate-y-px transition-all"
            >
              <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a2 2 0 002 2h12a2 2 0 002-2v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
              EXPORTAR .CSV
            </button>
          </div>
          <table className="min-w-full border-collapse text-[10px] text-[#1A1A1A] bg-white sketch-border">
            <thead>
              <tr className="bg-[#1A1A1A] text-white">
                {cleanTable[0].map((cell, j) => (
                  <th key={j} className="px-4 py-3 border border-[#1A1A1A] font-black uppercase text-left whitespace-nowrap">{cell.trim()}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {cleanTable.slice(1).map((row, i) => (
                <tr key={i} className="hover:bg-[#F2EFEA] transition-colors">
                  {row.map((cell, j) => (
                    <td key={j} className="px-4 py-3 border border-[#1A1A1A] font-bold uppercase whitespace-nowrap">{cell.trim()}</td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      );
      currentTable = [];
      return tableEl;
    };

    lines.forEach((line, idx) => {
      const trimmed = line.trim();
      if (trimmed.startsWith('|') && trimmed.includes('|')) {
        currentTable.push(trimmed.split('|').filter((_, i, arr) => i > 0 && i < arr.length - 1));
      } else {
        const table = flushTable(idx);
        if (table) elements.push(table);

        if (trimmed.startsWith('###')) {
          elements.push(<h3 key={idx} className="text-xs font-black mt-6 mb-3 uppercase border-b-2 border-[#1A1A1A] pb-1">{trimmed.replace('###', '')}</h3>);
        } else if (trimmed.startsWith('-') || trimmed.startsWith('*')) {
          elements.push(<li key={idx} className="text-[10px] font-medium leading-relaxed mb-1 ml-4 list-disc">{parseText(trimmed.substring(1).trim())}</li>);
        } else if (trimmed !== '') {
          elements.push(<p key={idx} className="text-[10px] font-medium leading-relaxed mb-3">{parseText(line)}</p>);
        }
      }
    });

    const finalTable = flushTable(lines.length);
    if (finalTable) elements.push(finalTable);

    return elements;
  };

  return (
    <div className="flex h-full bg-[#F2EFEA] overflow-hidden relative">
      {/* Overlay for mobile drawer */}
      {showHistory && (
        <div 
          className="fixed inset-0 bg-black/40 backdrop-blur-sm z-20 lg:hidden" 
          onClick={() => setShowHistory(false)}
        />
      )}

      {/* History Sidebar */}
      <div className={`
        fixed inset-y-0 left-0 z-30 w-72 bg-white border-r-2 border-[#1A1A1A] flex flex-col transition-transform duration-300 ease-in-out
        ${showHistory ? 'translate-x-0' : '-translate-x-full'}
        lg:relative lg:translate-x-0 lg:z-0
      `}>
        <div className="p-4 border-b-2 border-[#1A1A1A] bg-[#F2EFEA]">
          <h3 className="text-[9px] font-black uppercase text-[#7A7A7A] mb-3 tracking-widest">Sessões Recentes</h3>
          <button 
            onClick={createNewChat} 
            className="w-full sketch-button py-3 text-[10px] font-black uppercase tracking-widest flex items-center justify-center gap-2 hover:bg-[#1A1A1A] hover:text-white transition-all active:scale-[0.98]"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
            Novo Terminal
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-3">
          {sessions.length === 0 ? (
            <div className="text-center py-10 opacity-30">
              <p className="text-[9px] font-black uppercase">Nenhum Registro</p>
            </div>
          ) : (
            sessions.map((s) => (
              <div 
                key={s.id} 
                onClick={() => switchSession(s.id)} 
                className={`
                  p-4 sketch-border cursor-pointer relative group transition-all
                  ${currentSessionId === s.id ? 'bg-[#1A1A1A] text-white translate-x-1' : 'bg-white hover:border-[#7A7A7A]'}
                `}
              >
                <div className="flex items-center gap-2 mb-1">
                  <div className={`w-1.5 h-1.5 rounded-full ${s.syncStatus === 'synced' ? 'bg-emerald-500' : 'bg-amber-500'}`} />
                  <span className="text-[7px] font-black uppercase opacity-60">SESSÃO: {s.id.slice(-4)}</span>
                </div>
                <p className="text-[10px] font-black uppercase truncate pr-6">{s.title || 'Conversa Vazia'}</p>
                <button 
                  onClick={(e) => handleDeleteSession(e, s.id)} 
                  className="absolute right-2 top-1/2 -translate-y-1/2 text-rose-500 opacity-0 group-hover:opacity-100 p-2 hover:bg-rose-50 rounded-full transition-opacity"
                >
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
                </button>
              </div>
            ))
          )}
        </div>
      </div>

      {/* Main Chat Area */}
      <div className="flex-1 flex flex-col h-full relative min-w-0">
        <header className="px-6 py-4 border-b-2 border-[#1A1A1A] bg-white flex justify-between items-center z-10 shadow-sm">
          <div className="flex items-center gap-4">
            <button 
              onClick={() => setShowHistory(!showHistory)} 
              className="lg:hidden p-2 border-2 border-[#1A1A1A] hover:bg-[#1A1A1A] hover:text-white transition-colors"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg>
            </button>
            <div className="min-w-0">
              <h2 className="text-sm font-black uppercase truncate max-w-[200px] md:max-w-md">
                {sessions.find(s => s.id === currentSessionId)?.title || 'NOVO TERMINAL'}
              </h2>
              <div className="flex items-center gap-2">
                 <span className="text-[7px] font-black text-emerald-600 uppercase tracking-widest">Enclave IA Seguro</span>
              </div>
            </div>
          </div>
          <div className="hidden md:flex gap-2">
            <div className="px-3 py-1 bg-[#1A1A1A] text-white text-[8px] font-black uppercase tracking-tighter">API V3.5</div>
          </div>
        </header>

        {/* Message List */}
        <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 md:p-10 space-y-8 pb-32">
          {messages.map((msg) => (
            <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2 duration-300`}>
              <div className={`
                max-w-[95%] md:max-w-[85%] lg:max-w-[70%] sketch-border p-5 md:p-6
                ${msg.role === 'user' ? 'bg-[#1A1A1A] text-white' : 'bg-white text-[#1A1A1A]'}
              `}>
                <div className="flex justify-between items-center mb-4">
                  <span className={`text-[8px] font-black uppercase tracking-widest px-2 py-0.5 ${msg.role === 'user' ? 'bg-white/10' : 'bg-[#F2EFEA]'}`}>
                    {msg.role === 'user' ? 'OPERADOR SÊNIOR' : 'FINAIGPT ENGINE'}
                  </span>
                  <span className="text-[7px] font-bold opacity-40">{new Date(msg.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>
                </div>

                <div className="chat-content prose prose-sm max-w-none">
                  {renderFormattedContent(msg.content)}
                </div>

                {msg.sources && msg.sources.length > 0 && (
                  <div className="mt-6 pt-4 border-t border-[#1A1A1A]/10">
                    <p className="text-[7px] font-black uppercase text-[#7A7A7A] mb-2 tracking-widest">Fontes de Grounding (Google Search)</p>
                    <div className="flex flex-wrap gap-2">
                      {msg.sources.map((url, i) => (
                        <a 
                          key={i} 
