import React, { useState, useEffect, useRef } from 'react';
import { Document, DocumentSource } from '../types.ts';
import { StorageService } from '../services/storage.ts';
import { MarketService } from '../services/marketService.ts';

// Declare external libs for TypeScript
declare const pdfjsLib: any;
declare const mammoth: any;

const DocumentManager: React.FC = () => {
  const [documents, setDocuments] = useState<Document[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [parsingStatus, setParsingStatus] = useState<string>('');
  const [searchTerm, setSearchTerm] = useState('');
  const [externalUrl, setExternalUrl] = useState('');
  const [selectedProvider, setSelectedProvider] = useState<DocumentSource>('google_docs');
  const [selectedCategory, setSelectedCategory] = useState<'cost' | 'tax' | 'management' | 'general' | 'exercise'>('general');

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    setDocuments(StorageService.getDocuments());
    // Configure PDF.js worker
    if (typeof pdfjsLib !== 'undefined') {
      pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
    }
  }, []);

  const parsePDF = async (file: File): Promise<string> => {
    const arrayBuffer = await file.arrayBuffer();
    const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
    let fullText = "";
    for (let i = 1; i <= pdf.numPages; i++) {
      const page = await pdf.getPage(i);
      const textContent = await page.getTextContent();
      const pageText = textContent.items.map((item: any) => item.str).join(" ");
      fullText += pageText + "\n";
    }
    return fullText;
  };

  const parseDOCX = async (file: File): Promise<string> => {
    const arrayBuffer = await file.arrayBuffer();
    const result = await mammoth.extractRawText({ arrayBuffer });
    return result.value;
  };

  const handleFiles = async (files: FileList) => {
    setIsUploading(true);
    const filesArray = Array.from(files);

    for (const file of filesArray) {
      try {
        setParsingStatus(`Processando ${file.name}...`);
        let content = "";

        if (file.type === "application/pdf") {
          content = await parsePDF(file);
        } else if (file.type === "application/vnd.openxmlformats-officedocument.wordprocessingml.document") {
          content = await parseDOCX(file);
        } else {
          content = await file.text();
        }

        const doc: Document = {
          id: Math.random().toString(36).substr(2, 9),
          name: file.name,
          content: content,
          type: file.type || 'text/plain',
          uploadDate: new Date(),
          size: file.size,
          sourceType: 'local',
          metadata: {
            category: selectedCategory,
            lastSync: new Date()
          }
        };

        StorageService.saveDocument(doc);
        setDocuments(prev => [doc, ...prev]);
      } catch (e) {
        console.error(`Falha ao ler ${file.name}:`, e);
      }
    }

    setIsUploading(false);
    setParsingStatus('');
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleAddExternal = async () => {
    if (!externalUrl) return;
    setIsUploading(true);
    setParsingStatus('Sincronizando com Google Workspace API...');

    let content = `[DATA_SOURCE: ${selectedProvider.toUpperCase()}]\nURL: ${externalUrl}\nConectado via Proxy Cloud FinaIGPT.`;

    // Simulate fetching metrics if Google Analytics
    if (selectedProvider === 'google_analytics') {
      setParsingStatus('Autenticando e extraindo métricas do Google Analytics...');
      const metrics = await MarketService.fetchMockAnalytics(externalUrl);
      content = JSON.stringify(metrics);
    }

    const doc: Document = {
      id: Math.random().toString(36).substr(2, 9),
      name: `${selectedProvider === 'google_analytics' ? 'Propriedade GA4' : 'Cloud'}: ${externalUrl.split('/').pop()?.substring(0, 20)}`,
      content: content,
      type: selectedProvider === 'google_analytics' ? 'application/json' : 'external/link',
      uploadDate: new Date(),
      size: 0,
      sourceType: selectedProvider,
      externalUrl: externalUrl,
      metadata: {
        category: selectedCategory,
        lastSync: new Date()
      }
    };

    StorageService.saveDocument(doc);
    setDocuments(prev => [doc, ...prev]);
    setExternalUrl('');
    setIsUploading(false);
    setParsingStatus('');
  };

  const exportToNotebookLM = () => {
    const bundle = documents.map(d => (
      `========================================\n` +
      `FONTE: ${d.name}\n` +
      `ORIGEM: ${d.sourceType.toUpperCase()}\n` +
      `CATEGORIA: ${d.metadata?.category?.toUpperCase() || 'GERAL'}\n` +
      `----------------------------------------\n` +
      `${d.content}\n` +
      `========================================\n\n`
    )).join('');

    const blob = new Blob([bundle], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = window.document.createElement('a');
    a.href = url;
    a.download = `FinanGPT_Knowledge_Base_${new Date().toISOString().split('T')[0]}.txt`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const deleteDoc = (id: string) => {
    if (window.confirm("Remover este documento da base de conhecimento?")) {
      StorageService.deleteDocument(id);
      setDocuments(prev => prev.filter(d => d.id !== id));
    }
  };

  const filteredDocs = documents.filter(d => 
    d.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    d.metadata?.category?.includes(searchTerm.toLowerCase())
  );

  const getSourceStyle = (source: DocumentSource) => {
    switch (source) {
      case 'google_docs': return 'bg-blue-100 text-blue-700 border-blue-200';
      case 'google_sheets': return 'bg-emerald-100 text-emerald-700 border-emerald-200';
      case 'google_analytics': return 'bg-amber-100 text-amber-700 border-amber-200';
      default: return 'bg-gray-100 text-gray-700 border-gray-200';
    }
  };

  const getCategoryStyle = (cat: string) => {
    switch (cat) {
      case 'tax': return 'bg-rose-500 text-white';
      case 'cost': return 'bg-indigo-500 text-white';
      case 'management': return 'bg-emerald-500 text-white';
      case 'exercise': return 'bg-orange-500 text-white';
      default: return 'bg-[#1A1A1A] text-white';
    }
  };

  return (
    <div className="p-4 md:p-10 max-w-6xl mx-auto animate-in fade-in duration-500 overflow-y-auto h-full pb-20">
      <header className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 border-b-2 border-[#1A1A1A] pb-8 gap-6">
        <div>
          <h1 className="text-2xl md:text-3xl font-black text-[#1A1A1A] uppercase tracking-tighter leading-none">BASE DE DADOS RAG</h1>
          <p className="text-[#7A7A7A] mt-2 font-bold text-[9px] uppercase tracking-widest">Contabilidade • Google Workspace • Analytics</p>
        </div>
        <div className="flex flex-wrap gap-3">
          <button onClick={exportToNotebookLM} className="bg-[#1A1A1A] text-white font-black py-3 px-6 uppercase tracking-widest text-[9px] hover:bg-[#4A4A4A] sketch-border shadow-none transition-all active:translate-y-px">
            Exportar p/ NotebookLM
          </button>
          <button onClick={() => fileInputRef.current?.click()} className="sketch-button font-black py-3 px-6 uppercase tracking-widest text-[9px] active:scale-95 transition-all">
            + Upload Documentos
          </button>
        </div>
      </header>

      <input ref={fileInputRef} type="file" multiple accept=".pdf,.docx,.txt,.csv" className="hidden" onChange={(e) => e.target.files && handleFiles(e.target.files)} />

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-12">
        <div className="md:col-span-1">
          <label className="text-[8px] font-black text-[#7A7A7A] uppercase mb-2 block tracking-widest">Vincular Categoria</label>
          <select value={selectedCategory} onChange={(e) => setSelectedCategory(e.target.value as any)} className="w-full bg-white border-2 border-[#1A1A1A] p-3 text-[10px] font-black uppercase outline-none focus:bg-[#F2EFEA]">
            <option value="general">Geral / Normas</option>
            <option value="cost">Custos / DRE</option>
            <option value="tax">Fiscal / Tributário</option>
            <option value="management">Gerencial / KPIs</option>
            <option value="exercise">Exercício Fiscal</option>
          </select>
        </div>
        <div className="md:col-span-3 bg-white sketch-border p-6 flex flex-col md:flex-row gap-4 items-end">
          <div className="flex-1 w-full">
            <label className="text-[8px] font-black text-[#7A7A7A] uppercase mb-2 block tracking-widest">Google Service Connector</label>
            <div className="flex flex-col md:flex-row gap-2">
              <select 
                value={selectedProvider} 
                onChange={(e) => setSelectedProvider(e.target.value as DocumentSource)}
                className="bg-[#F2EFEA] border-2 border-[#1A1A1A] p-3 text-[10px] font-black uppercase outline-none"
              >
                <option value="google_docs">Google Docs</option>
                <option value="google_sheets">Google Sheets</option>
                <option value="google_analytics">Google Analytics (Property ID)</option>
              </select>
              <input 
                type="text" 
                value={externalUrl} 
                onChange={(e) => setExternalUrl(e.target.value)}
                placeholder="Insira a URL ou Property ID..." 
                className="flex-1 bg-white border-2 border-[#1A1A1A] p-3 text-[10px] font-bold outline-none"
              />
            </div>
          </div>
          <button 
            onClick={handleAddExternal} 
            disabled={isUploading || !externalUrl}
            className={`sketch-button py-3 px-8 text-[9px] font-black uppercase tracking-widest h-[48px] ${(!externalUrl || isUploading) && 'opacity-50 grayscale'}`}
          >
            Conectar
          </button>
        </div>
      </div>

      {parsingStatus && (
        <div className="mb-8 p-4 bg-[#1A1A1A] text-white flex items-center gap-4 sketch-border shadow-none">
          <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
          <span className="text-[10px] font-black uppercase tracking-widest">{parsingStatus}</span>
        </div>
      )}

      <div className="flex flex-col gap-6">
        <div className="flex justify-between items-center">
          <h2 className="text-sm font-black uppercase tracking-widest">Base de Conhecimento ({documents.length})</h2>
          <div className="relative w-64">
            <input 
              type="text" 
              value={searchTerm} 
              onChange={(e) => setSearchTerm(e.target.value)}
              placeholder="BUSCAR NA BASE..." 
              className="w-full bg-white border-2 border-[#1A1A1A] px-4 py-2 text-[9px] font-black uppercase outline-none"
            />
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredDocs.length === 0 ? (
            <div className="col-span-full py-20 bg-white border-2 border-dashed border-[#1A1A1A]/20 flex flex-col items-center justify-center">
              <p className="text-[10px] font-black uppercase text-[#B5B5B5]">Nenhum dado integrado</p>
            </div>
          ) : (
            filteredDocs.map((doc) => (
              <div key={doc.id} className="bg-white sketch-border p-5 group hover:bg-[#F2EFEA] transition-all flex flex-col h-full relative overflow-hidden">
                <div className="flex justify-between items-start mb-4">
                  <span className={`text-[7px] font-black px-2 py-1 rounded border ${getSourceStyle(doc.sourceType)}`}>
                    {doc.sourceType.replace('_', ' ').toUpperCase()}
                  </span>
                  <span className={`text-[7px] font-black px-2 py-1 uppercase tracking-tighter ${getCategoryStyle(doc.metadata?.category || 'general')}`}>
                    {doc.metadata?.category || 'GERAL'}
                  </span>
                </div>

                <h3 className="text-[11px] font-black uppercase mb-2 truncate pr-6">{doc.name}</h3>
                <p className="text-[9px] font-medium text-[#7A7A7A] line-clamp-3 mb-6 overflow-hidden">
                  {doc.content.substring(0, 150)}...
                </p>

                <div className="mt-auto pt-4 border-t border-[#1A1A1A]/10 flex justify-between items-center">
                  <span className="text-[7px] font-bold text-[#B5B5B5] uppercase">
                    {doc.uploadDate.toLocaleDateString()} • {doc.size ? `${(doc.size / 1024).toFixed(1)} KB` : 'LINK CLOUD'}
                  </span>
                  <button 
                    onClick={() => deleteDoc(doc.id)} 
                    className="text-rose-500 opacity-0 group-hover:opacity-100 transition-opacity p-2 hover:bg-rose-50 rounded"
                  >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                    </svg>
                  </button>
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

export default DocumentManager;

import { GoogleGenAI } from "@google/genai";
import { StorageService } from "./storage.ts";

export const GeminiService = {
  generateChatResponse: async (prompt: string, history: any[]) => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const docs = StorageService.getDocuments();
    const context = docs.length > 0 
      ? `BASE DE CONHECIMENTO INTEGRADA (GOOGLE + LOCAL):\n${docs.map(d => `[PROVEDOR: ${d.sourceType.toUpperCase()}] [CATEGORIA: ${d.metadata?.category || 'GERAL'}] [ARQUIVO: ${d.name}]\nCONTEÚDO: ${d.content}`).join('\n\n')}`
      : "O usuário ainda não conectou documentos ou serviços Google.";

    const systemInstruction = `
      Você é o "FinaIGPT", uma IA de elite especializada em Finanças, Contabilidade e Auditoria.

      OBJETIVO: Realizar cálculos complexos, análise técnica de documentos e organizar dados para EXPORTAÇÃO PARA PLANILHAS.

      DIRETRIZES TÉCNICAS:
      1. RIGOR MATEMÁTICO: Sempre utilize as fórmulas oficiais (CPC/IFRS). 
         - EBITDA, WACC, ROI, Liquidez, Margem de Contribuição, Ponto de Equilíbrio.
      2. ESTRUTURAÇÃO DE DADOS: Quando gerar tabelas, use Markdown rigoroso. 
      3. CONTEXTO RAG: Utilize as informações da "BASE DE CONHECIMENTO" fornecida abaixo para responder de forma precisa. Se a informação não estiver lá, você pode usar seu conhecimento geral ou o Google Search se habilitado.

      CONTEXTO RAG ATUAL:
      ${context}
    `;

    // History already contains the latest user message from the ChatInterface updatedMessages state
    const formattedHistory = history
      .filter(msg => msg.id !== 'welcome' && msg.id !== 'reset') 
      .map(msg => ({
        role: msg.role === 'user' ? 'user' : 'model',
        parts: [{ text: msg.content }]
      }));

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview', // Upgraded for math and reasoning
        contents: formattedHistory,
        config: {
          systemInstruction,
          tools: [{ googleSearch: {} }]
        },
      });

      return {
        text: response.text || "Erro no processamento da IA.",
        groundingMetadata: response.candidates?.[0]?.groundingMetadata
      };
    } catch (error) {
      console.error("Gemini Error:", error);
      throw error;
    }
  },

  generateTitle: async (firstPrompt: string): Promise<string> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Analise a intenção e palavras-chave desta consulta e crie um título curto (máximo 5 palavras) em português. Retorne APENAS o título: "${firstPrompt}"`,
        config: {
          temperature: 0.5,
          maxOutputTokens: 20
        }
      });
      return response.text?.replace(/["']/g, '').trim() || firstPrompt.substring(0, 30);
    } catch (e) {
      return firstPrompt.substring(0, 30);
    }
  }
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Message, ChatSession } from '../types.ts';
import { GeminiService } from '../services/geminiService.ts';
import { StorageService } from '../services/storage.ts';

const ChatInterface: React.FC = () => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string>('');
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [showHistory, setShowHistory] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  const WELCOME_MESSAGE: Message = {
    id: 'welcome',
    role: 'model',
    content: '### TERMINAL FINAIGPT INICIALIZADO\n\nPronto para cálculos financeiros avançados e análise técnica.\n\n- **Cálculos Ativos:** DRE, WACC, ROI, Tributos\n- **Exportação:** CSV disponível\n- **Cloud Sync:** Drive Ativo\n\n**Sugestões:**\n1. "Calcule o EBITDA desta empresa: Receita 500k, Custos 300k, Depreciação 20k."\n2. "Monte uma tabela de Simples Nacional Anexo III."',
    timestamp: new Date()
  };

  const loadData = useCallback(() => {
    const activeSessions = StorageService.getChatSessions();
    setSessions(activeSessions);

    if (currentSessionId) {
      const current = activeSessions.find(s => s.id === currentSessionId);
      if (current) {
        setMessages(current.messages);
      } else if (activeSessions.length > 0) {
        switchSession(activeSessions[0].id);
      } else {
        createNewChat();
      }
    } else if (activeSessions.length > 0) {
      switchSession(activeSessions[0].id);
    } else {
      createNewChat();
    }
  }, [currentSessionId]);

  useEffect(() => {
    loadData();
    const handleSyncEvent = () => {
      const updated = StorageService.getChatSessions();
      setSessions(updated);
    };
    window.addEventListener('session_synced', handleSyncEvent);
    return () => window.removeEventListener('session_synced', handleSyncEvent);
  }, [loadData]);

  useEffect(() => {
    if (scrollRef.current) {
      requestAnimationFrame(() => {
        if (scrollRef.current) {
          scrollRef.current.scrollTo({
            top: scrollRef.current.scrollHeight,
            behavior: 'smooth'
          });
        }
      });
    }
  }, [messages, isTyping]);

  const createNewChat = () => {
    const newId = Date.now().toString();
    setCurrentSessionId(newId);
    setMessages([WELCOME_MESSAGE]);
    if (window.innerWidth < 1024) setShowHistory(false);
  };

  const switchSession = (id: string) => {
    const session = StorageService.getChatSessions().find(s => s.id === id);
    if (session) {
      setCurrentSessionId(id);
      setMessages(session.messages);
    }
    if (window.innerWidth < 1024) setShowHistory(false);
  };

  const handleDeleteSession = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (window.confirm("Excluir chat permanentemente?")) {
      StorageService.deleteChatSession(id);
      const remaining = StorageService.getChatSessions();
      setSessions(remaining);
      if (id === currentSessionId) {
        if (remaining.length > 0) switchSession(remaining[0].id);
        else createNewChat();
      }
    }
  };

  const persistSession = useCallback((id: string, msgs: Message[], title?: string) => {
    if (!id || msgs.length === 0) return;
    const existingSessions = StorageService.getChatSessions();
    const existingSession = existingSessions.find(s => s.id === id);

    const hasUserContent = msgs.some(m => m.role === 'user');
    if (!hasUserContent) return;

    const firstUserMsg = msgs.find(m => m.role === 'user')?.content.substring(0, 30);
    const newTitle = title || existingSession?.title || firstUserMsg || 'Nova Conversa';

    const session: ChatSession = { 
      id, 
      title: newTitle, 
      messages: msgs, 
      lastUpdate: new Date(),
      updatedAt: new Date().toISOString(),
      version: existingSession ? existingSession.version + 1 : 1
    };

    StorageService.saveChatSession(session);
    setSessions(StorageService.getChatSessions());
  }, []);

  const exportTableToCSV = (tableData: string[][], fileName: string) => {
    const csvContent = tableData
      .map(row => row.map(cell => `"${cell.trim().replace(/"/g, '""')}"`).join(','))
      .join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.setAttribute("href", url);
    link.setAttribute("download", `${fileName.replace(/\s+/g, '_')}_FinaIGPT.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;

    const userMessage: Message = { 
      id: Date.now().toString(), 
      role: 'user', 
      content: input, 
      timestamp: new Date() 
    };

    const updatedMessages = [...messages, userMessage];
    setMessages(updatedMessages);
    const currentInput = input;
    setInput('');
    setIsTyping(true);

    persistSession(currentSessionId, updatedMessages);

    if (messages.filter(m => m.role === 'user').length === 0) {
      GeminiService.generateTitle(currentInput).then(title => {
        persistSession(currentSessionId, updatedMessages, title);
      });
    }

    try {
      const response = await GeminiService.generateChatResponse(currentInput, updatedMessages);

      const sources: string[] = [];
      if (response.groundingMetadata?.groundingChunks) {
        response.groundingMetadata.groundingChunks.forEach((chunk: any) => {
          if (chunk.web?.uri) sources.push(chunk.web.uri);
        });
      }

      const modelMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: response.text,
        timestamp: new Date(),
        sources: sources.length > 0 ? Array.from(new Set(sources)) : undefined
      };

      const finalMessages = [...updatedMessages, modelMessage];
      setMessages(finalMessages);
      persistSession(currentSessionId, finalMessages);
    } catch (error) {
      setMessages(prev => [...prev, { 
        id: Date.now().toString(), 
        role: 'model', 
        content: '### ERRO CRÍTICO\nFalha na comunicação com o processador de IA. Verifique sua conexão ou tente novamente.', 
        timestamp: new Date() 
      }]);
    } finally {
      setIsTyping(false);
    }
  };

  const renderFormattedContent = (content: string) => {
    const lines = content.split('\n');
    let elements: React.ReactNode[] = [];
    let currentTable: string[][] = [];

    const parseText = (text: string) => {
      const parts = text.split(/(\*\*.*?\*\*)/g);
      return parts.map((part, i) => {
        if (part.startsWith('**') && part.endsWith('**')) {
          return <strong key={i}>{part.slice(2, -2)}</strong>;
        }
        return part;
      });
    };

    const flushTable = (key: number) => {
      if (currentTable.length === 0) return null;
      const cleanTable = currentTable.filter(row => !row.every(cell => cell.trim().match(/^[:\s-]*$/)));
      if (cleanTable.length === 0) {
        currentTable = [];
        return null;
      }

      const tableEl = (
        <div key={`table-${key}`} className="my-6 overflow-x-auto w-full">
          <div className="flex justify-between items-center mb-2">
            <span className="text-[7px] font-black uppercase tracking-widest text-[#7A7A7A]">Planilha Gerada</span>
            <button 
              onClick={() => exportTableToCSV(cleanTable, "Relatorio_Financeiro")}
              className="text-[8px] font-black bg-emerald-600 text-white px-2 py-1 flex items-center gap-1 hover:bg-emerald-700 active:translate-y-px transition-all border border-[#1A1A1A]"
            >
              EXPORTAR .CSV
            </button>
          </div>
          <table className="min-w-full border-collapse text-[10px] text-[#1A1A1A] bg-white border-2 border-[#1A1A1A]">
            <thead>
              <tr className="bg-[#1A1A1A] text-white">
                {cleanTable[0].map((cell, j) => (
                  <th key={j} className="px-4 py-3 border border-[#1A1A1A] font-black uppercase text-left">{cell.trim()}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {cleanTable.slice(1).map((row, i) => (
                <tr key={i} className="hover:bg-[#F2EFEA]">
                  {row.map((cell, j) => (
                    <td key={j} className="px-4 py-3 border border-[#1A1A1A] font-bold uppercase">{cell.trim()}</td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      );
      currentTable = [];
      return tableEl;
    };

    lines.forEach((line, idx) => {
      const trimmed = line.trim();
      if (trimmed.startsWith('|') && trimmed.includes('|')) {
        const row = trimmed.split('|').filter((_, i, arr) => i > 0 && i < arr.length - 1);
        if (row.length > 0) currentTable.push(row);
      } else {
        const table = flushTable(idx);
        if (table) elements.push(table);

        if (trimmed.startsWith('###')) {
          elements.push(<h3 key={idx} className="text-xs font-black mt-6 mb-3 uppercase border-b-2 border-[#1A1A1A] pb-1">{trimmed.replace('###', '')}</h3>);
        } else if (trimmed.startsWith('-') || trimmed.startsWith('*')) {
          elements.push(<li key={idx} className="text-[10px] font-medium leading-relaxed mb-1 ml-4 list-disc">{parseText(trimmed.substring(1).trim())}</li>);
        } else if (trimmed !== '') {
          elements.push(<p key={idx} className="text-[10px] font-medium leading-relaxed mb-3">{parseText(line)}</p>);
        }
      }
    });

    const finalTable = flushTable(lines.length);
    if (finalTable) elements.push(finalTable);

    return elements;
  };

  return (
    <div className="flex h-full bg-[#F2EFEA] relative overflow-hidden">
      {/* Sessions History Sidebar */}
      <div className={`
        absolute lg:relative inset-y-0 left-0 z-30 w-72 bg-white border-r-2 border-[#1A1A1A] transform transition-transform duration-300
        ${showHistory ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}
      `}>
        <div className="flex flex-col h-full p-6">
          <div className="flex justify-between items-center mb-8">
            <h2 className="text-xs font-black uppercase tracking-widest">HISTÓRICO</h2>
            <button onClick={createNewChat} className="bg-[#1A1A1A] text-white p-2 hover:bg-[#4A4A4A] transition-colors">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" /></svg>
            </button>
          </div>

          <div className="flex-1 overflow-y-auto space-y-3 pr-2">
            {sessions.map((s) => (
              <div 
                key={s.id} 
                onClick={() => switchSession(s.id)}
                className={`
                  p-4 border-2 cursor-pointer transition-all group relative
                  ${s.id === currentSessionId ? 'bg-[#1A1A1A] text-white border-[#1A1A1A] shadow-none' : 'bg-white text-[#1A1A1A] border-[#1A1A1A] hover:bg-[#F2EFEA]'}
                `}
              >
                <p className="text-[9px] font-black uppercase truncate pr-6">{s.title}</p>
