import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Message, ChatSession, ViewState } from '../types.ts';
import { GeminiService } from '../services/geminiService.ts';
import { StorageService } from '../services/storage.ts';

const ChatInterface: React.FC = () => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);

  // Load sessions on mount
  useEffect(() => {
    const loadedSessions = StorageService.getChatSessions();
    setSessions(loadedSessions);
    if (loadedSessions.length > 0) {
      setCurrentSessionId(loadedSessions[0].id);
    }
  }, []);

  const currentSession = sessions.find(s => s.id === currentSessionId);

  // Auto-scroll logic
  const scrollToBottom = useCallback(() => {
    if (scrollRef.current) {
      const { scrollHeight, clientHeight } = scrollRef.current;
      scrollRef.current.scrollTo({
        top: scrollHeight - clientHeight,
        behavior: 'smooth'
      });
    }
  }, []);

  useEffect(() => {
    scrollToBottom();
  }, [currentSession?.messages, isLoading, scrollToBottom]);

  const handleNewChat = () => {
    const newSession: ChatSession = {
      id: Math.random().toString(36).substr(2, 9),
      title: 'Nova Consulta Contábil',
      messages: [],
      lastUpdate: new Date(),
      updatedAt: new Date().toISOString(),
      version: 1,
      syncStatus: 'local'
    };
    const updated = [newSession, ...sessions];
    setSessions(updated);
    setCurrentSessionId(newSession.id);
    StorageService.saveChatSession(newSession);
    setIsHistoryOpen(false);
  };

  const handleSendMessage = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      timestamp: new Date()
    };

    let targetSession = currentSession;
    let updatedSessions = [...sessions];

    // Create session if none exists
    if (!targetSession) {
      const newSession: ChatSession = {
        id: Math.random().toString(36).substr(2, 9),
        title: input.substring(0, 30),
        messages: [userMessage],
        lastUpdate: new Date(),
        updatedAt: new Date().toISOString(),
        version: 1,
        syncStatus: 'local'
      };
      updatedSessions = [newSession, ...sessions];
      setSessions(updatedSessions);
      setCurrentSessionId(newSession.id);
      targetSession = newSession;
    } else {
      targetSession.messages.push(userMessage);
      setSessions([...updatedSessions]);
    }

    setInput('');
    setIsLoading(true);

    try {
      const response = await GeminiService.generateChatResponse(input, targetSession.messages);

      const modelMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: response.text,
        timestamp: new Date(),
        sources: response.groundingMetadata?.groundingChunks?.map((c: any) => c.web?.uri || c.maps?.uri).filter(Boolean)
      };

      targetSession.messages.push(modelMessage);

      // Update Title if it's the first exchange
      if (targetSession.messages.length <= 3) {
        const newTitle = await GeminiService.generateTitle(input);
        targetSession.title = newTitle;
      }

      setSessions([...updatedSessions]);
      StorageService.saveChatSession(targetSession);
    } catch (error) {
      console.error("Chat Error:", error);
      const errorMessage: Message = {
        id: 'error-' + Date.now(),
        role: 'model',
        content: "Desculpe, ocorreu um erro técnico no processamento da sua solicitação. Por favor, verifique sua conexão ou tente novamente.",
        timestamp: new Date()
      };
      targetSession.messages.push(errorMessage);
      setSessions([...updatedSessions]);
    } finally {
      setIsLoading(false);
    }
  };

  const deleteSession = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (window.confirm("Mover esta conversa para a lixeira?")) {
      StorageService.deleteChatSession(id);
      const filtered = sessions.filter(s => s.id !== id);
      setSessions(filtered);
      if (currentSessionId === id) {
        setCurrentSessionId(filtered.length > 0 ? filtered[0].id : null);
      }
    }
  };

  const renderMessageContent = (content: string) => {
    // Basic Markdown Table support for the sketch UI
    if (content.includes('|')) {
      const lines = content.split('\n');
      return lines.map((line, i) => {
        if (line.trim().startsWith('|') && line.trim().endsWith('|')) {
          const cells = line.split('|').filter(c => c.trim() !== '');
          return (
            <div key={i} className="flex border-b border-[#1A1A1A] last:border-0 hover:bg-black/5">
              {cells.map((cell, ci) => (
                <div key={ci} className="flex-1 p-2 text-[10px] font-bold border-r border-[#1A1A1A] last:border-0 uppercase truncate">
                  {cell.trim()}
                </div>
              ))}
            </div>
          );
        }
        return <p key={i} className="mb-2 last:mb-0 leading-relaxed">{line}</p>;
      });
    }
    return content.split('\n').map((line, i) => <p key={i} className="mb-2 last:mb-0 leading-relaxed">{line}</p>);
  };

  return (
    <div className="flex h-full bg-[#F2EFEA] overflow-hidden relative">
      {/* Session History Sidebar (Drawer on Mobile) */}
      <aside className={`
        fixed inset-y-0 left-0 z-40 w-72 bg-[#1A1A1A] text-[#B5B5B5] flex flex-col transition-transform duration-300 transform border-r-2 border-[#1A1A1A]
