                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13" />
                  </svg>
                </button>
              </div>
            </div>
            <button 
              type="submit"
              disabled={isLoading || !input.trim()}
              className={`
                bg-[#1A1A1A] text-white font-black p-4 sketch-border shadow-none min-w-[60px] flex items-center justify-center transition-all
                ${(isLoading || !input.trim()) ? 'opacity-50' : 'hover:-translate-y-1 active:translate-y-px active:shadow-none'}
              `}
            >
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
