import { GoogleGenAI } from "@google/genai";
import { StorageService } from "./storage.ts";

export const GeminiService = {
  generateChatResponse: async (prompt: string, history: any[]) => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const docs = StorageService.getDocuments();
    const context = docs.length > 0 
      ? `BASE DE CONHECIMENTO INTEGRADA:\n${docs.map(d => `[ORIGEM: ${d.sourceType.toUpperCase()}] [CATEGORIA: ${d.metadata?.category || 'GERAL'}] [ARQUIVO: ${d.name}]\nCONTEÚDO: ${d.content}`).join('\n\n')}`
      : "O usuário ainda não conectou documentos ou serviços Google.";

    const systemInstruction = `
      Você é o "FinaIGPT", um Auditor de Elite e Analista Contábil Sênior.

      PROTOCOLO DE RESPOSTA EM 2 ETAPAS:
      1. EXECUÇÃO TÉCNICA: Realize os cálculos financeiros utilizando rigorosamente as normas CPC (Brasil) e IFRS (Internacional). 
      2. AUDITORIA INTERNA: Revise seus próprios cálculos, verifique erros de arredondamento, integridade de fórmulas e conformidade normativa antes de exibir o resultado.

      REGRAS DE OURO:
      - CITE A NORMA: Sempre que aplicar um conceito contábil, cite o CPC correspondente (Ex: CPC 01 para Teste de Recuperabilidade, CPC 20 para Custos de Empréstimos).
      - MEMÓRIA DE CÁLCULO: Exiba claramente as variáveis e a fórmula utilizada antes do resultado final.
      - TABELAS FINANCEIRAS: Use tabelas Markdown para balanços, DREs e fluxos de caixa.
      - RIGOR MATEMÁTICO: Diferencie claramente Juros Simples de Compostos, Amortização SAC de PRICE, e utilize as definições corretas de EBITDA (LAJIDA) vs EBIT.

      CONTEXTO DE DADOS (RAG):
      ${context}
    `;

    const formattedHistory = history
      .filter(msg => msg.id !== 'welcome' && msg.id !== 'reset') 
      .map(msg => ({
        role: msg.role === 'user' ? 'user' : 'model',
        parts: [{ text: msg.content }]
      }));

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: formattedHistory,
        config: {
          systemInstruction,
          tools: [{ googleSearch: {} }],
          thinkingConfig: { thinkingBudget: 15000 }, // Budget para raciocínio contábil complexo
          temperature: 0.2 // Baixa temperatura para maior precisão matemática
        },
      });

      return {
        text: response.text || "Erro no processamento da IA.",
        groundingMetadata: response.candidates?.[0]?.groundingMetadata
      };
    } catch (error) {
      console.error("Gemini Error:", error);
      throw error;
    }
  },

  generateTitle: async (firstPrompt: string): Promise<string> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Crie um título técnico e curto para esta consulta contábil/financeira: "${firstPrompt}"`,
        config: {
          temperature: 0.5,
          maxOutputTokens: 20
        }
      });
      return response.text?.replace(/["']/g, '').trim() || firstPrompt.substring(0, 30);
    } catch (e) {
      return firstPrompt.substring(0, 30);
    }
  }
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Message, ChatSession } from '../types.ts';
import { GeminiService } from '../services/geminiService.ts';
import { StorageService } from '../services/storage.ts';

const ChatInterface: React.FC = () => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [auditStep, setAuditStep] = useState<1 | 2>(1);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    const loadedSessions = StorageService.getChatSessions();
    setSessions(loadedSessions);
    if (loadedSessions.length > 0 && !currentSessionId) {
      setCurrentSessionId(loadedSessions[0].id);
    }
  }, []);

  const currentSession = sessions.find(s => s.id === currentSessionId);

  const scrollToBottom = useCallback(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, []);

  useEffect(() => {
    scrollToBottom();
  }, [currentSession?.messages, isLoading, scrollToBottom]);

  useEffect(() => {
    let interval: any;
    if (isLoading) {
      setAuditStep(1);
      interval = setInterval(() => {
        setAuditStep(prev => (prev === 1 ? 2 : 1));
      }, 2500);
    }
    return () => clearInterval(interval);
  }, [isLoading]);

  const handleNewChat = () => {
    const newSession: ChatSession = {
      id: Math.random().toString(36).substr(2, 9),
      title: 'Nova Consulta Contábil',
      messages: [],
      lastUpdate: new Date(),
      updatedAt: new Date().toISOString(),
      version: 1,
      syncStatus: 'local'
    };
    setSessions(prev => [newSession, ...prev]);
    setCurrentSessionId(newSession.id);
    StorageService.saveChatSession(newSession);
    setIsHistoryOpen(false);
  };

  const handleSendMessage = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading) return;

    const userMsg = input.trim();
    setInput('');

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: userMsg,
      timestamp: new Date()
    };

    let targetSession = currentSession;
    let updatedSessions = [...sessions];

    if (!targetSession) {
      targetSession = {
        id: Math.random().toString(36).substr(2, 9),
        title: userMsg.substring(0, 30),
        messages: [userMessage],
        lastUpdate: new Date(),
        updatedAt: new Date().toISOString(),
        version: 1,
        syncStatus: 'local'
      };
      updatedSessions = [targetSession, ...sessions];
      setSessions(updatedSessions);
      setCurrentSessionId(targetSession.id);
    } else {
      const sessionIndex = updatedSessions.findIndex(s => s.id === targetSession!.id);
      const updatedSession = {
        ...targetSession,
        messages: [...targetSession.messages, userMessage],
        lastUpdate: new Date(),
        updatedAt: new Date().toISOString()
      };
      updatedSessions[sessionIndex] = updatedSession;
      setSessions(updatedSessions);
      targetSession = updatedSession;
    }

    setIsLoading(true);

    try {
      const response = await GeminiService.generateChatResponse(userMsg, targetSession.messages);

      const modelMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: response.text,
        timestamp: new Date(),
        sources: response.groundingMetadata?.groundingChunks?.map((c: any) => c.web?.uri || c.maps?.uri).filter(Boolean)
      };

      const finalSession = {
        ...targetSession,
        messages: [...targetSession.messages, modelMessage],
        lastUpdate: new Date(),
        updatedAt: new Date().toISOString()
      };

      if (finalSession.messages.length <= 3) {
        const newTitle = await GeminiService.generateTitle(userMsg);
        finalSession.title = newTitle;
      }

      const finalSessions = updatedSessions.map(s => s.id === finalSession.id ? finalSession : s);
      setSessions(finalSessions);
      StorageService.saveChatSession(finalSession);
    } catch (error) {
      console.error("Chat Error:", error);
      const errorMessage: Message = {
        id: 'error-' + Date.now(),
        role: 'model',
        content: "### FALHA NO PROTOCOLO\nErro de processamento nos cálculos IFRS. Verifique a integridade dos dados e tente novamente.",
        timestamp: new Date()
      };
      const errorSession = {
        ...targetSession,
        messages: [...targetSession.messages, errorMessage]
      };
      setSessions(updatedSessions.map(s => s.id === errorSession.id ? errorSession : s));
    } finally {
      setIsLoading(false);
    }
  };

  const deleteSession = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    StorageService.deleteChatSession(id);
    const filtered = sessions.filter(s => s.id !== id);
    setSessions(filtered);
    if (currentSessionId === id) {
      setCurrentSessionId(filtered.length > 0 ? filtered[0].id : null);
    }
  };

  const renderMessageContent = (content: string) => {
    const lines = content.split('\n');
    const elements: React.ReactNode[] = [];
    let currentTable: string[][] = [];
    let isInsideTable = false;

    const pushTable = (key: string) => {
      if (currentTable.length > 0) {
        elements.push(
          <div key={key} className="my-4 overflow-x-auto sketch-border bg-white p-0">
            <table className="w-full text-left text-[9px] md:text-[10px] border-collapse">
              <thead>
                <tr className="bg-[#1A1A1A] text-white">
                  {currentTable[0].map((cell, i) => (
                    <th key={i} className="p-3 font-black uppercase tracking-widest border-r border-white/10 last:border-0">{cell}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {currentTable.slice(1).map((row, ri) => (
                  <tr key={ri} className="border-b border-[#1A1A1A]/10 hover:bg-[#F2EFEA]">
                    {row.map((cell, ci) => {
                      const cleanCell = cell.trim();
                      const isNeg = cleanCell.startsWith('-') || cleanCell.startsWith('(');
                      return (
                        <td key={ci} className={`p-3 font-bold border-r border-[#1A1A1A]/10 last:border-0 ${isNeg ? 'text-rose-600' : 'text-[#1A1A1A]'}`}>
                          {cleanCell}
                        </td>
                      );
                    })}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        );
        currentTable = [];
      }
    };

    lines.forEach((line, index) => {
      const trimmed = line.trim();
      const isTableLine = trimmed.startsWith('|') && trimmed.includes('|');

      if (isTableLine) {
        isInsideTable = true;
        const cells = line.split('|').map(c => c.trim()).filter((_, i, arr) => i > 0 && i < arr.length - 1);
        if (!cells.every(c => c.match(/^-+$/) || c === '')) {
          currentTable.push(cells);
        }
      } else {
        if (isInsideTable) {
          pushTable(`table-${index}`);
          isInsideTable = false;
        }

        if (trimmed) {
          if (trimmed.startsWith('#')) {
            elements.push(<h4 key={index} className="text-sm font-black uppercase mt-6 mb-3 text-[#1A1A1A] border-b-2 border-[#1A1A1A] pb-1">{trimmed.replace(/#/g, '').trim()}</h4>);
          } else if (trimmed.startsWith('**') && trimmed.endsWith('**')) {
            elements.push(<p key={index} className="font-black uppercase text-[10px] mb-2">{trimmed.replace(/\*\*/g, '')}</p>);
          } else {
            elements.push(<p key={index} className="text-[11px] leading-relaxed mb-3 text-[#333]">{trimmed}</p>);
          }
        }
      }
    });

    if (isInsideTable) pushTable('final-table');
    return elements;
  };

  return (
    <div className="flex h-full bg-[#F2EFEA] overflow-hidden relative">
      {/* Mobile History Toggle */}
      <button 
        onClick={() => setIsHistoryOpen(!isHistoryOpen)}
        className="lg:hidden absolute top-4 left-4 z-50 p-2 bg-[#1A1A1A] text-white sketch-border active:scale-95 transition-all"
      >
        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M4 6h16M4 12h16M4 18h16" strokeWidth={2.5} /></svg>
      </button>

      {/* History Sidebar */}
      <aside className={`
        fixed inset-y-0 left-0 z-40 w-72 bg-[#1A1A1A] text-[#B5B5B5] flex flex-col transition-transform duration-300 transform border-r-2 border-[#1A1A1A]
        ${isHistoryOpen ? 'translate-x-0' : '-translate-x-full'}
        lg:relative lg:translate-x-0 lg:z-0
      `}>
        <div className="p-6 border-b border-[#4A4A4A] flex justify-between items-center bg-[#1A1A1A] shrink-0 pt-safe">
          <h2 className="text-[10px] font-black uppercase tracking-widest text-white">PROTOCOLOS ATIVOS</h2>
          <button onClick={handleNewChat} className="p-2 bg-[#F2EFEA] text-[#1A1A1A] sketch-border hover:bg-white active:scale-95 transition-all">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
          </button>
        </div>

        <div className="flex-1 overflow-y-auto scroll-smooth custom-scrollbar p-4 space-y-2 touch-pan-y">
          {sessions.length === 0 ? (
            <div className="text-center py-20 px-6">
              <p className="text-[8px] font-black text-[#4A4A4A] uppercase tracking-widest leading-loose">Nenhuma consulta registrada no terminal</p>
            </div>
          ) : (
            sessions.map(s => (
              <div key={s.id} className="group relative">
                <button
                  onClick={() => { setCurrentSessionId(s.id); setIsHistoryOpen(false); }}
                  className={`w-full text-left p-4 sketch-border shadow-none transition-all ${currentSessionId === s.id ? 'bg-[#F2EFEA] text-[#1A1A1A] translate-x-1' : 'bg-[#2A2A2A] hover:bg-[#333]'}`}
                >
                  <span className="text-[9px] font-black uppercase tracking-tight line-clamp-2 pr-6">{s.title}</span>
                  <p className="text-[7px] font-bold mt-2 opacity-50 uppercase">{new Date(s.lastUpdate).toLocaleDateString()}</p>
                </button>
                <button 
                  onClick={(e) => deleteSession(e, s.id)}
                  className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 p-1 text-rose-500 hover:bg-rose-500/10 rounded transition-all"
                >
                  <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z" /></svg>
                </button>
              </div>
            ))
          )}
        </div>
      </aside>

      {/* Main Chat Area */}
      <div className="flex-1 flex flex-col min-w-0 bg-[#F2EFEA] relative">
        {/* Messages */}
        <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8 scroll-smooth custom-scrollbar pb-32 pt-16 lg:pt-8">
          {!currentSession || currentSession.messages.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-center max-w-md mx-auto opacity-40">
              <div className="w-16 h-16 bg-[#1A1A1A] text-white flex items-center justify-center text-3xl font-black sketch-border mb-6">?</div>
              <h3 className="text-sm font-black uppercase tracking-widest mb-2">Terminal de Auditoria</h3>
              <p className="text-[10px] font-bold uppercase leading-relaxed">Insira dados financeiros ou anexe documentos para iniciar a validação normativa CPC/IFRS.</p>
            </div>
          ) : (
            currentSession.messages.map((msg) => (
              <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in slide-in-from-bottom-2 duration-300`}>
                <div className={`max-w-[85%] md:max-w-[70%] ${msg.role === 'user' ? 'bg-[#1A1A1A] text-white' : 'bg-white text-[#1A1A1A]'} p-5 sketch-border shadow-none`}>
                  <div className="flex items-center gap-2 mb-3">
                    <span className="text-[8px] font-black uppercase tracking-widest opacity-60">
                      {msg.role === 'user' ? 'SOLICITANTE' : 'AUDITOR FINAIGPT'}
                    </span>
                    <span className="text-[7px] font-bold opacity-30">
                      {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
