import React, { useState, useEffect, useRef } from 'react';
import { Document, DocumentSource } from '../types.ts';
import { StorageService } from '../services/storage.ts';
import { MarketService } from '../services/marketService.ts';

// Declare external libs for TypeScript
declare const pdfjsLib: any;
declare const mammoth: any;
declare const XLSX: any;

const DocumentManager: React.FC = () => {
  const [documents, setDocuments] = useState<Document[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [parsingStatus, setParsingStatus] = useState<string>('');
  const [searchTerm, setSearchTerm] = useState('');
  const [externalUrl, setExternalUrl] = useState('');
  const [selectedProvider, setSelectedProvider] = useState<DocumentSource>('google_docs');
  const [selectedCategory, setSelectedCategory] = useState<'cost' | 'tax' | 'management' | 'general' | 'exercise'>('general');

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    setDocuments(StorageService.getDocuments());
    // Configure PDF.js worker
    if (typeof pdfjsLib !== 'undefined') {
      pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
    }
  }, []);

  const parsePDF = async (file: File): Promise<string> => {
    const arrayBuffer = await file.arrayBuffer();
    const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
    let fullText = "";
    for (let i = 1; i <= pdf.numPages; i++) {
      const page = await pdf.getPage(i);
      const textContent = await page.getTextContent();
      const pageText = textContent.items.map((item: any) => item.str).join(" ");
      fullText += pageText + "\n";
    }
    return fullText;
  };

  const parseDOCX = async (file: File): Promise<string> => {
    const arrayBuffer = await file.arrayBuffer();
    const result = await mammoth.extractRawText({ arrayBuffer });
    return result.value;
  };

  const parseExcel = async (file: File): Promise<string> => {
    const arrayBuffer = await file.arrayBuffer();
    const workbook = XLSX.read(arrayBuffer, { type: 'array' });
    let fullText = "";

    workbook.SheetNames.forEach((sheetName: string) => {
      const worksheet = workbook.Sheets[sheetName];
      const csv = XLSX.utils.sheet_to_csv(worksheet);
      fullText += `--- ABA: ${sheetName.toUpperCase()} ---\n${csv}\n\n`;
    });

    return fullText;
  };

  const handleFiles = async (files: FileList) => {
    setIsUploading(true);
    const filesArray = Array.from(files);

    for (const file of filesArray) {
      try {
        setParsingStatus(`Processando ${file.name}...`);
        let content = "";
        const fileExt = file.name.split('.').pop()?.toLowerCase();

        if (file.type === "application/pdf" || fileExt === 'pdf') {
          content = await parsePDF(file);
        } else if (file.type === "application/vnd.openxmlformats-officedocument.wordprocessingml.document" || fileExt === 'docx') {
          content = await parseDOCX(file);
        } else if (
          file.type === "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" || 
          file.type === "application/vnd.ms-excel" ||
          ['xlsx', 'xls', 'xlsm'].includes(fileExt || '')
        ) {
          content = await parseExcel(file);
        } else {
          content = await file.text();
        }

        const doc: Document = {
          id: Math.random().toString(36).substr(2, 9),
          name: file.name,
          content: content,
          type: file.type || 'text/plain',
          uploadDate: new Date(),
          size: file.size,
          sourceType: 'local',
          metadata: {
            category: selectedCategory,
            lastSync: new Date()
          }
        };

        StorageService.saveDocument(doc);
        setDocuments(prev => [doc, ...prev]);
      } catch (e) {
        console.error(`Falha ao ler ${file.name}:`, e);
      }
    }

    setIsUploading(false);
    setParsingStatus('');
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleAddExternal = async () => {
    if (!externalUrl) return;
    setIsUploading(true);
    setParsingStatus('Sincronizando com Google Workspace API...');

    let content = `[DATA_SOURCE: ${selectedProvider.toUpperCase()}]\nURL: ${externalUrl}\nConectado via Proxy Cloud FinaIGPT.`;

    if (selectedProvider === 'google_analytics') {
      setParsingStatus('Autenticando e extraindo métricas do Google Analytics...');
      const metrics = await MarketService.fetchMockAnalytics(externalUrl);
      content = JSON.stringify(metrics);
    }

    const doc: Document = {
      id: Math.random().toString(36).substr(2, 9),
      name: `${selectedProvider === 'google_analytics' ? 'Propriedade GA4' : 'Cloud'}: ${externalUrl.split('/').pop()?.substring(0, 20)}`,
      content: content,
      type: selectedProvider === 'google_analytics' ? 'application/json' : 'external/link',
      uploadDate: new Date(),
      size: 0,
      sourceType: selectedProvider,
      externalUrl: externalUrl,
      metadata: {
        category: selectedCategory,
        lastSync: new Date()
      }
    };

    StorageService.saveDocument(doc);
    setDocuments(prev => [doc, ...prev]);
    setExternalUrl('');
    setIsUploading(false);
    setParsingStatus('');
  };

  const exportToNotebookLM = () => {
    const bundle = documents.map(d => (
      `========================================\n` +
      `FONTE: ${d.name}\n` +
      `ORIGEM: ${d.sourceType.toUpperCase()}\n` +
      `CATEGORIA: ${d.metadata?.category?.toUpperCase() || 'GERAL'}\n` +
      `----------------------------------------\n` +
      `${d.content}\n` +
      `========================================\n\n`
    )).join('');

    const blob = new Blob([bundle], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = window.document.createElement('a');
    a.href = url;
    a.download = `FinanGPT_Knowledge_Base_${new Date().toISOString().split('T')[0]}.txt`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const deleteDoc = (id: string) => {
    if (window.confirm("Remover este documento da base de conhecimento?")) {
      StorageService.deleteDocument(id);
      setDocuments(prev => prev.filter(d => d.id !== id));
    }
  };

  const filteredDocs = documents.filter(d => 
    d.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    d.metadata?.category?.includes(searchTerm.toLowerCase())
  );

  const getSourceStyle = (source: DocumentSource) => {
    switch (source) {
      case 'google_docs': return 'bg-blue-100 text-blue-700 border-blue-200';
      case 'google_sheets': return 'bg-emerald-100 text-emerald-700 border-emerald-200';
      case 'google_analytics': return 'bg-amber-100 text-amber-700 border-amber-200';
      default: return 'bg-gray-100 text-gray-700 border-gray-200';
    }
  };

  const getCategoryStyle = (cat: string) => {
    switch (cat) {
      case 'tax': return 'bg-rose-500 text-white';
      case 'cost': return 'bg-indigo-500 text-white';
      case 'management': return 'bg-emerald-500 text-white';
      case 'exercise': return 'bg-orange-500 text-white';
      default: return 'bg-[#1A1A1A] text-white';
    }
  };

  return (
    <div className="p-4 md:p-10 max-w-6xl mx-auto animate-in fade-in duration-500 overflow-y-auto h-full pb-20">
      <header className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 border-b-2 border-[#1A1A1A] pb-8 gap-6">
        <div>
          <h1 className="text-2xl md:text-3xl font-black text-[#1A1A1A] uppercase tracking-tighter leading-none">BASE DE DADOS RAG</h1>
          <p className="text-[#7A7A7A] mt-2 font-bold text-[9px] uppercase tracking-widest">Contabilidade • Google Workspace • Analytics</p>
        </div>
        <div className="flex flex-wrap gap-3">
          <button onClick={exportToNotebookLM} className="bg-[#1A1A1A] text-white font-black py-3 px-6 uppercase tracking-widest text-[9px] hover:bg-[#4A4A4A] sketch-border shadow-none transition-all active:translate-y-px">
            Exportar p/ NotebookLM
          </button>
          <button onClick={() => fileInputRef.current?.click()} className="sketch-button font-black py-3 px-6 uppercase tracking-widest text-[9px] active:scale-95 transition-all">
            + Upload Documentos
          </button>
        </div>
      </header>

      <input 
        ref={fileInputRef} 
        type="file" 
        multiple 
        accept=".pdf,.docx,.txt,.csv,.xlsx,.xls,.xlsm" 
        className="hidden" 
        onChange={(e) => e.target.files && handleFiles(e.target.files)} 
      />

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-12">
        <div className="md:col-span-1">
          <label className="text-[8px] font-black text-[#7A7A7A] uppercase mb-2 block tracking-widest">Vincular Categoria</label>
          <select value={selectedCategory} onChange={(e) => setSelectedCategory(e.target.value as any)} className="w-full bg-white border-2 border-[#1A1A1A] p-3 text-[10px] font-black uppercase outline-none focus:bg-[#F2EFEA]">
            <option value="general">Geral / Normas</option>
            <option value="cost">Custos / DRE</option>
            <option value="tax">Fiscal / Tributário</option>
            <option value="management">Gerencial / KPIs</option>
            <option value="exercise">Exercício Fiscal</option>
          </select>
        </div>
        <div className="md:col-span-3 bg-white sketch-border p-6 flex flex-col md:flex-row gap-4 items-end">
          <div className="flex-1 w-full">
            <label className="text-[8px] font-black text-[#7A7A7A] uppercase mb-2 block tracking-widest">Google Service Connector</label>
            <div className="flex flex-col md:flex-row gap-2">
              <select 
                value={selectedProvider} 
                onChange={(e) => setSelectedProvider(e.target.value as any)}
                className="bg-white border-2 border-[#1A1A1A] p-3 text-[10px] font-black uppercase md:w-48"
              >
                <option value="google_docs">Google Docs</option>
                <option value="google_sheets">Google Sheets</option>
                <option value="google_analytics">Google Analytics</option>
              </select>
              <input 
                type="text" 
                placeholder="Insira a URL ou ID da Propriedade" 
                className="flex-1 border-2 border-[#1A1A1A] p-3 text-[10px] font-bold outline-none focus:bg-[#F2EFEA]"
                value={externalUrl}
                onChange={(e) => setExternalUrl(e.target.value)}
              />
            </div>
          </div>
          <button 
            onClick={handleAddExternal}
            disabled={!externalUrl || isUploading}
            className="sketch-button py-3 px-8 font-black uppercase text-[9px] h-[48px] disabled:opacity-50"
          >
            Vincular
          </button>
        </div>
      </div>

      {parsingStatus && (
        <div className="mb-8 p-4 bg-[#1A1A1A] text-white sketch-border flex items-center gap-4 animate-pulse">
          <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
          <p className="text-[9px] font-black uppercase tracking-widest">{parsingStatus}</p>
        </div>
      )}

      <div className="mb-6">
        <input 
          type="text" 
          placeholder="PESQUISAR NA BASE DE CONHECIMENTO..." 
          className="w-full bg-transparent border-b-4 border-[#1A1A1A] p-4 text-xl font-black uppercase tracking-tighter outline-none placeholder:opacity-20"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredDocs.length === 0 ? (
          <div className="md:col-span-3 py-20 text-center opacity-30">
            <p className="text-sm font-black uppercase tracking-[0.3em]">Nenhum dado integrado ao terminal</p>
          </div>
        ) : (
          filteredDocs.map(doc => (
            <div key={doc.id} className="bg-white sketch-border p-6 flex flex-col justify-between hover:translate-x-1 transition-transform group">
              <div>
                <div className="flex justify-between items-start mb-4">
                  <span className={`text-[7px] font-black uppercase px-2 py-0.5 border-2 border-current rounded ${getSourceStyle(doc.sourceType)}`}>
                    {doc.sourceType.replace('_', ' ')}
                  </span>
                  <button onClick={() => deleteDoc(doc.id)} className="opacity-0 group-hover:opacity-100 text-rose-600">
                    <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path d="M4.293 4.293a1 1 0 011.414 0L10 8.586l4.293-4.293a1 1 0 111.414 1.414L11.414 10l4.293 4.293a1 1 0 01-1.414 1.414L10 11.414l-4.293 4.293a1 1 0 01-1.414-1.414L8.586 10 4.293 5.707a1 1 0 010-1.414z" /></svg>
                  </button>
                </div>
                <h3 className="text-xs font-black uppercase tracking-tight line-clamp-2 mb-2">{doc.name}</h3>
                <span className={`text-[8px] font-black px-2 py-1 sketch-border shadow-none ${getCategoryStyle(doc.metadata?.category || 'general')}`}>
                  {doc.metadata?.category?.toUpperCase() || 'GERAL'}
                </span>
              </div>
              <div className="mt-8 pt-4 border-t border-[#F2F2F2] flex justify-between items-end">
                <div>
                  <p className="text-[7px] font-bold text-[#7A7A7A] uppercase">Tamanho: {doc.size ? (doc.size / 1024).toFixed(1) + ' KB' : 'Cloud Sync'}</p>
                  <p className="text-[7px] font-bold text-[#7A7A7A] uppercase">Indexado: {new Date(doc.uploadDate).toLocaleDateString()}</p>
                </div>
                <div className="w-6 h-6 bg-[#1A1A1A] text-white flex items-center justify-center text-[8px] font-black">
                  {doc.type.split('/')[1]?.toUpperCase() || 'DOC'}
                </div>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default DocumentManager;

