import { GoogleGenAI, Type } from "@google/genai";
import { StorageService } from "./storage.ts";
import { NewsArticle } from "../types.ts";

export const GeminiService = {
  generateChatResponse: async (prompt: string, history: any[]) => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const docs = StorageService.getDocuments();
    const context = docs.length > 0 
      ? `BASE DE CONHECIMENTO INTEGRADA:\n${docs.map(d => `[ORIGEM: ${d.sourceType.toUpperCase()}] [CATEGORIA: ${d.metadata?.category || 'GERAL'}] [ARQUIVO: ${d.name}]\nCONTEÚDO: ${d.content}`).join('\n\n')}`
      : "O usuário ainda não conectou documentos ou serviços Google.";

    const systemInstruction = `
      Você é o "FinaIGPT", um Auditor de Elite e Analista Contábil Sênior.

      PROTOCOLO DE RESPOSTA EM 2 ETAPAS:
      1. EXECUÇÃO TÉCNICA: Realize os cálculos financeiros utilizando rigorosamente as normas CPC (Brasil) e IFRS (Internacional). 
      2. AUDITORIA INTERNA: Revise seus próprios cálculos, verifique erros de arredondamento, integridade de fórmulas e conformidade normativa antes de exibir o resultado.

      REGRAS DE OURO:
      - CITE A NORMA: Sempre que aplicar um conceito contábil, cite o CPC correspondente (Ex: CPC 01 para Teste de Recuperabilidade, CPC 20 para Custos de Empréstimos).
      - MEMÓRIA DE CÁLCULO: Exiba claramente as variáveis e a fórmula utilizada antes do resultado final.
      - TABELAS FINANCEIRAS: Use tabelas Markdown para balanços, DREs e fluxos de caixa.
      - RIGOR MATEMÁTICO: Diferencie claramente Juros Simples de Compostos, Amortização SAC de PRICE, e utilize as definições corretas de EBITDA (LAJIDA) vs EBIT.

      CONTEXTO DE DADOS (RAG):
      ${context}
    `;

    const formattedHistory = history
      .filter(msg => msg.id !== 'welcome' && msg.id !== 'reset') 
      .map(msg => ({
        role: msg.role === 'user' ? 'user' : 'model',
        parts: [{ text: msg.content }]
      }));

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: formattedHistory,
        config: {
          systemInstruction,
          tools: [{ googleSearch: {} }],
          thinkingConfig: { thinkingBudget: 15000 }, // Budget para raciocínio contábil complexo
          temperature: 0.2 // Baixa temperatura para maior precisão matemática
        },
      });

      return {
        text: response.text || "Erro no processamento da IA.",
        groundingMetadata: response.candidates?.[0]?.groundingMetadata
      };
    } catch (error) {
      console.error("Gemini Error:", error);
      throw error;
    }
  },

  fetchLatestNews: async (): Promise<NewsArticle[]> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: 'Extraia as 5 notícias financeiras mais relevantes e recentes do mercado brasileiro e internacional (foco em economia, impostos e mercado de capitais). Retorne estritamente um array JSON de objetos.',
        config: {
          tools: [{ googleSearch: {} }],
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                summary: { type: Type.STRING },
                url: { type: Type.STRING },
                source: { type: Type.STRING },
                time: { type: Type.STRING }
              },
              required: ["title", "summary", "url", "source", "time"]
            }
          }
        }
      });

      return JSON.parse(response.text || "[]");
    } catch (e) {
      console.error("News Fetch Error:", e);
      return [];
    }
  },

  generateTitle: async (firstPrompt: string): Promise<string> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Crie um título técnico e curto para esta consulta contábil/financeira: "${firstPrompt}"`,
        config: {
          temperature: 0.5,
          maxOutputTokens: 20
        }
      });
      return response.text?.replace(/["']/g, '').trim() || firstPrompt.substring(0, 30);
    } catch (e) {
      return firstPrompt.substring(0, 30);
    }
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { MarketService, MarketRates, StockInfo, AnalyticsMetrics } from '../services/marketService.ts';
import { GeminiService } from '../services/geminiService.ts';
import { Candle, NewsArticle } from '../types.ts';
import { StorageService } from '../services/storage.ts';

const Dashboard: React.FC = () => {
  const [rates, setRates] = useState<MarketRates | null>(null);
  const [stocks, setStocks] = useState<StockInfo[]>([]);
  const [candles, setCandles] = useState<Candle[]>([]);
  const [news, setNews] = useState<NewsArticle[]>([]);
  const [selectedAsset, setSelectedAsset] = useState('BTC');
  const [timeframe, setTimeframe] = useState('1h');
  const [hoveredCandle, setHoveredCandle] = useState<Candle | null>(null);
  const [loadingMarket, setLoadingMarket] = useState(true);
  const [loadingNews, setLoadingNews] = useState(true);
  const [analyticsData, setAnalyticsData] = useState<AnalyticsMetrics | null>(null);
  const [connectedServices, setConnectedServices] = useState<string[]>([]);

  useEffect(() => {
    const docs = StorageService.getDocuments();
    const services = Array.from(new Set(docs.map(d => d.sourceType))).filter(s => s !== 'local');
    setConnectedServices(services);

    const gaDoc = docs.find(d => d.sourceType === 'google_analytics');
    if (gaDoc) {
      try {
        const metrics = JSON.parse(gaDoc.content);
        if (metrics.activeUsers) setAnalyticsData(metrics);
      } catch (e) {
        console.error("Failed to parse GA data from document");
      }
    }

    const loadMarketData = async () => {
      setLoadingMarket(true);
      try {
        const rateData = await MarketService.fetchExchangeRates();
        const [stockData, candleData] = await Promise.all([
          MarketService.fetchStockData(rateData),
          MarketService.fetchHistoricalCandles(selectedAsset, timeframe)
        ]);
        setRates(rateData);
        setStocks(stockData);
        setCandles(candleData);
      } catch (e) {
        console.error("Error updating dashboard data", e);
      } finally {
        setLoadingMarket(false);
      }
    };

    const loadNews = async () => {
      setLoadingNews(true);
      try {
        const latestNews = await GeminiService.fetchLatestNews();
        setNews(latestNews);
      } catch (e) {
        console.error("News Load Error:", e);
      } finally {
        setLoadingNews(false);
      }
    };

    loadMarketData();
    loadNews();

    const interval = setInterval(loadMarketData, timeframe.includes('m') ? 30000 : 60000); 
    const newsInterval = setInterval(loadNews, 300000); // 5 minutes news sync

    return () => {
      clearInterval(interval);
      clearInterval(newsInterval);
    };
  }, [selectedAsset, timeframe]);

  const chartMetrics = useMemo(() => {
    if (candles.length === 0) return null;
    const lows = candles.map(c => c.low);
    const highs = candles.map(c => c.high);
    const minLow = Math.min(...lows);
    const maxHigh = Math.max(...highs);
    const range = Math.max(0.0001, maxHigh - minLow);

    return { minLow, maxHigh, range };
  }, [candles]);

  const renderCandleChart = () => {
    if (!chartMetrics || candles.length === 0) return (
      <div className="h-[250px] md:h-[350px] flex flex-col items-center justify-center gap-4 bg-white sketch-border">
        <div className="w-6 h-6 border-4 border-[#1A1A1A] border-t-transparent rounded-full animate-spin"></div>
        <span className="text-[8px] font-black uppercase tracking-widest text-[#7A7A7A]">Sincronizando Mercado...</span>
      </div>
    );

    const width = 1000;
    const height = 350;
    const padding = 20;
    const candleSpace = (width - padding * 2) / candles.length;
    const candleWidth = candleSpace * 0.7;
    const getY = (price: number) => height - padding - ((price - chartMetrics.minLow) / chartMetrics.range) * (height - padding * 2);

    return (
      <div className="relative cursor-crosshair bg-white p-2 w-full overflow-hidden">
        <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-full min-h-[250px] md:min-h-[350px]" preserveAspectRatio="none">
          {[0, 0.5, 1].map((p, i) => {
            const y = padding + p * (height - padding * 2);
            const price = chartMetrics.maxHigh - p * chartMetrics.range;
            return (
              <g key={i}>
                <line x1={0} y1={y} x2={width} y2={y} stroke="#F2F2F2" strokeWidth="1" />
                <text x={2} y={y - 2} className="text-[10px] fill-[#B5B5B5] font-black">{price.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</text>
              </g>
            );
          })}

          {candles.map((candle, i) => {
            const x = padding + i * candleSpace;
            const openY = getY(candle.open);
            const closeY = getY(candle.close);
            const highY = getY(candle.high);
            const lowY = getY(candle.low);
            const color = candle.close >= candle.open ? '#10B981' : '#EF4444';

            return (
              <g key={i} onMouseEnter={() => setHoveredCandle(candle)} onMouseLeave={() => setHoveredCandle(null)}>
                <line x1={x + candleSpace/2} y1={highY} x2={x + candleSpace/2} y2={lowY} stroke={color} strokeWidth="1.5" />
                <rect 
                  x={x + (candleSpace - candleWidth)/2} 
                  y={Math.min(openY, closeY)} 
                  width={candleWidth} 
                  height={Math.max(1, Math.abs(openY - closeY))} 
                  fill={color}
                />
              </g>
            );
          })}
        </svg>
        {hoveredCandle && (
          <div className="absolute top-2 right-2 bg-[#1A1A1A] text-white p-2 text-[8px] font-black uppercase sketch-border shadow-none border-white/20 z-10">
            <p>O: {hoveredCandle.open.toFixed(2)}</p>
            <p>H: {hoveredCandle.high.toFixed(2)}</p>
            <p>L: {hoveredCandle.low.toFixed(2)}</p>
            <p>C: {hoveredCandle.close.toFixed(2)}</p>
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full bg-[#F2EFEA]">
      <div className="bg-[#1A1A1A] h-8 flex items-center overflow-hidden border-b-2 border-[#1A1A1A] relative shrink-0">
        <div className="flex animate-[ticker_30s_linear_infinite] whitespace-nowrap gap-12 px-4 items-center min-w-full">
          {stocks.concat(stocks).map((stock, i) => (
            <div key={i} className="flex items-center gap-2 text-[9px] font-black uppercase text-white">
              <span>{stock.symbol}</span>
              <span className="text-gray-400">{stock.price}</span>
              <span className={stock.isPositive ? 'text-emerald-400' : 'text-rose-400'}>{stock.change}</span>
            </div>
          ))}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 md:p-8 space-y-6">
        <header className="flex flex-col gap-4 border-b-2 border-[#1A1A1A] pb-4">
          <div className="flex flex-col md:flex-row md:justify-between md:items-end gap-2">
            <div>
              <h1 className="text-2xl md:text-4xl font-black text-[#1A1A1A] uppercase tracking-tighter">OPERACIONAL</h1>
              <p className="text-[8px] font-black uppercase text-emerald-600">Sincronização em Tempo Real</p>
            </div>
            <div className="flex gap-2 w-full md:w-auto">
              <select value={selectedAsset} onChange={(e) => setSelectedAsset(e.target.value)} className="flex-1 md:w-32 bg-white border-2 border-[#1A1A1A] px-2 py-2 font-black text-[9px] uppercase outline-none focus:bg-[#F2EFEA]">
                {stocks.map(s => <option key={s.symbol} value={s.symbol}>{s.symbol}</option>)}
              </select>
