import React, { useState, useEffect, useMemo } from 'react';
import { MarketService, MarketRates, StockInfo, AnalyticsMetrics } from '../services/marketService.ts';
import { GeminiService } from '../services/geminiService.ts';
import { Candle, NewsArticle } from '../types.ts';
import { StorageService } from '../services/storage.ts';

const Dashboard: React.FC = () => {
  const [rates, setRates] = useState<MarketRates | null>(null);
  const [stocks, setStocks] = useState<StockInfo[]>([]);
  const [candles, setCandles] = useState<Candle[]>([]);
  const [news, setNews] = useState<NewsArticle[]>([]);
  const [selectedAsset, setSelectedAsset] = useState('BTC');
  const [timeframe, setTimeframe] = useState('1h');
  const [hoveredCandle, setHoveredCandle] = useState<Candle | null>(null);
  const [loadingMarket, setLoadingMarket] = useState(true);
  const [loadingNews, setLoadingNews] = useState(true);
  const [analyticsData, setAnalyticsData] = useState<AnalyticsMetrics | null>(null);

  useEffect(() => {
    const docs = StorageService.getDocuments();
    const gaDoc = docs.find(d => d.sourceType === 'google_analytics');
    if (gaDoc) {
      try {
        const metrics = JSON.parse(gaDoc.content);
        if (metrics.activeUsers) setAnalyticsData(metrics);
      } catch (e) {
        console.error("Erro ao processar dados analíticos");
      }
    }

    const loadMarketData = async () => {
      setLoadingMarket(true);
      try {
        const rateData = await MarketService.fetchExchangeRates();
        const [stockData, candleData] = await Promise.all([
          MarketService.fetchStockData(rateData),
          MarketService.fetchHistoricalCandles(selectedAsset, timeframe)
        ]);
        setRates(rateData);
        setStocks(stockData);
        setCandles(candleData);
      } catch (e) {
        console.error("Erro ao atualizar dados de mercado", e);
      } finally {
        setLoadingMarket(false);
      }
    };

    const loadNews = async () => {
      setLoadingNews(true);
      try {
        const latestNews = await GeminiService.fetchLatestNews();
        setNews(latestNews);
      } catch (e) {
        console.error("Erro ao carregar notícias:", e);
      } finally {
        setLoadingNews(false);
      }
    };

    loadMarketData();
    loadNews();

    const marketInterval = setInterval(loadMarketData, 60000); 
    const newsInterval = setInterval(loadNews, 300000); 

    return () => {
      clearInterval(marketInterval);
      clearInterval(newsInterval);
    };
  }, [selectedAsset, timeframe]);

  const chartMetrics = useMemo(() => {
    if (candles.length === 0) return null;
    const minLow = Math.min(...candles.map(c => c.low));
    const maxHigh = Math.max(...candles.map(c => c.high));
    return { minLow, maxHigh, range: Math.max(0.0001, maxHigh - minLow) };
  }, [candles]);

  const renderCandleChart = () => {
    if (!chartMetrics || candles.length === 0) {
      return (
        <div className="h-[300px] flex flex-col items-center justify-center gap-4 bg-white sketch-border">
          <div className="w-6 h-6 border-4 border-[#1A1A1A] border-t-transparent rounded-full animate-spin"></div>
          <span className="text-[8px] font-black uppercase tracking-widest text-[#7A7A7A]">Sincronizando Mercado...</span>
        </div>
      );
    }

    const width = 1000;
    const height = 300;
    const padding = 20;
    const candleSpace = (width - padding * 2) / candles.length;
    const candleWidth = candleSpace * 0.7;
    const getY = (price: number) => height - padding - ((price - chartMetrics.minLow) / chartMetrics.range) * (height - padding * 2);

    return (
      <div className="relative cursor-crosshair bg-white p-2 w-full">
        <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-[300px]" preserveAspectRatio="none">
          {candles.map((candle, i) => {
            const x = padding + i * candleSpace;
            const openY = getY(candle.open);
            const closeY = getY(candle.close);
            const highY = getY(candle.high);
            const lowY = getY(candle.low);
            const color = candle.close >= candle.open ? '#10B981' : '#EF4444';

            return (
              <g key={i} onMouseEnter={() => setHoveredCandle(candle)} onMouseLeave={() => setHoveredCandle(null)}>
                <line x1={x + candleSpace/2} y1={highY} x2={x + candleSpace/2} y2={lowY} stroke={color} strokeWidth="1" />
                <rect 
                  x={x + (candleSpace - candleWidth)/2} 
                  y={Math.min(openY, closeY)} 
                  width={candleWidth} 
                  height={Math.max(1, Math.abs(openY - closeY))} 
                  fill={color}
                />
              </g>
            );
          })}
        </svg>
        {hoveredCandle && (
          <div className="absolute top-2 right-2 bg-[#1A1A1A] text-white p-2 text-[8px] font-black uppercase sketch-border border-white/20 z-10">
            <p>FECHAMENTO: {hoveredCandle.close.toFixed(2)}</p>
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full bg-[#F2EFEA] overflow-hidden">
      {/* Ticker de Mercado */}
      <div className="bg-[#1A1A1A] h-8 flex items-center overflow-hidden border-b-2 border-[#1A1A1A] relative shrink-0">
        <div className="flex animate-[ticker_40s_linear_infinite] whitespace-nowrap gap-12 px-4 items-center">
          {stocks.concat(stocks).map((stock, i) => (
            <div key={i} className="flex items-center gap-2 text-[9px] font-black uppercase text-white">
              <span>{stock.symbol}</span>
              <span className="text-gray-400">{stock.price}</span>
              <span className={stock.isPositive ? 'text-emerald-400' : 'text-rose-400'}>{stock.change}</span>
            </div>
          ))}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8 custom-scrollbar">
        <header className="flex flex-col md:flex-row md:justify-between md:items-end gap-4 border-b-2 border-[#1A1A1A] pb-6">
          <div>
            <h1 className="text-3xl md:text-5xl font-black text-[#1A1A1A] uppercase tracking-tighter leading-none">TERMINAL OPERACIONAL</h1>
            <p className="text-[9px] font-black uppercase text-emerald-600 mt-2 tracking-[0.2em]">● Feed de Dados em Tempo Real (Sync Global)</p>
          </div>
          <div className="flex gap-2">
            <select value={selectedAsset} onChange={(e) => setSelectedAsset(e.target.value)} className="bg-white border-2 border-[#1A1A1A] px-3 py-2 font-black text-[10px] uppercase outline-none focus:bg-[#F2EFEA]">
              {stocks.map(s => <option key={s.symbol} value={s.symbol}>{s.symbol}</option>)}
            </select>
            <select value={timeframe} onChange={(e) => setTimeframe(e.target.value)} className="bg-white border-2 border-[#1A1A1A] px-3 py-2 font-black text-[10px] uppercase outline-none focus:bg-[#F2EFEA]">
              <option value="15m">15M</option>
              <option value="1h">1H</option>
              <option value="4h">4H</option>
              <option value="1d">1D</option>
            </select>
          </div>
        </header>

        {/* Gráfico de Mercado */}
        <section className="bg-white sketch-border overflow-hidden">
          <div className="p-4 border-b-2 border-[#1A1A1A] flex justify-between items-center bg-[#F2EFEA]">
            <h2 className="text-[10px] font-black uppercase tracking-widest">{selectedAsset} Performance Analysis</h2>
            <span className="text-[8px] font-bold opacity-50 uppercase">Live Candles</span>
          </div>
          {renderCandleChart()}
        </section>

        {/* Terminal de Notícias com Links Reais */}
        <section className="space-y-4">
          <div className="flex items-center justify-between border-b-2 border-[#1A1A1A] pb-2">
            <div className="flex items-center gap-3">
              <h3 className="text-xs font-black uppercase tracking-widest bg-[#1A1A1A] text-white px-3 py-1">NEWS TERMINAL (GOOGLE NEWS)</h3>
              <span className="text-[8px] font-bold uppercase text-[#7A7A7A]">Sincronizado via Google Search</span>
            </div>
            {loadingNews && <div className="w-4 h-4 border-2 border-[#1A1A1A] border-t-transparent rounded-full animate-spin"></div>}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {loadingNews ? (
              Array(2).fill(0).map((_, i) => (
                <div key={i} className="bg-white sketch-border p-6 animate-pulse h-32">
                  <div className="h-4 bg-gray-200 w-3/4 mb-4"></div>
                  <div className="h-2 bg-gray-100 w-full"></div>
                </div>
              ))
            ) : (
              news.map((article, i) => (
                <a 
                  key={i} 
                  href={article.url} 
                  target="_blank" 
                  rel="noopener noreferrer" 
                  className="bg-white sketch-border p-5 hover:translate-x-1 hover:-translate-y-1 transition-all group block"
                >
                  <div className="flex justify-between items-start mb-3">
                    <span className="text-[7px] font-black uppercase bg-[#1A1A1A] text-white px-2 py-0.5">{article.source}</span>
                    <span className="text-[7px] font-bold text-[#7A7A7A] uppercase">{article.time}</span>
                  </div>
                  <h4 className="text-[11px] font-black uppercase tracking-tight mb-2 group-hover:underline leading-snug">{article.title}</h4>
                  <p className="text-[9px] text-[#4A4A4A] line-clamp-2 leading-relaxed font-medium">{article.summary}</p>
                  <div className="mt-4 flex items-center gap-2 text-[7px] font-black uppercase text-blue-600 group-hover:gap-3 transition-all">
                    Acessar Fonte Original <span>→</span>
                  </div>
                </a>
              ))
            )}
          </div>
        </section>

        {/* Widgets de Inteligência */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pb-12">
          <section className="bg-white sketch-border p-6">
            <h3 className="text-xs font-black uppercase tracking-widest mb-6 border-b-2 border-[#1A1A1A] pb-2 italic">Análise Preditiva IA</h3>
            {analyticsData ? (
              <div className="space-y-6">
                <div className="grid grid-cols-2 gap-4">
                  <div className="p-4 bg-[#F2EFEA] sketch-border shadow-none">
                    <p className="text-[8px] font-black text-[#7A7A7A] uppercase mb-1">Users Ativos</p>
                    <p className="text-xl font-black">{analyticsData.activeUsers.toLocaleString()}</p>
                    <span className="text-[7px] font-black text-emerald-500">↑ TREND ANALYTICS</span>
                  </div>
                  <div className="p-4 bg-[#F2EFEA] sketch-border shadow-none">
                    <p className="text-[8px] font-black text-[#7A7A7A] uppercase mb-1">Conversão</p>
                    <p className="text-xl font-black">{analyticsData.conversionRate.toFixed(2)}%</p>
                  </div>
                </div>
                <div className="bg-[#1A1A1A] p-4 text-white sketch-border shadow-none">
                  <p className="text-[8px] font-black uppercase mb-1 text-emerald-400">Insight Auditoria:</p>
                  <p className="text-[9px] leading-relaxed">Pico de tráfego detectado. Recomenda-se revisão das provisões de servidor para o fechamento fiscal do mês.</p>
                </div>
              </div>
            ) : (
              <div className="flex flex-col items-center justify-center py-10 opacity-30 text-center">
                <p className="text-[8px] font-black uppercase tracking-widest">Conecte o Google Analytics para Visualizar Insights IA</p>
              </div>
            )}
          </section>

          <section className="bg-white sketch-border p-6">
            <h3 className="text-xs font-black uppercase tracking-widest mb-6 border-b-2 border-[#1A1A1A] pb-2 italic">Status de Conformidade</h3>
            <div className="space-y-4">
              <div className="flex justify-between items-center p-3 border-2 border-[#1A1A1A]">
                <span className="text-[9px] font-black uppercase">Risco Fiscal Global</span>
                <span className="bg-emerald-500 text-white text-[8px] font-black px-3 py-1 uppercase">Baixo (A+)</span>
              </div>
              <div className="flex justify-between items-center p-3 border-2 border-[#1A1A1A]">
                <span className="text-[9px] font-black uppercase">Sync IFRS/CPC</span>
                <span className="bg-[#1A1A1A] text-white text-[8px] font-black px-3 py-1 uppercase">Sincronizado</span>
              </div>
              <p className="text-[7px] font-bold text-[#7A7A7A] uppercase mt-4">Última auditoria automatizada: {new Date().toLocaleDateString()}</p>
            </div>
          </section>
        </div>
      </div>
    </div>
  );
};

