      try {
        const metrics = JSON.parse(gaDoc.content);
        if (metrics.activeUsers) setAnalyticsData(metrics);
      } catch (e) {
        console.error("Erro ao processar dados analíticos");
      }
    }

    const loadMarketData = async () => {
      setLoadingMarket(true);
      try {
        const rateData = await MarketService.fetchExchangeRates();
        const [stockData, candleData] = await Promise.all([
          MarketService.fetchStockData(rateData),
          MarketService.fetchHistoricalCandles(selectedAsset, timeframe)
        ]);
        setRates(rateData);
        setStocks(stockData);
        setCandles(candleData);
        // Reset view params on asset change
        setScrollOffset(0);
      } catch (e) {
        console.error("Erro ao atualizar dados de mercado", e);
      } finally {
        setLoadingMarket(false);
      }
    };

    const loadNews = async () => {
      setLoadingNews(true);
      try {
        const latestNews = await GeminiService.fetchLatestNews();
        setNews(latestNews);
      } catch (e) {
        console.error("Erro ao carregar notícias:", e);
      } finally {
        setLoadingNews(false);
      }
    };

    loadMarketData();
    loadNews();

    const marketInterval = setInterval(loadMarketData, 60000); 
    const newsInterval = setInterval(loadNews, 300000); 

    return () => {
      clearInterval(marketInterval);
      clearInterval(newsInterval);
    };
  }, [selectedAsset, timeframe]);

  // Derived visible data
  const visibleCandles = useMemo(() => {
    if (candles.length === 0) return [];
    const end = candles.length - scrollOffset;
    const start = Math.max(0, end - visibleCount);
    return candles.slice(start, end);
  }, [candles, visibleCount, scrollOffset]);

  const chartMetrics = useMemo(() => {
    if (visibleCandles.length === 0) return null;
    const minLow = Math.min(...visibleCandles.map(c => c.low));
    const maxHigh = Math.max(...visibleCandles.map(c => c.high));
    return { minLow, maxHigh, range: Math.max(0.0001, maxHigh - minLow) };
  }, [visibleCandles]);

  // Event Handlers for Zoom/Pan
  const handleWheel = (e: React.WheelEvent) => {
    if (e.ctrlKey || e.metaKey) {
      e.preventDefault();
      const delta = e.deltaY > 0 ? 5 : -5;
      setVisibleCount(prev => Math.min(Math.max(10, prev + delta), candles.length));
    } else {
      const delta = e.deltaY > 0 ? 1 : -1;
      setScrollOffset(prev => Math.min(Math.max(0, prev + delta), candles.length - visibleCount));
    }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    setIsPanning(true);
    setStartX(e.clientX);
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isPanning) return;
    const dx = e.clientX - startX;
    if (Math.abs(dx) > 10) {
      const move = dx > 0 ? 1 : -1;
      setScrollOffset(prev => Math.min(Math.max(0, prev + move), candles.length - visibleCount));
      setStartX(e.clientX);
    }
  };

  const handleMouseUp = () => setIsPanning(false);

  const renderCandleChart = () => {
    if (!chartMetrics || visibleCandles.length === 0) {
      return (
        <div className="h-[350px] flex flex-col items-center justify-center gap-4 bg-white sketch-border">
          <div className="w-6 h-6 border-4 border-[#1A1A1A] border-t-transparent rounded-full animate-spin"></div>
          <span className="text-[8px] font-black uppercase tracking-widest text-[#7A7A7A]">Sincronizando Mercado...</span>
        </div>
      );
    }

    const width = 1000;
    const height = 350;
    const padding = 30;
    const candleSpace = (width - padding * 2) / visibleCandles.length;
    const candleWidth = candleSpace * 0.7;
    const getY = (price: number) => height - padding - ((price - chartMetrics.minLow) / chartMetrics.range) * (height - padding * 2);

    return (
      <div 
        ref={chartRef}
        className={`relative bg-white p-2 w-full select-none ${isPanning ? 'cursor-grabbing' : 'cursor-crosshair'}`}
        onWheel={handleWheel}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
      >
        <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-[350px]" preserveAspectRatio="none">
          {/* Grid Lines */}
          {[0, 0.25, 0.5, 0.75, 1].map((p, i) => {
            const y = padding + p * (height - padding * 2);
            const val = chartMetrics.maxHigh - (p * chartMetrics.range);
            return (
              <g key={i}>
                <line x1={padding} y1={y} x2={width - padding} y2={y} stroke="#F2EFEA" strokeWidth="1" strokeDasharray="4" />
                <text x={width - padding + 5} y={y + 3} className="text-[8px] font-black fill-[#7A7A7A]">{val.toFixed(2)}</text>
              </g>
            );
          })}

          {visibleCandles.map((candle, i) => {
            const x = padding + i * candleSpace;
            const openY = getY(candle.open);
            const closeY = getY(candle.close);
            const highY = getY(candle.high);
            const lowY = getY(candle.low);
            const color = candle.close >= candle.open ? '#10B981' : '#EF4444';
            const isHovered = hoveredCandle === candle;

            return (
              <g key={i} onMouseEnter={() => setHoveredCandle(candle)} onMouseLeave={() => setHoveredCandle(null)}>
                <line x1={x + candleSpace/2} y1={highY} x2={x + candleSpace/2} y2={lowY} stroke={color} strokeWidth={isHovered ? "2" : "1"} />
                <rect 
                  x={x + (candleSpace - candleWidth)/2} 
                  y={Math.min(openY, closeY)} 
                  width={candleWidth} 
                  height={Math.max(1, Math.abs(openY - closeY))} 
                  fill={color}
                  className="transition-all duration-75"
                  fillOpacity={isHovered ? 1 : 0.8}
                />
              </g>
            );
          })}
        </svg>

        {/* Dynamic Tooltip */}
        {hoveredCandle && (
          <div className="absolute top-4 left-4 bg-[#1A1A1A] text-white p-4 text-[9px] font-black uppercase sketch-border border-white/20 z-20 pointer-events-none min-w-[140px]">
            <p className="text-emerald-400 mb-2 border-b border-white/10 pb-1">{hoveredCandle.time}</p>
            <div className="grid grid-cols-2 gap-x-4 gap-y-1">
              <span className="text-gray-400">OPEN:</span> <span>{hoveredCandle.open.toFixed(2)}</span>
              <span className="text-gray-400">HIGH:</span> <span>{hoveredCandle.high.toFixed(2)}</span>
              <span className="text-gray-400">LOW:</span> <span>{hoveredCandle.low.toFixed(2)}</span>
              <span className="text-gray-400">CLOSE:</span> <span className={hoveredCandle.close >= hoveredCandle.open ? 'text-emerald-400' : 'text-rose-400'}>{hoveredCandle.close.toFixed(2)}</span>
            </div>
          </div>
        )}

        {/* Legend / Overlay Info */}
        <div className="absolute bottom-4 left-4 bg-white/90 px-3 py-1 sketch-border text-[7px] font-black uppercase">
          Arrastar para PAN • CTRL+Scroll para ZOOM • {visibleCandles.length} Candles visíveis
        </div>
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full bg-[#F2EFEA] overflow-hidden">
      {/* Ticker de Mercado */}
      <div className="bg-[#1A1A1A] h-8 flex items-center overflow-hidden border-b-2 border-[#1A1A1A] relative shrink-0">
        <div className="flex animate-[ticker_40s_linear_infinite] whitespace-nowrap gap-12 px-4 items-center">
          {stocks.concat(stocks).map((stock, i) => (
            <div key={i} className="flex items-center gap-2 text-[9px] font-black uppercase text-white">
              <span>{stock.symbol}</span>
              <span className="text-gray-400">{stock.price}</span>
              <span className={stock.isPositive ? 'text-emerald-400' : 'text-rose-400'}>{stock.change}</span>
            </div>
          ))}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8 custom-scrollbar">
        <header className="flex flex-col md:flex-row md:justify-between md:items-end gap-4 border-b-2 border-[#1A1A1A] pb-6">
          <div>
            <h1 className="text-3xl md:text-5xl font-black text-[#1A1A1A] uppercase tracking-tighter leading-none">TERMINAL OPERACIONAL</h1>
            <p className="text-[9px] font-black uppercase text-emerald-600 mt-2 tracking-[0.2em]">● Feed de Dados em Tempo Real (Sync Global)</p>
          </div>
          <div className="flex gap-2">
            <select value={selectedAsset} onChange={(e) => setSelectedAsset(e.target.value)} className="bg-white border-2 border-[#1A1A1A] px-3 py-2 font-black text-[10px] uppercase outline-none focus:bg-[#F2EFEA]">
              {stocks.map(s => <option key={s.symbol} value={s.symbol}>{s.symbol}</option>)}
            </select>
            <select value={timeframe} onChange={(e) => setTimeframe(e.target.value)} className="bg-white border-2 border-[#1A1A1A] px-3 py-2 font-black text-[10px] uppercase outline-none focus:bg-[#F2EFEA]">
              <option value="15m">15M</option>
              <option value="1h">1H</option>
              <option value="4h">4H</option>
              <option value="1d">1D</option>
            </select>
          </div>
        </header>

        {/* Gráfico de Mercado Interativo */}
        <section className="bg-white sketch-border overflow-hidden">
          <div className="p-4 border-b-2 border-[#1A1A1A] flex justify-between items-center bg-[#F2EFEA]">
            <h2 className="text-[10px] font-black uppercase tracking-widest">{selectedAsset} Interactive Analysis</h2>
            <div className="flex gap-4">
              <span className="text-[8px] font-bold opacity-50 uppercase">Base BRL</span>
              <span className="text-[8px] font-bold text-emerald-600 uppercase">● Live Sockets</span>
            </div>
          </div>
          {renderCandleChart()}
        </section>

        {/* Terminal de Notícias com Links Reais */}
        <section className="space-y-4">
          <div className="flex items-center justify-between border-b-2 border-[#1A1A1A] pb-2">
            <div className="flex items-center gap-3">
              <h3 className="text-xs font-black uppercase tracking-widest bg-[#1A1A1A] text-white px-3 py-1">NEWS TERMINAL (GOOGLE NEWS)</h3>
              <span className="text-[8px] font-bold uppercase text-[#7A7A7A]">Sincronizado via Google Search</span>
            </div>
            {loadingNews && <div className="w-4 h-4 border-2 border-[#1A1A1A] border-t-transparent rounded-full animate-spin"></div>}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {loadingNews ? (
              Array(2).fill(0).map((_, i) => (
                <div key={i} className="bg-white sketch-border p-6 animate-pulse h-32">
                  <div className="h-4 bg-gray-200 w-3/4 mb-4"></div>
                  <div className="h-2 bg-gray-100 w-full"></div>
                </div>
              ))
            ) : (
              news.map((article, i) => (
                <a 
                  key={i} 
                  href={article.url} 
                  target="_blank" 
                  rel="noopener noreferrer" 
                  className="bg-white sketch-border p-5 hover:translate-x-1 hover:-translate-y-1 transition-all group block"
                >
                  <div className="flex justify-between items-start mb-3">
                    <span className="text-[7px] font-black uppercase bg-[#1A1A1A] text-white px-2 py-0.5">{article.source}</span>
                    <span className="text-[7px] font-bold text-[#7A7A7A] uppercase">{article.time}</span>
