import { GoogleGenAI, Type } from "@google/genai";
import { StorageService } from "./storage.ts";
import { NewsArticle } from "../types.ts";

const FINNHUB_KEY = 'd5m1jn9r01qidp4jcfqgd5m1jn9r01qidp4jcfr0';

export const GeminiService = {
  generateChatResponse: async (prompt: string, history: any[]) => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const docs = StorageService.getDocuments();
    const context = docs.length > 0 
      ? `BASE DE CONHECIMENTO INTEGRADA:\n${docs.map(d => `[ORIGEM: ${d.sourceType.toUpperCase()}] [CATEGORIA: ${d.metadata?.category || 'GERAL'}] [ARQUIVO: ${d.name}]\nCONTEÚDO: ${d.content}`).join('\n\n')}`
      : "O usuário ainda não conectou documentos ou serviços Google.";

    const systemInstruction = `
      Você é o "FinaIGPT", um Auditor de Elite e Analista Contábil Sênior.

      PROTOCOLO DE RESPOSTA EM 2 ETAPAS:
      1. EXECUÇÃO TÉCNICA: Realize os cálculos financeiros utilizando rigorosamente as normas CPC (Brasil) e IFRS (Internacional). 
      2. AUDITORIA INTERNA: Revise seus próprios cálculos, verifique erros de arredondamento, integridade de fórmulas e conformidade normativa antes de exibir o resultado.

      REGRAS DE OURO:
      - CITE A NORMA: Sempre que aplicar um conceito contábil, cite o CPC correspondente.
      - MEMÓRIA DE CÁLCULO: Exiba claramente as variáveis e a fórmula utilizada antes do resultado final.
      - RIGOR MATEMÁTICO: Diferencie claramente Juros Simples de Compostos e utilize as definições corretas de EBITDA vs EBIT.

      CONTEXTO DE DADOS (RAG):
      ${context}
    `;

    const formattedHistory = history
      .filter(msg => msg.id !== 'welcome' && msg.id !== 'reset') 
      .map(msg => ({
        role: msg.role === 'user' ? 'user' : 'model',
        parts: [{ text: msg.content }]
      }));

    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: formattedHistory,
        config: {
          systemInstruction,
          tools: [{ googleSearch: {} }],
          thinkingConfig: { thinkingBudget: 15000 },
          temperature: 0.2
        },
      });

      return {
        text: response.text || "Erro no processamento da IA.",
        groundingMetadata: response.candidates?.[0]?.groundingMetadata
      };
    } catch (error) {
      console.error("Gemini Error:", error);
      throw error;
    }
  },

  fetchLatestNews: async (): Promise<NewsArticle[]> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    try {
      // 1. Fetch live news from Finnhub directly
      const finnhubRes = await fetch(`https://finnhub.io/api/v1/news?category=general&token=${FINNHUB_KEY}`);
      const finnhubData = finnhubRes.ok ? await finnhubRes.json() : [];

      // 2. Use Gemini to search for BCB and Yahoo Finance + Translate Finnhub data
      const finnhubSnippet = JSON.stringify(finnhubData.slice(0, 3));

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Analise os seguintes dados e retorne um JSON de notícias financeiras:

        DADOS FINNHUB (Traduza e resuma): ${finnhubSnippet}

        PESQUISA GOOGLE SEARCH: 
        1. Busque as notícias mais recentes do Banco Central do Brasil (bcb.gov.br).
        2. Busque os destaques do Yahoo Finance Brasil.
        3. Busque tendências no OpenBB.

        REGRAS:
        - Tudo em Português-BR.
        - Proibido InfoMoney.
        - Links diretos e reais para a fonte original.
        - Retorne exatamente 5 itens no total.`,
        config: {
          tools: [{ googleSearch: {} }],
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                summary: { type: Type.STRING },
                url: { type: Type.STRING },
                source: { type: Type.STRING },
                time: { type: Type.STRING }
              },
              required: ["title", "summary", "url", "source", "time"]
            }
          }
        }
      });

      const cleanJson = response.text.replace(/```json|```/g, '').trim();
      return JSON.parse(cleanJson || "[]");
    } catch (e) {
      console.error("News Aggregator Error:", e);
      return [];
    }
  },

  generateTitle: async (firstPrompt: string): Promise<string> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Crie um título técnico e curto para esta consulta: "${firstPrompt}"`,
        config: {
          temperature: 0.5,
          maxOutputTokens: 20
        }
      });
      return response.text?.replace(/["']/g, '').trim() || firstPrompt.substring(0, 30);
    } catch (e) {
      return firstPrompt.substring(0, 30);
    }
  }
};

