              },
              required: ["title", "summary", "url", "source", "time", "sentiment"]
            }
          }
        }
      });

      const text = response.text || "[]";
      const cleanJson = text.replace(/```json|```/g, '').trim();
      return JSON.parse(cleanJson || "[]");
    } catch (e) {
      console.error("News Aggregator Error:", e);
      return [];
    }
  },

  generateTitle: async (firstPrompt: string): Promise<string> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Crie um título técnico e curto para esta consulta: "${firstPrompt}"`,
        config: {
          temperature: 0.5,
          maxOutputTokens: 20
        }
      });
      return response.text?.replace(/["']/g, '').trim() || firstPrompt.substring(0, 30);
    } catch (e) {
      return firstPrompt.substring(0, 30);
    }
  }
};

import React, { useState, useEffect, useMemo, useRef, useLayoutEffect } from 'react';
import { MarketService, MarketRates, StockInfo, AnalyticsMetrics } from '../services/marketService.ts';
import { GeminiService } from '../services/geminiService.ts';
import { Candle, NewsArticle } from '../types.ts';
import { StorageService } from '../services/storage.ts';

const Dashboard: React.FC = () => {
  const [rates, setRates] = useState<MarketRates | null>(null);
  const [stocks, setStocks] = useState<StockInfo[]>([]);
  const [candles, setCandles] = useState<Candle[]>([]);
  const [news, setNews] = useState<NewsArticle[]>([]);
  const [selectedAsset, setSelectedAsset] = useState('BTC');
  const [timeframe, setTimeframe] = useState('1h');
  const [hoveredCandle, setHoveredCandle] = useState<Candle | null>(null);
  const [loadingMarket, setLoadingMarket] = useState(true);
  const [loadingNews, setLoadingNews] = useState(true);
  const [analyticsData, setAnalyticsData] = useState<AnalyticsMetrics | null>(null);
  const [lastUpdate, setLastUpdate] = useState<string>(new Date().toLocaleTimeString());

  const [visibleCount, setVisibleCount] = useState(40);
  const [scrollOffset, setScrollOffset] = useState(0);
  const [isPanning, setIsPanning] = useState(false);
  const [startX, setStartX] = useState(0);
  const chartRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const docs = StorageService.getDocuments();
    const gaDoc = docs.find(d => d.sourceType === 'google_analytics');
    if (gaDoc) {
      try {
        const metrics = JSON.parse(gaDoc.content);
        if (metrics.activeUsers) setAnalyticsData(metrics);
      } catch (e) { console.error("GA Parse Error"); }
    }

    const loadMarketData = async () => {
      setLoadingMarket(true);
      try {
        const rateData = await MarketService.fetchExchangeRates();
        const [stockData, candleData] = await Promise.all([
          MarketService.fetchStockData(rateData),
          MarketService.fetchHistoricalCandles(selectedAsset, timeframe)
        ]);
        setRates(rateData);
        setStocks(stockData);
        setCandles(candleData);
        setLastUpdate(new Date().toLocaleTimeString());
      } catch (e) {
        console.error("Market Update Error", e);
      } finally {
        setLoadingMarket(false);
      }
    };

    const loadNews = async () => {
      setLoadingNews(true);
      try {
        const latestNews = await GeminiService.fetchLatestNews();
        setNews(latestNews);
      } catch (e) { console.error("News Error", e); }
      finally { setLoadingNews(false); }
    };

    loadMarketData();
    loadNews();

    const mInterval = setInterval(loadMarketData, 60000); 
    const nInterval = setInterval(loadNews, 300000); 

    return () => { clearInterval(mInterval); clearInterval(nInterval); };
  }, [selectedAsset, timeframe]);

  useLayoutEffect(() => {
    const el = chartRef.current;
    if (!el) return;

    const handleWheel = (e: WheelEvent) => {
      if (e.ctrlKey || e.metaKey) {
        e.preventDefault();
        const delta = e.deltaY > 0 ? 5 : -5;
        setVisibleCount(prev => Math.min(Math.max(10, prev + delta), (candles.length || 100)));
      } else {
        const delta = e.deltaY > 0 ? 1 : -1;
        setScrollOffset(prev => Math.min(Math.max(0, prev + delta), Math.max(0, (candles.length || 0) - visibleCount)));
      }
    };

    el.addEventListener('wheel', handleWheel, { passive: false });
    return () => el.removeEventListener('wheel', handleWheel);
  }, [candles.length, visibleCount]);

  const visibleCandles = useMemo(() => {
    if (candles.length === 0) return [];
    const end = Math.max(visibleCount, candles.length - scrollOffset);
    const start = Math.max(0, end - visibleCount);
    return candles.slice(start, end);
  }, [candles, visibleCount, scrollOffset]);

  const chartMetrics = useMemo(() => {
    if (visibleCandles.length === 0) return null;
    const minLow = Math.min(...visibleCandles.map(c => c.low));
    const maxHigh = Math.max(...visibleCandles.map(c => c.high));
    return { minLow, maxHigh, range: Math.max(0.0001, maxHigh - minLow) };
  }, [visibleCandles]);

  const handleMouseDown = (e: React.MouseEvent) => {
    setIsPanning(true);
    setStartX(e.clientX);
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isPanning) return;
    const dx = e.clientX - startX;
    if (Math.abs(dx) > 10) {
      const move = dx > 0 ? 1 : -1;
      setScrollOffset(prev => Math.min(Math.max(0, prev + move), Math.max(0, (candles.length || 0) - visibleCount)));
      setStartX(e.clientX);
    }
  };

  const handleMouseUp = () => setIsPanning(false);

  const getSentimentColor = (sentiment?: string) => {
    switch(sentiment) {
      case 'BULLISH': return 'text-emerald-500 bg-emerald-500/10 border-emerald-500/20';
      case 'BEARISH': return 'text-rose-500 bg-rose-500/10 border-rose-500/20';
      default: return 'text-gray-500 bg-gray-500/10 border-gray-500/20';
    }
  };

  const renderCandleChart = () => {
    if (loadingMarket || !chartMetrics || visibleCandles.length === 0) {
      return (
        <div className="h-[350px] flex flex-col items-center justify-center gap-4 bg-white sketch-border">
          <div className="w-6 h-6 border-4 border-[#1A1A1A] border-t-transparent rounded-full animate-spin"></div>
          <span className="text-[8px] font-black uppercase tracking-widest text-[#7A7A7A]">Sincronizando Mercado...</span>
        </div>
      );
    }

    const width = 1000;
    const height = 350;
    const padding = 40;
    const candleSpace = (width - padding * 2) / (visibleCandles.length || 1);
    const candleWidth = candleSpace * 0.7;
    const getY = (price: number) => height - padding - ((price - chartMetrics.minLow) / chartMetrics.range) * (height - padding * 2);

    return (
      <div 
        ref={chartRef}
        className={`relative bg-white p-2 w-full select-none ${isPanning ? 'cursor-grabbing' : 'cursor-crosshair'}`}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseUp}
      >
        <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-[350px]" preserveAspectRatio="none">
          {[0, 0.25, 0.5, 0.75, 1].map((p, i) => {
            const y = padding + p * (height - padding * 2);
            const val = chartMetrics.maxHigh - (p * chartMetrics.range);
            return (
              <g key={i}>
                <line x1={padding} y1={y} x2={width - padding} y2={y} stroke="#F2EFEA" strokeWidth="1" strokeDasharray="4" />
                <text x={width - padding + 5} y={y + 3} className="text-[8px] font-black fill-[#7A7A7A]">{val.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</text>
              </g>
            );
          })}

          {visibleCandles.map((candle, i) => {
            const x = padding + i * candleSpace;
            const openY = getY(candle.open);
            const closeY = getY(candle.close);
            const highY = getY(candle.high);
            const lowY = getY(candle.low);
            const color = candle.close >= candle.open ? '#10B981' : '#EF4444';
            const isHovered = hoveredCandle === candle;

            return (
              <g key={i} onMouseEnter={() => setHoveredCandle(candle)} onMouseLeave={() => setHoveredCandle(null)}>
                <line x1={x + candleSpace/2} y1={highY} x2={x + candleSpace/2} y2={lowY} stroke={color} strokeWidth={isHovered ? "2" : "1"} />
                <rect 
                  x={x + (candleSpace - candleWidth)/2} 
                  y={Math.min(openY, closeY)} 
                  width={candleWidth} 
                  height={Math.max(1, Math.abs(openY - closeY))} 
                  fill={color}
                  className="transition-all duration-75"
                  fillOpacity={isHovered ? 1 : 0.8}
                />
              </g>
            );
          })}
        </svg>

        {hoveredCandle && (
          <div className="absolute top-4 right-4 bg-[#1A1A1A] text-white p-4 text-[9px] font-black uppercase sketch-border border-white/20 z-20 pointer-events-none min-w-[160px]">
            <p className="text-emerald-400 mb-2 border-b border-white/10 pb-1">{hoveredCandle.time}</p>
            <div className="grid grid-cols-2 gap-x-4 gap-y-1">
              <span className="text-gray-400">OPEN:</span> <span>{hoveredCandle.open.toFixed(2)}</span>
              <span className="text-gray-400">HIGH:</span> <span>{hoveredCandle.high.toFixed(2)}</span>
              <span className="text-gray-400">LOW:</span> <span>{hoveredCandle.low.toFixed(2)}</span>
              <span className="text-gray-400">CLOSE:</span> <span className={hoveredCandle.close >= hoveredCandle.open ? 'text-emerald-400' : 'text-rose-400'}>{hoveredCandle.close.toFixed(2)}</span>
            </div>
          </div>
        )}

        <div className="absolute bottom-4 left-4 bg-white/90 px-3 py-1 sketch-border text-[7px] font-black uppercase flex gap-4">
          <span>Arrastar para PAN</span>
          <span>CTRL+Scroll para ZOOM</span>
          <span className="text-blue-600">{visibleCandles.length} Candles</span>
        </div>
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full bg-[#F2EFEA] overflow-hidden">
      <div className="bg-[#1A1A1A] h-8 flex items-center overflow-hidden border-b-2 border-[#1A1A1A] relative shrink-0">
        <div className="flex animate-[ticker_40s_linear_infinite] whitespace-nowrap gap-12 px-4 items-center">
          {(stocks.length > 0 ? stocks.concat(stocks) : []).map((stock, i) => (
            <div key={i} className="flex items-center gap-2 text-[9px] font-black uppercase text-white">
              <span>{stock.symbol}</span>
              <span className="text-gray-400">{stock.price}</span>
              <span className={stock.isPositive ? 'text-emerald-400' : 'text-rose-400'}>{stock.change}</span>
            </div>
          ))}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8 custom-scrollbar">
        <header className="flex flex-col md:flex-row md:justify-between md:items-end gap-4 border-b-2 border-[#1A1A1A] pb-6">
          <div>
            <h1 className="text-3xl md:text-5xl font-black text-[#1A1A1A] uppercase tracking-tighter leading-none">TERMINAL DE OPERAÇÕES</h1>
            <p className="text-[9px] font-black uppercase text-emerald-600 mt-2 tracking-[0.2em]">● Feed Real-Time (Sincronizado {lastUpdate})</p>
          </div>
          <div className="flex gap-2">
            <select 
              value={selectedAsset} 
              onChange={(e) => setSelectedAsset(e.target.value)} 
              className="bg-white border-2 border-[#1A1A1A] px-3 py-2 font-black text-[10px] uppercase outline-none focus:bg-[#F2EFEA]"
            >
              {stocks.length > 0 ? stocks.map(s => <option key={s.symbol} value={s.symbol}>{s.symbol}</option>) : <option>Carregando...</option>}
            </select>
            <select 
              value={timeframe} 
              onChange={(e) => setTimeframe(e.target.value)} 
              className="bg-white border-2 border-[#1A1A1A] px-3 py-2 font-black text-[10px] uppercase outline-none focus:bg-[#F2EFEA]"
            >
              <option value="15m">15M</option>
              <option value="1h">1H</option>
              <option value="4h">4H</option>
              <option value="1d">1D</option>
            </select>
          </div>
        </header>

        <section className="bg-white sketch-border overflow-hidden">
          <div className="p-4 border-b-2 border-[#1A1A1A] flex justify-between items-center bg-[#F2EFEA]">
            <h2 className="text-[10px] font-black uppercase tracking-widest">{selectedAsset}/BRL Analysis</h2>
            <div className="flex gap-4">
              <span className="text-[8px] font-bold text-emerald-600 uppercase animate-pulse">● Live Data</span>
            </div>
          </div>
          {renderCandleChart()}
        </section>

        <section className="space-y-4">
          <div className="flex items-center justify-between border-b-2 border-[#1A1A1A] pb-2">
            <h3 className="text-xs font-black uppercase tracking-widest bg-[#1A1A1A] text-white px-3 py-1 italic">News Terminal (Hybrid Feed)</h3>
            {loadingNews && <div className="w-4 h-4 border-2 border-[#1A1A1A] border-t-transparent rounded-full animate-spin"></div>}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {loadingNews ? (
              Array(2).fill(0).map((_, i) => (
                <div key={i} className="bg-white sketch-border p-6 animate-pulse h-32">
                  <div className="h-4 bg-gray-200 w-3/4 mb-4"></div>
                  <div className="h-2 bg-gray-100 w-full"></div>
