import { GoogleGenAI, Type } from "@google/genai";
import { StorageService } from "./storage.ts";
import { NewsArticle } from "../types.ts";

const FINNHUB_KEY = 'd5m1jn9r01qidp4jcfqgd5m1jn9r01qidp4jcfr0';

export const GeminiService = {
  generateChatResponseStream: async (prompt: string, history: any[], onChunk: (text: string) => void) => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const docs = StorageService.getDocuments();
    const context = docs.length > 0 
      ? `BASE DE CONHECIMENTO INTEGRADA:\n${docs.map(d => `[ORIGEM: ${d.sourceType.toUpperCase()}] [CATEGORIA: ${d.metadata?.category || 'GERAL'}] [ARQUIVO: ${d.name}]\nCONTEÚDO: ${d.content}`).join('\n\n')}`
      : "O usuário ainda não conectou documentos ou serviços Google.";

    const systemInstruction = `
      Você é o "FinaIGPT", um Auditor de Elite e Analista Contábil Sênior.

      PROTOCOLO DE RESPOSTA:
      1. EXECUÇÃO TÉCNICA: Cálculos financeiros rigorosos via normas CPC/IFRS.
      2. AUDITORIA INTERNA: Revise integridade antes de exibir.

      FORMATAÇÃO:
      - Use tabelas Markdown para dados financeiros.
      - Valores negativos em parênteses ou com sinal negativo.
      - Sempre cite o CPC correspondente.

      CONTEXTO RAG: ${context}
    `;

    const formattedHistory = history
      .filter(msg => msg.id !== 'welcome' && msg.id !== 'reset') 
      .map(msg => ({
        role: msg.role === 'user' ? 'user' : 'model',
        parts: [{ text: msg.content }]
      }))
      .slice(-10); // Mantém apenas os últimos 10 turnos para performance

    try {
      const result = await ai.models.generateContentStream({
        model: 'gemini-3-pro-preview',
        contents: formattedHistory,
        config: {
          systemInstruction,
          tools: [{ googleSearch: {} }],
          thinkingConfig: { thinkingBudget: 15000 },
          temperature: 0.1, // Menor temperatura para maior precisão contábil
        },
      });

      let fullText = "";
      for await (const chunk of result) {
        const chunkText = chunk.text;
        if (chunkText) {
          fullText += chunkText;
          onChunk(fullText);
        }
      }
      return fullText;
    } catch (error) {
      console.error("Gemini Stream Error:", error);
      throw error;
    }
  },

  generateChatResponse: async (prompt: string, history: any[]) => {
    // Mantido para compatibilidade ou fallback
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const result = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: history.map(m => ({ role: m.role === 'user' ? 'user' : 'model', parts: [{ text: m.content }] })),
      config: { temperature: 0.2 }
    });
    return { text: result.text };
  },

  fetchLatestNews: async (): Promise<NewsArticle[]> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const finnhubRes = await fetch(`https://finnhub.io/api/v1/news?category=general&token=${FINNHUB_KEY}`);
      const finnhubData = finnhubRes.ok ? await finnhubRes.json() : [];
      const finnhubSnippet = JSON.stringify(finnhubData.slice(0, 5));

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Analise as notícias e retorne um JSON de 6 itens: ${finnhubSnippet}`,
        config: {
          tools: [{ googleSearch: {} }],
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                summary: { type: Type.STRING },
                url: { type: Type.STRING },
                source: { type: Type.STRING },
                time: { type: Type.STRING },
                sentiment: { type: Type.STRING, enum: ["BULLISH", "BEARISH", "NEUTRAL"] }
              },
              required: ["title", "summary", "url", "source", "time", "sentiment"]
            }
          }
        }
      });
      return JSON.parse(response.text || "[]");
    } catch (e) {
      return [];
    }
  },

  generateTitle: async (firstPrompt: string): Promise<string> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Título curto para: "${firstPrompt}"`,
        config: { maxOutputTokens: 20 }
      });
      return response.text?.replace(/["']/g, '').trim() || "Nova Consulta";
    } catch (e) {
      return "Nova Consulta";
    }
  }
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Message, ChatSession } from '../types.ts';
import { GeminiService } from '../services/geminiService.ts';
import { StorageService } from '../services/storage.ts';

const ChatInterface: React.FC = () => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [streamingText, setStreamingText] = useState('');
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    const loadedSessions = StorageService.getChatSessions();
    setSessions(loadedSessions);
    if (loadedSessions.length > 0 && !currentSessionId) {
      setCurrentSessionId(loadedSessions[0].id);
    }
  }, []);

  const currentSession = sessions.find(s => s.id === currentSessionId);

  const scrollToBottom = useCallback((force = false) => {
    if (scrollRef.current) {
      const { scrollHeight, scrollTop, clientHeight } = scrollRef.current;
      const isNearBottom = scrollHeight - scrollTop - clientHeight < 150;
      if (force || isNearBottom) {
        scrollRef.current.scrollTop = scrollHeight;
      }
    }
  }, []);

  useEffect(() => {
    scrollToBottom();
  }, [currentSession?.messages, streamingText, isLoading, scrollToBottom]);

  const handleNewChat = () => {
    const newSession: ChatSession = {
      id: Math.random().toString(36).substr(2, 9),
      title: 'Nova Consulta Contábil',
      messages: [],
      lastUpdate: new Date(),
      updatedAt: new Date().toISOString(),
      version: 1,
      syncStatus: 'local'
    };
    setSessions(prev => [newSession, ...prev]);
    setCurrentSessionId(newSession.id);
    StorageService.saveChatSession(newSession);
    setIsHistoryOpen(false);
  };

  const handleSendMessage = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!input.trim() || isLoading) return;

    const userMsg = input.trim();
    setInput('');
    setStreamingText('');

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: userMsg,
      timestamp: new Date()
    };

    let targetSession = currentSession;
    let updatedSessions = [...sessions];

    if (!targetSession) {
      targetSession = {
        id: Math.random().toString(36).substr(2, 9),
        title: userMsg.substring(0, 30),
        messages: [userMessage],
        lastUpdate: new Date(),
        updatedAt: new Date().toISOString(),
        version: 1,
        syncStatus: 'local'
      };
      updatedSessions = [targetSession, ...sessions];
      setSessions(updatedSessions);
      setCurrentSessionId(targetSession.id);
    } else {
      const sessionIndex = updatedSessions.findIndex(s => s.id === targetSession!.id);
      targetSession = {
        ...targetSession,
        messages: [...targetSession.messages, userMessage],
        lastUpdate: new Date(),
        updatedAt: new Date().toISOString()
      };
      updatedSessions[sessionIndex] = targetSession;
      setSessions(updatedSessions);
    }

    setIsLoading(true);

    try {
      const fullAiText = await GeminiService.generateChatResponseStream(
        userMsg, 
        targetSession.messages, 
        (text) => {
          setStreamingText(text);
          scrollToBottom();
        }
      );

      const modelMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: fullAiText,
        timestamp: new Date()
      };

      const finalSession = {
        ...targetSession,
        messages: [...targetSession.messages, modelMessage],
        lastUpdate: new Date(),
        updatedAt: new Date().toISOString()
      };

      if (finalSession.messages.length <= 2) {
        const title = await GeminiService.generateTitle(userMsg);
        finalSession.title = title;
        setSessions(prev => prev.map(s => s.id === finalSession.id ? { ...finalSession, title } : s));
        StorageService.saveChatSession({ ...finalSession, title });
      } else {
        setSessions(prev => prev.map(s => s.id === finalSession.id ? finalSession : s));
        StorageService.saveChatSession(finalSession);
      }
    } catch (error) {
      console.error("Chat Error:", error);
    } finally {
      setIsLoading(false);
      setStreamingText('');
    }
  };

  const renderMessageContent = (content: string) => {
    const lines = content.split('\n');
    const elements: React.ReactNode[] = [];
    let currentTable: string[][] = [];
    let isInsideTable = false;

    const pushTable = (key: string) => {
      if (currentTable.length > 0) {
        elements.push(
          <div key={key} className="my-6 overflow-x-auto sketch-border bg-white p-0 relative group/table">
            <button 
              onClick={() => {
                const csv = currentTable.map(row => row.join(',')).join('\n');
                navigator.clipboard.writeText(csv);
              }}
              className="absolute top-2 right-2 bg-[#1A1A1A] text-white text-[7px] font-black px-2 py-1 opacity-0 group-hover/table:opacity-100 transition-opacity uppercase z-10"
            >
              Copiar CSV
            </button>
            <table className="w-full text-left text-[9px] md:text-[10px] border-collapse">
              <thead>
                <tr className="bg-[#1A1A1A] text-white">
                  {currentTable[0].map((cell, i) => (
                    <th key={i} className="p-3 font-black uppercase tracking-widest border-r border-white/10 last:border-0">{cell.trim()}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {currentTable.slice(2).map((row, i) => (
                  <tr key={i} className="border-b border-gray-100 last:border-0 hover:bg-gray-50">
                    {row.map((cell, j) => (
                      <td key={j} className={`p-3 font-medium border-r border-gray-100 last:border-0 ${cell.includes('-') || cell.includes('(') ? 'text-rose-600' : ''}`}>
                        {cell.trim()}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        );
        currentTable = [];
      }
    };

    lines.forEach((line, idx) => {
      if (line.trim().startsWith('|') && line.trim().endsWith('|')) {
        isInsideTable = true;
        const row = line.split('|').filter(c => c.trim() !== '' || line.startsWith('|') && line.endsWith('|'));
        // Special check for markdown separators like |---|---|
        if (!line.includes('---')) {
          currentTable.push(row);
        }
      } else {
        if (isInsideTable) {
          pushTable(`table-${idx}`);
          isInsideTable = false;
        }
        if (line.trim().startsWith('###')) {
          elements.push(<h3 key={idx} className="text-sm font-black uppercase mt-6 mb-2 border-l-4 border-[#1A1A1A] pl-3">{line.replace('###', '').trim()}</h3>);
        } else if (line.trim()) {
          elements.push(<p key={idx} className="mb-4 leading-relaxed">{line}</p>);
        }
      }
    });

    if (isInsideTable) pushTable(`table-final`);

    return elements;
  };

  return (
    <div className="flex h-full flex-col bg-[#F2EFEA]">
      <header className="h-16 shrink-0 bg-white border-b-2 border-[#1A1A1A] flex items-center justify-between px-6 z-10">
        <div className="flex items-center gap-4">
          <button 
            onClick={() => setIsHistoryOpen(!isHistoryOpen)}
            className="lg:hidden w-10 h-10 flex items-center justify-center sketch-border shadow-none"
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
            </svg>
          </button>
          <h2 className="text-[10px] font-black uppercase tracking-widest">{currentSession?.title || 'SELECIONE UM CHAT'}</h2>
        </div>
        <button onClick={handleNewChat} className="bg-[#1A1A1A] text-white text-[9px] font-black uppercase px-4 py-2 sketch-border shadow-none hover:bg-[#4A4A4A]">
          Nova Consulta
        </button>
      </header>

      <div className="flex-1 flex overflow-hidden">
        {/* Sidebar History */}
        <aside className={`
          fixed lg:relative inset-y-0 left-0 w-72 bg-white border-r-2 border-[#1A1A1A] transition-transform duration-300 z-20
          ${isHistoryOpen ? 'translate-x-0 shadow-2xl' : '-translate-x-full lg:translate-x-0'}
        `}>
          <div className="p-6 h-full flex flex-col">
            <h3 className="text-[9px] font-black uppercase tracking-widest mb-4 text-gray-400">Recentes</h3>
            <div className="flex-1 overflow-y-auto space-y-2 custom-scrollbar">
              {sessions.map(session => (
                <button
                  key={session.id}
                  onClick={() => { setCurrentSessionId(session.id); setIsHistoryOpen(false); }}
                  className={`
                    w-full text-left p-3 sketch-border shadow-none transition-all
                    ${currentSessionId === session.id ? 'bg-[#1A1A1A] text-white' : 'bg-white hover:bg-gray-50'}
                  `}
                >
                  <p className="text-[10px] font-black uppercase truncate">{session.title}</p>
                  <p className={`text-[8px] font-bold uppercase mt-1 ${currentSessionId === session.id ? 'text-gray-400' : 'text-gray-400'}`}>
                    {new Date(session.lastUpdate).toLocaleDateString()}
                  </p>
                </button>
              ))}
            </div>
          </div>
        </aside>

        {/* Chat Main */}
        <div className="flex-1 flex flex-col min-w-0 bg-[#F2EFEA] relative">
          <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 md:p-8 space-y-6 custom-scrollbar scroll-smooth">
            {!currentSession?.messages.length && !isLoading && (
              <div className="h-full flex flex-col items-center justify-center text-center max-w-md mx-auto">
                <div className="w-16 h-16 bg-[#1A1A1A] text-white flex items-center justify-center text-3xl font-black mb-6 sketch-border">?</div>
                <h3 className="text-xl font-black uppercase mb-3">Assistente Contábil Sênior</h3>
                <p className="text-[10px] font-bold text-[#7A7A7A] uppercase leading-relaxed tracking-wider">
                  Analise balanços, calcule impostos ou verifique conformidade com CPC/IFRS em tempo real.
                </p>
                <div className="grid grid-cols-1 gap-3 w-full mt-8">
                  <button onClick={() => setInput("Analise meu DRE anexado e identifique oportunidades de economia fiscal.")} className="bg-white p-3 sketch-border text-[9px] font-black uppercase hover:translate-x-1 transition-transform">
                    "Analise meu DRE..."
                  </button>
                  <button onClick={() => setInput("Quais são as principais mudanças no CPC 06 (R2) para o setor varejista?")} className="bg-white p-3 sketch-border text-[9px] font-black uppercase hover:translate-x-1 transition-transform">
                    "Mudanças no CPC 06..."
                  </button>
                </div>
              </div>
            )}

            {currentSession?.messages.map((msg, i) => (
              <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`
                  max-w-[85%] md:max-w-[75%] p-4 md:p-6 sketch-border
                  ${msg.role === 'user' ? 'bg-[#1A1A1A] text-white' : 'bg-white text-[#1A1A1A]'}
                `}>
                  <div className="text-[11px] md:text-xs font-medium">
                    {renderMessageContent(msg.content)}
                  </div>
                  <p className={`text-[7px] font-black uppercase mt-4 opacity-40 ${msg.role === 'user' ? 'text-right' : 'text-left'}`}>
                    {new Date(msg.timestamp).toLocaleTimeString()}
                  </p>
                </div>
              </div>
            ))}

            {(isLoading || streamingText) && (
              <div className="flex justify-start">
                <div className="max-w-[85%] md:max-w-[75%] p-4 md:p-6 bg-white sketch-border">
                  <div className="text-[11px] md:text-xs font-medium min-h-[1.5em]">
                    {streamingText ? renderMessageContent(streamingText) : (
                      <div className="flex gap-1 items-center py-1">
                        <div className="w-1 h-1 bg-[#1A1A1A] rounded-full animate-bounce"></div>
                        <div className="w-1 h-1 bg-[#1A1A1A] rounded-full animate-bounce [animation-delay:0.2s]"></div>
                        <div className="w-1 h-1 bg-[#1A1A1A] rounded-full animate-bounce [animation-delay:0.4s]"></div>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            )}
          </div>

          {/* Input Area */}
          <div className="p-4 md:p-6 bg-[#F2EFEA] border-t-2 border-[#1A1A1A]">
            <form onSubmit={handleSendMessage} className="max-w-4xl mx-auto relative">
              <textarea
                ref={textareaRef}
                rows={1}
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' && !e.shiftKey) {
                    e.preventDefault();
                    handleSendMessage();
                  }
                }}
                placeholder="Pergunte ao FinaIGPT (ex: Normas CPC 06, Análise DRE...)"
                className="w-full bg-white sketch-border p-4 md:p-5 pr-16 text-xs md:text-sm font-bold uppercase outline-none resize-none placeholder:opacity-40 focus:bg-white"
                style={{ minHeight: '60px', maxHeight: '150px' }}
              />
              <button 
                type="submit" 
                disabled={isLoading || !input.trim()}
                className={`
                  absolute right-3 bottom-3 w-10 h-10 md:w-12 md:h-12 bg-[#1A1A1A] text-white sketch-border shadow-none flex items-center justify-center transition-all
                  ${isLoading || !input.trim() ? 'opacity-30' : 'hover:bg-emerald-600 hover:border-emerald-600 active:scale-95'}
                `}
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 10l7-7m0 0l7 7m-7-7v18" />
                </svg>
              </button>
            </form>
            <p className="text-center text-[7px] font-black text-gray-400 uppercase tracking-widest mt-3">
              FinaIGPT utiliza o Gemini 3 Pro • Auditoria Auditoria Fiscal Integrada
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ChatInterface;

export interface User {
  id: string;
  name: string;
  email: string;
  avatar: string;
}

export interface Message {
  id: string;
  role: 'user' | 'model';
  content: string;
  timestamp: Date;
  sources?: string[];
}

export type SyncStatus = 'synced' | 'pending' | 'local' | 'conflict' | 'syncing';

export interface ChatSession {
  id: string;
  title: string;
  messages: Message[];
  lastUpdate: Date;
  updatedAt: string; // ISO string for precise comparison
  deletedAt?: Date;
  // Sync fields
  syncStatus?: SyncStatus;
  syncedAt?: Date;
  version: number;
}

export type DocumentSource = 'local' | 'google_docs' | 'google_sheets' | 'google_analytics' | 'google_drive';

export interface Document {
  id: string;
  name: string;
  content: string;
  type: string;
  uploadDate: Date;
  size: number;
  sourceType: DocumentSource;
  externalUrl?: string;
  metadata?: {
    propertyId?: string;
    lastSync?: Date;
    category?: 'cost' | 'tax' | 'management' | 'general' | 'exercise';
  };
}

export interface NewsArticle {
  title: string;
  summary: string;
  url: string;
  source: string;
  time: string;
  sentiment?: 'BULLISH' | 'BEARISH' | 'NEUTRAL';
}

export interface Candle {
  time: string;
  open: number;
  high: number;
  low: number;
  close: number;
}

export interface MarketData {
  symbol: string;
  name: string;
  price: number;
  change: number;
  history: Candle[];
}

export enum ViewState {
  Dashboard = 'DASHBOARD',
  Chat = 'CHAT',
  Documents = 'DOCUMENTS',
  Reports = 'REPORTS',
  Trash = 'TRASH'
}

import React, { useState, useEffect, useRef } from 'react';
import { Document, DocumentSource } from '../types.ts';
import { StorageService } from '../services/storage.ts';
import { MarketService } from '../services/marketService.ts';

// Declare external libs for TypeScript
declare const pdfjsLib: any;
declare const mammoth: any;
declare const XLSX: any;

const DocumentManager: React.FC = () => {
  const [documents, setDocuments] = useState<Document[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [parsingStatus, setParsingStatus] = useState<string>('');
  const [searchTerm, setSearchTerm] = useState('');
  const [externalUrl, setExternalUrl] = useState('');
  const [selectedProvider, setSelectedProvider] = useState<DocumentSource>('google_docs');
  const [selectedCategory, setSelectedCategory] = useState<'cost' | 'tax' | 'management' | 'general' | 'exercise'>('general');
  const [isDrivePickerOpen, setIsDrivePickerOpen] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const driveFiles = [
    { id: '1', name: 'Relatório Anual 2024.gdoc', type: 'google_docs', size: 45200 },
    { id: '2', name: 'Budget Consolidado Q3.gsheet', type: 'google_sheets', size: 125000 },
    { id: '3', name: 'Normas IFRS 16.pdf', type: 'google_drive', size: 2400000 },
    { id: '4', name: 'Calculadora Tributária.xlsx', type: 'google_drive', size: 89000 },
    { id: '5', name: 'Atas de Auditoria - Outubro.gdoc', type: 'google_docs', size: 12000 },
  ];

  useEffect(() => {
    setDocuments(StorageService.getDocuments());
    if (typeof pdfjsLib !== 'undefined') {
      pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
    }
  }, []);

  const parsePDF = async (file: File): Promise<string> => {
    const arrayBuffer = await file.arrayBuffer();
    const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
    let fullText = "";
    for (let i = 1; i <= pdf.numPages; i++) {
      const page = await pdf.getPage(i);
      const textContent = await page.getTextContent();
      const pageText = textContent.items.map((item: any) => item.str).join(" ");
      fullText += pageText + "\n";
    }
    return fullText;
  };

  const parseDOCX = async (file: File): Promise<string> => {
    const arrayBuffer = await file.arrayBuffer();
    const result = await mammoth.extractRawText({ arrayBuffer });
    return result.value;
  };

  const parseExcel = async (file: File): Promise<string> => {
    const arrayBuffer = await file.arrayBuffer();
    const workbook = XLSX.read(arrayBuffer, { type: 'array' });
    let fullText = "";
    workbook.SheetNames.forEach((sheetName: string) => {
      const worksheet = workbook.Sheets[sheetName];
      const csv = XLSX.utils.sheet_to_csv(worksheet);
      fullText += `--- ABA: ${sheetName.toUpperCase()} ---\n${csv}\n\n`;
    });
    return fullText;
  };

  const handleFiles = async (files: FileList) => {
    setIsUploading(true);
    const filesArray = Array.from(files);

    for (const file of filesArray) {
      try {
        setParsingStatus(`Processando ${file.name}...`);
        let content = "";
        const fileExt = file.name.split('.').pop()?.toLowerCase();

        if (file.type === "application/pdf" || fileExt === 'pdf') {
          content = await parsePDF(file);
        } else if (file.type === "application/vnd.openxmlformats-officedocument.wordprocessingml.document" || fileExt === 'docx') {
          content = await parseDOCX(file);
        } else if (
          file.type === "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" || 
          file.type === "application/vnd.ms-excel" ||
          ['xlsx', 'xls', 'xlsm'].includes(fileExt || '')
        ) {
          content = await parseExcel(file);
        } else {
          content = await file.text();
        }

        const doc: Document = {
          id: Math.random().toString(36).substr(2, 9),
          name: file.name,
          content: content,
          type: file.type || 'text/plain',
          uploadDate: new Date(),
          size: file.size,
          sourceType: 'local',
          metadata: { category: selectedCategory, lastSync: new Date() }
        };

        StorageService.saveDocument(doc);
        setDocuments(prev => [doc, ...prev]);
      } catch (e) { 
        console.error(`Falha ao ler ${file.name}:`, e); 
        alert(`Erro ao processar ${file.name}`);
      }
    }
    setIsUploading(false);
    setParsingStatus('');
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const importFromDrive = (file: typeof driveFiles[0]) => {
    setIsUploading(true);
    setParsingStatus(`Importando ${file.name} do Google Drive...`);

    setTimeout(() => {
      const doc: Document = {
        id: Math.random().toString(36).substr(2, 9),
        name: file.name,
        content: `CONTEÚDO IMPORTADO DO GOOGLE DRIVE (${file.type.toUpperCase()})\nSimulando extração de dados contábeis via API...\n\nDocumento: ${file.name}\nID Drive: ${file.id}\nStatus: Indexado para RAG.`,
        type: file.type === 'google_docs' ? 'application/vnd.google-apps.document' : 'application/vnd.google-apps.spreadsheet',
        uploadDate: new Date(),
        size: file.size,
        sourceType: file.type as DocumentSource,
        metadata: { category: selectedCategory, lastSync: new Date() }
      };

      StorageService.saveDocument(doc);
      setDocuments(prev => [doc, ...prev]);
      setIsUploading(false);
      setParsingStatus('');
      setIsDrivePickerOpen(false);
    }, 1200);
  };

  const handleAddExternal = async () => {
    if (!externalUrl) return;
    setIsUploading(true);
    setParsingStatus('Validando link e permissões do Google Account...');

    let content = `[DATA_SOURCE: ${selectedProvider.toUpperCase()}]\nURL: ${externalUrl}\nIntegrado via Protocolo Google Auth.`;

    if (selectedProvider === 'google_analytics') {
      setParsingStatus('Sincronizando métricas do GA4 Property...');
      const metrics = await MarketService.fetchMockAnalytics(externalUrl);
      content = JSON.stringify(metrics);
    }

    const doc: Document = {
      id: Math.random().toString(36).substr(2, 9),
      name: `${selectedProvider.replace('_', ' ').toUpperCase()}: ${externalUrl.split('/').pop()?.substring(0, 20) || 'Link Externo'}`,
      content: content,
      type: selectedProvider === 'google_analytics' ? 'application/json' : 'external/link',
      uploadDate: new Date(),
      size: 0,
      sourceType: selectedProvider,
      externalUrl: externalUrl,
      metadata: { category: selectedCategory, lastSync: new Date() }
    };

    StorageService.saveDocument(doc);
    setDocuments(prev => [doc, ...prev]);
    setExternalUrl('');
    setIsUploading(false);
    setParsingStatus('');
  };

  const deleteDoc = (id: string) => {
    if (window.confirm("Remover da base de conhecimento?")) {
      StorageService.deleteDocument(id);
      setDocuments(prev => prev.filter(d => d.id !== id));
    }
  };

  const filteredDocs = documents.filter(doc => 
    doc.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    doc.sourceType.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="p-4 md:p-10 max-w-6xl mx-auto h-full overflow-y-auto custom-scrollbar">
      <header className="mb-8 border-b-2 border-[#1A1A1A] pb-6 flex flex-col md:flex-row md:justify-between md:items-end gap-4">
        <div>
          <h1 className="text-3xl font-black text-[#1A1A1A] uppercase tracking-tighter">BASE DE CONHECIMENTO</h1>
          <p className="text-[#7A7A7A] mt-1 font-bold text-[10px] uppercase tracking-widest italic">Protocolo RAG (Retrieval Augmented Generation)</p>
        </div>
        <div className="flex gap-2">
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="sketch-button px-6 py-2 text-[10px] font-black uppercase tracking-widest bg-emerald-600 border-emerald-900"
          >
            Upload Local
          </button>
          <button 
            onClick={() => setIsDrivePickerOpen(true)}
            className="sketch-button px-6 py-2 text-[10px] font-black uppercase tracking-widest bg-blue-600 border-blue-900"
          >
            Google Drive
          </button>
          <input 
            type="file" 
            ref={fileInputRef} 
            className="hidden" 
            multiple 
            onChange={(e) => e.target.files && handleFiles(e.target.files)} 
          />
        </div>
      </header>

      {/* Integration Bar */}
      <section className="bg-white sketch-border p-6 mb-8">
        <h3 className="text-[10px] font-black uppercase mb-4 tracking-widest border-b border-gray-100 pb-2">Conectar Serviços Externos</h3>
        <div className="flex flex-col md:flex-row gap-4">
          <select 
            value={selectedProvider} 
            onChange={(e) => setSelectedProvider(e.target.value as DocumentSource)}
            className="bg-[#F2EFEA] border-2 border-[#1A1A1A] px-4 py-3 font-black text-[10px] uppercase outline-none flex-shrink-0"
          >
            <option value="google_docs">Google Docs (URL)</option>
            <option value="google_sheets">Google Sheets (URL)</option>
            <option value="google_analytics">Google Analytics 4</option>
          </select>
          <input 
            type="text" 
            placeholder={selectedProvider === 'google_analytics' ? "ID da Propriedade (ex: 29384729)" : "Cole a URL do documento aqui..."}
            value={externalUrl}
            onChange={(e) => setExternalUrl(e.target.value)}
            className="flex-1 bg-white border-2 border-[#1A1A1A] px-4 py-3 font-bold text-[10px] uppercase outline-none focus:bg-[#F2EFEA]"
          />
          <button 
            onClick={handleAddExternal}
            disabled={!externalUrl || isUploading}
            className="sketch-button px-8 py-3 text-[10px] font-black uppercase tracking-widest flex items-center gap-2 disabled:opacity-50"
          >
            {isUploading ? 'Sincronizando...' : 'Conectar'}
          </button>
        </div>
      </section>

      {/* Parsing Status Loader */}
      {isUploading && (
        <div className="fixed inset-0 bg-[#1A1A1A]/80 backdrop-blur-sm z-[100] flex items-center justify-center p-6">
          <div className="bg-white sketch-border p-12 text-center max-w-sm w-full">
            <div className="w-12 h-12 border-4 border-[#1A1A1A] border-t-emerald-500 rounded-full animate-spin mx-auto mb-6"></div>
            <h3 className="text-xl font-black uppercase mb-2">Protocolo de Extração</h3>
            <p className="text-[10px] font-bold text-[#7A7A7A] uppercase tracking-widest">{parsingStatus || 'Analisando estrutura de dados...'}</p>
          </div>
        </div>
      )}

      {/* Drive Picker Modal Simulation */}
      {isDrivePickerOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-md z-[110] flex items-center justify-center p-4">
          <div className="bg-white sketch-border w-full max-w-2xl overflow-hidden flex flex-col max-h-[80vh]">
            <div className="p-6 bg-[#1A1A1A] text-white flex justify-between items-center">
              <div className="flex items-center gap-3">
                <svg className="w-6 h-6 text-blue-400" fill="currentColor" viewBox="0 0 24 24"><path d="M7.74,9.8,4.69,15,1.65,9.8ZM19.34,15l-3.05-5.27,3.05-5.27h6.11L22.4,9.73ZM15.29,15,12.24,20.27,9.19,15Zm2-8.54L11,17.46,4.69,6.46Zm0,0,0,0Z"/></svg>
                <h3 className="font-black uppercase text-sm tracking-widest">Google Drive Picker</h3>
              </div>
              <button onClick={() => setIsDrivePickerOpen(false)} className="text-gray-400 hover:text-white transition-colors">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </div>
            <div className="p-6 flex-1 overflow-y-auto space-y-4 bg-[#F2EFEA]">
              <p className="text-[10px] font-black text-[#7A7A7A] uppercase mb-2">Selecione arquivos para importar para o FinaIGPT:</p>
              {driveFiles.map(file => (
                <div key={file.id} className="bg-white sketch-border p-4 flex items-center justify-between hover:translate-x-1 transition-transform cursor-pointer" onClick={() => importFromDrive(file)}>
                  <div className="flex items-center gap-4">
                    <div className={`w-10 h-10 flex items-center justify-center text-white font-black text-[8px] ${file.type === 'google_docs' ? 'bg-blue-500' : file.type === 'google_sheets' ? 'bg-emerald-500' : 'bg-gray-500'}`}>
                      {file.type.split('_').pop()?.toUpperCase() || 'FILE'}
                    </div>
                    <div>
                      <p className="text-[11px] font-black uppercase tracking-tight">{file.name}</p>
                      <p className="text-[8px] font-bold text-gray-400">{(file.size / 1024).toFixed(1)} KB</p>
                    </div>
                  </div>
                  <button className="text-[10px] font-black text-blue-600 hover:underline uppercase">Importar</button>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Document List */}
      <div className="space-y-6">
        <div className="flex items-center gap-4 mb-4">
          <div className="flex-1 relative">
            <input 
              type="text" 
              placeholder="Pesquisar na base..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full bg-white sketch-border px-10 py-3 text-[11px] font-bold uppercase outline-none focus:bg-[#F2EFEA]"
            />
            <svg className="w-5 h-5 absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
            </svg>
          </div>
        </div>

        {filteredDocs.length === 0 ? (
          <div className="bg-white sketch-border p-16 text-center">
            <h3 className="text-xl font-black uppercase mb-2">Base de Conhecimento Vazia</h3>
            <p className="text-[10px] font-bold text-[#7A7A7A] uppercase tracking-widest leading-relaxed">
              O modelo ainda não possui contexto local para responder suas dúvidas.<br/>Faça o upload de documentos para habilitar o modo RAG.
            </p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {filteredDocs.map((doc) => (
              <div key={doc.id} className="bg-white sketch-border p-5 hover:bg-[#F2EFEA] transition-colors relative group">
                <div className="flex justify-between items-start mb-4">
                  <div className="flex gap-3 items-center">
                    <span className={`text-[7px] font-black uppercase px-2 py-0.5 text-white ${doc.sourceType === 'local' ? 'bg-[#1A1A1A]' : 'bg-blue-600'}`}>
                      {doc.sourceType.replace('_', ' ')}
                    </span>
                    <span className="text-[7px] font-black uppercase bg-gray-100 text-gray-500 px-2 py-0.5">
                      {doc.metadata?.category || 'Geral'}
                    </span>
                  </div>
                  <button 
                    onClick={() => deleteDoc(doc.id)}
                    className="text-rose-500 hover:bg-rose-50 p-1 opacity-0 group-hover:opacity-100 transition-opacity"
                  >
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                    </svg>
                  </button>
                </div>
                <h4 className="text-[11px] font-black uppercase tracking-tight mb-2 truncate pr-6">{doc.name}</h4>
                <div className="flex justify-between items-end mt-4">
                  <div>
                    <p className="text-[7px] font-black text-gray-400 uppercase tracking-widest">
                      Indexado em: {new Date(doc.uploadDate).toLocaleDateString()}
                    </p>
                    <p className="text-[8px] font-bold text-[#1A1A1A] mt-1">
                      {doc.size > 0 ? `${(doc.size / 1024).toFixed(1)} KB` : 'Referência Cloud'}
                    </p>
                  </div>
                  <div className="flex gap-2">
                    <button className="text-[9px] font-black uppercase text-blue-600 hover:underline">Ver</button>
                    {doc.externalUrl && <a href={doc.externalUrl} target="_blank" className="text-[9px] font-black uppercase text-gray-400 hover:underline">Link</a>}
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Spacer for bottom on mobile */}
      <div className="h-20 lg:h-0"></div>
    </div>
  );
};

export default DocumentManager;

export interface User {
  id: string;
  name: string;
  email: string;
  avatar: string;
}

export interface Message {
  id: string;
  role: 'user' | 'model';
  content: string;
  timestamp: Date;
  sources?: string[];
}

export type SyncStatus = 'synced' | 'pending' | 'local' | 'conflict' | 'syncing';

export interface ChatSession {
  id: string;
  title: string;
  messages: Message[];
  lastUpdate: Date;
  updatedAt: string;
  deletedAt?: Date;
  syncStatus?: SyncStatus;
  syncedAt?: Date;
  version: number;
}

export type DocumentSource = 'local' | 'google_docs' | 'google_sheets' | 'google_analytics' | 'google_drive' | 'xero' | 'quickbooks' | 'omie';

export interface Document {
  id: string;
  name: string;
  content: string;
  type: string;
  uploadDate: Date;
  size: number;
  sourceType: DocumentSource;
  externalUrl?: string;
  metadata?: {
    propertyId?: string;
    lastSync?: Date;
    category?: 'cost' | 'tax' | 'management' | 'general' | 'exercise';
  };
}

