import { Document, User, ChatSession, SyncStatus } from '../types.ts';

const DOCS_KEY = 'finan_gpt_docs';
const USER_KEY = 'finan_gpt_user';
const CHATS_KEY = 'finan_gpt_chats';
const CLOUD_MOCK_KEY = 'finan_gpt_cloud_mock';

export const StorageService = {
  // Documents
  getDocuments: (): Document[] => {
    try {
      const data = localStorage.getItem(DOCS_KEY);
      if (!data) return [];
      const docs = JSON.parse(data);
      return docs.map((d: any) => ({
        ...d,
        uploadDate: new Date(d.uploadDate),
        metadata: {
          ...d.metadata,
          lastSync: d.metadata?.lastSync ? new Date(d.metadata.lastSync) : undefined
        }
      }));
    } catch (e) {
      console.error("Error reading documents", e);
      return [];
    }
  },

  saveDocument: (doc: Document) => {
    const docs = StorageService.getDocuments();
    docs.push(doc);
    localStorage.setItem(DOCS_KEY, JSON.stringify(docs));
  },

  deleteDocument: (id: string) => {
    const docs = StorageService.getDocuments().filter(d => d.id !== id);
    localStorage.setItem(DOCS_KEY, JSON.stringify(docs));
  },

  // User
  getUser: (): User | null => {
    try {
      const data = localStorage.getItem(USER_KEY);
      return data ? JSON.parse(data) : null;
    } catch (e) {
      return null;
    }
  },

  setUser: (user: User) => {
    localStorage.setItem(USER_KEY, JSON.stringify(user));
  },

  // Chat Sessions
  getChatSessions: (includeDeleted: boolean = false): ChatSession[] => {
    const data = localStorage.getItem(CHATS_KEY);
    if (!data) return [];

    try {
      const parsed = JSON.parse(data);
      if (!Array.isArray(parsed)) return [];

      const sessions = parsed.map((s: any) => ({
        ...s,
        lastUpdate: new Date(s.lastUpdate),
        syncedAt: s.syncedAt ? new Date(s.syncedAt) : undefined,
        deletedAt: s.deletedAt ? new Date(s.deletedAt) : undefined,
        messages: (s.messages || []).map((m: any) => ({ 
          ...m, 
          timestamp: new Date(m.timestamp) 
        }))
      }));

      if (includeDeleted) return sessions;
      return sessions.filter(s => !s.deletedAt);
    } catch (e) {
      console.error("Failed to parse chat sessions", e);
      return [];
    }
  },

  saveChatSession: (session: ChatSession) => {
    const sessions = StorageService.getChatSessions(true);
    const index = sessions.findIndex(s => s.id === session.id);

    const user = StorageService.getUser();
    const now = new Date();

    const updatedSession: ChatSession = { 
      ...session, 
      lastUpdate: now,
      updatedAt: now.toISOString(),
      version: (session.version || 0) + 1,
      syncStatus: user ? 'pending' : 'local' as SyncStatus 
    };

    if (index >= 0) {
      sessions[index] = updatedSession;
    } else {
      sessions.unshift(updatedSession);
    }

    localStorage.setItem(CHATS_KEY, JSON.stringify(sessions));

    if (user) {
      StorageService.syncSessionWithCloud(updatedSession.id);
    }
  },

  togglePin: (id: string) => {
    const sessions = StorageService.getChatSessions(true);
    const index = sessions.findIndex(s => s.id === id);
    if (index >= 0) {
      sessions[index].isPinned = !sessions[index].isPinned;
      sessions[index].updatedAt = new Date().toISOString();
      localStorage.setItem(CHATS_KEY, JSON.stringify(sessions));
      StorageService.syncWithCloud();
    }
  },

  /**
   * Performs a robust sync with the simulated "Google Account" cloud.
   * Handles conflicts using Last-Writer-Wins strategy based on updatedAt timestamp.
   */
  syncWithCloud: async () => {
    const user = StorageService.getUser();
    if (!user) return;

    window.dispatchEvent(new CustomEvent('sync_status_change', { detail: 'syncing' }));

    try {
      // Simulate network delay
      await new Promise(resolve => setTimeout(resolve, 800));

      // 1. Fetch Cloud State (Simulated)
      const cloudData = localStorage.getItem(`${CLOUD_MOCK_KEY}_${user.id}`);
      const cloudSessions: ChatSession[] = cloudData ? JSON.parse(cloudData) : [];

      // 2. Fetch Local State
      const localSessions = StorageService.getChatSessions(true);

      // 3. Robust Merge Logic
      const mergedMap = new Map<string, ChatSession>();

      // Load cloud sessions first
      cloudSessions.forEach(cs => mergedMap.set(cs.id, cs));

      // Compare with local
      localSessions.forEach(ls => {
        const cs = mergedMap.get(ls.id);
        if (!cs) {
          // Exists locally only
          mergedMap.set(ls.id, { ...ls, syncStatus: 'synced' });
        } else {
          // Conflict Resolution: Last-Writer-Wins
          const localTime = new Date(ls.updatedAt).getTime();
          const cloudTime = new Date(cs.updatedAt).getTime();

          if (localTime > cloudTime) {
            // Local is newer, keep local
            mergedMap.set(ls.id, { ...ls, syncStatus: 'synced' });
          } else {
            // Cloud is newer or same, keep cloud
            mergedMap.set(ls.id, { ...cs, syncStatus: 'synced' });
          }
        }
      });

      const finalSessions = Array.from(mergedMap.values());

      // 4. Update both stores
      localStorage.setItem(CHATS_KEY, JSON.stringify(finalSessions));
      localStorage.setItem(`${CLOUD_MOCK_KEY}_${user.id}`, JSON.stringify(finalSessions));

      window.dispatchEvent(new CustomEvent('session_synced', { detail: 'all' }));
      window.dispatchEvent(new CustomEvent('sync_status_change', { detail: 'synced' }));
    } catch (error) {
      console.error("Cloud Sync Failed:", error);
      window.dispatchEvent(new CustomEvent('sync_status_change', { detail: 'error' }));
    }
  },

  syncSessionWithCloud: async (sessionId: string) => {
    // For specific session sync, we trigger the full robust sync to ensure consistency
    StorageService.syncWithCloud();
  },

  deleteChatSession: (id: string) => {
    const sessions = StorageService.getChatSessions(true);
    const index = sessions.findIndex(s => s.id === id);
    if (index >= 0) {
      const now = new Date();
      sessions[index].deletedAt = now;
      sessions[index].updatedAt = now.toISOString();
      sessions[index].syncStatus = 'pending';
      localStorage.setItem(CHATS_KEY, JSON.stringify(sessions));
      StorageService.syncWithCloud();
    }
  },

  restoreFromTrash: (id: string) => {
    const sessions = StorageService.getChatSessions(true);
    const index = sessions.findIndex(s => s.id === id);
    if (index >= 0) {
      const now = new Date();
      delete sessions[index].deletedAt;
      sessions[index].updatedAt = now.toISOString();
      sessions[index].syncStatus = 'pending';
      localStorage.setItem(CHATS_KEY, JSON.stringify(sessions));
      StorageService.syncWithCloud();
    }
  },

  deletePermanently: (id: string) => {
    const sessions = StorageService.getChatSessions(true);
    const updatedSessions = sessions.filter(s => s.id !== id);
    localStorage.setItem(CHATS_KEY, JSON.stringify(updatedSessions));
    // Also update cloud mock to reflect permanent deletion
    const user = StorageService.getUser();
    if (user) {
      localStorage.setItem(`${CLOUD_MOCK_KEY}_${user.id}`, JSON.stringify(updatedSessions));
    }
  },

  clearAll: () => {
    localStorage.clear();
  }
};

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Message, ChatSession } from '../types.ts';
import { GeminiService } from '../services/geminiService.ts';
import { StorageService } from '../services/storage.ts';

const ChatListItem: React.FC<{
