};

const ChatInterface: React.FC = () => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [streamingText, setStreamingText] = useState('');
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    const loadedSessions = StorageService.getChatSessions();
    setSessions(loadedSessions);
    if (loadedSessions.length > 0 && !currentSessionId) {
      setCurrentSessionId(loadedSessions[0].id);
    }
  }, []);

  useEffect(() => {
    const handleSync = () => setSessions(StorageService.getChatSessions());
    window.addEventListener('session_synced', handleSync);
    return () => window.removeEventListener('session_synced', handleSync);
  }, []);

  const currentSession = useMemo(() => sessions.find(s => s.id === currentSessionId), [sessions, currentSessionId]);

  const scrollToBottom = useCallback((force = false) => {
    if (scrollRef.current) {
      const { scrollHeight, scrollTop, clientHeight } = scrollRef.current;
      const isNearBottom = scrollHeight - scrollTop - clientHeight < 250;
      if (force || isNearBottom) {
        scrollRef.current.scrollTo({
          top: scrollHeight,
          behavior: force ? 'auto' : 'smooth'
        });
      }
    }
  }, []);

  useEffect(() => {
    scrollToBottom();
  }, [currentSession?.messages, streamingText, isLoading, scrollToBottom]);

  useEffect(() => {
    if (currentSessionId) {
      setTimeout(() => scrollToBottom(true), 100);
    }
  }, [currentSessionId, scrollToBottom]);

  const handleNewChat = () => {
    const newId = Math.random().toString(36).substr(2, 9);
    const newSession: ChatSession = {
      id: newId,
      title: 'Nova Consulta Contábil',
      messages: [],
      lastUpdate: new Date(),
      updatedAt: new Date().toISOString(),
      version: 1,
      isPinned: false
    };
    StorageService.saveChatSession(newSession);
    setSessions(StorageService.getChatSessions());
    setCurrentSessionId(newId);
    setIsHistoryOpen(false);
    if (textareaRef.current) textareaRef.current.focus();
  };

  const handleTogglePin = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    StorageService.togglePin(id);
    setSessions(StorageService.getChatSessions());
  };

  const handleDeleteChat = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (window.confirm("Mover esta consulta para a lixeira?")) {
      StorageService.deleteChatSession(id);
      const updated = StorageService.getChatSessions();
      setSessions(updated);
      if (currentSessionId === id) {
        setCurrentSessionId(updated.length > 0 ? updated[0].id : null);
      }
    }
  };

  const handleSendMessage = async () => {
    if (!input.trim() || isLoading) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      timestamp: new Date()
    };

    let session = currentSession;
    if (!session) {
      const newId = Math.random().toString(36).substr(2, 9);
      session = {
        id: newId,
        title: input.substring(0, 30) + '...',
        messages: [],
        lastUpdate: new Date(),
        updatedAt: new Date().toISOString(),
        version: 1,
        isPinned: false
      };
      setCurrentSessionId(newId);
    }

    const updatedMessages = [...session.messages, userMessage];
    const updatedSession = { ...session, messages: updatedMessages };

    StorageService.saveChatSession(updatedSession);
    setSessions(StorageService.getChatSessions());
    setInput('');
    setIsLoading(true);
    setStreamingText('');

    try {
      const response = await GeminiService.generateChatResponseStream(
        input,
        updatedMessages,
        (chunk) => setStreamingText(chunk)
      );

      const modelMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: response,
        timestamp: new Date()
      };

      const finalSession = {
        ...updatedSession,
        messages: [...updatedMessages, modelMessage],
        lastUpdate: new Date()
      };

      if (updatedMessages.length === 1) {
        const generatedTitle = await GeminiService.generateTitle(input);
        finalSession.title = generatedTitle;
      }

      StorageService.saveChatSession(finalSession);
      setSessions(StorageService.getChatSessions());
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
      setStreamingText('');
    }
  };

  const pinnedSessions = useMemo(() => sessions.filter(s => s.isPinned).sort((a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime()), [sessions]);
  const recentSessions = useMemo(() => sessions.filter(s => !s.isPinned).sort((a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime()), [sessions]);

  return (
    <div className="flex h-full bg-[#F2EFEA] overflow-hidden">
      {/* Sidebar de Sessões */}
      <aside className={`
        fixed inset-y-0 left-0 z-40 w-72 bg-white border-r-2 border-[#1A1A1A] flex flex-col transition-transform duration-300 transform
        ${isHistoryOpen ? 'translate-x-0 shadow-2xl' : '-translate-x-full lg:translate-x-0 lg:static'}
      `}>
        <div className="p-6 border-b-2 border-[#1A1A1A] bg-[#F2EFEA] shrink-0">
          <button 
            onClick={handleNewChat}
            className="w-full sketch-button py-3 text-[10px] font-black uppercase tracking-widest bg-[#1A1A1A] text-white flex items-center justify-center gap-2"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" />
            </svg>
            Nova Auditoria
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
          {pinnedSessions.length > 0 && (
            <div className="mb-6">
              <h3 className="text-[8px] font-black uppercase tracking-[0.3em] text-[#7A7A7A] mb-3 px-2">Sessões Fixadas</h3>
              {pinnedSessions.map(s => (
                <ChatListItem 
                  key={s.id} 
                  session={s} 
                  isActive={currentSessionId === s.id}
                  onClick={() => { setCurrentSessionId(s.id); setIsHistoryOpen(false); }}
                  onTogglePin={handleTogglePin}
                  onDelete={handleDeleteChat}
                />
              ))}
            </div>
          )}

          <div>
            <h3 className="text-[8px] font-black uppercase tracking-[0.3em] text-[#7A7A7A] mb-3 px-2">Recentes</h3>
            {recentSessions.length === 0 && pinnedSessions.length === 0 ? (
              <div className="p-8 text-center opacity-40">
                <p className="text-[8px] font-black uppercase italic">Nenhuma sessão ativa</p>
              </div>
            ) : (
              recentSessions.map(s => (
                <ChatListItem 
                  key={s.id} 
                  session={s} 
                  isActive={currentSessionId === s.id}
                  onClick={() => { setCurrentSessionId(s.id); setIsHistoryOpen(false); }}
                  onTogglePin={handleTogglePin}
                  onDelete={handleDeleteChat}
                />
              ))
            )}
          </div>
        </div>
      </aside>

      {/* Área do Chat */}
      <div className="flex-1 flex flex-col h-full relative overflow-hidden">
        {/* Header Mobile Only */}
        <header className="lg:hidden flex items-center justify-between p-4 bg-white border-b-2 border-[#1A1A1A]">
          <button onClick={() => setIsHistoryOpen(true)} className="p-2 bg-[#1A1A1A] text-white sketch-border">
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
            </svg>
          </button>
          <span className="text-[10px] font-black uppercase">{currentSession?.title || 'FinaIGPT'}</span>
          <div className="w-10" />
        </header>

        {/* Mensagens */}
        <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 md:p-8 space-y-6 custom-scrollbar">
          {!currentSession && (
            <div className="h-full flex flex-col items-center justify-center opacity-40 text-center">
              <div className="w-16 h-16 bg-[#1A1A1A] text-white flex items-center justify-center text-4xl font-black sketch-border mb-6">F</div>
              <p className="text-xs font-black uppercase tracking-widest italic">Inicie uma nova análise contábil no terminal.</p>
            </div>
          )}

          {currentSession?.messages.map((msg) => (
            <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`
                max-w-[85%] md:max-w-[70%] p-4 sketch-border
                ${msg.role === 'user' ? 'bg-[#1A1A1A] text-white' : 'bg-white text-[#1A1A1A]'}
              `}>
                <div className="flex items-center gap-2 mb-2 border-b border-current/10 pb-1">
                  <span className="text-[8px] font-black uppercase tracking-widest">
                    {msg.role === 'user' ? 'AUDITOR' : 'FINAIGPT IA'}
                  </span>
                  <span className="text-[7px] opacity-40 uppercase">
                    {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </span>
                </div>
                <div className="text-xs font-medium leading-relaxed whitespace-pre-wrap break-words">
                  {msg.content}
                </div>
              </div>
            </div>
          ))}

          {isLoading && (
            <div className="flex justify-start">
              <div className="max-w-[85%] md:max-w-[70%] p-4 bg-white text-[#1A1A1A] sketch-border animate-pulse">
                <div className="flex items-center gap-2 mb-2">
                  <span className="text-[8px] font-black uppercase tracking-widest">PROCESSANDO...</span>
                  <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-ping" />
                </div>
                <div className="text-xs font-medium leading-relaxed whitespace-pre-wrap">
                  {streamingText || "Analisando normativas CPC/IFRS..."}
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Input */}
        <div className="p-4 md:p-8 pt-0 bg-transparent">
          <div className="max-w-4xl mx-auto relative group">
            <textarea
              ref={textareaRef}
              rows={1}
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter' && !e.shiftKey) {
                  e.preventDefault();
                  handleSendMessage();
                }
              }}
              placeholder="Digite sua dúvida contábil ou peça um balanço..."
              className="w-full bg-white sketch-border p-4 md:p-6 pr-16 text-xs font-bold uppercase tracking-tight outline-none focus:ring-2 ring-[#1A1A1A]/5 resize-none overflow-hidden min-h-[60px]"
            />
            <button 
              onClick={handleSendMessage}
              disabled={isLoading || !input.trim()}
              className={`
                absolute right-4 bottom-4 md:right-6 md:bottom-6 p-2 rounded-lg transition-all
                ${isLoading || !input.trim() ? 'text-gray-300' : 'bg-[#1A1A1A] text-white hover:scale-110 active:scale-95'}
              `}
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
              </svg>
            </button>
          </div>
          <p className="mt-3 text-[7px] text-center font-black text-[#7A7A7A] uppercase tracking-[0.2em]">
            Base de dados sincronizada com APIs contábeis ativas • Auditoria IA Certificada
          </p>
        </div>
      </div>

      {/* Overlay Mobile */}
      {isHistoryOpen && (
        <div 
          className="fixed inset-0 bg-black/40 backdrop-blur-sm z-30 lg:hidden"
          onClick={() => setIsHistoryOpen(false)}
        />
      )}
    </div>
  );
};

export default ChatInterface;

import React, { useState, useEffect, useMemo, useRef, useLayoutEffect } from 'react';
import { MarketService, MarketRates, StockInfo, AnalyticsMetrics } from '../services/marketService.ts';
import { GeminiService } from '../services/geminiService.ts';
import { Candle, NewsArticle } from '../types.ts';
import { StorageService } from '../services/storage.ts';

const Dashboard: React.FC = () => {
  const [rates, setRates] = useState<MarketRates | null>(null);
  const [stocks, setStocks] = useState<StockInfo[]>([]);
  const [candles, setCandles] = useState<Candle[]>([]);
  const [news, setNews] = useState<NewsArticle[]>([]);
  const [selectedAsset, setSelectedAsset] = useState('BTC');
  const [timeframe, setTimeframe] = useState('1h');
  const [hoveredCandle, setHoveredCandle] = useState<Candle | null>(null);
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });
  const [loadingMarket, setLoadingMarket] = useState(true);
  const [loadingNews, setLoadingNews] = useState(true);
  const [analyticsData, setAnalyticsData] = useState<AnalyticsMetrics | null>(null);
  const [lastUpdate, setLastUpdate] = useState<string>(new Date().toLocaleTimeString());

  const [visibleCount, setVisibleCount] = useState(50);
  const [scrollOffset, setScrollOffset] = useState(0);
  const [isPanning, setIsPanning] = useState(false);
  const [startX, setStartX] = useState(0);
  const chartRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const docs = StorageService.getDocuments();
    const gaDoc = docs.find(d => d.sourceType === 'google_analytics');
    if (gaDoc) {
      try {
        const metrics = JSON.parse(gaDoc.content);
        if (metrics.activeUsers) setAnalyticsData(metrics);
      } catch (e) { console.error("GA Parse Error"); }
    }

    const loadMarketData = async () => {
      setLoadingMarket(true);
      try {
        const rateData = await MarketService.fetchExchangeRates();
        const [stockData, candleData] = await Promise.all([
          MarketService.fetchStockData(rateData),
          MarketService.fetchHistoricalCandles(selectedAsset, timeframe)
        ]);
        setRates(rateData);
        setStocks(stockData);
        setCandles(candleData);
        setLastUpdate(new Date().toLocaleTimeString());
      } catch (e) {
        console.error("Market Update Error", e);
      } finally {
        setLoadingMarket(false);
      }
    };

    const loadNews = async () => {
      setLoadingNews(true);
      try {
        const latestNews = await GeminiService.fetchLatestNews();
        setNews(latestNews);
      } catch (e) { console.error("News Error", e); }
      finally { setLoadingNews(false); }
    };

    loadMarketData();
    loadNews();

    const mInterval = setInterval(loadMarketData, 60000); 
    const nInterval = setInterval(loadNews, 300000); 

    return () => { clearInterval(mInterval); clearInterval(nInterval); };
  }, [selectedAsset, timeframe]);

  useLayoutEffect(() => {
    const el = chartRef.current;
    if (!el) return;

    const handleWheel = (e: WheelEvent) => {
      e.preventDefault();
      if (e.ctrlKey || e.metaKey || e.altKey) {
        // Zoom Granular
        const zoomSpeed = 2;
        const delta = e.deltaY > 0 ? zoomSpeed : -zoomSpeed;
        setVisibleCount(prev => Math.min(Math.max(10, prev + delta), (candles.length || 100)));
      } else {
        // Scroll Suave
        const scrollSpeed = 1;
        const delta = e.deltaY > 0 ? scrollSpeed : -scrollSpeed;
        setScrollOffset(prev => Math.min(Math.max(0, prev + delta), Math.max(0, (candles.length || 0) - visibleCount)));
      }
    };

    el.addEventListener('wheel', handleWheel, { passive: false });
    return () => el.removeEventListener('wheel', handleWheel);
  }, [candles.length, visibleCount]);

  const visibleCandles = useMemo(() => {
    if (candles.length === 0) return [];
    // Garantir que o offset não ultrapasse os limites ao mudar zoom
    const maxOffset = Math.max(0, candles.length - visibleCount);
    const safeOffset = Math.min(scrollOffset, maxOffset);

    const end = candles.length - safeOffset;
    const start = Math.max(0, end - visibleCount);
    return candles.slice(start, end);
  }, [candles, visibleCount, scrollOffset]);

  const chartMetrics = useMemo(() => {
    if (visibleCandles.length === 0) return null;
    const lows = visibleCandles.map(c => c.low);
    const highs = visibleCandles.map(c => c.high);
    const minLow = Math.min(...lows);
    const maxHigh = Math.max(...highs);
    const range = Math.max(0.00001, maxHigh - minLow);
    return { minLow, maxHigh, range };
  }, [visibleCandles]);

  const handleMouseDown = (e: React.MouseEvent) => {
    setIsPanning(true);
    setStartX(e.clientX);
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    const rect = chartRef.current?.getBoundingClientRect();
    if (rect) {
      setMousePos({ 
        x: e.clientX - rect.left, 
        y: e.clientY - rect.top 
      });
    }

    if (!isPanning) return;
    const dx = e.clientX - startX;
    if (Math.abs(dx) > 5) {
      const sensitivity = Math.ceil(visibleCount / 50);
      const move = dx > 0 ? sensitivity : -sensitivity;
      setScrollOffset(prev => Math.min(Math.max(0, prev + move), Math.max(0, (candles.length || 0) - visibleCount)));
      setStartX(e.clientX);
    }
  };

  const handleMouseUp = () => setIsPanning(false);

  const getSentimentColor = (sentiment?: string) => {
    switch(sentiment) {
      case 'BULLISH': return 'text-emerald-500 bg-emerald-500/10 border-emerald-500/20';
      case 'BEARISH': return 'text-rose-500 bg-rose-500/10 border-rose-500/20';
      default: return 'text-gray-500 bg-gray-500/10 border-gray-500/20';
    }
  };

  const renderCandleChart = () => {
    if (loadingMarket || !chartMetrics || visibleCandles.length === 0) {
      return (
        <div className="h-[400px] flex flex-col items-center justify-center gap-4 bg-white sketch-border">
          <div className="w-6 h-6 border-4 border-[#1A1A1A] border-t-transparent rounded-full animate-spin"></div>
          <span className="text-[8px] font-black uppercase tracking-widest text-[#7A7A7A]">Sincronizando Terminal...</span>
        </div>
      );
    }

    const width = 1200;
    const height = 400;
    const paddingRight = 80;
    const paddingTop = 40;
    const paddingBottom = 40;
    const chartWidth = width - paddingRight;
    const chartHeight = height - paddingTop - paddingBottom;

    const getY = (price: number) => paddingTop + chartHeight - ((price - chartMetrics.minLow) / chartMetrics.range) * chartHeight;
    const getPriceAtY = (y: number) => {
      const ratio = (paddingTop + chartHeight - y) / chartHeight;
      return chartMetrics.minLow + ratio * chartMetrics.range;
    };

    const candleSpace = chartWidth / (visibleCandles.length || 1);
    const candleWidth = Math.max(1, candleSpace * 0.8);

    const currentLastPrice = visibleCandles[visibleCandles.length - 1]?.close;
    const currentPriceY = getY(currentLastPrice);

    return (
      <div 
        ref={chartRef}
        className={`relative bg-white p-2 w-full select-none overflow-hidden ${isPanning ? 'cursor-grabbing' : 'cursor-crosshair'}`}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={() => { handleMouseUp(); setHoveredCandle(null); }}
      >
        {/* OHLC Bar - Top Overlay */}
        <div className="absolute top-2 left-4 z-10 flex gap-6 text-[10px] font-black uppercase pointer-events-none">
          {hoveredCandle ? (
            <>
              <div className="flex gap-1.5"><span className="text-gray-400">O:</span><span className="text-[#1A1A1A]">{hoveredCandle.open.toLocaleString()}</span></div>
              <div className="flex gap-1.5"><span className="text-gray-400">H:</span><span className="text-emerald-600">{hoveredCandle.high.toLocaleString()}</span></div>
              <div className="flex gap-1.5"><span className="text-gray-400">L:</span><span className="text-rose-600">{hoveredCandle.low.toLocaleString()}</span></div>
              <div className="flex gap-1.5"><span className="text-gray-400">C:</span><span className={hoveredCandle.close >= hoveredCandle.open ? 'text-emerald-600' : 'text-rose-600'}>{hoveredCandle.close.toLocaleString()}</span></div>
              <div className="flex gap-1.5"><span className="text-gray-400">V:</span><span className="text-blue-600">{((hoveredCandle.high - hoveredCandle.low) * 1000).toFixed(0)}</span></div>
            </>
          ) : (
             <span className="text-gray-300 italic">Passe o mouse para detalhes OHLC</span>
          )}
        </div>

        <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-[400px]" preserveAspectRatio="none">
          {/* Grid lines */}
          {[0, 0.25, 0.5, 0.75, 1].map((p, i) => {
            const y = paddingTop + p * chartHeight;
            const val = chartMetrics.maxHigh - (p * chartMetrics.range);
            return (
              <g key={i}>
                <line x1={0} y1={y} x2={chartWidth} y2={y} stroke="#F2EFEA" strokeWidth="1" />
                <text x={chartWidth + 5} y={y + 3} className="text-[9px] font-black fill-[#7A7A7A]">{val.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</text>
              </g>
            );
          })}

          {/* Current Price Line */}
          <line x1={0} y1={currentPriceY} x2={chartWidth} y2={currentPriceY} stroke="#1A1A1A" strokeWidth="1" strokeDasharray="4,2" opacity="0.5" />
          <rect x={chartWidth} y={currentPriceY - 8} width={paddingRight} height={16} fill="#1A1A1A" />
          <text x={chartWidth + 5} y={currentPriceY + 4} className="text-[9px] font-black fill-white">{currentLastPrice.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</text>

          {/* Candles */}
          {visibleCandles.map((candle, i) => {
            const x = i * candleSpace;
            const openY = getY(candle.open);
            const closeY = getY(candle.close);
            const highY = getY(candle.high);
            const lowY = getY(candle.low);
            const isBull = candle.close >= candle.open;
            const color = isBull ? '#10B981' : '#EF4444';

            return (
              <g key={i} onMouseEnter={() => setHoveredCandle(candle)}>
                {/* Wick */}
                <line x1={x + candleSpace/2} y1={highY} x2={x + candleSpace/2} y2={lowY} stroke={color} strokeWidth="1.5" />
                {/* Body */}
                <rect 
                  x={x + (candleSpace - candleWidth)/2} 
                  y={Math.min(openY, closeY)} 
                  width={candleWidth} 
                  height={Math.max(1, Math.abs(openY - closeY))} 
                  fill={isBull ? 'white' : color}
                  stroke={color}
                  strokeWidth="1.5"
                />
              </g>
            );
          })}

          {/* Crosshair */}
          {!isPanning && mousePos.x < chartWidth && (
            <g className="pointer-events-none">
              <line x1={mousePos.x * (width/chartRef.current!.clientWidth)} y1={0} x2={mousePos.x * (width/chartRef.current!.clientWidth)} y2={height} stroke="#1A1A1A" strokeWidth="0.5" strokeDasharray="2,2" />
              <line x1={0} y1={mousePos.y * (height/chartRef.current!.clientHeight)} x2={chartWidth} y2={mousePos.y * (height/chartRef.current!.clientHeight)} stroke="#1A1A1A" strokeWidth="0.5" strokeDasharray="2,2" />

              {/* Price Tag on Axis */}
              <rect x={chartWidth} y={(mousePos.y * (height/chartRef.current!.clientHeight)) - 8} width={paddingRight} height={16} fill="#7A7A7A" />
              <text x={chartWidth + 5} y={(mousePos.y * (height/chartRef.current!.clientHeight)) + 4} className="text-[9px] font-black fill-white">
                {getPriceAtY(mousePos.y * (height/chartRef.current!.clientHeight)).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
              </text>
            </g>
          )}
        </svg>

        <div className="absolute bottom-4 left-4 flex gap-4 pointer-events-none">
          <div className="bg-white/90 px-3 py-1 sketch-border text-[8px] font-black uppercase flex gap-4">
            <span className="flex items-center gap-1"><kbd className="bg-gray-100 px-1 border">Alt</kbd>+Scroll para Zoom</span>
            <span className="flex items-center gap-1">Drag para Mover</span>
            <span className="text-blue-600 font-black">{selectedAsset} • {timeframe} • {visibleCandles.length} VELAS</span>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full bg-[#F2EFEA] overflow-hidden">
      <div className="bg-[#1A1A1A] h-8 flex items-center overflow-hidden border-b-2 border-[#1A1A1A] relative shrink-0">
        <div className="flex animate-[ticker_40s_linear_infinite] whitespace-nowrap gap-12 px-4 items-center">
          {(stocks.length > 0 ? stocks.concat(stocks) : []).map((stock, i) => (
            <div key={i} className="flex items-center gap-2 text-[9px] font-black uppercase text-white">
              <span>{stock.symbol}</span>
              <span className="text-gray-400">{stock.price}</span>
              <span className={stock.isPositive ? 'text-emerald-400' : 'text-rose-400'}>{stock.change}</span>
            </div>
          ))}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8 custom-scrollbar">
        <header className="flex flex-col md:flex-row md:justify-between md:items-end gap-4 border-b-2 border-[#1A1A1A] pb-6">
          <div>
            <h1 className="text-3xl md:text-5xl font-black text-[#1A1A1A] uppercase tracking-tighter leading-none">TERMINAL DE OPERAÇÕES</h1>
            <p className="text-[9px] font-black uppercase text-emerald-600 mt-2 tracking-[0.2em]">● Feed Real-Time (Sincronizado {lastUpdate})</p>
          </div>
          <div className="flex gap-2">
            <select 
              value={selectedAsset} 
              onChange={(e) => setSelectedAsset(e.target.value)} 
              className="bg-white border-2 border-[#1A1A1A] px-3 py-2 font-black text-[10px] uppercase outline-none focus:bg-[#F2EFEA]"
            >
              {stocks.length > 0 ? stocks.map(s => <option key={s.symbol} value={s.symbol}>{s.symbol}</option>) : <option>Carregando...</option>}
            </select>
            <select 
              value={timeframe} 
              onChange={(e) => setTimeframe(e.target.value)} 
              className="bg-white border-2 border-[#1A1A1A] px-3 py-2 font-black text-[10px] uppercase outline-none focus:bg-[#F2EFEA]"
            >
              <option value="15m">15M</option>
              <option value="1h">1H</option>
              <option value="4h">4H</option>
              <option value="1d">1D</option>
            </select>
          </div>
        </header>

        <section className="bg-white sketch-border overflow-hidden">
          <div className="p-4 border-b-2 border-[#1A1A1A] flex justify-between items-center bg-[#F2EFEA]">
            <h2 className="text-[10px] font-black uppercase tracking-widest">{selectedAsset}/BRL Analysis</h2>
            <div className="flex gap-4">
              <span className="text-[8px] font-bold text-emerald-600 uppercase animate-pulse">● Live Data</span>
            </div>
          </div>
          {renderCandleChart()}
        </section>

        <section className="space-y-4">
          <div className="flex items-center justify-between border-b-2 border-[#1A1A1A] pb-2">
            <h3 className="text-xs font-black uppercase tracking-widest bg-[#1A1A1A] text-white px-3 py-1 italic">News Terminal (Hybrid Feed)</h3>
            {loadingNews && <div className="w-4 h-4 border-2 border-[#1A1A1A] border-t-transparent rounded-full animate-spin"></div>}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {loadingNews ? (
              Array(2).fill(0).map((_, i) => (
                <div key={i} className="bg-white sketch-border p-6 animate-pulse h-32">
                  <div className="h-4 bg-gray-200 w-3/4 mb-4"></div>
                  <div className="h-2 bg-gray-100 w-full"></div>
                </div>
              ))
            ) : (
              news.map((article, i) => (
                <a 
                  key={i} 
                  href={article.url} 
                  target="_blank" 
                  rel="noopener noreferrer" 
                  className="bg-white sketch-border p-5 hover:translate-x-1 hover:-translate-y-1 transition-all group block relative overflow-hidden"
                >
                  <div className="flex justify-between items-start mb-3">
                    <div className="flex gap-2 items-center">
                      <span className="text-[7px] font-black uppercase bg-[#1A1A1A] text-white px-2 py-0.5">{article.source}</span>
                      <span className={`text-[7px] font-black uppercase px-2 py-0.5 border ${getSentimentColor(article.sentiment)}`}>
                        {article.sentiment || 'NEUTRAL'}
                      </span>
                    </div>
                    <span className="text-[7px] font-bold text-[#7A7A7A] uppercase">{article.time}</span>
                  </div>
                  <h4 className="text-[11px] font-black uppercase tracking-tight mb-2 group-hover:underline leading-snug">{article.title}</h4>
                  <p className="text-[9px] text-[#4A4A4A] line-clamp-2 leading-relaxed font-medium">{article.summary}</p>
                </a>
              ))
            )}
          </div>
        </section>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pb-12">
          <section className="bg-white sketch-border p-6">
            <h3 className="text-xs font-black uppercase tracking-widest mb-6 border-b-2 border-[#1A1A1A] pb-2">Métricas Auditoria GA4</h3>
            {analyticsData ? (
              <div className="space-y-6">
                <div className="grid grid-cols-2 gap-4">
                  <div className="p-4 bg-[#F2EFEA] sketch-border shadow-none">
                    <p className="text-[8px] font-black text-[#7A7A7A] uppercase mb-1">Users Ativos</p>
                    <p className="text-xl font-black">{analyticsData.activeUsers.toLocaleString()}</p>
                    <span className="text-[7px] font-black text-emerald-500">
                      ↑ {(((analyticsData.activeUsers / (analyticsData.previousActiveUsers || 1)) - 1) * 100).toFixed(1)}% CRESCIMENTO
                    </span>
                  </div>
                  <div className="p-4 bg-[#F2EFEA] sketch-border shadow-none">
                    <p className="text-[8px] font-black text-[#7A7A7A] uppercase mb-1">Taxa Conversão</p>
                    <p className="text-xl font-black">{analyticsData.conversionRate.toFixed(2)}%</p>
                  </div>
                </div>
              </div>
            ) : (
              <div className="h-40 flex flex-col items-center justify-center bg-[#F2EFEA] sketch-border opacity-50">
                <p className="text-[8px] font-black uppercase tracking-widest">Nenhum dado GA4 vinculado</p>
              </div>
            )}
          </section>

          <section className="bg-[#1A1A1A] text-white sketch-border p-6">
            <h3 className="text-xs font-black uppercase tracking-widest mb-6 border-b border-white/20 pb-2">Compliance Assistant</h3>
            <div className="space-y-4">
              <div className="flex items-start gap-4 p-3 bg-white/5 border border-white/10">
                <div className="w-5 h-5 bg-emerald-500 rounded-full flex items-center justify-center text-[10px] font-bold text-[#1A1A1A]">✓</div>
                <div>
                  <p className="text-[9px] font-black uppercase tracking-tight">IFRS 16 - LEASES</p>
                  <p className="text-[8px] text-gray-400 mt-1">Verificação de passivos de arrendamento ativa na base de dados.</p>
                </div>
              </div>
              <div className="flex items-start gap-4 p-3 bg-white/5 border border-white/10">
                <div className="w-5 h-5 bg-amber-500 rounded-full flex items-center justify-center text-[10px] font-bold text-[#1A1A1A]">!</div>
                <div>
                  <p className="text-[9px] font-black uppercase tracking-tight">CPC 01 - REDUÇÃO AO VALOR RECUPERÁVEL</p>
                  <p className="text-[8px] text-gray-400 mt-1">Atenção: Teste de impairment necessário para ativos do grupo VALE3.</p>
                </div>
              </div>
            </div>
          </section>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useMemo, useRef, useLayoutEffect } from 'react';
import { MarketService, MarketRates, StockInfo, AnalyticsMetrics } from '../services/marketService.ts';
import { GeminiService } from '../services/geminiService.ts';
import { Candle, NewsArticle } from '../types.ts';
import { StorageService } from '../services/storage.ts';

const Dashboard: React.FC = () => {
  const [rates, setRates] = useState<MarketRates | null>(null);
  const [stocks, setStocks] = useState<StockInfo[]>([]);
  const [candles, setCandles] = useState<Candle[]>([]);
  const [news, setNews] = useState<NewsArticle[]>([]);
  const [selectedAsset, setSelectedAsset] = useState('BTC');
  const [timeframe, setTimeframe] = useState('1h');
  const [hoveredCandle, setHoveredCandle] = useState<Candle | null>(null);
  const [mousePos, setMousePos] = useState({ x: -1, y: -1 }); // Inicializado fora do gráfico
  const [loadingMarket, setLoadingMarket] = useState(true);
  const [loadingNews, setLoadingNews] = useState(true);
  const [analyticsData, setAnalyticsData] = useState<AnalyticsMetrics | null>(null);
  const [lastUpdate, setLastUpdate] = useState<string>(new Date().toLocaleTimeString());

  const [visibleCount, setVisibleCount] = useState(50);
  const [scrollOffset, setScrollOffset] = useState(0);
  const [isPanning, setIsPanning] = useState(false);
  const [startX, setStartX] = useState(0);
  const chartRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const docs = StorageService.getDocuments();
    const gaDoc = docs.find(d => d.sourceType === 'google_analytics');
    if (gaDoc) {
      try {
        const metrics = JSON.parse(gaDoc.content);
        if (metrics.activeUsers) setAnalyticsData(metrics);
      } catch (e) { console.error("GA Parse Error"); }
    }

    const loadMarketData = async () => {
      setLoadingMarket(true);
      try {
        const rateData = await MarketService.fetchExchangeRates();
        const [stockData, candleData] = await Promise.all([
          MarketService.fetchStockData(rateData),
          MarketService.fetchHistoricalCandles(selectedAsset, timeframe)
        ]);
        setRates(rateData);
        setStocks(stockData);
        setCandles(candleData);
        setLastUpdate(new Date().toLocaleTimeString());
      } catch (e) {
        console.error("Market Update Error", e);
      } finally {
        setLoadingMarket(false);
      }
    };

    const loadNews = async () => {
      setLoadingNews(true);
      try {
        const latestNews = await GeminiService.fetchLatestNews();
        setNews(latestNews);
      } catch (e) { console.error("News Error", e); }
      finally { setLoadingNews(false); }
    };

    loadMarketData();
    loadNews();

    const mInterval = setInterval(loadMarketData, 60000); 
    const nInterval = setInterval(loadNews, 300000); 

    return () => { clearInterval(mInterval); clearInterval(nInterval); };
  }, [selectedAsset, timeframe]);

  useLayoutEffect(() => {
    const el = chartRef.current;
    if (!el) return;

    const handleWheel = (e: WheelEvent) => {
      e.preventDefault();
      if (e.ctrlKey || e.metaKey || e.altKey) {
        // Zoom Granular
        const zoomSpeed = 2;
        const delta = e.deltaY > 0 ? zoomSpeed : -zoomSpeed;
        setVisibleCount(prev => Math.min(Math.max(10, prev + delta), (candles.length || 100)));
      } else {
        // Scroll Suave
        const scrollSpeed = 1;
        const delta = e.deltaY > 0 ? scrollSpeed : -scrollSpeed;
        setScrollOffset(prev => Math.min(Math.max(0, prev + delta), Math.max(0, (candles.length || 0) - visibleCount)));
      }
    };

    el.addEventListener('wheel', handleWheel, { passive: false });
    return () => el.removeEventListener('wheel', handleWheel);
  }, [candles.length, visibleCount]);

  const visibleCandles = useMemo(() => {
    if (candles.length === 0) return [];
    const maxOffset = Math.max(0, candles.length - visibleCount);
    const safeOffset = Math.min(scrollOffset, maxOffset);

    const end = candles.length - safeOffset;
    const start = Math.max(0, end - visibleCount);
    return candles.slice(start, end);
  }, [candles, visibleCount, scrollOffset]);

  const chartMetrics = useMemo(() => {
    if (visibleCandles.length === 0) return null;
    const lows = visibleCandles.map(c => c.low);
    const highs = visibleCandles.map(c => c.high);
    const minLow = Math.min(...lows);
    const maxHigh = Math.max(...highs);
    const range = Math.max(0.00001, maxHigh - minLow);
    return { minLow, maxHigh, range };
  }, [visibleCandles]);

  const handleMouseDown = (e: React.MouseEvent) => {
    setIsPanning(true);
    setStartX(e.clientX);
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    const rect = chartRef.current?.getBoundingClientRect();
    if (rect) {
      setMousePos({ 
        x: e.clientX - rect.left, 
        y: e.clientY - rect.top 
      });
    }

    if (!isPanning) return;
    const dx = e.clientX - startX;
    if (Math.abs(dx) > 5) {
      const sensitivity = Math.ceil(visibleCount / 50);
      const move = dx > 0 ? sensitivity : -sensitivity;
      setScrollOffset(prev => Math.min(Math.max(0, prev + move), Math.max(0, (candles.length || 0) - visibleCount)));
      setStartX(e.clientX);
    }
  };

  const handleMouseUp = () => setIsPanning(false);

  const getSentimentColor = (sentiment?: string) => {
    switch(sentiment) {
      case 'BULLISH': return 'text-emerald-500 bg-emerald-500/10 border-emerald-500/20';
      case 'BEARISH': return 'text-rose-500 bg-rose-500/10 border-rose-500/20';
      default: return 'text-gray-500 bg-gray-500/10 border-gray-500/20';
    }
  };

  const renderCandleChart = () => {
    if (loadingMarket || !chartMetrics || visibleCandles.length === 0) {
      return (
        <div className="h-[400px] flex flex-col items-center justify-center gap-4 bg-white sketch-border">
          <div className="w-6 h-6 border-4 border-[#1A1A1A] border-t-transparent rounded-full animate-spin"></div>
          <span className="text-[8px] font-black uppercase tracking-widest text-[#7A7A7A]">Sincronizando Terminal...</span>
        </div>
      );
    }

    const width = 1200;
    const height = 400;
    const paddingRight = 80;
    const paddingTop = 40;
    const paddingBottom = 40;
    const chartWidth = width - paddingRight;
    const chartHeight = height - paddingTop - paddingBottom;

    const getY = (price: number) => paddingTop + chartHeight - ((price - chartMetrics.minLow) / chartMetrics.range) * chartHeight;
    const getPriceAtY = (y: number) => {
      const ratio = (paddingTop + chartHeight - y) / chartHeight;
      return chartMetrics.minLow + ratio * chartMetrics.range;
    };

    const candleSpace = chartWidth / (visibleCandles.length || 1);
    const candleWidth = Math.max(1, candleSpace * 0.8);

    const currentLastPrice = visibleCandles[visibleCandles.length - 1]?.close;
    const currentPriceY = getY(currentLastPrice);

    return (
      <div 
        ref={chartRef}
        className={`relative bg-white p-2 w-full select-none overflow-hidden ${isPanning ? 'cursor-grabbing' : 'cursor-crosshair'}`}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={() => { handleMouseUp(); setHoveredCandle(null); setMousePos({ x: -1, y: -1 }); }}
      >
        <div className="absolute top-2 left-4 z-10 flex gap-6 text-[10px] font-black uppercase pointer-events-none">
          {hoveredCandle ? (
            <>
              <div className="flex gap-1.5"><span className="text-gray-400">O:</span><span className="text-[#1A1A1A]">{hoveredCandle.open.toLocaleString()}</span></div>
              <div className="flex gap-1.5"><span className="text-gray-400">H:</span><span className="text-emerald-600">{hoveredCandle.high.toLocaleString()}</span></div>
              <div className="flex gap-1.5"><span className="text-gray-400">L:</span><span className="text-rose-600">{hoveredCandle.low.toLocaleString()}</span></div>
              <div className="flex gap-1.5"><span className="text-gray-400">C:</span><span className={hoveredCandle.close >= hoveredCandle.open ? 'text-emerald-600' : 'text-rose-600'}>{hoveredCandle.close.toLocaleString()}</span></div>
              <div className="flex gap-1.5"><span className="text-gray-400">V:</span><span className="text-blue-600">{((hoveredCandle.high - hoveredCandle.low) * 1000).toFixed(0)}</span></div>
            </>
          ) : (
             <span className="text-gray-300 italic">Passe o mouse para detalhes OHLC</span>
          )}
        </div>

        <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-[400px]" preserveAspectRatio="none">
          {[0, 0.25, 0.5, 0.75, 1].map((p, i) => {
            const y = paddingTop + p * chartHeight;
            const val = chartMetrics.maxHigh - (p * chartMetrics.range);
            return (
              <g key={i}>
                <line x1={0} y1={y} x2={chartWidth} y2={y} stroke="#F2EFEA" strokeWidth="1" />
                <text x={chartWidth + 5} y={y + 3} className="text-[9px] font-black fill-[#7A7A7A]">{val.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</text>
              </g>
            );
          })}

          <line x1={0} y1={currentPriceY} x2={chartWidth} y2={currentPriceY} stroke="#1A1A1A" strokeWidth="1" strokeDasharray="4,2" opacity="0.5" />
          <rect x={chartWidth} y={currentPriceY - 8} width={paddingRight} height={16} fill="#1A1A1A" />
          <text x={chartWidth + 5} y={currentPriceY + 4} className="text-[9px] font-black fill-white">{currentLastPrice.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</text>

          {visibleCandles.map((candle, i) => {
            const x = i * candleSpace;
            const openY = getY(candle.open);
            const closeY = getY(candle.close);
            const highY = getY(candle.high);
            const lowY = getY(candle.low);
            const isBull = candle.close >= candle.open;
            const color = isBull ? '#10B981' : '#EF4444';

            return (
              <g key={i} onMouseEnter={() => setHoveredCandle(candle)}>
                <line x1={x + candleSpace/2} y1={highY} x2={x + candleSpace/2} y2={lowY} stroke={color} strokeWidth="1.5" />
                <rect 
                  x={x + (candleSpace - candleWidth)/2} 
                  y={Math.min(openY, closeY)} 
                  width={candleWidth} 
                  height={Math.max(1, Math.abs(openY - closeY))} 
                  fill={isBull ? 'white' : color}
                  stroke={color}
                  strokeWidth="1.5"
                />
              </g>
            );
          })}

          {/* Crosshair - Com verificação de segurança no chartRef e posições válidas */}
          {!isPanning && chartRef.current && mousePos.x >= 0 && mousePos.x < chartRef.current.clientWidth && (
            <g className="pointer-events-none">
              {(() => {
                const svgX = mousePos.x * (width / chartRef.current.clientWidth);
                const svgY = mousePos.y * (height / chartRef.current.clientHeight);

                if (svgX > chartWidth) return null;

                return (
                  <>
                    <line x1={svgX} y1={0} x2={svgX} y2={height} stroke="#1A1A1A" strokeWidth="0.5" strokeDasharray="2,2" />
                    <line x1={0} y1={svgY} x2={chartWidth} y2={svgY} stroke="#1A1A1A" strokeWidth="0.5" strokeDasharray="2,2" />

                    <rect x={chartWidth} y={svgY - 8} width={paddingRight} height={16} fill="#7A7A7A" />
                    <text x={chartWidth + 5} y={svgY + 4} className="text-[9px] font-black fill-white">
                      {getPriceAtY(svgY).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                    </text>
                  </>
                );
              })()}
            </g>
          )}
        </svg>

        <div className="absolute bottom-4 left-4 flex gap-4 pointer-events-none">
          <div className="bg-white/90 px-3 py-1 sketch-border text-[8px] font-black uppercase flex gap-4">
            <span className="flex items-center gap-1"><kbd className="bg-gray-100 px-1 border">Alt</kbd>+Scroll para Zoom</span>
            <span className="flex items-center gap-1">Drag para Mover</span>
            <span className="text-blue-600 font-black">{selectedAsset} • {timeframe} • {visibleCandles.length} VELAS</span>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full bg-[#F2EFEA] overflow-hidden">
      <div className="bg-[#1A1A1A] h-8 flex items-center overflow-hidden border-b-2 border-[#1A1A1A] relative shrink-0">
        <div className="flex animate-[ticker_40s_linear_infinite] whitespace-nowrap gap-12 px-4 items-center">
          {(stocks.length > 0 ? stocks.concat(stocks) : []).map((stock, i) => (
            <div key={i} className="flex items-center gap-2 text-[9px] font-black uppercase text-white">
              <span>{stock.symbol}</span>
              <span className="text-gray-400">{stock.price}</span>
              <span className={stock.isPositive ? 'text-emerald-400' : 'text-rose-400'}>{stock.change}</span>
            </div>
          ))}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 md:p-8 space-y-8 custom-scrollbar">
        <header className="flex flex-col md:flex-row md:justify-between md:items-end gap-4 border-b-2 border-[#1A1A1A] pb-6">
          <div>
            <h1 className="text-3xl md:text-5xl font-black text-[#1A1A1A] uppercase tracking-tighter leading-none">TERMINAL DE OPERAÇÕES</h1>
            <p className="text-[9px] font-black uppercase text-emerald-600 mt-2 tracking-[0.2em]">● Feed Real-Time (Sincronizado {lastUpdate})</p>
          </div>
          <div className="flex gap-2">
            <select 
              value={selectedAsset} 
              onChange={(e) => setSelectedAsset(e.target.value)} 
              className="bg-white border-2 border-[#1A1A1A] px-3 py-2 font-black text-[10px] uppercase outline-none focus:bg-[#F2EFEA]"
            >
              {stocks.length > 0 ? stocks.map(s => <option key={s.symbol} value={s.symbol}>{s.symbol}</option>) : <option>Carregando...</option>}
            </select>
            <select 
              value={timeframe} 
              onChange={(e) => setTimeframe(e.target.value)} 
              className="bg-white border-2 border-[#1A1A1A] px-3 py-2 font-black text-[10px] uppercase outline-none focus:bg-[#F2EFEA]"
            >
              <option value="15m">15M</option>
              <option value="1h">1H</option>
              <option value="4h">4H</option>
              <option value="1d">1D</option>
            </select>
          </div>
        </header>

        <section className="bg-white sketch-border overflow-hidden">
          <div className="p-4 border-b-2 border-[#1A1A1A] flex justify-between items-center bg-[#F2EFEA]">
            <h2 className="text-[10px] font-black uppercase tracking-widest">{selectedAsset}/BRL Analysis</h2>
            <div className="flex gap-4">
              <span className="text-[8px] font-bold text-emerald-600 uppercase animate-pulse">● Live Data</span>
            </div>
          </div>
          {renderCandleChart()}
        </section>

        <section className="space-y-4">
          <div className="flex items-center justify-between border-b-2 border-[#1A1A1A] pb-2">
            <h3 className="text-xs font-black uppercase tracking-widest bg-[#1A1A1A] text-white px-3 py-1 italic">News Terminal (Hybrid Feed)</h3>
            {loadingNews && <div className="w-4 h-4 border-2 border-[#1A1A1A] border-t-transparent rounded-full animate-spin"></div>}
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {loadingNews ? (
              Array(2).fill(0).map((_, i) => (
                <div key={i} className="bg-white sketch-border p-6 animate-pulse h-32">
                  <div className="h-4 bg-gray-200 w-3/4 mb-4"></div>
                  <div className="h-2 bg-gray-100 w-full"></div>
                </div>
              ))
            ) : (
              news.map((article, i) => (
                <a 
                  key={i} 
                  href={article.url} 
                  target="_blank" 
                  rel="noopener noreferrer" 
                  className="bg-white sketch-border p-5 hover:translate-x-1 hover:-translate-y-1 transition-all group block relative overflow-hidden"
                >
                  <div className="flex justify-between items-start mb-3">
                    <div className="flex gap-2 items-center">
                      <span className="text-[7px] font-black uppercase bg-[#1A1A1A] text-white px-2 py-0.5">{article.source}</span>
                      <span className={`text-[7px] font-black uppercase px-2 py-0.5 border ${getSentimentColor(article.sentiment)}`}>
                        {article.sentiment || 'NEUTRAL'}
                      </span>
                    </div>
                    <span className="text-[7px] font-bold text-[#7A7A7A] uppercase">{article.time}</span>
                  </div>
                  <h4 className="text-[11px] font-black uppercase tracking-tight mb-2 group-hover:underline leading-snug">{article.title}</h4>
                  <p className="text-[9px] text-[#4A4A4A] line-clamp-2 leading-relaxed font-medium">{article.summary}</p>
                </a>
              ))
            )}
          </div>
        </section>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pb-12">
          <section className="bg-white sketch-border p-6">
            <h3 className="text-xs font-black uppercase tracking-widest mb-6 border-b-2 border-[#1A1A1A] pb-2">Métricas Auditoria GA4</h3>
            {analyticsData ? (
              <div className="space-y-6">
                <div className="grid grid-cols-2 gap-4">
                  <div className="p-4 bg-[#F2EFEA] sketch-border shadow-none">
                    <p className="text-[8px] font-black text-[#7A7A7A] uppercase mb-1">Users Ativos</p>
                    <p className="text-xl font-black">{analyticsData.activeUsers.toLocaleString()}</p>
                    <span className="text-[7px] font-black text-emerald-500">
                      ↑ {(((analyticsData.activeUsers / (analyticsData.previousActiveUsers || 1)) - 1) * 100).toFixed(1)}% CRESCIMENTO
                    </span>
                  </div>
                  <div className="p-4 bg-[#F2EFEA] sketch-border shadow-none">
                    <p className="text-[8px] font-black text-[#7A7A7A] uppercase mb-1">Taxa Conversão</p>
                    <p className="text-xl font-black">{analyticsData.conversionRate.toFixed(2)}%</p>
                  </div>
                </div>
              </div>
            ) : (
              <div className="h-40 flex flex-col items-center justify-center bg-[#F2EFEA] sketch-border opacity-50">
                <p className="text-[8px] font-black uppercase tracking-widest">Nenhum dado GA4 vinculado</p>
              </div>
            )}
          </section>

          <section className="bg-[#1A1A1A] text-white sketch-border p-6">
            <h3 className="text-xs font-black uppercase tracking-widest mb-6 border-b border-white/20 pb-2">Compliance Assistant</h3>
            <div className="space-y-4">
              <div className="flex items-start gap-4 p-3 bg-white/5 border border-white/10">
                <div className="w-5 h-5 bg-emerald-500 rounded-full flex items-center justify-center text-[10px] font-bold text-[#1A1A1A]">✓</div>
                <div>
                  <p className="text-[9px] font-black uppercase tracking-tight">IFRS 16 - LEASES</p>
                  <p className="text-[8px] text-gray-400 mt-1">Verificação de passivos de arrendamento ativa na base de dados.</p>
                </div>
              </div>
              <div className="flex items-start gap-4 p-3 bg-white/5 border border-white/10">
                <div className="w-5 h-5 bg-amber-500 rounded-full flex items-center justify-center text-[10px] font-bold text-[#1A1A1A]">!</div>
                <div>
                  <p className="text-[9px] font-black uppercase tracking-tight">CPC 01 - REDUÇÃO AO VALOR RECUPERÁVEL</p>
                  <p className="text-[8px] text-gray-400 mt-1">Atenção: Teste de impairment necessário para ativos do grupo VALE3.</p>
                </div>
              </div>
            </div>
          </section>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { ChatSession } from '../types';
import { StorageService } from '../services/storage';

const TrashBin: React.FC = () => {
  const [deletedSessions, setDeletedSessions] = useState<ChatSession[]>([]);

  useEffect(() => {
    // Filtrando apenas os que possuem data de exclusão
    const allSessions = StorageService.getChatSessions(true);
    setDeletedSessions(allSessions.filter(s => !!s.deletedAt));
  }, []);

  const handlePermanentDelete = (id: string) => {
    if (window.confirm("Tem certeza que deseja excluir permanentemente este chat? Esta ação não pode ser desfeita.")) {
      StorageService.deletePermanently(id);
      setDeletedSessions(prev => prev.filter(s => s.id !== id));
    }
  };

  const getDaysLeft = (deletedAt?: Date) => {
    if (!deletedAt) return 0;
    const now = new Date();
    const diffTime = Math.abs(now.getTime() - deletedAt.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return Math.max(0, 30 - diffDays);
  };

  return (
    <div className="p-10 max-w-6xl mx-auto">
      <header className="mb-12 border-b-2 border-[#1A1A1A] pb-8">
        <h1 className="text-3xl font-bold text-[#1A1A1A] uppercase tracking-tighter">LIXEIRA DE CHATS</h1>
        <p className="text-[#7A7A7A] mt-2 font-bold text-xs uppercase tracking-widest">Conversas Excluídas • Expiração em 30 Dias</p>
      </header>

      {deletedSessions.length === 0 ? (
        <div className="bg-white sketch-border p-20 text-center">
          <svg className="w-16 h-16 mx-auto mb-6 text-[#B5B5B5]" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
          </svg>
          <h3 className="text-xl font-bold uppercase mb-2">Lixeira Vazia</h3>
          <p className="text-[#7A7A7A] text-[10px] font-bold uppercase tracking-widest">Nenhuma conversa deletada recentemente.</p>
        </div>
      ) : (
        <div className="space-y-6">
          <div className="flex items-center gap-4 p-4 bg-[#F2EFEA] border-2 border-[#1A1A1A] mb-8">
            <div className="w-8 h-8 bg-[#1A1A1A] text-white flex items-center justify-center font-bold">i</div>
            <p className="text-[10px] font-bold uppercase tracking-widest leading-relaxed">
              Mensagens nesta área serão excluídas permanentemente após 30 dias. A restauração não está disponível neste terminal.
            </p>
          </div>

          <div className="grid grid-cols-1 gap-4">
            {deletedSessions.map((session) => {
              const daysLeft = getDaysLeft(session.deletedAt);
              return (
                <div key={session.id} className="bg-white p-6 sketch-border flex flex-col md:flex-row items-start md:items-center justify-between hover:bg-[#F2EFEA] transition-colors group gap-6">
                  <div className="flex items-center gap-6">
                    <div className="w-12 h-12 bg-[#B5B5B5] text-[#1A1A1A] flex items-center justify-center font-bold text-xs sketch-border shadow-none">
                      {session.messages.length}
                    </div>
                    <div>
                      <h4 className="font-bold text-[#1A1A1A] text-sm uppercase tracking-tight truncate max-w-[300px]">
                        {session.title}
                      </h4>
