import { GoogleGenAI, Type } from "@google/genai";
import { StorageService } from "./storage.ts";
import { NewsArticle } from "../types.ts";

const FINNHUB_KEY = 'd5m1jn9r01qidp4jcfqgd5m1jn9r01qidp4jcfr0';

export const GeminiService = {
  generateChatResponseStream: async (prompt: string, history: any[], onChunk: (text: string) => void) => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const docs = StorageService.getDocuments();
    const context = docs.length > 0 
      ? `BASE DE DADOS REAL DO USUÁRIO (AUDITORIA ATIVA):\n${docs.map(d => `[ID: ${d.id}] [FONTE: ${d.sourceType.toUpperCase()}] [CATEGORIA: ${d.metadata?.category || 'GERAL'}] [NOME: ${d.name}]\nCONTEÚDO REAL: ${d.content}`).join('\n\n')}`
      : "NENHUM DADO REAL FORNECIDO. O usuário ainda não conectou documentos ou APIs contábeis. Não invente dados.";

    const systemInstruction = `
      Você é o "FinaIGPT", um Auditor de Elite e Analista Contábil Sênior.

      PROTOCOLO DE RESPOSTA ESTRITO:
      1. SOBERANIA DOS DADOS REAIS: Você deve analisar e estruturar EXCLUSIVAMENTE os dados reais fornecidos pelo usuário no contexto abaixo.
      2. PROIBIÇÃO DE INVENÇÃO: Se a informação solicitada não constar nos documentos ou APIs conectadas, responda: "Informação não localizada na base de dados real fornecida."
      3. ESTRUTURAÇÃO DE DADOS: Transforme dados brutos em tabelas Markdown e listas estruturadas.
      4. RIGOR TÉCNICO: Cálculos financeiros devem seguir estritamente as normas CPC/IFRS aplicadas sobre os números REAIS.

      CONTEXTO DE DADOS REAIS:
      ${context}
    `;

    const formattedHistory = history
      .filter(msg => msg.id !== 'welcome' && msg.id !== 'reset') 
      .map(msg => ({
        role: msg.role === 'user' ? 'user' : 'model',
        parts: [{ text: msg.content }]
      }))
      .slice(-10);

    try {
      const result = await ai.models.generateContentStream({
        model: 'gemini-3-pro-preview',
        contents: formattedHistory,
        config: {
          systemInstruction,
          tools: [{ googleSearch: {} }],
          thinkingConfig: { thinkingBudget: 15000 },
          temperature: 0.1, // Baixa temperatura para maior precisão nos dados
        },
      });

      let fullText = "";
      for await (const chunk of result) {
        const chunkText = chunk.text;
        if (chunkText) {
          fullText += chunkText;
          onChunk(fullText);
        }
      }
      return fullText;
    } catch (error) {
      console.error("Gemini Stream Error:", error);
      throw error;
    }
  },

  generateChatResponse: async (prompt: string, history: any[]) => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const result = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: history.map(m => ({ role: m.role === 'user' ? 'user' : 'model', parts: [{ text: m.content }] })),
      config: { temperature: 0.1 }
    });
    return { text: result.text };
  },

  fetchLatestNews: async (): Promise<NewsArticle[]> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const finnhubRes = await fetch(`https://finnhub.io/api/v1/news?category=general&token=${FINNHUB_KEY}`);
      const finnhubData = finnhubRes.ok ? await finnhubRes.json() : [];
      const finnhubSnippet = JSON.stringify(finnhubData.slice(0, 5));

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Analise as notícias e retorne um JSON de 6 itens: ${finnhubSnippet}`,
        config: {
          tools: [{ googleSearch: {} }],
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                title: { type: Type.STRING },
                summary: { type: Type.STRING },
                url: { type: Type.STRING },
                source: { type: Type.STRING },
                time: { type: Type.STRING },
                sentiment: { type: Type.STRING, enum: ["BULLISH", "BEARISH", "NEUTRAL"] }
              },
              required: ["title", "summary", "url", "source", "time", "sentiment"]
            }
          }
        }
      });
      return JSON.parse(response.text || "[]");
    } catch (e) {
      return [];
    }
  },

  generateTitle: async (firstPrompt: string): Promise<string> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Título curto para: "${firstPrompt}"`,
        config: { maxOutputTokens: 20 }
      });
      return response.text?.replace(/["']/g, '').trim() || "Nova Consulta";
    } catch (e) {
      return "Nova Consulta";
    }
  }
};

