import React, { useState, useRef, useEffect } from 'react';
import { GeminiService } from '../services/geminiService.ts';
import { Message } from '../types.ts';

const FloatingAssistant: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<Message[]>([
    {
      id: 'welcome',
      role: 'model',
      content: 'Olá! Sou seu assistente de auditoria rápida. Como posso ajudar com seus dados contábeis agora?',
      timestamp: new Date()
    }
  ]);
  const [isLoading, setIsLoading] = useState(false);
  const [streamingText, setStreamingText] = useState('');
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, streamingText]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);
    setStreamingText('');

    try {
      const response = await GeminiService.generateChatResponseStream(
        input,
        [...messages, userMsg],
        (chunk) => setStreamingText(chunk)
      );

      const modelMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: response,
        timestamp: new Date()
      };

      setMessages(prev => [...prev, modelMsg]);
    } catch (error) {
      console.error("Assistant Error:", error);
    } finally {
      setIsLoading(false);
      setStreamingText('');
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-[100] flex flex-col items-end">
      {/* Chat Window */}
      {isOpen && (
        <div className="mb-4 w-[320px] md:w-[400px] h-[500px] bg-white sketch-border flex flex-col overflow-hidden animate-in slide-in-from-bottom-10 fade-in duration-300">
          <header className="p-4 bg-[#1A1A1A] text-white flex justify-between items-center shrink-0">
            <div className="flex items-center gap-2">
              <div className="w-6 h-6 bg-white text-[#1A1A1A] flex items-center justify-center font-black text-[10px] sketch-border shadow-none">F</div>
              <span className="text-[10px] font-black uppercase tracking-widest">Suporte IA Rápido</span>
            </div>
            <button onClick={() => setIsOpen(false)} className="hover:scale-110 transition-transform">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </header>

          <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar bg-[#F2EFEA]/30">
            {messages.map((msg) => (
              <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`
                  max-w-[85%] p-3 text-[11px] font-bold sketch-border leading-relaxed
                  ${msg.role === 'user' ? 'bg-[#1A1A1A] text-white' : 'bg-white text-[#1A1A1A]'}
                `}>
                  {msg.content}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <div className="max-w-[85%] p-3 bg-white text-[#1A1A1A] sketch-border animate-pulse">
                  <div className="flex items-center gap-2 mb-1">
                    <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-ping" />
                    <span className="text-[8px] font-black uppercase">Analisando...</span>
                  </div>
                  <div className="text-[11px] font-bold opacity-70">
                    {streamingText || "Verificando conformidade fiscal..."}
                  </div>
                </div>
              </div>
            )}
          </div>

          <div className="p-4 bg-white border-t-2 border-[#1A1A1A]">
            <div className="relative">
              <input
                type="text"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder="Dúvida rápida..."
                className="w-full bg-[#F2EFEA] sketch-border p-3 pr-12 text-[10px] font-black uppercase outline-none focus:bg-white transition-colors"
              />
              <button 
                onClick={handleSend}
                disabled={isLoading || !input.trim()}
                className={`absolute right-3 top-1/2 -translate-y-1/2 ${isLoading || !input.trim() ? 'text-gray-300' : 'text-[#1A1A1A] hover:scale-110'}`}
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
                </svg>
              </button>
            </div>
          </div>
        </div>
      )}

      {/* FAB Button */}
      <button
        onClick={() => setIsOpen(!isOpen)}
        className={`
          w-16 h-16 rounded-full bg-[#1A1A1A] text-white flex items-center justify-center sketch-border shadow-2xl transition-all active:scale-90
          ${isOpen ? 'rotate-90' : 'hover:scale-110 hover:-rotate-12'}
        `}
      >
        {isOpen ? (
          <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
          </svg>
        ) : (
          <div className="flex flex-col items-center">
            <span className="text-xl font-black leading-none">F</span>
            <span className="text-[7px] font-black uppercase mt-1">GPT</span>
          </div>
        )}
      </button>
    </div>
  );
};

