  const [isDrivePickerOpen, setIsDrivePickerOpen] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const driveFiles = [
    { id: '1', name: 'Relatório Trimestral Q1.gdoc', type: 'google_docs', content: 'Auditoria de despesas Q1: Crescimento de 15% em marketing. Margem operacional estável em 22%.' },
    { id: '2', name: 'Fluxo de Caixa 2024.gsheet', type: 'google_sheets', content: 'Saldo inicial: R$ 1.2M. Entradas: R$ 450k. Saídas: R$ 380k. Saldo final: R$ 1.27M.' },
