  ];

  useEffect(() => {
    const loadedSessions = StorageService.getChatSessions();
    setSessions(loadedSessions);
    if (loadedSessions.length > 0 && !currentSessionId) {
      setCurrentSessionId(loadedSessions[0].id);
    }
  }, []);

  useEffect(() => {
    const handleSync = () => setSessions(StorageService.getChatSessions());
    window.addEventListener('session_synced', handleSync);
    return () => window.removeEventListener('session_synced', handleSync);
  }, []);

  const currentSession = useMemo(() => sessions.find(s => s.id === currentSessionId), [sessions, currentSessionId]);

  const scrollToBottom = useCallback((force = false) => {
    if (scrollRef.current) {
      const { scrollHeight, scrollTop, clientHeight } = scrollRef.current;
      const isNearBottom = scrollHeight - scrollTop - clientHeight < 250;
      if (force || isNearBottom) {
        scrollRef.current.scrollTo({
          top: scrollHeight,
          behavior: force ? 'auto' : 'smooth'
        });
      }
    }
  }, []);

  useEffect(() => {
    scrollToBottom();
  }, [currentSession?.messages, streamingText, isLoading, scrollToBottom]);

  useEffect(() => {
    if (currentSessionId) {
      setTimeout(() => scrollToBottom(true), 100);
    }
  }, [currentSessionId, scrollToBottom]);

