import React, { useState, useEffect, useRef } from 'react';
import { Document, DocumentSource } from '../types.ts';
import { StorageService } from '../services/storage.ts';
import { MarketService } from '../services/marketService.ts';

// Bibliotecas declaradas no index.html
declare const pdfjsLib: any;
declare const mammoth: any;
declare const XLSX: any;

const DocumentManager: React.FC = () => {
  const [documents, setDocuments] = useState<Document[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [parsingStatus, setParsingStatus] = useState<string>('');
  const [externalUrl, setExternalUrl] = useState('');
  const [selectedProvider, setSelectedProvider] = useState<DocumentSource>('google_docs');
  const [selectedCategory, setSelectedCategory] = useState<'cost' | 'tax' | 'management' | 'general' | 'exercise'>('general');
  const [isDrivePickerOpen, setIsDrivePickerOpen] = useState(false);
  const [isGoogleConnected, setIsGoogleConnected] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const driveFiles = [
    { id: '1', name: 'Contrato Social - Consolidado 2024.gdoc', type: 'google_docs', size: 15400 },
    { id: '2', name: 'Planilha de Provisões Tributárias.gsheet', type: 'google_sheets', size: 89000 },
    { id: '3', name: 'Auditoria Externa - KPMG.pdf', type: 'google_drive', size: 4500000 },
    { id: '4', name: 'Fluxo de Caixa Operacional Q4.gsheet', type: 'google_sheets', size: 67000 },
  ];

  useEffect(() => {
    setDocuments(StorageService.getDocuments());
    if (typeof pdfjsLib !== 'undefined') {
      pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
    }
  }, []);

  const processFile = async (file: File) => {
    setIsUploading(true);
    setParsingStatus(`Lendo ${file.name}...`);

    try {
      let content = "";
      const extension = file.name.split('.').pop()?.toLowerCase();

      if (extension === 'pdf') {
        setParsingStatus('Extraindo texto de PDF (OCR Nativo)...');
        const arrayBuffer = await file.arrayBuffer();
        const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
        for (let i = 1; i <= pdf.numPages; i++) {
          const page = await pdf.getPage(i);
          const textContent = await page.getTextContent();
          content += textContent.items.map((it: any) => it.str).join(" ") + "\n";
        }
      } 
      else if (['xlsx', 'xls', 'csv'].includes(extension || '')) {
        setParsingStatus('Convertendo Planilha para Formato Auditor...');
        const arrayBuffer = await file.arrayBuffer();
        const workbook = XLSX.read(arrayBuffer);
        const firstSheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[firstSheetName];
        content = XLSX.utils.sheet_to_csv(worksheet);
      } 
      else if (extension === 'docx') {
        setParsingStatus('Processando Documento Word...');
        const arrayBuffer = await file.arrayBuffer();
        const result = await mammoth.extractRawText({ arrayBuffer });
        content = result.value;
      } 
      else {
        content = await file.text();
      }

      const doc: Document = {
        id: Math.random().toString(36).substr(2, 9),
        name: file.name,
        content: content || "Sem conteúdo legível.",
        type: file.type || 'text/plain',
        uploadDate: new Date(),
        size: file.size,
        sourceType: 'local',
        metadata: { category: selectedCategory }
      };

      StorageService.saveDocument(doc);
      setDocuments(prev => [doc, ...prev]);
      setParsingStatus('Indexação Concluída!');
    } catch (error) {
      console.error(error);
      alert("Falha ao processar arquivo técnico.");
    } finally {
      setTimeout(() => {
        setIsUploading(false);
        setParsingStatus('');
      }, 1000);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files) {
      Array.from(files).forEach(processFile);
    }
  };

  const handleConnectGoogle = () => {
    setIsUploading(true);
    setParsingStatus('Autenticando com Google Cloud...');
    setTimeout(() => {
      setIsGoogleConnected(true);
      setIsUploading(false);
      setParsingStatus('');
      setIsDrivePickerOpen(true);
    }, 1500);
  };

  const importFromDrive = (file: typeof driveFiles[0]) => {
    setIsUploading(true);
    setParsingStatus(`Importando e Indexando ${file.name}...`);
    setTimeout(() => {
      const doc: Document = {
        id: Math.random().toString(36).substr(2, 9),
        name: file.name,
        content: `[DATA_SOURCE: GOOGLE_DRIVE] [FILE_ID: ${file.id}]\nCONTEÚDO SINCRONIZADO VIA CLOUD.\nEste documento contém metadados de conformidade fiscal e foi extraído para análise RAG.\nDocumento: ${file.name}`,
        type: file.type.includes('sheet') ? 'application/vnd.google-apps.spreadsheet' : 'application/vnd.google-apps.document',
        uploadDate: new Date(),
        size: file.size,
        sourceType: 'google_drive',
        metadata: { category: selectedCategory, lastSync: new Date() }
      };
      StorageService.saveDocument(doc);
      setDocuments(prev => [doc, ...prev]);
      setIsUploading(false);
      setParsingStatus('');
      setIsDrivePickerOpen(false);
    }, 1200);
  };

  const handleAddExternal = async () => {
    if (!externalUrl) return;
    setIsUploading(true);
    setParsingStatus('Vínculo de API Ativo...');
    try {
      let content = `[DATA_SOURCE: ${selectedProvider.toUpperCase()}]\nURL: ${externalUrl}\nLink dinâmico indexado.`;
      if (selectedProvider === 'google_analytics') {
        const metrics = await MarketService.fetchMockAnalytics(externalUrl);
        content = JSON.stringify(metrics);
      }
      const doc: Document = {
        id: Math.random().toString(36).substr(2, 9),
        name: `${selectedProvider.split('_')[1]?.toUpperCase()}: ${externalUrl.split('/').pop()?.substring(0, 10)}`,
        content: content,
        type: 'external/link',
        uploadDate: new Date(),
        size: 0,
        sourceType: selectedProvider,
        externalUrl: externalUrl,
        metadata: { category: selectedCategory, lastSync: new Date() }
      };
      StorageService.saveDocument(doc);
      setDocuments(prev => [doc, ...prev]);
      setExternalUrl('');
      setIsUploading(false);
      setParsingStatus('');
    } catch (e) {
      setIsUploading(false);
    }
  };

  const deleteDoc = (id: string) => {
    if (window.confirm("Remover da base fiscal?")) {
      StorageService.deleteDocument(id);
      setDocuments(prev => prev.filter(d => d.id !== id));
    }
  };

  return (
    <div className="p-4 md:p-10 max-w-6xl mx-auto h-full overflow-y-auto custom-scrollbar bg-[#F2EFEA]">
      <header className="mb-8 border-b-2 border-[#1A1A1A] pb-6 flex flex-col md:flex-row md:justify-between md:items-end gap-4">
        <div>
          <h1 className="text-3xl font-black text-[#1A1A1A] uppercase tracking-tighter">GESTÃO DE DOCUMENTOS</h1>
          <p className="text-[#7A7A7A] mt-1 font-bold text-[10px] uppercase tracking-widest italic">Protocolo de Inteligência RAG & Google Cloud</p>
        </div>
        <div className="flex gap-2">
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="sketch-button px-6 py-2 text-[10px] font-black uppercase tracking-widest bg-[#1A1A1A] text-white"
          >
            Upload Local
          </button>
          <button 
            onClick={handleConnectGoogle}
            className="sketch-button px-6 py-2 text-[10px] font-black uppercase tracking-widest bg-[#4285F4] text-white flex items-center gap-2"
          >
            Google Drive
          </button>
          <input 
            type="file" 
            ref={fileInputRef} 
            className="hidden" 
            multiple 
            accept=".pdf,.docx,.xlsx,.xls,.csv,.txt"
            onChange={handleFileUpload} 
          />
        </div>
      </header>

      <section className="bg-white sketch-border p-6 mb-8">
        <div className="flex items-center justify-between mb-4 border-b border-gray-100 pb-2">
          <h3 className="text-[10px] font-black uppercase tracking-widest">Conexões de Serviços</h3>
          {isGoogleConnected && <span className="text-[7px] font-black uppercase text-emerald-600">Autenticado</span>}
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="space-y-4">
            <div className="flex gap-2">
              <select 
                value={selectedProvider} 
                onChange={(e) => setSelectedProvider(e.target.value as DocumentSource)}
                className="flex-1 bg-white border-2 border-[#1A1A1A] p-3 text-[10px] font-black uppercase outline-none"
              >
                <option value="google_docs">Google Docs</option>
                <option value="google_sheets">Google Sheets</option>
                <option value="google_analytics">Google Analytics</option>
              </select>
              <select 
                value={selectedCategory} 
                onChange={(e) => setSelectedCategory(e.target.value as any)}
                className="flex-1 bg-white border-2 border-[#1A1A1A] p-3 text-[10px] font-black uppercase outline-none"
              >
                <option value="general">Geral</option>
                <option value="tax">Fiscal/Tributário</option>
                <option value="management">Gestão/KPIs</option>
              </select>
            </div>
            <div className="flex gap-2">
              <input 
                type="text" 
                placeholder="URL do Recurso..."
                value={externalUrl}
                onChange={(e) => setExternalUrl(e.target.value)}
                className="flex-1 border-2 border-[#1A1A1A] p-3 text-[10px] font-black uppercase outline-none"
              />
              <button 
                onClick={handleAddExternal}
                disabled={isUploading}
                className="bg-[#1A1A1A] text-white px-6 py-3 text-[10px] font-black uppercase disabled:opacity-50"
              >
                Vincular
              </button>
            </div>
          </div>
        </div>
      </section>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {documents.map((doc) => (
          <div key={doc.id} className="bg-white sketch-border p-6 relative group hover:bg-emerald-50 transition-colors">
            <div className="flex items-start justify-between mb-4">
              <div className="w-10 h-10 bg-[#1A1A1A] text-white flex items-center justify-center font-black text-[10px]">
                {doc.sourceType.substring(0, 2).toUpperCase()}
              </div>
              <button 
                onClick={() => deleteDoc(doc.id)}
                className="text-rose-500 opacity-0 group-hover:opacity-100 transition-opacity"
              >
                Excluir
              </button>
            </div>
            <h4 className="text-[10px] font-black uppercase truncate mb-2">{doc.name}</h4>
            <div className="flex justify-between items-end">
              <p className="text-[8px] font-bold text-[#7A7A7A] uppercase">
                {new Date(doc.uploadDate).toLocaleDateString()} • {(doc.size / 1024).toFixed(1)}KB
              </p>
              <span className="text-[7px] font-black bg-emerald-100 text-emerald-700 px-2 py-0.5">INDEXADO RAG</span>
            </div>
          </div>
        ))}
      </div>

      {isDrivePickerOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/60 backdrop-blur-sm shadow-inner" onClick={() => setIsDrivePickerOpen(false)}></div>
          <div className="relative bg-white sketch-border w-full max-w-xl max-h-[80vh] overflow-hidden flex flex-col">
            <div className="p-6 border-b-2 border-[#1A1A1A] flex justify-between items-center bg-[#F2EFEA]">
              <h3 className="text-xs font-black uppercase">Google Cloud Drive</h3>
              <button onClick={() => setIsDrivePickerOpen(false)} className="text-xs font-black uppercase">Fechar</button>
            </div>
            <div className="flex-1 overflow-y-auto p-4 space-y-2">
              {driveFiles.map(file => (
                <button 
                  key={file.id} 
                  onClick={() => importFromDrive(file)}
                  className="w-full text-left p-4 hover:bg-[#F2EFEA] border-2 border-transparent hover:border-[#1A1A1A] flex items-center justify-between group transition-all"
                >
                  <div>
                    <p className="text-[10px] font-black uppercase">{file.name}</p>
                    <p className="text-[8px] font-bold text-[#7A7A7A] uppercase">{file.type} • Cloud Sync</p>
                  </div>
                  <span className="text-[8px] font-black uppercase text-blue-600 opacity-0 group-hover:opacity-100">Indexar</span>
                </button>
              ))}
            </div>
          </div>
        </div>
      )}

      {isUploading && (
        <div className="fixed bottom-10 right-10 bg-[#1A1A1A] text-white p-6 sketch-border shadow-2xl z-[110] flex items-center gap-4 animate-in slide-in-from-right-10">
          <div className="w-5 h-5 border-2 border-white border-t-emerald-500 rounded-full animate-spin"></div>
          <p className="text-[10px] font-black uppercase tracking-widest">{parsingStatus}</p>
        </div>
      )}
    </div>
  );
};

