  const [timeframe, setTimeframe] = useState('1h');

  // UI Interaction States
  const [hoveredCandle, setHoveredCandle] = useState<Candle | null>(null);
  const [mousePos, setMousePos] = useState({ x: -1, y: -1 });
  const [loadingMarket, setLoadingMarket] = useState(true);
  const [loadingNews, setLoadingNews] = useState(true);
  const [analyticsData, setAnalyticsData] = useState<AnalyticsMetrics | null>(null);
  const [lastUpdate, setLastUpdate] = useState<string>(new Date().toLocaleTimeString());

  // Market Intel State
  const [intelQuery, setIntelQuery] = useState('');
  const [intelResult, setIntelResult] = useState<{text: string, sources: any[]} | null>(null);
  const [isIntelLoading, setIsIntelLoading] = useState(false);

  // Chart Navigation State
  const [visibleCount, setVisibleCount] = useState(50);
  const [scrollOffset, setScrollOffset] = useState(0);
  const [isPanning, setIsPanning] = useState(false);
  const [startX, setStartX] = useState(0);
  const chartRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Load Analytics from RAG if available
    const docs = StorageService.getDocuments();
    const gaDoc = docs.find(d => d.sourceType === 'google_analytics');
    if (gaDoc) {
      try {
        const metrics = JSON.parse(gaDoc.content);
        if (metrics.activeUsers) setAnalyticsData(metrics);
      } catch (e) { console.error("GA Parse Error"); }
    }

    const loadMarketData = async () => {
      setLoadingMarket(true);
      try {
        const rateData = await MarketService.fetchExchangeRates();
        const [stockData, candleData] = await Promise.all([
          MarketService.fetchStockData(rateData),
          MarketService.fetchHistoricalCandles(selectedAsset, timeframe)
        ]);
        setRates(rateData);
        setStocks(stockData);
        setCandles(candleData);
        setLastUpdate(new Date().toLocaleTimeString());
      } catch (e) {
        console.error("Market Update Error", e);
      } finally {
        setLoadingMarket(false);
      }
    };

    const loadNews = async () => {
      setLoadingNews(true);
      try {
        const latestNews = await GeminiService.fetchLatestNews();
        setNews(latestNews);
      } catch (e) { console.error("News Error", e); }
      finally { setLoadingNews(false); }
    };

    loadMarketData();
    loadNews();

    const mInterval = setInterval(loadMarketData, 60000); 
    const nInterval = setInterval(loadNews, 300000); 

    return () => { clearInterval(mInterval); clearInterval(nInterval); };
  }, [selectedAsset, timeframe]);

  useLayoutEffect(() => {
    const el = chartRef.current;
    if (!el) return;

    const handleWheel = (e: WheelEvent) => {
      if (e.ctrlKey || e.metaKey || e.altKey) {
        e.preventDefault();
        const zoomSpeed = 2;
        const delta = e.deltaY > 0 ? zoomSpeed : -zoomSpeed;
        setVisibleCount(prev => Math.min(Math.max(10, prev + delta), (candles.length || 100)));
      }
    };

    el.addEventListener('wheel', handleWheel, { passive: false });
    return () => el.removeEventListener('wheel', handleWheel);
  }, [candles.length, visibleCount]);

  const visibleCandles = useMemo(() => {
    if (candles.length === 0) return [];
    const maxOffset = Math.max(0, candles.length - visibleCount);
    const safeOffset = Math.min(scrollOffset, maxOffset);
    const end = candles.length - safeOffset;
    const start = Math.max(0, end - visibleCount);
    return candles.slice(start, end);
  }, [candles, visibleCount, scrollOffset]);

  const chartMetrics = useMemo(() => {
    if (visibleCandles.length === 0) return null;
    const lows = visibleCandles.map(c => c.low);
    const highs = visibleCandles.map(c => c.high);
    const minLow = Math.min(...lows);
    const maxHigh = Math.max(...highs);
    const range = Math.max(0.00001, maxHigh - minLow);
    return { minLow, maxHigh, range };
  }, [visibleCandles]);

  const handleMouseDown = (e: React.MouseEvent) => {
    setIsPanning(true);
    setStartX(e.clientX);
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    const rect = chartRef.current?.getBoundingClientRect();
    if (rect) {
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      setMousePos({ x, y });

      if (chartMetrics && visibleCandles.length > 0) {
        const width = rect.width;
        const candleSpace = width / visibleCandles.length;
        const index = Math.floor(x / candleSpace);
        if (index >= 0 && index < visibleCandles.length) {
          setHoveredCandle(visibleCandles[index]);
        }
      }
    }

    if (!isPanning) return;
    const dx = e.clientX - startX;
    if (Math.abs(dx) > 5) {
      const sensitivity = Math.ceil(visibleCount / 50);
      const move = dx > 0 ? -sensitivity : sensitivity; 
      setScrollOffset(prev => Math.min(Math.max(0, prev + move), Math.max(0, (candles.length || 0) - visibleCount)));
      setStartX(e.clientX);
    }
  };

  const handleMouseUp = () => setIsPanning(false);

  const handleMarketResearch = async () => {
    if (!intelQuery.trim() || isIntelLoading) return;
    setIsIntelLoading(true);
    setIntelResult(null);
    try {
      const result = await GeminiService.getMarketIntelligence(intelQuery);
      setIntelResult(result);
    } catch (e) {
      console.error(e);
    } finally {
      setIsIntelLoading(false);
    }
  };

  const getSentimentColor = (sentiment?: string) => {
    switch(sentiment) {
      case 'BULLISH': return 'text-emerald-500 bg-emerald-500/10 border-emerald-500/20';
      case 'BEARISH': return 'text-rose-500 bg-rose-500/10 border-rose-500/20';
      default: return 'text-gray-500 bg-gray-500/10 border-gray-500/20';
    }
  };

  const renderCandleChart = () => {
    if (loadingMarket) {
      return (
        <div className="h-[400px] flex items-center justify-center bg-white sketch-border">
          <div className="flex flex-col items-center gap-4">
            <div className="w-10 h-10 border-4 border-[#1A1A1A] border-t-emerald-500 rounded-full animate-spin"></div>
            <p className="text-[10px] font-black uppercase tracking-widest">Carregando Fluxos...</p>
          </div>
        </div>
      );
    }

    if (!chartMetrics || visibleCandles.length === 0) return (
      <div className="h-[400px] flex items-center justify-center bg-white sketch-border">
        <p className="text-[10px] font-black uppercase opacity-40">Nenhum dado de gráfico disponível</p>
      </div>
    );

    const { minLow, maxHigh, range } = chartMetrics;
    const width = 1000;
    const height = 400;
    const candleSpace = width / visibleCandles.length;
    const candleWidth = candleSpace * 0.7;

    return (
      <div 
        ref={chartRef}
        className="relative h-[400px] bg-white sketch-border overflow-hidden cursor-crosshair select-none"
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={() => { handleMouseUp(); setMousePos({x:-1, y:-1}); setHoveredCandle(null); }}
      >
        <svg viewBox={`0 0 ${width} ${height}`} className="w-full h-full" preserveAspectRatio="none">
          {/* Grid Lines */}
          {[0, 0.25, 0.5, 0.75, 1].map(p => (
            <line 
              key={p} 
              x1="0" y1={p * height} x2={width} y2={p * height} 
              stroke="#F2EFEA" strokeWidth="1" 
            />
          ))}

          {/* Candles */}
          {visibleCandles.map((c, i) => {
            const x = i * candleSpace + (candleSpace - candleWidth) / 2;
            const yOpen = ((maxHigh - c.open) / range) * height;
            const yClose = ((maxHigh - c.close) / range) * height;
            const yHigh = ((maxHigh - c.high) / range) * height;
            const yLow = ((maxHigh - c.low) / range) * height;
            const isGreen = c.close >= c.open;

            return (
              <g key={i}>
                <line x1={x + candleWidth / 2} y1={yHigh} x2={x + candleWidth / 2} y2={yLow} stroke={isGreen ? '#10b981' : '#ef4444'} strokeWidth="1" />
                <rect 
                  x={x} 
                  y={Math.min(yOpen, yClose)} 
                  width={candleWidth} 
                  height={Math.max(1, Math.abs(yOpen - yClose))} 
                  fill={isGreen ? '#10b981' : '#ef4444'} 
                  opacity={hoveredCandle === c ? 1 : 0.8}
                />
              </g>
            );
          })}

          {/* Crosshair */}
          {mousePos.x !== -1 && (
            <g>
              <line x1={mousePos.x * (width / (chartRef.current?.clientWidth || width))} y1="0" x2={mousePos.x * (width / (chartRef.current?.clientWidth || width))} y2={height} stroke="#1A1A1A" strokeWidth="0.5" strokeDasharray="4" />
              <line x1="0" y1={mousePos.y * (height / (chartRef.current?.clientHeight || height))} x2={width} y2={mousePos.y * (height / (chartRef.current?.clientHeight || height))} stroke="#1A1A1A" strokeWidth="0.5" strokeDasharray="4" />
            </g>
          )}
        </svg>

        {/* Floating Tooltip */}
        {hoveredCandle && (
          <div className="absolute top-4 left-4 bg-[#1A1A1A] text-white p-3 text-[9px] font-black uppercase sketch-border z-20 pointer-events-none">
            <div className="grid grid-cols-2 gap-x-4 gap-y-1">
              <span className="opacity-50 text-emerald-400">Time:</span> <span>{hoveredCandle.time}</span>
              <span className="opacity-50">Open:</span> <span>{hoveredCandle.open.toFixed(2)}</span>
              <span className="opacity-50">High:</span> <span>{hoveredCandle.high.toFixed(2)}</span>
              <span className="opacity-50">Low:</span> <span>{hoveredCandle.low.toFixed(2)}</span>
              <span className="opacity-50">Close:</span> <span>{hoveredCandle.close.toFixed(2)}</span>
            </div>
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="p-4 md:p-10 max-w-7xl mx-auto h-full overflow-y-auto custom-scrollbar bg-[#F2EFEA]">
      <header className="mb-8 border-b-2 border-[#1A1A1A] pb-6 flex flex-col md:flex-row justify-between items-end gap-4">
        <div>
          <h1 className="text-3xl font-black text-[#1A1A1A] uppercase tracking-tighter">TERMINAL DE MERCADO</h1>
          <p className="text-[#7A7A7A] mt-1 font-bold text-[10px] uppercase tracking-widest italic">Análise de Ativos & Inteligência Preditiva</p>
        </div>
        <div className="flex gap-2 text-[8px] font-black uppercase">
          <span className="bg-white p-2 sketch-border">Sync: {lastUpdate}</span>
          <span className="bg-[#1A1A1A] text-white p-2 sketch-border">Terminal v2.5.0</span>
        </div>
      </header>

      {/* Ticker Row */}
      <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-7 gap-4 mb-8">
        {stocks.map((stock) => (
          <button 
            key={stock.symbol}
            onClick={() => setSelectedAsset(stock.symbol)}
            className={`p-4 sketch-border transition-all flex flex-col items-center ${selectedAsset === stock.symbol ? 'bg-[#1A1A1A] text-white scale-105 z-10' : 'bg-white hover:bg-gray-50'}`}
          >
            <span className="text-[10px] font-black">{stock.symbol}</span>
            <span className="text-[9px] font-bold opacity-60 mb-2">{stock.price}</span>
            <span className={`text-[8px] font-black ${stock.isPositive ? 'text-emerald-500' : 'text-rose-500'}`}>
              {stock.change}
            </span>
          </button>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 mb-8">
        {/* Main Chart Area */}
        <div className="lg:col-span-2 space-y-4">
          <div className="flex items-center justify-between">
            <div className="flex gap-4 items-baseline">
              <h2 className="text-xl font-black uppercase">{selectedAsset} / BRL</h2>
              <span className="text-[10px] font-bold text-[#7A7A7A]">CANDLESTICK CHART</span>
            </div>
            <div className="flex gap-2">
              {['1h', '4h', '1d', '1w'].map(t => (
                <button
                  key={t}
                  onClick={() => setTimeframe(t)}
                  className={`px-3 py-1 text-[9px] font-black uppercase sketch-border ${timeframe === t ? 'bg-[#1A1A1A] text-white' : 'bg-white hover:bg-gray-100'}`}
                >
                  {t}
                </button>
              ))}
            </div>
          </div>

          {renderCandleChart()}

          <div className="flex gap-4 text-[8px] font-black uppercase text-[#7A7A7A] justify-between">
            <span>Scroll para Zoom • Arraste para Mover</span>
            <span>Range: {visibleCount} candles</span>
          </div>
        </div>

        {/* Market Intelligence Panel */}
        <div className="flex flex-col h-full bg-white sketch-border p-6 relative overflow-hidden">
          <div className="mb-4">
            <h3 className="text-[10px] font-black uppercase tracking-widest text-[#1A1A1A] mb-1">Inteligência de Mercado</h3>
            <p className="text-[8px] font-bold text-[#7A7A7A]">Gemini Grounding Search</p>
          </div>

          <div className="flex-1 overflow-y-auto mb-4 custom-scrollbar min-h-[200px]">
            {!intelResult ? (
              <div className="h-full flex flex-col items-center justify-center opacity-40 text-center">
                <div className="w-12 h-12 bg-[#F2EFEA] rounded-full flex items-center justify-center mb-3 text-xl">✨</div>
                <p className="text-[9px] font-bold uppercase max-w-[200px]">
                  Pesquise sobre dividendos, riscos macroeconômicos ou valuation de {selectedAsset}.
                </p>
              </div>
            ) : (
              <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2">
                <div className="text-[10px] leading-relaxed whitespace-pre-wrap font-medium">
                  {intelResult.text}
                </div>
                {intelResult.sources?.length > 0 && (
                  <div className="border-t pt-3 border-gray-100">
                    <p className="text-[7px] font-black uppercase text-[#7A7A7A] mb-2">Fontes Verificadas:</p>
                    <div className="flex flex-wrap gap-2">
                      {intelResult.sources.map((src, i) => (
                        <a 
                          key={i} 
                          href={src.uri} 
                          target="_blank" 
                          rel="noreferrer"
                          className="text-[7px] bg-[#F2EFEA] px-2 py-1 rounded truncate max-w-[100%] hover:bg-[#1A1A1A] hover:text-white transition-colors"
                        >
                          {src.title || new URL(src.uri).hostname}
                        </a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>

          <div className="mt-auto">
            <div className="relative">
              <input 
                type="text" 
                value={intelQuery}
                onChange={(e) => setIntelQuery(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleMarketResearch()}
                placeholder={`Analisar ${selectedAsset}...`}
                className="w-full bg-[#F2EFEA] p-3 pr-10 text-[9px] font-black uppercase outline-none focus:bg-white border-2 border-transparent focus:border-[#1A1A1A] transition-colors"
              />
              <button 
                onClick={handleMarketResearch}
                disabled={isIntelLoading}
                className="absolute right-2 top-1/2 -translate-y-1/2 p-1 hover:scale-110 transition-transform"
              >
                {isIntelLoading ? (
                  <div className="w-4 h-4 border-2 border-[#1A1A1A] border-t-transparent rounded-full animate-spin" />
                ) : (
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                  </svg>
                )}
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Analytics & News Row */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* GA4 Metrics */}
        <div className="lg:col-span-1 bg-[#1A1A1A] text-white p-6 sketch-border shadow-none">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-[10px] font-black uppercase tracking-widest">Tráfego Web (GA4)</h3>
            <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></span>
          </div>

          {analyticsData ? (
            <div className="space-y-6">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <p className="text-[7px] font-black uppercase opacity-50 mb-1">Usuários Ativos</p>
                  <p className="text-2xl font-black">{analyticsData.activeUsers.toLocaleString()}</p>
                </div>
                <div>
                  <p className="text-[7px] font-black uppercase opacity-50 mb-1">Receita Digital</p>
                  <p className="text-xl font-black text-emerald-400">R$ {analyticsData.revenue.toLocaleString()}</p>
                </div>
              </div>
              <div>
                <div className="flex justify-between text-[7px] font-black uppercase mb-1">
                  <span>Meta de Conversão</span>
                  <span>{analyticsData.conversionRate.toFixed(1)}%</span>
                </div>
                <div className="h-1 bg-white/20 rounded-full overflow-hidden">
                  <div className="h-full bg-emerald-500" style={{ width: `${Math.min(100, analyticsData.conversionRate * 20)}%` }}></div>
                </div>
              </div>
            </div>
          ) : (
             <div className="h-[150px] flex items-center justify-center opacity-30 text-center">
               <p className="text-[8px] font-black uppercase">Nenhum relatório RAG Analytics conectado.</p>
             </div>
          )}
        </div>

        {/* Market News Feed */}
        <div className="lg:col-span-2 bg-white sketch-border p-6">
          <div className="flex items-center justify-between mb-6 border-b-2 border-[#1A1A1A] pb-2">
            <h3 className="text-[10px] font-black uppercase tracking-widest">Feed de Notícias (Gemini Live)</h3>
            <button onClick={() => {}} className="text-[8px] font-black uppercase hover:underline">Atualizar</button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {loadingNews ? (
               Array(4).fill(0).map((_, i) => (
                 <div key={i} className="animate-pulse space-y-2">
                   <div className="h-4 bg-gray-200 w-3/4"></div>
                   <div className="h-10 bg-gray-100 w-full"></div>
                 </div>
               ))
            ) : news.length === 0 ? (
              <div className="col-span-2 text-center py-10 opacity-50">
                <p className="text-[9px] font-black uppercase">Sem notícias relevantes no momento.</p>
              </div>
            ) : (
              news.slice(0, 4).map((article, i) => (
                <a 
                  key={i} 
                  href={article.url} 
                  target="_blank" 
                  rel="noreferrer" 
                  className="block group hover:bg-[#F2EFEA] p-3 transition-colors border border-transparent hover:border-[#1A1A1A]/10"
                >
                  <div className="flex items-start justify-between mb-2">
                    <span className={`text-[7px] font-black px-1.5 py-0.5 border ${getSentimentColor(article.sentiment)}`}>
                      {article.sentiment || 'NEUTRAL'}
                    </span>
                    <span className="text-[7px] font-bold text-[#7A7A7A] uppercase">{article.source} • {article.time}</span>
                  </div>
                  <h4 className="text-[9px] font-black uppercase leading-tight mb-2 group-hover:text-[#1A1A1A]">{article.title}</h4>
                  <p className="text-[8px] font-medium text-gray-500 line-clamp-2 leading-relaxed">
                    {article.summary}
                  </p>
                </a>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

export interface User {
  id: string;
  name: string;
  email: string;
  avatar: string;
}

export interface Message {
  id: string;
  role: 'user' | 'model';
  content: string;
  timestamp: Date;
  sources?: string[];
}

export type SyncStatus = 'synced' | 'pending' | 'local' | 'conflict' | 'syncing';

export interface ChatSession {
  id: string;
  title: string;
  messages: Message[];
  lastUpdate: Date;
  updatedAt: string;
  deletedAt?: Date;
  syncStatus?: SyncStatus;
  syncedAt?: Date;
  version: number;
  isPinned?: boolean;
}

export type DocumentSource = 'local' | 'google_docs' | 'google_sheets' | 'google_analytics' | 'google_drive' | 'google_slides' | 'xero' | 'quickbooks' | 'omie';

export interface Document {
  id: string;
  name: string;
  content: string;
  type: string;
  uploadDate: Date;
  size: number;
  sourceType: DocumentSource;
  externalUrl?: string;
  metadata?: {
    propertyId?: string;
    lastSync?: Date;
    category?: 'cost' | 'tax' | 'management' | 'general' | 'exercise';
  };
}

// Accounting Types
export interface Invoice {
  id: string;
  number: string;
  contact: string;
  date: string;
  dueDate: string;
  amount: number;
  status: 'PAID' | 'DUE' | 'VOID' | 'DRAFT';
  currency: string;
}

export interface FinancialMetric {
  label: string;
  value: number;
  prefix?: string;
  suffix?: string;
  trend: 'up' | 'down' | 'neutral';
  change: number;
}

export enum ViewState {
  Dashboard = 'DASHBOARD',
  Chat = 'CHAT',
  FinancialAI = 'FINANCIAL_AI',
  Documents = 'DOCUMENTS',
  Accounting = 'ACCOUNTING',
  Reports = 'REPORTS',
  Trash = 'TRASH'
}

// Interface for News results from Gemini
export interface NewsArticle {
  title: string;
  summary: string;
  url: string;
  source: string;
  time: string;
  sentiment?: 'BULLISH' | 'BEARISH' | 'NEUTRAL';
}

// Interface for market chart candles
export interface Candle {
  time: string;
  open: number;
  high: number;
  low: number;
  close: number;
}

import React, { useState, useEffect } from 'react';
import { ViewState, User } from '../types.ts';

interface SidebarProps {
  currentView: ViewState;
  setView: (view: ViewState) => void;
  user: User;
  onLogout: () => void;
  isOpen?: boolean;
}

const Sidebar: React.FC<SidebarProps> = ({ currentView, setView, user, onLogout, isOpen }) => {
  const [syncStatus, setSyncStatus] = useState<'synced' | 'syncing' | 'error'>('synced');

  useEffect(() => {
    const handleSyncStatus = (e: any) => setSyncStatus(e.detail);
    window.addEventListener('sync_status_change', handleSyncStatus as any);
    return () => window.removeEventListener('sync_status_change', handleSyncStatus as any);
  }, []);

  const menuItems = [
    { 
      id: ViewState.Dashboard, 
      label: 'DASHBOARD', 
      icon: (
        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z" />
        </svg>
      )
    },
    { 
      id: ViewState.Chat, 
      label: 'IA CONTÁBIL', 
      icon: (
        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 12h.01M12 12h.01M16 12h.01M21 12c0 4.418-4.03 8-9 8a9.863 9.863 0 01-4.255-.949L3 20l1.395-3.72C3.512 15.042 3 13.574 3 12c0-4.418 4.03-8 9-8s9 3.582 9 8z" />
        </svg>
