import { GoogleGenAI, Type } from "@google/genai";
import { StorageService } from "./storage.ts";
import { NewsArticle, Document } from "../types.ts";

export const GeminiService = {
  /**
   * Filtra e ranqueia documentos com base na consulta para otimizar a janela de contexto (RAG Top-K).
   */
  getRelevantContext: (query: string, docs: Document[]) => {
    if (!docs.length) return "NENHUM DADO REAL FORNECIDO.";

    const queryWords = query.toLowerCase().split(/\W+/).filter(w => w.length > 3);

    const rankedDocs = docs.map(doc => {
      let score = 0;
      const contentLower = doc.content.toLowerCase();
      queryWords.forEach(word => {
        if (contentLower.includes(word)) score += 1;
      });
      // Prioriza documentos mais recentes se o score for igual
      return { doc, score };
    }).sort((a, b) => b.score !== a.score ? b.score - a.score : b.doc.uploadDate.getTime() - a.doc.uploadDate.getTime());

    let contextStr = "BASE DE DADOS REAL DO USUÁRIO (AUDITORIA ATIVA):\n";
    let currentLength = 0;
    const MAX_CONTEXT_CHARS = 25000; // Limite seguro para Gemini Pro/Flash

    for (const item of rankedDocs) {
      const docEntry = `[ID: ${item.doc.id}] [FONTE: ${item.doc.sourceType.toUpperCase()}] [NOME: ${item.doc.name}]\nCONTEÚDO: ${item.doc.content}\n\n`;
      if (currentLength + docEntry.length > MAX_CONTEXT_CHARS) break;
      contextStr += docEntry;
      currentLength += docEntry.length;
    }

    return contextStr;
  },

  generateChatResponseStream: async (prompt: string, history: any[], onChunk: (text: string) => void) => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const docs = StorageService.getDocuments();
    const context = GeminiService.getRelevantContext(prompt, docs);

    const systemInstruction = `
      Você é o "FinaIGPT Auditor Sênior", especializado em Análise Financeira e Auditoria.

      PROTOCOLO:
      1. SOBERANIA DOS DADOS: Use o contexto fornecido abaixo. Se não houver dados relevantes no contexto, informe.
      2. RIGOR: Identifique anomalias e use termos técnicos (CPC/IFRS).
      3. FORMATO: Tabelas Markdown e destaque para valores monetários.

      CONTEXTO RAG ATUALIZADO:
      ${context}
    `;

    const formattedHistory = history
      .filter(msg => msg.id !== 'welcome' && msg.id !== 'reset') 
      .map(msg => ({
        role: msg.role === 'user' ? 'user' : 'model',
        parts: [{ text: msg.content }]
      }))
      .slice(-10);

    try {
      const result = await ai.models.generateContentStream({
        model: 'gemini-3-pro-preview',
        contents: formattedHistory,
        config: {
          systemInstruction,
          tools: [{ googleSearch: {} }],
          thinkingConfig: { thinkingBudget: 15000 },
          temperature: 0.1, 
        },
      });

      let fullText = "";
      for await (const chunk of result) {
        const chunkText = chunk.text;
        if (chunkText) {
          fullText += chunkText;
          onChunk(fullText);
        }
      }
      return fullText;
    } catch (error) {
      console.error("Gemini Stream Error:", error);
      throw error;
    }
  },

  generateFinancialAnalysisStream: async (prompt: string, history: any[], onChunk: (text: string) => void) => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // Para análise financeira, usamos menos RAG pessoal e mais dados de mercado externos
    const systemInstruction = `
      Você é um Analista de Investimentos Sênior (CFA Charterholder) e estrategista de mercado.

      SUA MISSÃO:
      1. Fornecer análises de Valuation (DCF, Múltiplos), Análise Técnica e Fundamentalista.
      2. Interpretar cenários macroeconômicos (Taxa Selic, FED, Inflação).
      3. Sugerir alocação de ativos e gerenciamento de risco.
      4. SEMPRE use a ferramenta de busca para obter a cotação e notícias mais recentes do mercado.

      ESTILO:
      - Profissional, direto, focado em dados (Data-Driven).
      - Use tabelas para comparar indicadores (P/L, ROE, DY).
      - Se o usuário pedir recomendação, sempre adicione o disclaimer: "Isto não é uma recomendação de compra/venda, mas uma análise educacional."
    `;

    const formattedHistory = history
      .map(msg => ({
        role: msg.role === 'user' ? 'user' : 'model',
        parts: [{ text: msg.content }]
      }))
      .slice(-6); // Menor histórico para focar no presente

    try {
      const result = await ai.models.generateContentStream({
        model: 'gemini-3-pro-preview', // Modelo mais inteligente para raciocínio financeiro
        contents: [...formattedHistory, { role: 'user', parts: [{ text: prompt }] }],
        config: {
          systemInstruction,
          tools: [{ googleSearch: {} }], // Grounding é essencial para finanças
          temperature: 0.2, 
        },
      });

      let fullText = "";
      for await (const chunk of result) {
        const chunkText = chunk.text;
        if (chunkText) {
          fullText += chunkText;
          onChunk(fullText);
        }
      }
      return fullText;
    } catch (error) {
      console.error("Gemini Financial Stream Error:", error);
      throw error;
    }
  },

  getMarketIntelligence: async (asset: string) => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: `Analise o ativo "${asset}" para fins de auditoria de mercado: preço atual, valuation, dividendos recentes e riscos macroeconômicos. Forneça fontes confiáveis.`,
        config: {
          tools: [{ googleSearch: {} }],
          temperature: 0,
        },
      });

      const text = response.text || "Erro ao coletar dados.";
      const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks?.map((chunk: any) => ({
        title: chunk.web?.title,
        uri: chunk.web?.uri
      })) || [];

      return { text, sources };
    } catch (e) {
      return { text: "Falha na conexão com o terminal de busca.", sources: [] };
    }
  },

  fetchLatestNews: async (): Promise<NewsArticle[]> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      // Usamos o Google Search diretamente via Gemini para buscar as notícias reais sem precisar de keys externas
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: `Encontre as 6 notícias mais importantes de hoje (últimas 24h) sobre o mercado financeiro brasileiro e internacional, contabilidade e economia. Retorne EXCLUSIVAMENTE um array JSON com objetos contendo: title, summary (máx 150 caracteres), url, source, time e sentiment (BULLISH, BEARISH ou NEUTRAL). Não adicione explicações fora do JSON.`,
        config: {
          tools: [{ googleSearch: {} }],
          temperature: 0.1,
        },
      });

      const text = response.text || "[]";
      // Limpeza robusta para extrair apenas o bloco JSON caso o modelo retorne Markdown
      const jsonMatch = text.match(/\[[\s\S]*\]/);
      if (jsonMatch) {
        return JSON.parse(jsonMatch[0]);
      }

      return [];
    } catch (e) {
      console.error("Erro ao buscar notícias via Search Grounding:", e);
      return [];
    }
  },

  generateTitle: async (firstPrompt: string): Promise<string> => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Crie um título curto de auditoria (3-5 palavras) para: "${firstPrompt}"`,
        config: { maxOutputTokens: 20 }
      });
      return response.text?.replace(/["']/g, '').trim() || "Análise Contábil";
    } catch (e) {
      return "Análise Contábil";
    }
  }
};

