                    {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </span>
                </div>
                <div className="text-xs font-medium leading-relaxed whitespace-pre-wrap break-words font-mono">
                  {msg.content}
                </div>
              </div>
            </div>
          ))}

          {isLoading && (
            <div className="flex justify-start">
               <div className="max-w-[90%] md:max-w-[75%] p-5 bg-white text-[#1A1A1A] sketch-border animate-pulse">
                <div className="flex items-center gap-2 mb-2">
                  <span className="text-[8px] font-black uppercase tracking-widest">ANALISANDO MERCADO...</span>
                  <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-ping" />
                </div>
                <div className="text-xs font-medium leading-relaxed whitespace-pre-wrap font-mono">
                  {streamingText || "Calculando indicadores e consultando fontes..."}
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Input Area */}
        <div className="p-4 md:p-8 bg-[#F2EFEA]">
           {messages.length < 3 && (
            <div className="flex gap-2 overflow-x-auto pb-4 mb-2 custom-scrollbar">
              {quickActions.map((action, i) => (
                <button
                  key={i}
