const ChatInterface: React.FC = () => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [streamingText, setStreamingText] = useState('');

  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    loadSessions();
    const handleSync = (e: any) => {
      if (e.detail === 'all') loadSessions();
    };
    window.addEventListener('session_synced', handleSync as any);
    return () => window.removeEventListener('session_synced', handleSync as any);
  }, []);

  useEffect(() => {
    scrollToBottom();
  }, [currentSessionId, sessions, streamingText]);

  const loadSessions = () => {
    const loaded = StorageService.getChatSessions();
    setSessions(loaded);
    if (!currentSessionId && loaded.length > 0) {
      setCurrentSessionId(loaded[0].id);
    }
  };

  const scrollToBottom = () => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  };

  const createNewSession = () => {
    const newSession: ChatSession = {
      id: Date.now().toString(),
      title: 'Nova Auditoria',
      messages: [],
      lastUpdate: new Date(),
      updatedAt: new Date().toISOString(),
      version: 1,
      syncStatus: 'local'
    };
    StorageService.saveChatSession(newSession);
    setSessions(prev => [newSession, ...prev]);
    setCurrentSessionId(newSession.id);
  };

  const handleSendMessage = async () => {
    if (!input.trim() || !currentSessionId || isLoading) return;

    const currentSession = sessions.find(s => s.id === currentSessionId);
    if (!currentSession) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      timestamp: new Date()
    };

    // Optimistic update
    const updatedMessages = [...currentSession.messages, userMsg];
    const updatedSession = { ...currentSession, messages: updatedMessages, lastUpdate: new Date() };

    // Generate title if first message
    if (updatedMessages.length === 1) {
       GeminiService.generateTitle(input).then(title => {
         const titledSession = { ...updatedSession, title };
         StorageService.saveChatSession(titledSession);
         loadSessions();
       });
    } else {
      StorageService.saveChatSession(updatedSession);
      setSessions(prev => prev.map(s => s.id === currentSessionId ? updatedSession : s));
    }

    setInput('');
    setIsLoading(true);
    setStreamingText('');

    try {
      const responseText = await GeminiService.generateChatResponseStream(
        input,
        updatedMessages,
        (chunk) => setStreamingText(chunk)
      );

      const modelMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: responseText,
        timestamp: new Date()
      };

      const finalSession = { 
        ...updatedSession, 
        messages: [...updatedMessages, modelMsg],
        lastUpdate: new Date()
      };

      StorageService.saveChatSession(finalSession);
      setSessions(prev => prev.map(s => s.id === currentSessionId ? finalSession : s));
    } catch (error) {
      console.error(error);
      alert("Erro ao conectar com Gemini API");
    } finally {
      setIsLoading(false);
      setStreamingText('');
      inputRef.current?.focus();
    }
  };

  const handleDeleteSession = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (window.confirm('Mover esta auditoria para a lixeira?')) {
      StorageService.deleteChatSession(id);
      loadSessions();
      if (currentSessionId === id) {
        setCurrentSessionId(null);
      }
    }
  };

  const handleTogglePin = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    StorageService.togglePin(id);
    loadSessions();
  };

  const activeSession = sessions.find(s => s.id === currentSessionId);

  return (
    <div className="flex h-full bg-[#F2EFEA]">
      {/* Sidebar */}
      <div className="w-80 border-r-2 border-[#1A1A1A] flex flex-col bg-[#F2EFEA] shrink-0">
        <div className="p-4 border-b-2 border-[#1A1A1A] bg-white">
          <button 
            onClick={createNewSession}
            className="w-full py-3 bg-[#1A1A1A] text-white text-[10px] font-black uppercase tracking-widest sketch-button flex items-center justify-center gap-2 hover:bg-emerald-600"
          >
            <span>+</span> Nova Auditoria
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-2 custom-scrollbar">
          {sessions.length === 0 ? (
            <div className="text-center p-8 opacity-40">
              <p className="text-[9px] font-bold uppercase">Histórico Vazio</p>
            </div>
          ) : (
            <>
              {sessions.filter(s => s.isPinned).map(session => (
                <ChatListItem 
                  key={session.id}
                  session={session}
                  isActive={session.id === currentSessionId}
                  onClick={() => setCurrentSessionId(session.id)}
                  onTogglePin={handleTogglePin}
                  onDelete={handleDeleteSession}
                />
              ))}
              {sessions.some(s => s.isPinned) && <div className="h-px bg-[#1A1A1A]/10 my-2 mx-4" />}
              {sessions.filter(s => !s.isPinned).map(session => (
                <ChatListItem 
                  key={session.id}
                  session={session}
                  isActive={session.id === currentSessionId}
                  onClick={() => setCurrentSessionId(session.id)}
                  onTogglePin={handleTogglePin}
                  onDelete={handleDeleteSession}
                />
              ))}
            </>
          )}
        </div>
      </div>

      {/* Main Chat Area */}
      <div className="flex-1 flex flex-col min-w-0 bg-[#F2EFEA] relative">
        {activeSession ? (
          <>
            {/* Messages List */}
            <div ref={scrollRef} className="flex-1 overflow-y-auto p-8 space-y-8 custom-scrollbar">
              {activeSession.messages.length === 0 && (
                <div className="flex flex-col items-center justify-center h-full opacity-30">
                  <div className="w-20 h-20 border-4 border-[#1A1A1A] rounded-full flex items-center justify-center mb-4">
                    <span className="text-4xl">?</span>
                  </div>
                  <p className="text-[10px] font-black uppercase tracking-widest">Inicie uma auditoria...</p>
                </div>
              )}

              {activeSession.messages.map((msg) => (
                <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`
                    max-w-[85%] md:max-w-[75%] p-6 sketch-border
                    ${msg.role === 'user' ? 'bg-[#1A1A1A] text-white' : 'bg-white text-[#1A1A1A]'}
                  `}>
                    <div className="flex items-center gap-2 mb-3 border-b border-current/10 pb-2">
                      <span className="text-[8px] font-black uppercase tracking-widest">
                        {msg.role === 'user' ? 'AUDITOR' : 'FINAIGPT'}
                      </span>
                      <span className="text-[7px] opacity-40 uppercase">
                        {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      </span>
                    </div>
                    {/* Typography: Text Base + Medium + Sans-Serif */}
                    <div className="text-base font-medium leading-relaxed whitespace-pre-wrap break-words">
                      {msg.content}
                    </div>
                  </div>
                </div>
              ))}

              {isLoading && (
                <div className="flex justify-start">
                  <div className="max-w-[75%] p-6 bg-white text-[#1A1A1A] sketch-border animate-pulse">
                    <div className="flex items-center gap-2 mb-3">
                      <span className="text-[8px] font-black uppercase tracking-widest">PROCESSANDO RAG...</span>
                      <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-ping" />
                    </div>
                    <div className="text-base font-medium leading-relaxed whitespace-pre-wrap">
                      {streamingText || "Consultando base de conhecimento..."}
                    </div>
                  </div>
                </div>
              )}
            </div>

            {/* Input Area */}
            <div className="p-6 bg-[#F2EFEA]">
              <div className="max-w-4xl mx-auto relative group">
                <textarea
                  ref={inputRef}
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' && !e.shiftKey) {
                      e.preventDefault();
                      handleSendMessage();
                    }
                  }}
                  placeholder="Descreva a solicitação contábil ou anexe um contexto..."
                  className="w-full bg-white sketch-border p-4 pr-16 text-base font-medium uppercase tracking-tight outline-none focus:ring-2 ring-emerald-500/20 resize-none min-h-[80px]"
                />
                <button 
                  onClick={handleSendMessage}
                  disabled={isLoading || !input.trim()}
                  className="absolute right-4 top-4 bottom-4 aspect-square bg-[#1A1A1A] text-white flex items-center justify-center hover:bg-emerald-600 transition-colors disabled:opacity-50 disabled:hover:bg-[#1A1A1A]"
                >
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
                  </svg>
                </button>
              </div>
              <p className="text-center mt-3 text-[8px] font-bold text-[#7A7A7A] uppercase">
                IA treinada em CPC/IFRS. Verifique sempre com um contador humano.
              </p>
            </div>
          </>
        ) : (
          <div className="flex items-center justify-center h-full">
            <div className="text-center">
              <h2 className="text-2xl font-black uppercase mb-4">Terminal Contábil</h2>
              <button 
                onClick={createNewSession}
                className="sketch-button px-8 py-4 text-xs font-black uppercase tracking-widest"
              >
                Iniciar Nova Sessão
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

