    } catch (e) {
      return null;
    }
  },

  setUser: (user: User) => {
    localStorage.setItem(USER_KEY, JSON.stringify(user));
  },

  clearAll: () => {
    localStorage.removeItem(USER_KEY);
    // Optional: clear other keys if logout should wipe everything
  },

  syncWithCloud: () => {
    // Mock sync
    window.dispatchEvent(new CustomEvent('sync_status_change', { detail: 'syncing' }));
    setTimeout(() => {
      window.dispatchEvent(new CustomEvent('sync_status_change', { detail: 'synced' }));
      window.dispatchEvent(new CustomEvent('session_synced', { detail: 'all' }));
    }, 1500);
  },

  // Chat Sessions (Professional/Audit)
  getChatSessions: (includeDeleted: boolean = false): ChatSession[] => {
    const data = localStorage.getItem(CHATS_KEY);
    if (!data) return [];

    try {
      const parsed = JSON.parse(data);
      if (!Array.isArray(parsed)) return [];

      const sessions = parsed.map((s: any) => ({
        ...s,
        lastUpdate: new Date(s.lastUpdate),
        syncedAt: s.syncedAt ? new Date(s.syncedAt) : undefined,
        deletedAt: s.deletedAt ? new Date(s.deletedAt) : undefined,
        messages: (s.messages || []).map((m: any) => ({ 
          ...m, 
          timestamp: new Date(m.timestamp) 
        }))
      }));

      if (includeDeleted) return sessions;
      return sessions.filter(s => !s.deletedAt);
    } catch (e) {
      console.error("Error parsing chats", e);
      return [];
    }
  },

  saveChatSession: (session: ChatSession) => {
    const sessions = StorageService.getChatSessions(true);
    const index = sessions.findIndex(s => s.id === session.id);

    if (index >= 0) {
      sessions[index] = session;
    } else {
      sessions.unshift(session);
    }

    localStorage.setItem(CHATS_KEY, JSON.stringify(sessions));
    // Trigger sync event (mock)
    window.dispatchEvent(new CustomEvent('session_synced', { detail: session.id }));
  },

  deleteChatSession: (id: string) => {
    const sessions = StorageService.getChatSessions(true);
    const session = sessions.find(s => s.id === id);
    if (session) {
      session.deletedAt = new Date();
      StorageService.saveChatSession(session);
    }
  },

  deletePermanently: (id: string) => {
    const sessions = StorageService.getChatSessions(true).filter(s => s.id !== id);
    localStorage.setItem(CHATS_KEY, JSON.stringify(sessions));
  },

  togglePin: (id: string) => {
    const sessions = StorageService.getChatSessions(true);
    const session = sessions.find(s => s.id === id);
    if (session) {
      session.isPinned = !session.isPinned;
      localStorage.setItem(CHATS_KEY, JSON.stringify(sessions));
    }
  },

  // STUDENT AREA SESSIONS
  getStudentSessions: (): ChatSession[] => {
    const data = localStorage.getItem(STUDENT_CHATS_KEY);
    if (!data) return [];

    try {
      const parsed = JSON.parse(data);
      if (!Array.isArray(parsed)) return [];

      return parsed.map((s: any) => ({
        ...s,
        lastUpdate: new Date(s.lastUpdate),
        messages: (s.messages || []).map((m: any) => ({ 
          ...m, 
          timestamp: new Date(m.timestamp) 
        }))
      }));
