      console.error("Error parsing student chats", e);
      return [];
    }
  },

  saveStudentSession: (session: ChatSession) => {
    const sessions = StorageService.getStudentSessions();
    const index = sessions.findIndex(s => s.id === session.id);

    if (index >= 0) {
      sessions[index] = session;
    } else {
      sessions.unshift(session);
    }

    localStorage.setItem(STUDENT_CHATS_KEY, JSON.stringify(sessions));
    window.dispatchEvent(new CustomEvent('student_session_synced', { detail: session.id }));
  },

  deleteStudentSession: (id: string) => {
    const sessions = StorageService.getStudentSessions().filter(s => s.id !== id);
    localStorage.setItem(STUDENT_CHATS_KEY, JSON.stringify(sessions));
  },

  toggleStudentPin: (id: string) => {
    const sessions = StorageService.getStudentSessions();
    const session = sessions.find(s => s.id === id);
    if (session) {
      session.isPinned = !session.isPinned;
      localStorage.setItem(STUDENT_CHATS_KEY, JSON.stringify(sessions));
    }
  }
};

import { GoogleGenAI, GenerateContentResponse } from "@google/genai";
import { StorageService } from "./storage.ts";
import { NewsArticle, Document, Message } from "../types.ts";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const GeminiService = {
  /**
   * Helper: Get Relevant Context (RAG)
   */
  getRelevantContext: (query: string, docs: Document[]) => {
    if (!docs.length) return "NENHUM DADO REAL FORNECIDO.";

    const queryWords = query.toLowerCase().split(/\W+/).filter(w => w.length > 3);

    const rankedDocs = docs.map(doc => {
      let score = 0;
      const contentLower = doc.content.toLowerCase();
      queryWords.forEach(word => {
        if (contentLower.includes(word)) score += 1;
      });
      return { doc, score };
    }).sort((a, b) => b.score !== a.score ? b.score - a.score : b.doc.uploadDate.getTime() - a.doc.uploadDate.getTime());

    let contextStr = "BASE DE DADOS REAL DO USUÁRIO (AUDITORIA ATIVA):\n";
    let currentLength = 0;
    const MAX_CONTEXT_CHARS = 25000;

    for (const item of rankedDocs) {
      if (item.score === 0 && rankedDocs.length > 5) continue; // Skip irrelevant if we have many docs
      const docEntry = `[ID: ${item.doc.id}] [FONTE: ${item.doc.sourceType.toUpperCase()}] [NOME: ${item.doc.name}]\nCONTEÚDO: ${item.doc.content}\n\n`;
      if (currentLength + docEntry.length > MAX_CONTEXT_CHARS) break;
      contextStr += docEntry;
      currentLength += docEntry.length;
    }
    return contextStr;
  },

  /**
   * Helper: Generate Chat Title
   */
  generateTitle: async (firstMessage: string): Promise<string> => {
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-latest',
        contents: `Gere um título muito curto (max 4 palavras), profissional e em MAIÚSCULAS para este chat: "${firstMessage}". Responda APENAS o título.`,
      });
      return response.text?.trim().replace(/['"]+/g, '') || 'NOVA SESSÃO';
    } catch (e) {
      return 'NOVA SESSÃO';
    }
  },

  /**
   * 1. NEWS AGENT (Uses Google Search Grounding)
   */
  fetchLatestNews: async (): Promise<NewsArticle[]> => {
    try {
      // We ask for a JSON response representing news
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-latest',
        contents: `Find the 4 most important financial news headlines right now for Brazil and Global markets.
        Return a JSON array where each object has:
        - title (string, translated to Portuguese)
        - summary (string, max 20 words in Portuguese)
        - source (string)
        - sentiment (string: 'BULLISH', 'BEARISH', or 'NEUTRAL')
        - time (string, e.g. '2h ago')

        Use the Google Search tool to get real data.`,
        config: {
          tools: [{ googleSearch: {} }],
          responseMimeType: 'application/json'
        }
      });

      const text = response.text;
      if (!text) return [];

      const articles = JSON.parse(text);

      // Enhance with URLs from grounding if available (though JSON mode might mask direct grounding chunks, 
      // typically we map them. For simplicity in this robust fix, we rely on the model filling the 'source' or we mock the URL if missing)
      return articles.map((a: any) => ({
        ...a,
        url: a.url || `https://google.com/search?q=${encodeURIComponent(a.title)}` // Fallback URL
      }));
    } catch (e) {
      console.error("News Fetch Error", e);
      return [];
    }
  },

  /**
   * 2. MARKET INTELLIGENCE AGENT
   */
  getMarketIntelligence: async (query: string) => {
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-latest',
        contents: `Analyze this market query acting as a Senior Financial Analyst: "${query}".
        Provide a concise, data-driven insight considering current market conditions.`,
        config: {
          tools: [{ googleSearch: {} }],
        }
      });

      // Extract sources from grounding metadata
      const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks
        ?.map((chunk: any) => chunk.web?.uri ? { uri: chunk.web.uri, title: chunk.web.title } : null)
        .filter(Boolean) || [];

      return {
        text: response.text || "Não foi possível obter dados de mercado no momento.",
        sources: sources
      };
    } catch (e) {
      console.error("Market Intel Error", e);
      return { text: "Erro ao consultar mercado.", sources: [] };
    }
  },

  /**
   * 3. PROFESSIONAL AUDITOR AGENT (Streaming)
   */
  generateChatResponseStream: async (
    currentMessage: string, 
    history: Message[], 
    onChunk: (text: string) => void
  ): Promise<string> => {
    const docs = StorageService.getDocuments();
    const context = GeminiService.getRelevantContext(currentMessage, docs);

    const systemInstruction = `
      VOCÊ É O FINAIGPT, UM AUDITOR SÊNIOR ESPECIALISTA EM IFRS, CPC E ANÁLISE DE DADOS.

      DIRETRIZES:
      1. Use estritamente o contexto fornecido (RAG) para responder perguntas sobre documentos.
      2. Se a informação não estiver nos documentos, use seu conhecimento geral mas AVISE que é uma resposta genérica.
      3. Seja técnico, direto e profissional. Use terminologia contábil correta (Ativo, Passivo, Patrimônio Líquido, DRE, EBITDA).
      4. Formate a resposta usando Markdown para clareza (tabelas, negrito, listas).
      5. Nunca invente números.

      CONTEXTO RAG ATUAL:
      ${context}
    `;

    const chatHistory = history.slice(0, -1).map(m => ({
      role: m.role,
      parts: [{ text: m.content }]
    }));

    const chat = ai.chats.create({
      model: 'gemini-2.5-flash-latest',
      config: { systemInstruction },
      history: chatHistory
    });

    const result = await chat.sendMessageStream({ message: currentMessage });

    let fullText = '';
    for await (const chunk of result) {
      const text = chunk.text;
      if (text) {
        fullText += text;
        onChunk(fullText);
      }
    }
    return fullText;
  },

