const ChatListItem: React.FC<{
  session: ChatSession;
  isActive: boolean;
  onClick: () => void;
  onTogglePin: (e: React.MouseEvent, id: string) => void;
  onDelete: (e: React.MouseEvent, id: string) => void;
}> = ({ session, isActive, onClick, onTogglePin, onDelete }) => {
  return (
    <div 
      onClick={onClick}
      className={`
        group relative flex items-center gap-3 p-3 cursor-pointer transition-all duration-200 border-2 mb-2
        ${isActive 
          ? 'bg-[#1A1A1A] text-white border-[#1A1A1A] translate-x-1' 
          : 'bg-white text-[#1A1A1A] border-transparent hover:border-[#1A1A1A]/10 hover:bg-[#F2EFEA]'
        }
      `}
    >
      <div className={`w-8 h-8 flex items-center justify-center font-black text-[10px] border-2 ${isActive ? 'bg-white text-[#1A1A1A] border-white' : 'bg-[#F2EFEA] border-[#1A1A1A] text-[#1A1A1A]'}`}>
        A
      </div>

      <div className="flex-1 min-w-0">
        <h4 className="text-[10px] font-black uppercase truncate tracking-tight">
          {session.title || 'Nova Aula'}
        </h4>
        <p className={`text-[8px] font-bold uppercase opacity-60`}>
          {new Date(session.lastUpdate).toLocaleDateString()}
        </p>
      </div>

      <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
        <button 
          onClick={(e) => onTogglePin(e, session.id)}
          className={`p-1.5 hover:bg-white/10 rounded transition-colors ${session.isPinned ? 'text-amber-400' : 'text-gray-400'}`}
          title={session.isPinned ? "Desafixar" : "Fixar"}
        >
          <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20">
            <path d="M5 4a2 2 0 012-2h6a2 2 0 012 2v14l-5-2.5L5 18V4z" />
          </svg>
        </button>
        <button 
          onClick={(e) => onDelete(e, session.id)}
          className="p-1.5 hover:bg-rose-500 hover:text-white rounded text-gray-400 transition-colors"
          title="Excluir"
        >
          <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
          </svg>
        </button>
      </div>
    </div>
  );
};

const StudentArea: React.FC = () => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [streamingText, setStreamingText] = useState('');

  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    loadSessions();
    const handleSync = (e: any) => {
      if (e.detail === 'all' || typeof e.detail === 'string') loadSessions();
    };
    window.addEventListener('student_session_synced', handleSync as any);
    return () => window.removeEventListener('student_session_synced', handleSync as any);
  }, []);

  useEffect(() => {
    scrollToBottom();
  }, [currentSessionId, sessions, streamingText]);

  const loadSessions = () => {
    const loaded = StorageService.getStudentSessions();
    setSessions(loaded);
    if (!currentSessionId && loaded.length > 0) {
      setCurrentSessionId(loaded[0].id);
    }
  };

  const scrollToBottom = () => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  };

  const createNewSession = () => {
    const newSession: ChatSession = {
      id: Date.now().toString(),
      title: 'Nova Aula',
      messages: [{
        id: 'intro',
        role: 'model',
        content: 'Olá! Sou seu Tutor de Finanças. 🎓\n\nPodemos estudar:\n1. Contabilidade Básica (Débito/Crédito)\n2. Análise de Balanços\n3. Matemática Financeira\n\nQual tema você quer dominar hoje?',
        timestamp: new Date()
      }],
      lastUpdate: new Date(),
      updatedAt: new Date().toISOString(),
      version: 1,
      syncStatus: 'local'
    };
    StorageService.saveStudentSession(newSession);
    setSessions(prev => [newSession, ...prev]);
    setCurrentSessionId(newSession.id);
  };

  const handleSendMessage = async () => {
    if (!input.trim() || !currentSessionId || isLoading) return;

    const currentSession = sessions.find(s => s.id === currentSessionId);
    if (!currentSession) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      timestamp: new Date()
    };

    const updatedMessages = [...currentSession.messages, userMsg];
    const updatedSession = { ...currentSession, messages: updatedMessages, lastUpdate: new Date() };

    // Auto title update for first question
    if (updatedMessages.length === 2) { 
       GeminiService.generateTitle(input).then(title => {
         const titledSession = { ...updatedSession, title };
         StorageService.saveStudentSession(titledSession);
         loadSessions();
       });
    } else {
      StorageService.saveStudentSession(updatedSession);
      setSessions(prev => prev.map(s => s.id === currentSessionId ? updatedSession : s));
    }

    setInput('');
    setIsLoading(true);
    setStreamingText('');

    try {
      const response = await GeminiService.generateStudentResponseStream(
        input,
        updatedMessages,
        (chunk) => setStreamingText(chunk)
      );

      const modelMsg: Message = {
        id: (Date.now() + 1).toString(),
        role: 'model',
        content: response,
        timestamp: new Date()
      };

      const finalSession = { 
        ...updatedSession, 
        messages: [...updatedMessages, modelMsg], 
        lastUpdate: new Date() 
      };

      StorageService.saveStudentSession(finalSession);
      setSessions(prev => prev.map(s => s.id === currentSessionId ? finalSession : s));
    } catch (error) {
      console.error(error);
      alert("Erro ao conectar com o Tutor IA");
    } finally {
      setIsLoading(false);
      setStreamingText('');
      inputRef.current?.focus();
    }
  };

  const handleDeleteSession = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (window.confirm('Excluir esta aula do histórico?')) {
      StorageService.deleteStudentSession(id);
      loadSessions();
      if (currentSessionId === id) setCurrentSessionId(null);
    }
  };

  const handleTogglePin = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    StorageService.toggleStudentPin(id);
    loadSessions();
  };

  const activeSession = sessions.find(s => s.id === currentSessionId);

  return (
    <div className="flex h-full bg-[#F2EFEA]">
      {/* Sidebar - Student Mode */}
      <div className="w-80 border-r-2 border-[#1A1A1A] flex flex-col bg-[#F2EFEA] shrink-0">
        <div className="p-4 border-b-2 border-[#1A1A1A] bg-white">
          <div className="mb-4">
            <h2 className="text-xl font-black uppercase text-[#1A1A1A]">Área do Aluno</h2>
            <p className="text-[9px] font-bold text-[#7A7A7A] uppercase tracking-widest">Tutor Didático • IFRS Education</p>
          </div>
          <button 
            onClick={createNewSession}
            className="w-full py-3 bg-[#1A1A1A] text-white text-[10px] font-black uppercase tracking-widest sketch-button flex items-center justify-center gap-2"
          >
            <span>+</span> Nova Aula
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-2 custom-scrollbar">
          {sessions.length === 0 ? (
            <div className="text-center p-8 opacity-40">
              <p className="text-[9px] font-bold uppercase">Caderno Vazio</p>
            </div>
          ) : (
            sessions.map(session => (
              <ChatListItem 
                key={session.id}
                session={session}
                isActive={session.id === currentSessionId}
                onClick={() => setCurrentSessionId(session.id)}
                onTogglePin={handleTogglePin}
                onDelete={handleDeleteSession}
              />
            ))
          )}
        </div>
      </div>

      {/* Main Chat Area */}
      <div className="flex-1 flex flex-col min-w-0 bg-[#fff] relative">
        {activeSession ? (
          <>
            <div ref={scrollRef} className="flex-1 overflow-y-auto p-8 space-y-8 custom-scrollbar bg-[#F2EFEA]">
              {activeSession.messages.map((msg) => (
                <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`
                    max-w-[85%] md:max-w-[75%] p-6 sketch-border relative
                    ${msg.role === 'user' ? 'bg-[#1A1A1A] text-white' : 'bg-white text-[#1A1A1A]'}
                  `}>
                    {/* Role Label */}
                    <div className={`absolute -top-3 ${msg.role === 'user' ? 'right-4' : 'left-4'} px-2 py-0.5 bg-[#F2EFEA] border-2 border-[#1A1A1A] text-[7px] font-black uppercase tracking-widest text-[#1A1A1A]`}>
                      {msg.role === 'user' ? 'ALUNO' : 'PROFESSOR'}
                    </div>

                    <div className="text-base font-medium leading-relaxed whitespace-pre-wrap break-words pt-2">
                      {msg.content}
                    </div>
                  </div>
                </div>
              ))}

              {isLoading && (
                <div className="flex justify-start">
                  <div className="max-w-[75%] p-6 bg-white text-[#1A1A1A] sketch-border animate-pulse relative">
                    <div className="absolute -top-3 left-4 px-2 py-0.5 bg-[#F2EFEA] border-2 border-[#1A1A1A] text-[7px] font-black uppercase tracking-widest text-[#1A1A1A]">
                      ESCREVENDO...
                    </div>
                    <div className="text-base font-medium leading-relaxed whitespace-pre-wrap pt-2">
                      {streamingText || "Elaborando explicação didática..."}
                    </div>
                  </div>
                </div>
              )}
            </div>

            <div className="p-6 bg-white border-t-2 border-[#1A1A1A]">
              <div className="max-w-4xl mx-auto relative group">
                <textarea
                  ref={inputRef}
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' && !e.shiftKey) {
                      e.preventDefault();
                      handleSendMessage();
                    }
                  }}
                  placeholder="Ex: Não entendi a diferença entre Regime de Caixa e Competência..."
                  className="w-full bg-[#F2EFEA] sketch-border p-4 pr-16 text-base font-medium uppercase tracking-tight outline-none focus:ring-2 ring-emerald-500/20 resize-none min-h-[80px]"
                />
                <button 
                  onClick={handleSendMessage}
                  disabled={isLoading || !input.trim()}
                  className="absolute right-4 top-4 bottom-4 aspect-square bg-[#1A1A1A] text-white flex items-center justify-center hover:bg-emerald-600 transition-colors disabled:opacity-50 disabled:hover:bg-[#1A1A1A]"
                >
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
                  </svg>
                </button>
              </div>
            </div>
          </>
        ) : (
          <div className="flex items-center justify-center h-full bg-[#F2EFEA]">
            <div className="text-center">
              <div className="text-6xl mb-4">🎓</div>
              <h2 className="text-2xl font-black uppercase mb-4 text-[#1A1A1A]">Sala de Aula Virtual</h2>
              <button 
                onClick={createNewSession}
                className="sketch-button px-8 py-4 text-xs font-black uppercase tracking-widest"
              >
                Começar a Estudar
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default StudentArea;

