const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const GeminiService = {
  /**
   * Helper: Get Relevant Context (RAG)
   */
  getRelevantContext: (query: string, docs: Document[]) => {
    if (!docs.length) return "NENHUM DADO REAL FORNECIDO.";

    const queryLower = query.toLowerCase();
    const queryWords = queryLower.split(/\W+/).filter(w => w.length > 3);

    // Keywords that trigger DRE prioritization
    const dreKeywords = ['lucro', 'receita', 'despesa', 'ebitda', 'margem', 'faturamento', 'custo'];
    const isDreQuery = dreKeywords.some(kw => queryLower.includes(kw));

    const rankedDocs = docs.map(doc => {
      let score = 0;
      const contentLower = doc.content.toLowerCase();
      const nameLower = doc.name.toLowerCase();

      // Base keyword matching score
      queryWords.forEach(word => {
        if (contentLower.includes(word)) score += 1;
        if (nameLower.includes(word)) score += 2; // Name matches are more significant
      });

      // DRE Prioritization Logic
      if (isDreQuery) {
        const isDreDoc = 
          contentLower.includes('dre') || 
          contentLower.includes('demonstração de resultado') || 
          contentLower.includes('demonstracao de resultado') ||
          nameLower.includes('dre');

        if (isDreDoc) {
          score += 10; // Significant boost for DRE docs on financial queries
        }
      }

      return { doc, score };
    }).sort((a, b) => {
      if (b.score !== a.score) return b.score - a.score;
      const dateA = a.doc.uploadDate instanceof Date ? a.doc.uploadDate.getTime() : 0;
      const dateB = b.doc.uploadDate instanceof Date ? b.doc.uploadDate.getTime() : 0;
      return dateB - dateA;
    });

    let contextStr = "BASE DE DADOS REAL DO USUÁRIO (AUDITORIA ATIVA):\n";
    let currentLength = 0;
    const MAX_CONTEXT_CHARS = 25000;

    for (const item of rankedDocs) {
      if (item.score === 0 && rankedDocs.length > 5) continue; 
      const docEntry = `[ID: ${item.doc.id}] [FONTE: ${item.doc.sourceType.toUpperCase()}] [NOME: ${item.doc.name}]\nCONTEÚDO: ${item.doc.content}\n\n`;
      if (currentLength + docEntry.length > MAX_CONTEXT_CHARS) break;
      contextStr += docEntry;
      currentLength += docEntry.length;
    }
    return contextStr;
  },

  /**
   * Helper: Generate Chat Title
   */
  generateTitle: async (firstMessage: string): Promise<string> => {
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Gere um título muito curto (max 4 palavras), profissional e em MAIÚSCULAS para este chat: "${firstMessage}". Responda APENAS o título.`,
      });
      return response.text?.trim().replace(/['"]+/g, '') || 'NOVA SESSÃO';
    } catch (e) {
      return 'NOVA SESSÃO';
    }
  },

  /**
   * 1. NEWS AGENT (Uses Google Search Grounding)
   */
  fetchLatestNews: async (): Promise<NewsArticle[]> => {
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: `Find the 4 most important financial news headlines right now for Brazil and Global markets.
        Return a JSON array ONLY. Do not add any text before or after the JSON.
        The JSON should be an array of objects with these keys:
        - title (string, translated to Portuguese)
        - summary (string, max 20 words in Portuguese)
        - source (string)
        - sentiment (string: 'BULLISH', 'BEARISH', or 'NEUTRAL')
        - time (string, e.g. '2h ago')`,
        config: {
          tools: [{ googleSearch: {} }]
        }
      });

      let text = response.text || "[]";
      text = text.replace(/```json/g, '').replace(/```/g, '').trim();

      const articles = JSON.parse(text);

      return articles.map((a: any) => ({
        ...a,
        url: a.url || `https://www.google.com/search?q=${encodeURIComponent(a.title)}`
      }));
    } catch (e) {
      console.error("News Fetch Error", e);
      return [];
    }
  },

  /**
   * 2. MARKET INTELLIGENCE AGENT
   */
  getMarketIntelligence: async (query: string) => {
    try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Analyze this market query acting as a Senior Financial Analyst: "${query}".
