const ChatInterface: React.FC = () => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [streamingText, setStreamingText] = useState('');
  const [imageAttachment, setImageAttachment] = useState<{data: string, mimeType: string} | null>(null);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const loaded = StorageService.getChatSessions();
    setSessions(loaded);
    if (loaded.length > 0) setCurrentSessionId(loaded[0].id);
  }, []);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [sessions, streamingText]);

  const createNewSession = () => {
    const newSession: ChatSession = {
      id: Date.now().toString(),
      title: 'IA CONTÁBIL SÊNIOR',
      messages: [{ id: 'init', role: 'model', content: 'Auditor FinaIGPT pronto. Como posso analisar sua saúde contábil ou fiscal hoje?', timestamp: new Date() }],
      lastUpdate: new Date(),
      updatedAt: new Date().toISOString(),
      version: 1
    };
    StorageService.saveChatSession(newSession);
    setSessions([newSession, ...sessions]);
    setCurrentSessionId(newSession.id);
  };

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (re) => {
        const base64 = (re.target?.result as string).split(',')[1];
        setImageAttachment({ data: base64, mimeType: file.type });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSend = async () => {
    if ((!input.trim() && !imageAttachment) || !currentSessionId || isLoading) return;

    const currentSession = sessions.find(s => s.id === currentSessionId);
    if (!currentSession) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      image: imageAttachment || undefined,
      timestamp: new Date()
    };

    const updatedSession = { ...currentSession, messages: [...currentSession.messages, userMsg], lastUpdate: new Date() };
    setSessions(prev => prev.map(s => s.id === currentSessionId ? updatedSession : s));

    const textToSend = input;
    const imgToSend = imageAttachment;
    setInput('');
    setImageAttachment(null);
    setIsLoading(true);

    try {
      const response = await GeminiService.generateChatResponseStream(
        textToSend,
        updatedSession.messages,
        (chunk) => setStreamingText(chunk),
        imgToSend || undefined
      );

      const modelMsg: Message = { id: (Date.now() + 1).toString(), role: 'model', content: response, timestamp: new Date() };
      const finalSession = { ...updatedSession, messages: [...updatedSession.messages, modelMsg] };
      StorageService.saveChatSession(finalSession);
      setSessions(prev => prev.map(s => s.id === currentSessionId ? finalSession : s));
    } catch (e) {
      console.error(e);
    } finally {
      setIsLoading(false);
      setStreamingText('');
    }
  };

  const currentSession = sessions.find(s => s.id === currentSessionId);

  return (
    <div className="flex h-full">
      {/* Sidebar */}
      <div className="w-64 border-r-2 border-[#1A1A1A] flex flex-col shrink-0 bg-[#F2EFEA]">
        <div className="p-4 border-b-2 border-[#1A1A1A] bg-white">
          <button onClick={createNewSession} className="w-full sketch-button py-2 text-[10px] font-black uppercase">+ Nova Auditoria</button>
        </div>
        <div className="flex-1 overflow-y-auto p-2 custom-scrollbar">
          {sessions.map(s => (
            <ChatListItem 
              key={s.id} session={s} isActive={s.id === currentSessionId} 
              onClick={() => setCurrentSessionId(s.id)} 
              onTogglePin={() => StorageService.togglePin(s.id)} 
              onDelete={() => StorageService.deleteChatSession(s.id)} 
            />
          ))}
        </div>
      </div>

      {/* Main */}
      <div className="flex-1 flex flex-col bg-white overflow-hidden">
        <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar bg-[#F2EFEA]/30">
          {currentSession?.messages.map(m => (
            <div key={m.id} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[80%] p-4 sketch-border ${m.role === 'user' ? 'bg-[#1A1A1A] text-white' : 'bg-white text-[#1A1A1A]'}`}>
                {m.image && (
                  <img src={`data:${m.image.mimeType};base64,${m.image.data}`} className="max-w-xs mb-3 sketch-border shadow-none" alt="Anexo" />
                )}
                <div className="text-sm font-medium whitespace-pre-wrap">{m.content}</div>
              </div>
            </div>
          ))}
          {isLoading && (
            <div className="flex justify-start">
              <div className="max-w-[80%] p-4 bg-white sketch-border animate-pulse">
                <div className="text-sm font-medium">{streamingText || "Auditando fluxos..."}</div>
              </div>
            </div>
          )}
        </div>

        <div className="p-4 bg-white border-t-2 border-[#1A1A1A]">
          {imageAttachment && (
            <div className="flex items-center gap-2 mb-2 p-2 bg-[#F2EFEA] border-2 border-[#1A1A1A] w-fit">
              <img src={`data:${imageAttachment.mimeType};base64,${imageAttachment.data}`} className="h-10 w-10 object-cover" />
              <button onClick={() => setImageAttachment(null)} className="text-[10px] font-bold text-rose-500 px-2">Remover</button>
            </div>
          )}
          <div className="relative flex items-center gap-2">
            <button onClick={() => fileInputRef.current?.click()} className="p-3 bg-[#F2EFEA] sketch-border hover:bg-white transition-colors">
              📷
            </button>
            <input type="file" ref={fileInputRef} hidden accept="image/*" onChange={handleImageSelect} />
            <textarea
              value={input} onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
              placeholder="Digite sua dúvida ou envie uma foto para o Google Lens IA..."
              className="flex-1 bg-[#F2EFEA] sketch-border p-3 text-sm outline-none focus:bg-white resize-none h-12"
            />
            <button onClick={handleSend} disabled={isLoading} className="p-3 bg-[#1A1A1A] text-white sketch-border">
              ENVIAR
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

