        const base64 = (re.target?.result as string).split(',')[1];
        setImageAttachment({ data: base64, mimeType: file.type });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSend = async () => {
    if ((!input.trim() && !imageAttachment) || !currentSessionId || isLoading) return;

    const currentSession = sessions.find(s => s.id === currentSessionId);
    if (!currentSession) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      image: imageAttachment || undefined,
      timestamp: new Date()
    };

    const updatedSession = { 
      ...currentSession, 
      messages: [...currentSession.messages, userMsg], 
      lastUpdate: new Date() 
    };

    setSessions(prev => prev.map(s => s.id === currentSessionId ? updatedSession : s));

    const textToSend = input;
    const imgToSend = imageAttachment;

    setInput('');
    setImageAttachment(null);
    setIsLoading(true);

    try {
      const responseText = await GeminiService.generateChatResponseStream(
        textToSend,
        currentSession.messages, // History excluding the latest user message
        (chunk) => setStreamingText(chunk),
        imgToSend || undefined
      );

      const modelMsg: Message = { 
        id: (Date.now() + 1).toString(), 
        role: 'model', 
        content: responseText, 
        timestamp: new Date() 
      };

      const finalSession = { 
        ...updatedSession, 
        messages: [...updatedSession.messages, modelMsg],
        lastUpdate: new Date()
      };

      StorageService.saveChatSession(finalSession);
      setSessions(prev => prev.map(s => s.id === currentSessionId ? finalSession : s));

      if (finalSession.messages.length <= 3) {
        const title = await GeminiService.generateTitle(textToSend || "Análise de Imagem");
        const titledSession = { ...finalSession, title };
        StorageService.saveChatSession(titledSession);
        setSessions(prev => prev.map(s => s.id === currentSessionId ? titledSession : s));
      }

    } catch (e) {
      console.error(e);
      const errorMsg: Message = { 
        id: `err-${Date.now()}`, 
        role: 'model', 
        content: 'Desculpe, ocorreu um erro na análise contábil. Por favor, tente novamente.', 
        timestamp: new Date() 
      };
      setSessions(prev => prev.map(s => s.id === currentSessionId ? { ...s, messages: [...s.messages, errorMsg] } : s));
    } finally {
      setIsLoading(false);
      setStreamingText('');
    }
  };

  const activeSession = sessions.find(s => s.id === currentSessionId);

  const handleDelete = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm('Deseja excluir esta conversa?')) {
      StorageService.deleteChatSession(id);
      const nextSessions = sessions.filter(s => s.id !== id);
      setSessions(nextSessions);
      if (currentSessionId === id) {
        setCurrentSessionId(nextSessions.length > 0 ? nextSessions[0].id : null);
      }
    }
  };

  const handleTogglePin = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    StorageService.togglePin(id);
    setSessions(prev => prev.map(s => s.id === id ? { ...s, isPinned: !s.isPinned } : s));
  };

  return (
    <div className="flex h-full bg-[#F2EFEA]">
      {/* Sidebar */}
      <div className="w-64 border-r-2 border-[#1A1A1A] flex flex-col shrink-0">
        <div className="p-4 border-b-2 border-[#1A1A1A] bg-white">
          <button onClick={createNewSession} className="w-full sketch-button py-2 text-[10px] font-black uppercase">+ Nova Auditoria</button>
        </div>
        <div className="flex-1 overflow-y-auto p-2 custom-scrollbar">
          {sessions.map(s => (
            <ChatListItem 
              key={s.id} 
              session={s} 
              isActive={s.id === currentSessionId} 
              onClick={() => setCurrentSessionId(s.id)}
              onTogglePin={handleTogglePin}
              onDelete={handleDelete}
            />
          ))}
        </div>
      </div>

      {/* Main Chat Area */}
      <div className="flex-1 flex flex-col min-w-0 bg-white relative">
        {activeSession ? (
          <>
            <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar bg-[#F2EFEA]/30">
              {activeSession.messages.map(m => (
                <div key={m.id} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[85%] p-4 sketch-border ${m.role === 'user' ? 'bg-[#1A1A1A] text-white' : 'bg-white text-[#1A1A1A]'}`}>
                    {m.image && (
                      <div className="mb-3">
                         <img 
                          src={`data:${m.image.mimeType};base64,${m.image.data}`} 
                          className="max-w-full rounded border-2 border-[#1A1A1A] max-h-64 object-contain" 
                          alt="Anexo contábil" 
                        />
                      </div>
                    )}
                    <div className="text-sm font-medium whitespace-pre-wrap">{m.content}</div>
                    <div className={`text-[8px] font-bold mt-2 opacity-50 uppercase ${m.role === 'user' ? 'text-right' : 'text-left'}`}>
                       {new Date(m.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                    </div>
                  </div>
                </div>
              ))}
              {isLoading && (
                <div className="flex justify-start">
                  <div className="max-w-[85%] p-4 bg-white text-[#1A1A1A] sketch-border animate-pulse">
                    <div className="flex items-center gap-2 mb-2">
                       <div className="w-2 h-2 bg-emerald-500 rounded-full animate-ping" />
                       <span className="text-[10px] font-black uppercase">Processando...</span>
                    </div>
                    <div className="text-sm font-medium">{streamingText || "Analisando conformidade..."}</div>
                  </div>
                </div>
              )}
            </div>

            <div className="p-4 bg-white border-t-2 border-[#1A1A1A]">
              {imageAttachment && (
                <div className="mb-3 p-2 bg-[#F2EFEA] border-2 border-[#1A1A1A] inline-flex items-center gap-2 animate-in slide-in-from-bottom-2">
                   <img 
                    src={`data:${imageAttachment.mimeType};base64,${imageAttachment.data}`} 
                    className="h-12 w-12 object-cover border border-[#1A1A1A]" 
                    alt="Preview"
                  />
                  <button onClick={() => setImageAttachment(null)} className="text-[10px] font-black text-rose-500 uppercase px-2 hover:underline">Remover</button>
                </div>
              )}
              <div className="flex items-end gap-2">
                <button 
                  onClick={() => fileInputRef.current?.click()}
                  className="p-3 bg-[#F2EFEA] sketch-border hover:bg-white transition-colors"
                  title="Anexar Foto (Lens)"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z" />
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 13a3 3 0 11-6 0 3 3 0 016 0z" />
                  </svg>
                </button>
                <input 
                  type="file" 
                  ref={fileInputRef} 
                  hidden 
                  accept="image/*" 
                  onChange={handleImageSelect} 
                />
                <textarea
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' && !e.shiftKey) {
                      e.preventDefault();
                      handleSend();
                    }
                  }}
                  placeholder="Pergunte sobre impostos ou anexe uma nota..."
                  className="flex-1 bg-[#F2EFEA] sketch-border p-3 text-sm outline-none focus:bg-white resize-none h-12 min-h-[48px] max-h-32"
                />
                <button 
                  onClick={handleSend}
                  disabled={isLoading || (!input.trim() && !imageAttachment)}
                  className="bg-[#1A1A1A] text-white p-3 sketch-border disabled:opacity-50 transition-all active:scale-95"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
                  </svg>
                </button>
              </div>
            </div>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center bg-[#F2EFEA]">
             <div className="w-20 h-20 bg-white sketch-border flex items-center justify-center text-4xl mb-6">🔍</div>
             <h3 className="text-xl font-black uppercase mb-4">Nenhuma Auditoria Selecionada</h3>
             <button onClick={createNewSession} className="sketch-button px-8 py-3 text-xs font-black uppercase">+ Iniciar Consulta</button>
          </div>
        )}
      </div>
    </div>
  );
};

