import { Document, User, ChatSession, SyncStatus } from '../types.ts';

const DOCS_KEY = 'finan_gpt_docs';
const USER_KEY = 'finan_gpt_user';
const CHATS_KEY = 'finan_gpt_chats';
const FINANCIAL_CHATS_KEY = 'finan_gpt_financial_chats';
const STUDENT_CHATS_KEY = 'finan_gpt_student_chats';

export const StorageService = {
  // Documents
  getDocuments: (): Document[] => {
    try {
      const data = localStorage.getItem(DOCS_KEY);
      if (!data) return [];
      const docs = JSON.parse(data);
      return docs.map((d: any) => ({
        ...d,
        uploadDate: new Date(d.uploadDate),
        metadata: {
          ...d.metadata,
          lastSync: d.metadata?.lastSync ? new Date(d.metadata.lastSync) : undefined
        }
      }));
    } catch (e) {
      console.error("Error reading documents", e);
      return [];
    }
  },

  saveDocument: (doc: Document) => {
    const docs = StorageService.getDocuments();
    docs.push(doc);
    localStorage.setItem(DOCS_KEY, JSON.stringify(docs));
  },

  deleteDocument: (id: string) => {
    const docs = StorageService.getDocuments().filter(d => d.id !== id);
    localStorage.setItem(DOCS_KEY, JSON.stringify(docs));
  },

  // User
  getUser: (): User | null => {
    try {
      const data = localStorage.getItem(USER_KEY);
      return data ? JSON.parse(data) : null;
    } catch (e) {
      return null;
    }
  },

  setUser: (user: User) => {
    localStorage.setItem(USER_KEY, JSON.stringify(user));
  },

  clearAll: () => {
    localStorage.removeItem(USER_KEY);
  },

  syncWithCloud: () => {
    window.dispatchEvent(new CustomEvent('sync_status_change', { detail: 'syncing' }));
    setTimeout(() => {
      window.dispatchEvent(new CustomEvent('sync_status_change', { detail: 'synced' }));
      window.dispatchEvent(new CustomEvent('session_synced', { detail: 'all' }));
    }, 1500);
  },

  // Generic Session Loader
  _getSessions: (key: string): ChatSession[] => {
    const data = localStorage.getItem(key);
    if (!data) return [];
    try {
      const parsed = JSON.parse(data);
      return parsed.map((s: any) => ({
        ...s,
        lastUpdate: new Date(s.lastUpdate),
        messages: (s.messages || []).map((m: any) => ({ 
          ...m, 
          timestamp: new Date(m.timestamp) 
        }))
      }));
    } catch (e) {
      return [];
    }
  },

  // Chat Sessions (Accounting/Audit)
  getChatSessions: (includeDeleted: boolean = false): ChatSession[] => {
    const sessions = StorageService._getSessions(CHATS_KEY);
    if (includeDeleted) return sessions;
    return sessions.filter(s => !s.deletedAt);
  },

  saveChatSession: (session: ChatSession) => {
    const sessions = StorageService.getChatSessions(true);
    const index = sessions.findIndex(s => s.id === session.id);
    if (index >= 0) sessions[index] = session;
    else sessions.unshift(session);
    localStorage.setItem(CHATS_KEY, JSON.stringify(sessions));
    window.dispatchEvent(new CustomEvent('session_synced', { detail: session.id }));
  },

  deleteChatSession: (id: string) => {
    const sessions = StorageService.getChatSessions(true);
    const session = sessions.find(s => s.id === id);
    if (session) {
      session.deletedAt = new Date();
      StorageService.saveChatSession(session);
    }
  },

  togglePin: (id: string) => {
    const sessions = StorageService.getChatSessions(true);
    const session = sessions.find(s => s.id === id);
    if (session) {
      session.isPinned = !session.isPinned;
      localStorage.setItem(CHATS_KEY, JSON.stringify(sessions));
    }
  },

  // FINANCIAL AI SESSIONS
  getFinancialSessions: (): ChatSession[] => {
    return StorageService._getSessions(FINANCIAL_CHATS_KEY);
  },

  saveFinancialSession: (session: ChatSession) => {
    const sessions = StorageService.getFinancialSessions();
    const index = sessions.findIndex(s => s.id === session.id);
    if (index >= 0) sessions[index] = session;
    else sessions.unshift(session);
    localStorage.setItem(FINANCIAL_CHATS_KEY, JSON.stringify(sessions));
    window.dispatchEvent(new CustomEvent('financial_session_synced', { detail: session.id }));
  },

  deleteFinancialSession: (id: string) => {
    const sessions = StorageService.getFinancialSessions().filter(s => s.id !== id);
    localStorage.setItem(FINANCIAL_CHATS_KEY, JSON.stringify(sessions));
  },

  // STUDENT AREA SESSIONS
  getStudentSessions: (): ChatSession[] => {
    return StorageService._getSessions(STUDENT_CHATS_KEY);
  },

  saveStudentSession: (session: ChatSession) => {
    const sessions = StorageService.getStudentSessions();
    const index = sessions.findIndex(s => s.id === session.id);
    if (index >= 0) sessions[index] = session;
    else sessions.unshift(session);
    localStorage.setItem(STUDENT_CHATS_KEY, JSON.stringify(sessions));
    window.dispatchEvent(new CustomEvent('student_session_synced', { detail: session.id }));
  },

  deleteStudentSession: (id: string) => {
    const sessions = StorageService.getStudentSessions().filter(s => s.id !== id);
    localStorage.setItem(STUDENT_CHATS_KEY, JSON.stringify(sessions));
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { Message, ChatSession } from '../types.ts';
import { GeminiService } from '../services/geminiService.ts';
import { StorageService } from '../services/storage.ts';

const ChatListItem: React.FC<{
  session: ChatSession;
  isActive: boolean;
  onClick: () => void;
  onTogglePin: (e: React.MouseEvent, id: string) => void;
  onDelete: (e: React.MouseEvent, id: string) => void;
}> = ({ session, isActive, onClick, onTogglePin, onDelete }) => (
  <div 
    onClick={onClick}
    className={`group relative flex items-center gap-3 p-3 cursor-pointer transition-all border-2 mb-2 ${isActive ? 'bg-[#1A1A1A] text-white border-[#1A1A1A] translate-x-1' : 'bg-white text-[#1A1A1A] border-transparent hover:bg-[#F2EFEA]'}`}
  >
    <div className={`w-2 h-2 rounded-full ${isActive ? 'bg-emerald-400 animate-pulse' : 'bg-gray-300'}`} />
    <div className="flex-1 min-w-0">
      <h4 className="text-[10px] font-black uppercase truncate">{session.title || 'Nova Consulta'}</h4>
      <p className="text-[8px] font-bold uppercase opacity-60">{new Date(session.lastUpdate).toLocaleDateString()}</p>
    </div>
    <div className="flex gap-1 opacity-0 group-hover:opacity-100">
      <button onClick={(e) => onTogglePin(e, session.id)} className={`p-1 ${session.isPinned ? 'text-amber-400' : 'text-gray-400'}`}>
        ★
      </button>
      <button onClick={(e) => onDelete(e, session.id)} className="p-1 text-rose-500">
        ✕
      </button>
    </div>
  </div>
);

const ChatInterface: React.FC = () => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [streamingText, setStreamingText] = useState('');
  const [imageAttachment, setImageAttachment] = useState<{data: string, mimeType: string} | null>(null);
  const [showListOnMobile, setShowListOnMobile] = useState(true);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const loaded = StorageService.getChatSessions();
    setSessions(loaded);
    if (loaded.length > 0 && !currentSessionId) {
      setCurrentSessionId(loaded[0].id);
      if (window.innerWidth >= 1024) setShowListOnMobile(false);
    }
  }, []);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [sessions, streamingText]);

  const createNewSession = () => {
    const newSession: ChatSession = {
      id: Date.now().toString(),
      title: 'IA CONTÁBIL SÊNIOR',
      messages: [{ id: 'init', role: 'model', content: 'Auditor FinaIGPT pronto. Como posso analisar sua saúde contábil ou fiscal hoje?', timestamp: new Date() }],
      lastUpdate: new Date(),
      updatedAt: new Date().toISOString(),
      version: 1
    };
    StorageService.saveChatSession(newSession);
    setSessions([newSession, ...sessions]);
    setCurrentSessionId(newSession.id);
    setShowListOnMobile(false);
  };

  const handleSelectSession = (id: string) => {
    setCurrentSessionId(id);
    setShowListOnMobile(false);
  };

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (re) => {
        const base64 = (re.target?.result as string).split(',')[1];
        setImageAttachment({ data: base64, mimeType: file.type });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSend = async () => {
    if ((!input.trim() && !imageAttachment) || !currentSessionId || isLoading) return;

    const currentSession = sessions.find(s => s.id === currentSessionId);
    if (!currentSession) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      image: imageAttachment || undefined,
      timestamp: new Date()
    };

    const updatedSession = { ...currentSession, messages: [...currentSession.messages, userMsg], lastUpdate: new Date() };
    setSessions(prev => prev.map(s => s.id === currentSessionId ? updatedSession : s));

    const textToSend = input;
    const imgToSend = imageAttachment;
    setInput('');
    setImageAttachment(null);
    setIsLoading(true);

    try {
      const response = await GeminiService.generateChatResponseStream(
        textToSend,
        updatedSession.messages,
        (chunk) => setStreamingText(chunk),
        imgToSend || undefined
      );

      const modelMsg: Message = { id: (Date.now() + 1).toString(), role: 'model', content: response, timestamp: new Date() };
      const finalSession = { ...updatedSession, messages: [...updatedSession.messages, modelMsg] };
      StorageService.saveChatSession(finalSession);
      setSessions(prev => prev.map(s => s.id === currentSessionId ? finalSession : s));

      if (finalSession.messages.length <= 3) {
        const title = await GeminiService.generateTitle(textToSend || "Análise Documental");
        const titledSession = { ...finalSession, title };
        StorageService.saveChatSession(titledSession);
        setSessions(prev => prev.map(s => s.id === currentSessionId ? titledSession : s));
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsLoading(false);
      setStreamingText('');
    }
  };

  const currentSession = sessions.find(s => s.id === currentSessionId);

  return (
    <div className="flex h-full overflow-hidden bg-[#F2EFEA]">
      {/* Sidebar / History List */}
      <div className={`
        ${showListOnMobile ? 'flex' : 'hidden'} lg:flex
        w-full lg:w-72 border-r-2 border-[#1A1A1A] flex-col shrink-0 bg-[#F2EFEA]
      `}>
        <div className="p-4 border-b-2 border-[#1A1A1A] bg-white">
          <button onClick={createNewSession} className="w-full sketch-button py-3 text-[10px] font-black uppercase">+ Iniciar Auditoria</button>
        </div>
        <div className="flex-1 overflow-y-auto p-2 custom-scrollbar">
          {sessions.length === 0 ? (
            <div className="p-10 text-center opacity-30 text-[10px] font-black uppercase">Sem Histórico</div>
          ) : (
            sessions.map(s => (
              <ChatListItem 
                key={s.id} session={s} isActive={s.id === currentSessionId} 
                onClick={() => handleSelectSession(s.id)} 
                onTogglePin={(e, id) => { e.stopPropagation(); StorageService.togglePin(id); setSessions(StorageService.getChatSessions()); }} 
                onDelete={(e, id) => { e.stopPropagation(); if(confirm('Excluir?')){ StorageService.deleteChatSession(id); setSessions(StorageService.getChatSessions()); } }} 
              />
            ))
          )}
        </div>
      </div>

      {/* Chat Conversation */}
      <div className={`
        ${!showListOnMobile ? 'flex' : 'hidden'} lg:flex
        flex-1 flex-col bg-white overflow-hidden relative
