        {currentSession ? (
          <>
            {/* Mobile Nav Header */}
            <div className="lg:hidden p-3 bg-[#1A1A1A] text-white flex items-center gap-3">
              <button onClick={() => setShowListOnMobile(true)} className="p-2 border border-white/20">
