                  onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                  placeholder="Dúvida ou Foto (Lens)..."
                  className="flex-1 bg-[#F2EFEA] sketch-border p-3 text-sm outline-none focus:bg-white resize-none h-12 min-h-[48px]"
                />
                <button onClick={handleSend} disabled={isLoading} className="p-3 bg-[#1A1A1A] text-white sketch-border disabled:opacity-50">
                   <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
                </button>
              </div>
            </div>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center p-10 opacity-30 text-center">
             <div className="text-6xl mb-4">🔍</div>
             <p className="text-xs font-black uppercase">Selecione uma auditoria ou inicie uma nova.</p>
          </div>
        )}
      </div>
