    const sessions = StorageService.getFinancialSessions();
    const index = sessions.findIndex(s => s.id === session.id);
    if (index >= 0) sessions[index] = session;
    else sessions.unshift(session);
    localStorage.setItem(FINANCIAL_CHATS_KEY, JSON.stringify(sessions));
    window.dispatchEvent(new CustomEvent('financial_session_synced', { detail: session.id }));
  },

  deleteFinancialSession: (id: string) => {
    const sessions = StorageService.getFinancialSessions().filter(s => s.id !== id);
    localStorage.setItem(FINANCIAL_CHATS_KEY, JSON.stringify(sessions));
  },

  toggleFinancialPin: (id: string) => {
    const sessions = StorageService.getFinancialSessions();
    const session = sessions.find(s => s.id === id);
    if (session) {
      session.isPinned = !session.isPinned;
      localStorage.setItem(FINANCIAL_CHATS_KEY, JSON.stringify(sessions));
    }
  },

  // STUDENT SESSIONS
  getStudentSessions: (): ChatSession[] => {
    return StorageService._getSessions(STUDENT_CHATS_KEY);
  },

  saveStudentSession: (session: ChatSession) => {
    const sessions = StorageService.getStudentSessions();
    const index = sessions.findIndex(s => s.id === session.id);
    if (index >= 0) sessions[index] = session;
    else sessions.unshift(session);
    localStorage.setItem(STUDENT_CHATS_KEY, JSON.stringify(sessions));
    window.dispatchEvent(new CustomEvent('student_session_synced', { detail: session.id }));
  },

  deleteStudentSession: (id: string) => {
    const sessions = StorageService.getStudentSessions().filter(s => s.id !== id);
    localStorage.setItem(STUDENT_CHATS_KEY, JSON.stringify(sessions));
  },

  toggleStudentPin: (id: string) => {
    const sessions = StorageService.getStudentSessions();
    const session = sessions.find(s => s.id === id);
    if (session) {
      session.isPinned = !session.isPinned;
      localStorage.setItem(STUDENT_CHATS_KEY, JSON.stringify(sessions));
    }
  }
};

