import React, { useState, useRef, useEffect } from 'react';
import { Message, ChatSession } from '../types.ts';
import { GeminiService } from '../services/geminiService.ts';
import { StorageService } from '../services/storage.ts';

const ChatListItem: React.FC<{
  session: ChatSession;
  isActive: boolean;
  onClick: () => void;
  onTogglePin: (e: React.MouseEvent, id: string) => void;
  onDelete: (e: React.MouseEvent, id: string) => void;
}> = ({ session, isActive, onClick, onTogglePin, onDelete }) => (
  <div 
    onClick={onClick}
    className={`group relative flex items-center gap-3 p-3 cursor-pointer transition-all border-2 mb-2 ${isActive ? 'bg-[#1A1A1A] text-white border-[#1A1A1A] translate-x-1' : 'bg-white text-[#1A1A1A] border-transparent hover:bg-[#F2EFEA]'}`}
  >
    <div className={`w-2 h-2 rounded-full ${isActive ? 'bg-emerald-400 animate-pulse' : 'bg-gray-300'}`} />
    <div className="flex-1 min-w-0">
      <h4 className="text-[10px] font-black uppercase truncate">{session.title || 'Nova Análise'}</h4>
      <p className="text-[8px] font-bold uppercase opacity-60">{new Date(session.lastUpdate).toLocaleDateString()}</p>
    </div>
    <div className="flex gap-1 opacity-0 group-hover:opacity-100">
      <button onClick={(e) => onTogglePin(e, session.id)} className={`p-1 ${session.isPinned ? 'text-amber-400' : 'text-gray-400'}`}>
        ★
      </button>
      <button onClick={(e) => onDelete(e, session.id)} className="p-1 text-rose-500">
        ✕
      </button>
    </div>
  </div>
);

const FinancialAI: React.FC = () => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [streamingText, setStreamingText] = useState('');
  const [imageAttachment, setImageAttachment] = useState<{data: string, mimeType: string} | null>(null);
  const [showListOnMobile, setShowListOnMobile] = useState(true);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const loaded = StorageService.getFinancialSessions();
    setSessions(loaded);
    if (loaded.length > 0 && !currentSessionId) {
      setCurrentSessionId(loaded[0].id);
      if (window.innerWidth >= 1024) setShowListOnMobile(false);
    }
  }, []);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [sessions, streamingText]);

  const createNewSession = () => {
    const newSession: ChatSession = {
      id: Date.now().toString(),
      title: 'ANALISTA CFA GPT',
      messages: [{ id: 'init', role: 'model', content: 'Analista CFA pronto. Envie um gráfico ou pergunte sobre ativos para análise técnica e fundamentalista.', timestamp: new Date() }],
      lastUpdate: new Date(),
      updatedAt: new Date().toISOString(),
      version: 1
    };
    StorageService.saveFinancialSession(newSession);
    setSessions([newSession, ...sessions]);
    setCurrentSessionId(newSession.id);
    setShowListOnMobile(false);
  };

  const handleSelectSession = (id: string) => {
    setCurrentSessionId(id);
    setShowListOnMobile(false);
  };

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (re) => {
        const base64 = (re.target?.result as string).split(',')[1];
        setImageAttachment({ data: base64, mimeType: file.type });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSend = async () => {
    if ((!input.trim() && !imageAttachment) || !currentSessionId || isLoading) return;

    const currentSession = sessions.find(s => s.id === currentSessionId);
    if (!currentSession) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      image: imageAttachment || undefined,
      timestamp: new Date()
    };

    const updatedSession = { ...currentSession, messages: [...currentSession.messages, userMsg], lastUpdate: new Date() };
    setSessions(prev => prev.map(s => s.id === currentSessionId ? updatedSession : s));

    const textToSend = input;
    const imgToSend = imageAttachment;
    setInput('');
    setImageAttachment(null);
    setIsLoading(true);

    try {
      const response = await GeminiService.generateFinancialAnalysisStream(
        textToSend,
        updatedSession.messages,
        (chunk) => setStreamingText(chunk),
        imgToSend || undefined
      );

      const modelMsg: Message = { id: (Date.now() + 1).toString(), role: 'model', content: response, timestamp: new Date() };
      const finalSession = { ...updatedSession, messages: [...updatedSession.messages, modelMsg] };
      StorageService.saveFinancialSession(finalSession);
      setSessions(prev => prev.map(s => s.id === currentSessionId ? finalSession : s));

      if (finalSession.messages.length <= 3) {
        const title = await GeminiService.generateTitle(textToSend || "Análise CFA");
        const titledSession = { ...finalSession, title };
        StorageService.saveFinancialSession(titledSession);
        setSessions(prev => prev.map(s => s.id === currentSessionId ? titledSession : s));
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsLoading(false);
      setStreamingText('');
    }
  };

  const currentSession = sessions.find(s => s.id === currentSessionId);

  return (
    <div className="flex h-full overflow-hidden bg-[#F2EFEA]">
      {/* Sidebar de Histórico */}
      <div className={`
        ${showListOnMobile ? 'flex' : 'hidden'} lg:flex
        w-full lg:w-72 border-r-2 border-[#1A1A1A] flex-col shrink-0 bg-[#F2EFEA]
      `}>
        <div className="p-4 border-b-2 border-[#1A1A1A] bg-white">
          <button onClick={createNewSession} className="w-full sketch-button py-3 text-[10px] font-black uppercase tracking-widest">+ Nova Análise</button>
        </div>
        <div className="flex-1 overflow-y-auto p-2 custom-scrollbar">
          {sessions.length === 0 ? (
            <div className="p-10 text-center opacity-30 text-[10px] font-black uppercase">Sem Histórico</div>
          ) : (
            sessions.map(s => (
              <ChatListItem 
                key={s.id} 
                session={s} 
                isActive={s.id === currentSessionId} 
                onClick={() => handleSelectSession(s.id)}
                onTogglePin={(e, id) => { e.stopPropagation(); StorageService.toggleFinancialPin(id); setSessions(StorageService.getFinancialSessions()); }}
                onDelete={(e, id) => { e.stopPropagation(); if(confirm('Excluir?')){ StorageService.deleteFinancialSession(id); setSessions(StorageService.getFinancialSessions()); } }}
              />
            ))
          )}
        </div>
      </div>

      {/* Janela de Chat */}
      <div className={`
        ${!showListOnMobile ? 'flex' : 'hidden'} lg:flex
        flex-1 flex-col bg-white overflow-hidden relative
      `}>
        {currentSession ? (
          <>
            <div className="lg:hidden p-3 bg-[#1A1A1A] text-white flex items-center gap-3">
              <button onClick={() => setShowListOnMobile(true)} className="p-2 border border-white/20">
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
              </button>
              <h2 className="text-[10px] font-black uppercase truncate">{currentSession.title}</h2>
            </div>

            <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 lg:p-6 space-y-6 custom-scrollbar bg-[#F2EFEA]/30">
              {currentSession.messages.map(m => (
                <div key={m.id} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[90%] lg:max-w-[80%] p-4 sketch-border ${m.role === 'user' ? 'bg-[#1A1A1A] text-white' : 'bg-white text-[#1A1A1A]'}`}>
                    {m.image && <img src={`data:${m.image.mimeType};base64,${m.image.data}`} className="max-w-full rounded mb-3 border-2 border-[#1A1A1A]" alt="attachment" />}
                    <div className="text-sm font-medium whitespace-pre-wrap">{m.content}</div>
                  </div>
                </div>
              ))}
              {isLoading && (
                <div className="flex justify-start">
                  <div className="max-w-[80%] p-4 bg-white sketch-border animate-pulse">
                    <div className="text-sm font-medium">{streamingText || "Analisando mercado..."}</div>
                  </div>
                </div>
              )}
            </div>

            <div className="p-4 bg-white border-t-2 border-[#1A1A1A] pb-safe">
              {imageAttachment && (
                <div className="mb-2 p-2 bg-[#F2EFEA] border-2 border-[#1A1A1A] flex items-center gap-2 w-fit">
                  <img src={`data:${imageAttachment.mimeType};base64,${imageAttachment.data}`} className="h-10 w-10 object-cover" alt="preview" />
                  <button onClick={() => setImageAttachment(null)} className="text-[8px] font-black text-rose-500 uppercase">Remover</button>
                </div>
              )}
              <div className="flex items-end gap-2">
                <button onClick={() => fileInputRef.current?.click()} className="p-3 bg-[#F2EFEA] sketch-border hover:bg-white transition-colors">📷</button>
                <input type="file" ref={fileInputRef} hidden accept="image/*" onChange={handleImageSelect} />
                <textarea
                  value={input} onChange={(e) => setInput(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                  placeholder="Pergunta ou Gráfico (LENS)..."
                  className="flex-1 bg-[#F2EFEA] sketch-border p-3 text-sm outline-none focus:bg-white resize-none h-12 min-h-[48px]"
                />
                <button onClick={handleSend} disabled={isLoading} className="p-3 bg-[#1A1A1A] text-white sketch-border disabled:opacity-50">
                   <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
                </button>
              </div>
            </div>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center p-10 opacity-30 text-center">
             <div className="text-6xl mb-4">📈</div>
             <p className="text-xs font-black uppercase">Selecione uma análise financeira ou inicie uma nova.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default FinancialAI;

