import React, { useState, useEffect } from 'react';
import { ViewState, User } from './types.ts';
import { StorageService } from './services/storage.ts';
import Sidebar from './components/Sidebar.tsx';
import Dashboard from './components/Dashboard.tsx';
import ChatInterface from './components/ChatInterface.tsx';
import FinancialAI from './components/FinancialAI.tsx';
import DocumentManager from './components/DocumentManager.tsx';
import AccountingView from './components/AccountingView.tsx';
import Reports from './components/Reports.tsx';
import TrashBin from './components/TrashBin.tsx';
import FloatingAssistant from './components/FloatingAssistant.tsx';
import StudentArea from './components/StudentArea.tsx';

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>(ViewState.Dashboard);
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const savedUser = StorageService.getUser();
    if (savedUser) {
      setUser(savedUser);
      StorageService.syncWithCloud();
    }
    setLoading(false);
  }, []);

  const handleLogin = () => {
    const mockUser: User = {
      id: 'usr_' + Math.random().toString(36).substr(2, 9),
      name: 'Auditor Sênior',
      email: 'contato@finaigpt.ai',
      avatar: `https://api.dicebear.com/7.x/bottts-neutral/svg?seed=${Math.random()}`
    };
    StorageService.setUser(mockUser);
    setUser(mockUser);
    StorageService.syncWithCloud();
  };

  const handleLogout = () => {
    if (window.confirm("Deseja realmente encerrar a sessão do terminal?")) {
      StorageService.clearAll();
      setUser(null);
      setView(ViewState.Dashboard);
    }
  };

  if (loading) {
    return (
      <div className="h-full w-full flex items-center justify-center bg-[#F2EFEA]">
        <div className="flex flex-col items-center gap-4">
          <div className="w-12 h-12 border-4 border-[#1A1A1A] border-t-emerald-500 rounded-full animate-spin"></div>
          <p className="text-[10px] font-black uppercase tracking-[0.2em]">Inicializando Terminal...</p>
        </div>
      </div>
    );
  }

  if (!user) {
    return (
      <div className="h-full w-full flex items-center justify-center bg-[#F2EFEA] p-6">
        <div className="max-w-md w-full bg-white sketch-border p-10 text-center animate-in zoom-in duration-300">
          <div className="w-20 h-20 bg-[#1A1A1A] text-white flex items-center justify-center text-3xl font-black sketch-border mx-auto mb-8 shadow-[6px_6px_0px_0px_#4285F4]">
            F
          </div>
          <h1 className="text-2xl font-black uppercase mb-2 tracking-tighter">FinAIGPT Terminal</h1>
          <p className="text-[10px] font-bold text-[#7A7A7A] uppercase tracking-widest mb-10 leading-relaxed">
            Inteligência Artificial para Contabilidade <br/> & Gestão Financeira RAG
          </p>
          <button 
            onClick={handleLogin}
            className="w-full bg-[#1A1A1A] text-white py-4 px-6 text-[10px] font-black uppercase tracking-[0.2em] sketch-button"
          >
            Acessar Terminal
          </button>
          <p className="mt-8 text-[7px] font-black opacity-30 uppercase tracking-[0.3em]">Build v2.5.0-STABLE • RSA-256</p>
        </div>
      </div>
    );
  }

  const renderView = () => {
    switch (view) {
      case ViewState.Dashboard: return <Dashboard />;
      case ViewState.Chat: return <ChatInterface />;
      case ViewState.FinancialAI: return <FinancialAI />;
      case ViewState.StudentArea: return <StudentArea />;
      case ViewState.Documents: return <DocumentManager />;
      case ViewState.Accounting: return <AccountingView />;
      case ViewState.Reports: return <Reports />;
      case ViewState.Trash: return <TrashBin />;
      default: return <Dashboard />;
    }
  };

  return (
    <div className="flex h-full w-full bg-[#F2EFEA] overflow-hidden">
      {/* Mobile Menu Trigger - Top Left to avoid floating assistant */}
      <button 
        onClick={() => setIsMobileMenuOpen(true)}
        className="lg:hidden fixed top-4 left-4 z-[60] p-3 bg-white sketch-border active:scale-95 transition-all"
        aria-label="Abrir Menu"
      >
        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 6h16M4 12h16M4 18h16" />
        </svg>
      </button>

      <Sidebar 
        currentView={view} 
        setView={setView} 
        user={user} 
        onLogout={handleLogout} 
        isOpen={isMobileMenuOpen}
        onClose={() => setIsMobileMenuOpen(false)}
      />

      <main className="flex-1 h-full overflow-hidden relative">
        {renderView()}
        <FloatingAssistant />
      </main>
    </div>
  );
};

