              candles.map((c, i) => {
                const height = ((c.close - Math.min(...candles.map(v => v.low))) / (Math.max(...candles.map(v => v.high)) - Math.min(...candles.map(v => v.low)))) * 100;
                return (
                  <div key={i} className="flex-1 flex flex-col justify-end items-center h-full group/bar">
                    <div 
