);

const FinancialAI: React.FC = () => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [streamingText, setStreamingText] = useState('');
  const [imageAttachment, setImageAttachment] = useState<{data: string, mimeType: string} | null>(null);
  const [showListOnMobile, setShowListOnMobile] = useState(true);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const loaded = StorageService.getFinancialSessions();
    setSessions(loaded);
    if (loaded.length > 0 && !currentSessionId) {
      setCurrentSessionId(loaded[0].id);
      if (window.innerWidth >= 1024) setShowListOnMobile(false);
    }
  }, []);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [sessions, streamingText]);

  const createNewSession = () => {
    const newSession: ChatSession = {
      id: Date.now().toString(),
      title: 'ANALISTA CFA GPT',
      messages: [{ id: 'init', role: 'model', content: 'Analista CFA pronto. Envie um gráfico ou pergunte sobre ativos para análise técnica e fundamentalista.', timestamp: new Date() }],
      lastUpdate: new Date(),
      updatedAt: new Date().toISOString(),
      version: 1
    };
    StorageService.saveFinancialSession(newSession);
    setSessions([newSession, ...sessions]);
    setCurrentSessionId(newSession.id);
    setShowListOnMobile(false);
  };

  const handleSelectSession = (id: string) => {
    setCurrentSessionId(id);
    setShowListOnMobile(false);
  };

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (re) => {
        const base64 = (re.target?.result as string).split(',')[1];
        setImageAttachment({ data: base64, mimeType: file.type });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSend = async () => {
    if ((!input.trim() && !imageAttachment) || !currentSessionId || isLoading) return;

    const currentSession = sessions.find(s => s.id === currentSessionId);
    if (!currentSession) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      image: imageAttachment || undefined,
      timestamp: new Date()
    };

    const updatedSession = { ...currentSession, messages: [...currentSession.messages, userMsg], lastUpdate: new Date() };
    setSessions(prev => prev.map(s => s.id === currentSessionId ? updatedSession : s));

    const textToSend = input;
    const imgToSend = imageAttachment;
    setInput('');
    setImageAttachment(null);
    setIsLoading(true);

    try {
      const response = await GeminiService.generateFinancialAnalysisStream(
        textToSend,
        updatedSession.messages,
        (chunk) => setStreamingText(chunk),
        imgToSend || undefined
      );

      const modelMsg: Message = { id: (Date.now() + 1).toString(), role: 'model', content: response, timestamp: new Date() };
      const finalSession = { ...updatedSession, messages: [...updatedSession.messages, modelMsg] };
      StorageService.saveFinancialSession(finalSession);
      setSessions(prev => prev.map(s => s.id === currentSessionId ? finalSession : s));

      if (finalSession.messages.length <= 3) {
        const title = await GeminiService.generateTitle(textToSend || "Análise CFA");
        const titledSession = { ...finalSession, title };
        StorageService.saveFinancialSession(titledSession);
        setSessions(prev => prev.map(s => s.id === currentSessionId ? titledSession : s));
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsLoading(false);
      setStreamingText('');
    }
  };

  const currentSession = sessions.find(s => s.id === currentSessionId);

  return (
    <div className="flex h-full bg-[#F2EFEA] overflow-hidden">
      {/* Session Sidebar */}
      <div className={`
        ${showListOnMobile ? 'flex' : 'hidden'} lg:flex
        w-full lg:w-80 border-r border-gray-100 flex-col bg-white shrink-0
      `}>
        <div className="p-6 border-b border-gray-50">
          <button onClick={createNewSession} className="modern-button w-full shadow-lg shadow-black/10">+ Nova Análise CFA</button>
        </div>
        <div className="flex-1 overflow-y-auto p-4 custom-scrollbar bg-gray-50/30">
          <h3 className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em] mb-4 px-2">Estratégias & Portfólio</h3>
          {sessions.length === 0 ? (
            <div className="p-10 text-center opacity-30 text-[10px] font-bold uppercase tracking-widest">Sem análises ativas</div>
          ) : (
            sessions.map(s => (
              <ChatListItem 
                key={s.id} session={s} isActive={s.id === currentSessionId} 
                onClick={() => handleSelectSession(s.id)} 
                onTogglePin={(e, id) => { e.stopPropagation(); StorageService.toggleFinancialPin(id); setSessions(StorageService.getFinancialSessions()); }} 
                onDelete={(e, id) => { e.stopPropagation(); if(confirm('Excluir?')){ StorageService.deleteFinancialSession(id); setSessions(StorageService.getFinancialSessions()); } }} 
              />
            ))
          )}
        </div>
      </div>

      {/* Main Content Area */}
      <div className={`
        ${!showListOnMobile ? 'flex' : 'hidden'} lg:flex
        flex-1 flex-col bg-[#F2EFEA] overflow-hidden relative
      `}>
        {currentSession ? (
          <>
            {/* Header */}
            <header className="p-6 bg-white border-b border-gray-100 flex items-center justify-between">
              <div className="flex items-center gap-4">
                <button onClick={() => setShowListOnMobile(true)} className="lg:hidden p-2 text-gray-400">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" /></svg>
                </button>
                <div>
                  <h2 className="text-sm font-bold text-[#1A1A1A] tracking-tight">{currentSession.title}</h2>
                  <p className="text-[10px] font-medium text-blue-500 uppercase tracking-widest flex items-center gap-1.5 mt-0.5">
                    <span className="w-1 h-1 bg-blue-500 rounded-full"></span> Analista CFA Ativo
                  </p>
                </div>
              </div>
            </header>

            {/* Conversation Flow */}
            <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-8 custom-scrollbar">
              {currentSession.messages.map(m => (
                <div key={m.id} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`
                    max-w-[85%] lg:max-w-[70%] p-5 shadow-sm
                    ${m.role === 'user' 
                      ? 'bg-[#1A1A1A] text-white rounded-[1.5rem] rounded-tr-none' 
                      : 'bg-white text-[#1A1A1A] border border-gray-100 rounded-[1.5rem] rounded-tl-none'
                    }
                  `}>
                    {m.image && (
                      <div className="mb-4 rounded-xl overflow-hidden border border-gray-100/10">
                        <img src={`data:${m.image.mimeType};base64,${m.image.data}`} className="max-w-full" alt="Anexo" />
                      </div>
                    )}
                    <div className="text-[13px] font-medium leading-relaxed whitespace-pre-wrap">{m.content}</div>
                  </div>
                </div>
              ))}
              {isLoading && (
                <div className="flex justify-start">
                  <div className="max-w-[70%] p-6 bg-white border border-gray-100 rounded-[1.5rem] rounded-tl-none shadow-sm animate-pulse">
                    <div className="text-[13px] font-medium text-gray-400">
                      {streamingText || "Computando indicadores técnicos..."}
                    </div>
                  </div>
                </div>
              )}
            </div>

            {/* Input Bar */}
            <div className="p-8">
              <div className="max-w-4xl mx-auto bg-white rounded-[2rem] shadow-xl shadow-black/5 p-2 flex flex-col gap-2">
                {imageAttachment && (
                  <div className="p-3 bg-gray-50 rounded-2xl flex items-center justify-between border border-gray-100 mx-2 mt-1">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-lg overflow-hidden border border-gray-200">
                        <img src={`data:${imageAttachment.mimeType};base64,${imageAttachment.data}`} className="w-full h-full object-cover" alt="preview" />
                      </div>
                      <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Gráfico anexado</span>
                    </div>
                    <button onClick={() => setImageAttachment(null)} className="p-2 text-rose-500 hover:bg-rose-50 rounded-xl transition-colors">
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                  </div>
                )}
                <div className="flex items-end gap-2 px-2 pb-2">
                  <button onClick={() => fileInputRef.current?.click()} className="p-3 text-gray-400 hover:text-[#1A1A1A] transition-colors rounded-2xl hover:bg-gray-50">
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                  </button>
                  <input type="file" ref={fileInputRef} hidden accept="image/*" onChange={handleImageSelect} />
                  <textarea
                    value={input} onChange={(e) => setInput(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                    placeholder="Analise este gráfico ou pergunte sobre ativos..."
                    className="flex-1 bg-transparent py-4 px-2 text-[13px] font-medium outline-none resize-none h-[56px] min-h-[56px] max-h-32"
                  />
                  <button 
                    onClick={handleSend} 
                    disabled={isLoading || (!input.trim() && !imageAttachment)} 
                    className={`p-4 rounded-2xl transition-all ${isLoading || (!input.trim() && !imageAttachment) ? 'bg-gray-100 text-gray-300' : 'bg-[#1A1A1A] text-white shadow-lg shadow-black/10'}`}
                  >
                     <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
                  </button>
                </div>
              </div>
            </div>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center p-12 text-center">
             <div className="w-24 h-24 bg-white rounded-[2rem] shadow-sm flex items-center justify-center text-4xl mb-8 border border-gray-50">📈</div>
             <h3 className="text-xl font-bold text-[#1A1A1A] mb-2 tracking-tight">Estratégias Avançadas</h3>
             <p className="text-sm font-medium text-gray-400 max-w-xs leading-relaxed">Selecione um histórico ou inicie uma nova consulta de mercado.</p>
          </div>
        )}
      </div>
    </div>
  );
};

