                w-full flex items-center gap-4 px-5 py-3.5 rounded-2xl transition-all duration-200 group
                ${currentView === item.id 
                  ? 'bg-[#1A1A1A] dark:bg-white text-white dark:text-[#1A1A1A] shadow-lg shadow-black/10 scale-[1.02]' 
                  : 'text-gray-500 dark:text-gray-400 hover:bg-gray-50 dark:hover:bg-white/5 hover:text-[#1A1A1A] dark:hover:text-white'
                }
              `}
            >
              <span className={`transition-transform duration-200 ${currentView === item.id ? 'scale-110' : 'group-hover:scale-110'}`}>
                {item.icon}
              </span>
              <span className="text-[11px] font-bold uppercase tracking-wider">{item.label}</span>
            </button>
          ))}
        </nav>

        {/* Footer / User Profile */}
        <div className="p-4 mt-auto">
          <div className="bg-gray-50 dark:bg-white/5 rounded-[2rem] p-4 border border-transparent dark:border-white/5">
            {/* Theme Toggle */}
            <div className="flex items-center justify-between mb-4 bg-white dark:bg-[#1A1A1A] p-1.5 rounded-2xl shadow-sm border border-gray-100 dark:border-white/5">
              <button 
                onClick={() => theme !== 'light' && onToggleTheme()}
                className={`flex-1 flex items-center justify-center gap-2 py-2 rounded-xl transition-all ${theme === 'light' ? 'bg-[#1A1A1A] text-white shadow-md' : 'text-gray-400 hover:text-gray-600'}`}
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364-6.364l-.707.707M6.364 17.364l-.707.707M17.364 17.364l-.707-.707M6.364 6.364l-.707-.707M12 8a4 4 0 100 8 4 4 0 000-8z" /></svg>
                <span className="text-[9px] font-bold uppercase tracking-widest">Solar</span>
              </button>
              <button 
                onClick={() => theme !== 'dark' && onToggleTheme()}
                className={`flex-1 flex items-center justify-center gap-2 py-2 rounded-xl transition-all ${theme === 'dark' ? 'bg-white text-[#1A1A1A] shadow-md' : 'text-gray-400 hover:text-gray-600'}`}
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" /></svg>
                <span className="text-[9px] font-bold uppercase tracking-widest">Lunar</span>
              </button>
            </div>

            <div className="flex items-center gap-3">
              <img src={user.avatar} className="w-10 h-10 rounded-xl bg-white p-1 border border-gray-100 dark:border-white/5" alt="Avatar" />
              <div className="flex-1 min-w-0">
                <p className="text-[10px] font-black text-[#1A1A1A] dark:text-white uppercase truncate">{user.name}</p>
                <p className="text-[8px] font-bold text-gray-400 truncate">{user.email}</p>
              </div>
              <button 
                onClick={onLogout}
                className="p-2 text-gray-300 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-500/10 rounded-lg transition-all"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" /></svg>
              </button>
            </div>
          </div>
        </div>
      </aside>
    </>
  );
};

export default Sidebar;

import React, { useState, useRef, useEffect } from 'react';
import { GeminiService } from '../services/geminiService.ts';
import { Message } from '../types.ts';

const FloatingAssistant: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<Message[]>([
    {
      id: 'welcome',
      role: 'model',
      content: 'Olá! Sou seu assistente rápido de auditoria. Qual sua dúvida financeira agora?',
      timestamp: new Date()
    }
  ]);
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;
    const userMsg: Message = { id: Date.now().toString(), role: 'user', content: input, timestamp: new Date() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);
    try {
      const response = await GeminiService.generateChatResponseStream(input, [...messages, userMsg], (chunk) => {});
      const modelMsg: Message = { id: (Date.now() + 1).toString(), role: 'model', content: response, timestamp: new Date() };
      setMessages(prev => [...prev, modelMsg]);
    } catch (e) { console.error(e); } finally { setIsLoading(false); }
  };

  return (
    <div className="fixed top-6 right-6 z-[100] flex flex-col items-end">
      <button
        onClick={() => setIsOpen(!isOpen)}
        className={`
          w-14 h-14 rounded-[1.5rem] bg-[#1A1A1A] text-white flex items-center justify-center shadow-xl shadow-black/10 transition-all duration-300 active:scale-90
          ${isOpen ? 'rotate-180 scale-90' : 'hover:scale-110 hover:translate-y-1'}
        `}
      >
        {isOpen ? (
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>
        ) : (
          <div className="flex flex-col items-center">
            <span className="text-xl font-black">F</span>
          </div>
        )}
      </button>

      {isOpen && (
        <div className="mt-4 w-[350px] md:w-[400px] h-[550px] bg-white rounded-[2.5rem] flex flex-col overflow-hidden shadow-2xl shadow-black/10 border border-gray-100 animate-in slide-in-from-top-6 fade-in duration-500">
          <header className="p-8 pb-4 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="w-8 h-8 bg-[#1A1A1A] text-white rounded-xl flex items-center justify-center font-bold text-sm">F</div>
              <div>
                <h3 className="text-xs font-bold text-[#1A1A1A]">Smart Support</h3>
                <div className="flex items-center gap-1.5">
                  <span className="w-1 h-1 bg-emerald-500 rounded-full animate-pulse"></span>
                  <span className="text-[9px] font-bold text-gray-400 uppercase tracking-widest">Sempre Online</span>
                </div>
              </div>
            </div>
            <button onClick={() => setIsOpen(false)} className="p-2 text-gray-300 hover:text-gray-600 transition-colors">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 9l-7 7-7-7" /></svg>
            </button>
          </header>

          <div ref={scrollRef} className="flex-1 overflow-y-auto p-8 space-y-6 custom-scrollbar bg-gray-50/20">
            {messages.map((msg) => (
              <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`
                  max-w-[85%] p-4 text-[12px] font-medium leading-relaxed shadow-sm
                  ${msg.role === 'user' 
                    ? 'bg-[#1A1A1A] text-white rounded-2xl rounded-tr-none' 
                    : 'bg-white text-gray-700 border border-gray-50 rounded-2xl rounded-tl-none'
                  }
                `}>
                  {msg.content}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <div className="w-10 h-1 border-2 border-gray-100 border-t-gray-300 rounded-full animate-spin"></div>
              </div>
            )}
          </div>

          <div className="p-8 pt-4">
            <div className="relative">
              <input
                type="text"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder="Como posso ajudar hoje?"
                className="w-full bg-gray-50 px-6 py-4 rounded-2xl text-[12px] font-medium outline-none border border-transparent focus:border-gray-200 transition-all pr-14"
              />
              <button 
                onClick={handleSend}
                disabled={isLoading || !input.trim()}
                className="absolute right-2 top-2 bottom-2 w-10 bg-[#1A1A1A] text-white rounded-xl flex items-center justify-center disabled:opacity-20 transition-all hover:scale-105 active:scale-95"
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 12h14M12 5l7 7-7 7" /></svg>
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default FloatingAssistant;

import React, { useState, useRef, useEffect } from 'react';
import { Message, ChatSession } from '../types.ts';
import { GeminiService } from '../services/geminiService.ts';
import { StorageService } from '../services/storage.ts';

const ChatListItem: React.FC<{
  session: ChatSession;
  isActive: boolean;
  onClick: () => void;
  onTogglePin: (e: React.MouseEvent, id: string) => void;
  onDelete: (e: React.MouseEvent, id: string) => void;
}> = ({ session, isActive, onClick, onTogglePin, onDelete }) => (
  <div 
    onClick={onClick}
    className={`
      group relative flex items-center gap-3 p-4 cursor-pointer transition-all rounded-2xl mb-1
      ${isActive 
        ? 'bg-white shadow-lg shadow-black/5 text-[#1A1A1A]' 
        : 'hover:bg-gray-100/50 text-gray-500 hover:text-[#1A1A1A]'
      }
    `}
  >
    <div className={`w-1.5 h-1.5 rounded-full ${isActive ? 'bg-[#1A1A1A]' : 'bg-gray-200'}`} />
    <div className="flex-1 min-w-0">
      <h4 className={`text-xs font-bold truncate ${isActive ? 'text-[#1A1A1A]' : 'text-gray-600'}`}>
        {session.title || 'Nova Auditoria'}
      </h4>
      <p className="text-[9px] font-medium opacity-50">{new Date(session.lastUpdate).toLocaleDateString()}</p>
    </div>
    <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
      <button onClick={(e) => onTogglePin(e, session.id)} className={`p-1.5 rounded-lg hover:bg-white transition-colors ${session.isPinned ? 'text-amber-400' : 'text-gray-300'}`}>
        ★
      </button>
      <button onClick={(e) => onDelete(e, session.id)} className="p-1.5 rounded-lg hover:bg-rose-50 text-gray-300 hover:text-rose-500 transition-colors">
        <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
      </button>
    </div>
  </div>
);

const ChatInterface: React.FC = () => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [streamingText, setStreamingText] = useState('');
  const [imageAttachment, setImageAttachment] = useState<{data: string, mimeType: string} | null>(null);
  const [showListOnMobile, setShowListOnMobile] = useState(true);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const loaded = StorageService.getChatSessions();
    setSessions(loaded);
    if (loaded.length > 0 && !currentSessionId) {
      setCurrentSessionId(loaded[0].id);
      if (window.innerWidth >= 1024) setShowListOnMobile(false);
    }
  }, []);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [sessions, streamingText]);

  const createNewSession = () => {
    const newSession: ChatSession = {
      id: Date.now().toString(),
      title: 'Nova Auditoria',
      messages: [{ id: 'init', role: 'model', content: 'Auditor IA iniciado. Envie documentos ou perguntas sobre normas contábeis.', timestamp: new Date() }],
      lastUpdate: new Date(),
      updatedAt: new Date().toISOString(),
      version: 1
    };
    StorageService.saveChatSession(newSession);
    setSessions([newSession, ...sessions]);
    setCurrentSessionId(newSession.id);
    setShowListOnMobile(false);
  };

  const handleSelectSession = (id: string) => {
    setCurrentSessionId(id);
    setShowListOnMobile(false);
  };

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (re) => {
        const base64 = (re.target?.result as string).split(',')[1];
        setImageAttachment({ data: base64, mimeType: file.type });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSend = async () => {
    if ((!input.trim() && !imageAttachment) || !currentSessionId || isLoading) return;

    const currentSession = sessions.find(s => s.id === currentSessionId);
    if (!currentSession) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      image: imageAttachment || undefined,
      timestamp: new Date()
    };

    // Update UI immediately with user message
    const updatedSession = { ...currentSession, messages: [...currentSession.messages, userMsg], lastUpdate: new Date() };
    setSessions(prev => prev.map(s => s.id === currentSessionId ? updatedSession : s));

    const textToSend = input;
    const imgToSend = imageAttachment;
    setInput('');
    setImageAttachment(null);
    setIsLoading(true);

    try {
      // FIX: Pass 'currentSession.messages' (history BEFORE this specific message) 
      // because GeminiService appends the new message internally.
      const response = await GeminiService.generateChatResponseStream(
        textToSend,
        currentSession.messages,
        (chunk) => setStreamingText(chunk),
        imgToSend || undefined
      );

      const modelMsg: Message = { id: (Date.now() + 1).toString(), role: 'model', content: response, timestamp: new Date() };
      const finalSession = { ...updatedSession, messages: [...updatedSession.messages, modelMsg] };
      StorageService.saveChatSession(finalSession);
      setSessions(prev => prev.map(s => s.id === currentSessionId ? finalSession : s));

      if (finalSession.messages.length <= 3) {
        const title = await GeminiService.generateTitle(textToSend || "Auditoria Contábil");
        const titledSession = { ...finalSession, title };
        StorageService.saveChatSession(titledSession);
        setSessions(prev => prev.map(s => s.id === currentSessionId ? titledSession : s));
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsLoading(false);
      setStreamingText('');
    }
  };

  const currentSession = sessions.find(s => s.id === currentSessionId);

  return (
    <div className="flex h-full bg-[#F2EFEA] overflow-hidden">
      {/* Sidebar List */}
      <div className={`
        ${showListOnMobile ? 'flex' : 'hidden'} lg:flex
        w-full lg:w-80 border-r border-gray-100 flex-col bg-white shrink-0
      `}>
        <div className="p-6 border-b border-gray-50">
          <button onClick={createNewSession} className="modern-button w-full shadow-lg shadow-black/10">+ Nova Auditoria</button>
        </div>
        <div className="flex-1 overflow-y-auto p-4 custom-scrollbar bg-gray-50/30">
          <h3 className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em] mb-4 px-2">Histórico de Sessões</h3>
          {sessions.length === 0 ? (
            <div className="p-10 text-center opacity-30 text-[10px] font-bold uppercase tracking-widest">Sem auditorias</div>
          ) : (
            sessions.map(s => (
              <ChatListItem 
                key={s.id} session={s} isActive={s.id === currentSessionId} 
                onClick={() => handleSelectSession(s.id)} 
                onTogglePin={(e, id) => { e.stopPropagation(); StorageService.togglePin(id); setSessions(StorageService.getChatSessions()); }} 
                onDelete={(e, id) => { e.stopPropagation(); if(confirm('Excluir?')){ StorageService.deleteChatSession(id); setSessions(StorageService.getChatSessions()); } }} 
              />
            ))
          )}
        </div>
      </div>

      {/* Chat Area */}
      <div className={`
        ${!showListOnMobile ? 'flex' : 'hidden'} lg:flex
        flex-1 flex-col bg-[#F2EFEA] overflow-hidden relative
      `}>
        {currentSession ? (
          <>
            <header className="p-6 bg-white border-b border-gray-100 flex items-center justify-between">
              <div className="flex items-center gap-4">
                <button onClick={() => setShowListOnMobile(true)} className="lg:hidden p-2 text-gray-400">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" /></svg>
                </button>
                <div>
                  <h2 className="text-sm font-bold text-[#1A1A1A] tracking-tight">{currentSession.title}</h2>
                  <p className="text-[10px] font-medium text-emerald-600 uppercase tracking-widest flex items-center gap-1.5 mt-0.5">
                    <span className="w-1 h-1 bg-emerald-600 rounded-full"></span> Auditoria Ativa (RAG)
                  </p>
                </div>
              </div>
            </header>

            <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-8 custom-scrollbar">
              {currentSession.messages.map(m => (
                <div key={m.id} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`
                    max-w-[85%] lg:max-w-[70%] p-5 shadow-sm
                    ${m.role === 'user' 
                      ? 'bg-[#1A1A1A] text-white rounded-[1.5rem] rounded-tr-none' 
                      : 'bg-white text-[#1A1A1A] border border-gray-100 rounded-[1.5rem] rounded-tl-none'
                    }
                  `}>
                    {m.image && (
                      <div className="mb-4 rounded-xl overflow-hidden border border-gray-100/10">
                        <img src={`data:${m.image.mimeType};base64,${m.image.data}`} className="max-w-full" alt="Anexo" />
                      </div>
                    )}
                    <div className="text-[13px] font-medium leading-relaxed whitespace-pre-wrap">{m.content}</div>
                  </div>
                </div>
              ))}
              {isLoading && (
                <div className="flex justify-start">
                  <div className="max-w-[70%] p-6 bg-white border border-gray-100 rounded-[1.5rem] rounded-tl-none shadow-sm animate-pulse">
                    <div className="text-[13px] font-medium text-gray-400">
                      {streamingText || "Consultando base RAG..."}
                    </div>
                  </div>
                </div>
              )}
            </div>

            <div className="p-8">
              <div className="max-w-4xl mx-auto bg-white rounded-[2rem] shadow-xl shadow-black/5 p-2 flex flex-col gap-2">
                {imageAttachment && (
                  <div className="p-3 bg-gray-50 rounded-2xl flex items-center justify-between border border-gray-100 mx-2 mt-1">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-lg overflow-hidden border border-gray-200">
                        <img src={`data:${imageAttachment.mimeType};base64,${imageAttachment.data}`} className="w-full h-full object-cover" alt="preview" />
                      </div>
                      <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Imagem anexada</span>
                    </div>
                    <button onClick={() => setImageAttachment(null)} className="p-2 text-rose-500 hover:bg-rose-50 rounded-xl transition-colors">
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                  </div>
                )}
                <div className="flex items-end gap-2 px-2 pb-2">
                  <button onClick={() => fileInputRef.current?.click()} className="p-3 text-gray-400 hover:text-[#1A1A1A] transition-colors rounded-2xl hover:bg-gray-50">
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                  </button>
                  <input type="file" ref={fileInputRef} hidden accept="image/*" onChange={handleImageSelect} />
                  <textarea
                    value={input} onChange={(e) => setInput(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                    placeholder="Digite sua dúvida ou anexe um documento..."
                    className="flex-1 bg-transparent py-4 px-2 text-[13px] font-medium outline-none resize-none h-[56px] min-h-[56px] max-h-32"
                  />
                  <button 
                    onClick={handleSend} 
                    disabled={isLoading || (!input.trim() && !imageAttachment)} 
                    className={`p-4 rounded-2xl transition-all ${isLoading || (!input.trim() && !imageAttachment) ? 'bg-gray-100 text-gray-300' : 'bg-[#1A1A1A] text-white shadow-lg shadow-black/10'}`}
                  >
                     <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
                  </button>
                </div>
              </div>
            </div>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center p-12 text-center">
             <div className="w-24 h-24 bg-white rounded-[2rem] shadow-sm flex items-center justify-center text-4xl mb-8 border border-gray-50">📑</div>
             <h3 className="text-xl font-bold text-[#1A1A1A] mb-2 tracking-tight">Auditoria & RAG</h3>
             <p className="text-sm font-medium text-gray-400 max-w-xs leading-relaxed">Selecione uma sessão ou inicie uma nova auditoria de documentos.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default ChatInterface;

