                        <div className="absolute -top-3 -left-3 w-6 h-6 bg-blue-100 rounded-lg flex items-center justify-center border border-blue-200">
                          <svg className="w-3 h-3 text-blue-700" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" /></svg>
                        </div>
                      )}
                      {m.image && (
                        <div className="mb-4 rounded-xl overflow-hidden border border-gray-100/10">
                          <img src={`data:${m.image.mimeType};base64,${m.image.data}`} className="max-w-full h-auto object-cover" alt="Anexo" />
                        </div>
                      )}
                      <div className="text-[13px] leading-7 font-medium whitespace-pre-wrap">{m.content}</div>
                    </div>
                    <span className="text-[9px] font-bold text-gray-300 uppercase tracking-widest px-1">
                      {m.role === 'user' ? 'Você' : 'Analista CFA'} • {m.timestamp.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                    </span>
                  </div>
                </div>
              ))}
              {isLoading && (
                <div className="flex justify-start w-full">
                  <div className="max-w-[70%] p-6 bg-white border border-gray-100 rounded-2xl rounded-tl-sm shadow-sm">
                    <div className="flex items-center gap-3 mb-2">
                       <div className="w-4 h-4 border-2 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
                       <span className="text-[10px] font-bold text-blue-600 uppercase tracking-widest">Analisando Mercado</span>
                    </div>
                    <div className="text-[13px] font-medium text-gray-400 animate-pulse">
                      {streamingText || "Computando indicadores técnicos..."}
                    </div>
                  </div>
                </div>
              )}
            </div>

            <div className="p-4 lg:p-6 bg-gradient-to-t from-white via-white to-transparent">
              <div className="max-w-4xl mx-auto bg-white rounded-[2rem] shadow-2xl shadow-blue-900/5 p-2 flex flex-col gap-2 border border-gray-100">
                {imageAttachment && (
                  <div className="p-3 bg-gray-50 rounded-2xl flex items-center justify-between border border-gray-100 mx-2 mt-1">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-lg overflow-hidden border border-gray-200">
                        <img src={`data:${imageAttachment.mimeType};base64,${imageAttachment.data}`} className="w-full h-full object-cover" alt="Preview" />
                      </div>
                      <span className="text-[10px] font-bold uppercase text-gray-500">Imagem Anexada</span>
                    </div>
                    <button onClick={() => setImageAttachment(null)} className="p-2 hover:bg-gray-200 rounded-lg text-gray-400">
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                  </div>
                )}

                <div className="flex items-end gap-2 px-2 pb-2">
                  <button 
                    onClick={() => fileInputRef.current?.click()}
                    className="p-3 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all"
                  >
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                  </button>
                  <input ref={fileInputRef} type="file" accept="image/*" onChange={handleImageSelect} className="hidden" />

                  <textarea
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                    placeholder="Envie gráficos de ações ou pergunte sobre tendências..."
                    className="flex-1 bg-transparent py-4 px-2 text-[13px] font-medium text-[#1A1A1A] placeholder-gray-400 outline-none resize-none h-[56px] min-h-[56px] max-h-32 custom-scrollbar"
                  />

                  <button 
                    onClick={handleSend}
                    disabled={isLoading || (!input.trim() && !imageAttachment)}
                    className={`
                      p-4 rounded-2xl transition-all duration-300
                      ${isLoading || (!input.trim() && !imageAttachment)
                        ? 'bg-gray-100 text-gray-300' 
                        : 'bg-[#007AFF] text-white shadow-lg shadow-blue-500/30 hover:scale-105 active:scale-95'
                      }
                    `}
                  >
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
                  </button>
                </div>
              </div>
              <p className="text-center text-[9px] font-bold text-gray-300 uppercase mt-4 tracking-widest">
                Dados em tempo real via Google Search e Análise Técnica IA.
              </p>
            </div>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center p-12 text-center opacity-40">
            <div className="w-24 h-24 bg-blue-600 text-white rounded-[2rem] flex items-center justify-center text-4xl mb-6 shadow-2xl shadow-blue-500/20">
              $
            </div>
            <h3 className="text-xl font-bold text-[#1A1A1A] mb-2">Terminal CFA</h3>
            <p className="text-sm font-medium text-gray-400 max-w-xs leading-relaxed">Selecione uma análise no histórico ou inicie um novo estudo de mercado.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default FinancialAI;

import React, { useState, useEffect } from 'react';
import { ViewState, User } from './types.ts';
import { StorageService } from './services/storage.ts';
import Sidebar from './components/Sidebar.tsx';
import Dashboard from './components/Dashboard.tsx';
import ChatInterface from './components/ChatInterface.tsx';
import FinancialAI from './components/FinancialAI.tsx';
import DocumentManager from './components/DocumentManager.tsx';
import AccountingView from './components/AccountingView.tsx';
import Reports from './components/Reports.tsx';
import TrashBin from './components/TrashBin.tsx';
import FloatingAssistant from './components/FloatingAssistant.tsx';
import StudentArea from './components/StudentArea.tsx';

const App: React.FC = () => {
  const [view, setView] = useState<ViewState>(ViewState.Dashboard);
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [theme, setTheme] = useState<'light' | 'dark'>(StorageService.getTheme());

  useEffect(() => {
    const savedUser = StorageService.getUser();
    if (savedUser) {
      setUser(savedUser);
      StorageService.syncWithCloud();
    }
    setLoading(false);
  }, []);

  useEffect(() => {
    if (theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
    StorageService.setTheme(theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'light' ? 'dark' : 'light');
  };

  const handleLogin = () => {
    const mockUser: User = {
      id: 'usr_' + Math.random().toString(36).substr(2, 9),
      name: 'Auditor Sênior',
      email: 'contato@finaigpt.ai',
      avatar: `https://api.dicebear.com/7.x/bottts-neutral/svg?seed=${Math.random()}`
    };
    StorageService.setUser(mockUser);
    setUser(mockUser);
    StorageService.syncWithCloud();
  };

  const handleLogout = () => {
    if (window.confirm("Deseja realmente encerrar a sessão?")) {
      StorageService.clearAll();
      setUser(null);
      setView(ViewState.Dashboard);
    }
  };

  if (loading) {
    return (
      <div className="h-full w-full flex items-center justify-center bg-[#F2EFEA] dark:bg-[#121212] transition-colors duration-300">
        <div className="flex flex-col items-center gap-4">
          <div className="w-10 h-10 border-2 border-gray-200 dark:border-gray-800 border-t-[#1A1A1A] dark:border-t-white rounded-full animate-spin"></div>
          <p className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em]">Sincronizando Terminal...</p>
        </div>
      </div>
    );
  }

  if (!user) {
    return (
      <div className="h-full w-full flex items-center justify-center bg-[#F2EFEA] dark:bg-[#121212] p-6 transition-colors duration-300">
        <div className="max-w-md w-full bg-white dark:bg-[#1A1A1A] rounded-[2rem] p-12 text-center shadow-2xl shadow-black/5 dark:shadow-black/20 animate-in zoom-in duration-500 border border-transparent dark:border-white/5">
          <div className="w-16 h-16 bg-[#1A1A1A] dark:bg-white text-white dark:text-[#1A1A1A] flex items-center justify-center text-2xl font-black rounded-2xl mx-auto mb-8 shadow-xl shadow-blue-500/20">
            F
          </div>
          <h1 className="text-2xl font-bold tracking-tight mb-2 text-[#1A1A1A] dark:text-white">FinAIGPT Terminal</h1>
          <p className="text-xs font-medium text-gray-500 dark:text-gray-400 mb-10 leading-relaxed">
            Inteligência Artificial Especializada em <br/> Contabilidade & Análise CFA.
          </p>
          <button 
            onClick={handleLogin}
            className="modern-button w-full dark:bg-white dark:text-[#1A1A1A]"
          >
            Acessar Sistema
          </button>
          <div className="mt-12 flex items-center justify-center gap-2 opacity-30">
            <span className="w-1.5 h-1.5 bg-gray-400 rounded-full"></span>
            <p className="text-[8px] font-bold text-gray-600 dark:text-gray-400 uppercase tracking-[0.3em]">Build 2.5.0-STABLE</p>
            <span className="w-1.5 h-1.5 bg-gray-400 rounded-full"></span>
          </div>
        </div>
      </div>
    );
  }

  // Determine if we are in a chat view to conditionally hide the global menu button
  const isChatView = [ViewState.Chat, ViewState.FinancialAI, ViewState.StudentArea].includes(view);

  const renderView = () => {
    const commonProps = {
      onOpenMenu: () => setIsMobileMenuOpen(true)
    };

    switch (view) {
      case ViewState.Dashboard: return <Dashboard />;
      case ViewState.Chat: return <ChatInterface {...commonProps} />;
      case ViewState.FinancialAI: return <FinancialAI {...commonProps} />;
      case ViewState.StudentArea: return <StudentArea {...commonProps} />;
      case ViewState.Documents: return <DocumentManager />;
      case ViewState.Accounting: return <AccountingView />;
      case ViewState.Reports: return <Reports />;
      case ViewState.Trash: return <TrashBin />;
      default: return <Dashboard />;
    }
  };

  return (
    <div className="flex h-full w-full bg-[#F2EFEA] dark:bg-[#121212] overflow-hidden transition-colors duration-300">
      {/* Mobile Menu Trigger - Only show on non-chat views. Chat views handle their own menu button. */}
      {!isChatView && (
        <button 
          onClick={() => setIsMobileMenuOpen(true)}
          className="lg:hidden fixed top-6 left-6 z-[60] p-3.5 bg-white dark:bg-[#1A1A1A] rounded-2xl shadow-lg border border-gray-100 dark:border-white/5 active:scale-90 transition-all"
        >
          <svg className="w-5 h-5 text-[#1A1A1A] dark:text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 6h16M4 12h16M4 18h16" />
          </svg>
        </button>
      )}

      <Sidebar 
        currentView={view} 
        setView={setView} 
        user={user} 
        onLogout={handleLogout} 
        isOpen={isMobileMenuOpen}
        onClose={() => setIsMobileMenuOpen(false)}
        theme={theme}
        onToggleTheme={toggleTheme}
      />

      <main className="flex-1 h-full overflow-hidden relative">
        <div className="h-full pt-safe pb-safe lg:pt-0 lg:pb-0">
          {renderView()}
        </div>
        {!isChatView && <FloatingAssistant />}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { Message, ChatSession } from '../types.ts';
import { GeminiService } from '../services/geminiService.ts';
import { StorageService } from '../services/storage.ts';

interface ChatInterfaceProps {
  onOpenMenu?: () => void;
}

const ChatListItem: React.FC<{
  session: ChatSession;
  isActive: boolean;
  onClick: () => void;
  onTogglePin: (e: React.MouseEvent, id: string) => void;
  onDelete: (e: React.MouseEvent, id: string) => void;
}> = ({ session, isActive, onClick, onTogglePin, onDelete }) => (
  <div 
    onClick={onClick}
    className={`
      group relative flex items-start gap-3 p-4 cursor-pointer transition-all duration-200 border-l-[3px]
      ${isActive 
        ? 'border-[#1A1A1A] bg-white text-[#1A1A1A] shadow-sm' 
        : 'border-transparent hover:bg-white/60 text-gray-500 hover:text-[#1A1A1A]'
      }
    `}
  >
    <div className="flex-1 min-w-0 py-1">
      <div className="flex justify-between items-start mb-1">
        <h4 className={`text-xs font-bold truncate pr-4 ${isActive ? 'text-[#1A1A1A]' : 'text-gray-600'}`}>
          {session.title || 'Nova Auditoria'}
        </h4>
        {session.isPinned && <span className="text-[10px] text-amber-500">★</span>}
      </div>
      <p className="text-[9px] font-semibold uppercase tracking-wider opacity-60">
        {new Date(session.lastUpdate).toLocaleDateString(undefined, { month: 'short', day: 'numeric' })}
      </p>
    </div>
    <button 
      onClick={(e) => onDelete(e, session.id)} 
      className="absolute right-2 top-1/2 -translate-y-1/2 p-2 rounded-lg text-gray-300 hover:text-rose-500 hover:bg-rose-50 opacity-0 group-hover:opacity-100 transition-all"
    >
      <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
    </button>
  </div>
);

const ChatInterface: React.FC<ChatInterfaceProps> = ({ onOpenMenu }) => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [streamingText, setStreamingText] = useState('');
  const [imageAttachment, setImageAttachment] = useState<{data: string, mimeType: string} | null>(null);
  const [showListOnMobile, setShowListOnMobile] = useState(true);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const loaded = StorageService.getChatSessions();
    setSessions(loaded);
    if (loaded.length > 0 && !currentSessionId) {
      setCurrentSessionId(loaded[0].id);
      if (window.innerWidth >= 1024) setShowListOnMobile(false);
    }
  }, []);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [sessions, streamingText]);

  const createNewSession = () => {
    const newSession: ChatSession = {
      id: Date.now().toString(),
      title: 'Nova Auditoria',
      messages: [{ id: 'init', role: 'model', content: 'Auditor IA iniciado. Envie documentos ou perguntas sobre normas contábeis.', timestamp: new Date() }],
      lastUpdate: new Date(),
      updatedAt: new Date().toISOString(),
      version: 1
    };
    StorageService.saveChatSession(newSession);
    setSessions([newSession, ...sessions]);
    setCurrentSessionId(newSession.id);
    setShowListOnMobile(false);
  };

  const handleSelectSession = (id: string) => {
    setCurrentSessionId(id);
    setShowListOnMobile(false);
  };

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (re) => {
        const base64 = (re.target?.result as string).split(',')[1];
        setImageAttachment({ data: base64, mimeType: file.type });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSend = async () => {
    if ((!input.trim() && !imageAttachment) || !currentSessionId || isLoading) return;

    const currentSession = sessions.find(s => s.id === currentSessionId);
    if (!currentSession) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      image: imageAttachment || undefined,
      timestamp: new Date()
    };

    // Optimistic UI update
    const updatedSession = { ...currentSession, messages: [...currentSession.messages, userMsg], lastUpdate: new Date() };
    setSessions(prev => prev.map(s => s.id === currentSessionId ? updatedSession : s));

    const textToSend = input;
    const imgToSend = imageAttachment;
    setInput('');
    setImageAttachment(null);
    setIsLoading(true);

    try {
      const response = await GeminiService.generateChatResponseStream(
        textToSend,
        currentSession.messages,
        (chunk) => setStreamingText(chunk),
        imgToSend || undefined
      );

      const modelMsg: Message = { id: (Date.now() + 1).toString(), role: 'model', content: response, timestamp: new Date() };
      const finalSession = { ...updatedSession, messages: [...updatedSession.messages, modelMsg] };
      StorageService.saveChatSession(finalSession);
      setSessions(prev => prev.map(s => s.id === currentSessionId ? finalSession : s));

      if (finalSession.messages.length <= 3) {
        const title = await GeminiService.generateTitle(textToSend || "Auditoria Contábil");
        const titledSession = { ...finalSession, title };
        StorageService.saveChatSession(titledSession);
        setSessions(prev => prev.map(s => s.id === currentSessionId ? titledSession : s));
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsLoading(false);
      setStreamingText('');
    }
  };

  const currentSession = sessions.find(s => s.id === currentSessionId);

  return (
    <div className="flex h-full bg-[#F9F9F9] overflow-hidden">
      {/* Sidebar List */}
      <div className={`
        ${showListOnMobile ? 'flex' : 'hidden'} lg:flex
        w-full lg:w-80 border-r border-gray-200/60 flex-col bg-[#F5F5F7] shrink-0
      `}>
        <div className="p-6">
          {/* Mobile Menu Header for List View */}
          <div className="flex items-center justify-between mb-4 lg:hidden">
            <button 
              onClick={onOpenMenu}
              className="p-2 -ml-2 text-gray-400 hover:text-gray-900 transition-colors"
            >
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 6h16M4 12h16M4 18h16" />
              </svg>
            </button>
            <span className="text-xs font-bold text-gray-500 uppercase tracking-widest">IA Auditora</span>
            <div className="w-8"></div> {/* Spacer for balance */}
          </div>

          <button 
            onClick={createNewSession} 
            className="w-full py-3 px-4 bg-[#1A1A1A] text-white rounded-xl text-xs font-bold uppercase tracking-widest hover:bg-gray-900 transition-all shadow-lg shadow-black/5"
          >
            + Nova Auditoria
          </button>
        </div>
        <div className="flex-1 overflow-y-auto px-3 pb-4 space-y-1 custom-scrollbar">
          <h3 className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em] mb-3 px-3 mt-2">Histórico</h3>
          {sessions.length === 0 ? (
            <div className="p-8 text-center opacity-40 text-[10px] font-bold uppercase tracking-widest">Nenhuma auditoria iniciada</div>
          ) : (
            sessions.map(s => (
              <ChatListItem 
                key={s.id} session={s} isActive={s.id === currentSessionId} 
                onClick={() => handleSelectSession(s.id)} 
                onTogglePin={(e, id) => { e.stopPropagation(); StorageService.togglePin(id); setSessions(StorageService.getChatSessions()); }} 
                onDelete={(e, id) => { e.stopPropagation(); if(confirm('Excluir?')){ StorageService.deleteChatSession(id); setSessions(StorageService.getChatSessions()); } }} 
              />
            ))
          )}
        </div>
      </div>

      {/* Chat Area */}
      <div className={`
        ${!showListOnMobile ? 'flex' : 'hidden'} lg:flex
        flex-1 flex-col bg-white overflow-hidden relative
      `}>
        {currentSession ? (
          <>
            <header className="h-16 px-6 bg-white/80 backdrop-blur-md border-b border-gray-100 flex items-center justify-between sticky top-0 z-10">
              <div className="flex items-center gap-4">
                <button onClick={() => setShowListOnMobile(true)} className="lg:hidden p-2 -ml-2 text-gray-400 hover:text-gray-900">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" /></svg>
                </button>
                <div className="flex flex-col">
                  <h2 className="text-sm font-bold text-[#1A1A1A] tracking-tight">{currentSession.title}</h2>
                  <div className="flex items-center gap-2">
                    <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-pulse"></span>
                    <p className="text-[9px] font-bold text-gray-400 uppercase tracking-widest">Auditoria RAG Conectada</p>
                  </div>
                </div>
              </div>
            </header>

            <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 lg:p-8 space-y-8 custom-scrollbar scroll-smooth">
              {currentSession.messages.map(m => (
                <div key={m.id} className={`flex w-full ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-slide-in-bottom`}>
                  <div className={`flex flex-col gap-1 max-w-[85%] lg:max-w-[70%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                    <div className={`
                      p-5 shadow-sm relative
                      ${m.role === 'user' 
                        ? 'bg-[#1A1A1A] text-white rounded-2xl rounded-tr-sm' 
                        : 'bg-white text-[#1A1A1A] border border-gray-100 rounded-2xl rounded-tl-sm shadow-md shadow-gray-100/50'
                      }
                    `}>
                      {m.role === 'model' && (
                        <div className="absolute -top-3 -left-3 w-6 h-6 bg-emerald-100 rounded-lg flex items-center justify-center border border-emerald-200">
                          <svg className="w-3 h-3 text-emerald-700" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" /></svg>
                        </div>
                      )}
                      {m.image && (
                        <div className="mb-4 rounded-xl overflow-hidden border border-gray-100/10">
                          <img src={`data:${m.image.mimeType};base64,${m.image.data}`} className="max-w-full h-auto object-cover" alt="Anexo" />
                        </div>
                      )}
                      <div className="text-[13px] leading-7 font-medium whitespace-pre-wrap">{m.content}</div>
                    </div>
                    <span className="text-[9px] font-bold text-gray-300 uppercase tracking-widest px-1">
                      {m.role === 'user' ? 'Você' : 'Auditor IA'} • {m.timestamp.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                    </span>
                  </div>
                </div>
              ))}
              {isLoading && (
                <div className="flex justify-start w-full">
