import React, { useState, useRef, useEffect } from 'react';
import { Message, ChatSession } from '../types.ts';
import { GeminiService } from '../services/geminiService.ts';
import { StorageService } from '../services/storage.ts';

interface FinancialAIProps {
  onOpenMenu?: () => void;
}

const ChatListItem: React.FC<{
  session: ChatSession;
  isActive: boolean;
  onClick: () => void;
  onTogglePin: (e: React.MouseEvent, id: string) => void;
  onDelete: (e: React.MouseEvent, id: string) => void;
}> = ({ session, isActive, onClick, onTogglePin, onDelete }) => (
  <div 
    onClick={onClick}
    className={`
      group relative flex items-start gap-3 p-4 cursor-pointer transition-all duration-200 border-l-[3px]
      ${isActive 
        ? 'border-[#007AFF] bg-white text-[#1A1A1A] shadow-sm' 
        : 'border-transparent hover:bg-white/60 text-gray-500 hover:text-[#1A1A1A]'
      }
    `}
  >
    <div className="flex-1 min-w-0 py-1">
      <div className="flex justify-between items-start mb-1">
        <h4 className={`text-xs font-bold truncate pr-4 ${isActive ? 'text-[#1A1A1A]' : 'text-gray-600'}`}>
          {session.title || 'Nova Análise CFA'}
        </h4>
        {session.isPinned && <span className="text-[10px] text-amber-500">★</span>}
      </div>
