    >
      <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
    </button>
  </div>
);

const FinancialAI: React.FC<FinancialAIProps> = ({ onOpenMenu }) => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [streamingText, setStreamingText] = useState('');
  const [imageAttachment, setImageAttachment] = useState<{data: string, mimeType: string} | null>(null);
  const [showListOnMobile, setShowListOnMobile] = useState(true);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const loaded = StorageService.getFinancialSessions();
    setSessions(loaded);
    if (loaded.length > 0 && !currentSessionId) {
      setCurrentSessionId(loaded[0].id);
      if (window.innerWidth >= 1024) setShowListOnMobile(false);
    }
  }, []);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [sessions, streamingText]);

  const createNewSession = () => {
    const newSession: ChatSession = {
      id: Date.now().toString(),
      title: 'Nova Análise CFA',
      messages: [{ id: 'init', role: 'model', content: 'Analista CFA pronto. Envie um gráfico ou pergunte sobre ativos para análise técnica e fundamentalista.', timestamp: new Date() }],
      lastUpdate: new Date(),
      updatedAt: new Date().toISOString(),
      version: 1
    };
    StorageService.saveFinancialSession(newSession);
    setSessions([newSession, ...sessions]);
    setCurrentSessionId(newSession.id);
    setShowListOnMobile(false);
  };

  const handleSelectSession = (id: string) => {
    setCurrentSessionId(id);
    setShowListOnMobile(false);
  };

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (re) => {
        const base64 = (re.target?.result as string).split(',')[1];
        setImageAttachment({ data: base64, mimeType: file.type });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSend = async () => {
    if ((!input.trim() && !imageAttachment) || !currentSessionId || isLoading) return;

    const currentSession = sessions.find(s => s.id === currentSessionId);
    if (!currentSession) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      image: imageAttachment || undefined,
      timestamp: new Date()
    };

    // Optimistic update
    const updatedSession = { ...currentSession, messages: [...currentSession.messages, userMsg], lastUpdate: new Date() };
    setSessions(prev => prev.map(s => s.id === currentSessionId ? updatedSession : s));

    const textToSend = input;
    const imgToSend = imageAttachment;
    setInput('');
    setImageAttachment(null);
    setIsLoading(true);

    try {
      const response = await GeminiService.generateFinancialAnalysisStream(
        textToSend,
        currentSession.messages,
        (chunk) => setStreamingText(chunk),
        imgToSend || undefined
      );

      const modelMsg: Message = { id: (Date.now() + 1).toString(), role: 'model', content: response, timestamp: new Date() };
      const finalSession = { ...updatedSession, messages: [...updatedSession.messages, modelMsg] };
      StorageService.saveFinancialSession(finalSession);
      setSessions(prev => prev.map(s => s.id === currentSessionId ? finalSession : s));

      if (finalSession.messages.length <= 3) {
        const title = await GeminiService.generateTitle(textToSend || "Análise CFA");
        const titledSession = { ...finalSession, title };
        StorageService.saveFinancialSession(titledSession);
        setSessions(prev => prev.map(s => s.id === currentSessionId ? titledSession : s));
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsLoading(false);
      setStreamingText('');
    }
  };

  const currentSession = sessions.find(s => s.id === currentSessionId);

  return (
    <div className="flex h-full bg-[#F9F9F9] overflow-hidden">
      {/* Sidebar List */}
      <div className={`
        ${showListOnMobile ? 'flex' : 'hidden'} lg:flex
        w-full lg:w-80 border-r border-gray-200/60 flex-col bg-[#F5F5F7] shrink-0
      `}>
        <div className="p-6">
          {/* Mobile Menu Header for List View */}
          <div className="flex items-center justify-between mb-4 lg:hidden">
            <button 
              onClick={onOpenMenu}
              className="p-2 -ml-2 text-gray-400 hover:text-gray-900 transition-colors"
            >
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 6h16M4 12h16M4 18h16" />
              </svg>
            </button>
            <span className="text-xs font-bold text-gray-500 uppercase tracking-widest">IA Financeira</span>
            <div className="w-8"></div>
          </div>

          <button 
            onClick={createNewSession} 
            className="w-full py-3 px-4 bg-[#007AFF] text-white rounded-xl text-xs font-bold uppercase tracking-widest hover:bg-blue-600 transition-all shadow-lg shadow-blue-500/20"
          >
            + Nova Análise CFA
          </button>
        </div>
        <div className="flex-1 overflow-y-auto px-3 pb-4 space-y-1 custom-scrollbar">
          <h3 className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em] mb-3 px-3 mt-2">Portfólio & Estratégia</h3>
          {sessions.length === 0 ? (
            <div className="p-8 text-center opacity-40 text-[10px] font-bold uppercase tracking-widest">Nenhuma análise iniciada</div>
          ) : (
            sessions.map(s => (
              <ChatListItem 
                key={s.id} session={s} isActive={s.id === currentSessionId} 
                onClick={() => handleSelectSession(s.id)} 
                onTogglePin={(e, id) => { e.stopPropagation(); StorageService.toggleFinancialPin(id); setSessions(StorageService.getFinancialSessions()); }} 
                onDelete={(e, id) => { e.stopPropagation(); if(confirm('Excluir?')){ StorageService.deleteFinancialSession(id); setSessions(StorageService.getFinancialSessions()); } }} 
              />
            ))
          )}
        </div>
      </div>

      {/* Chat Area */}
      <div className={`
        ${!showListOnMobile ? 'flex' : 'hidden'} lg:flex
        flex-1 flex-col bg-white overflow-hidden relative
      `}>
        {currentSession ? (
          <>
            <header className="h-16 px-6 bg-white/80 backdrop-blur-md border-b border-gray-100 flex items-center justify-between sticky top-0 z-10">
              <div className="flex items-center gap-4">
                <button onClick={() => setShowListOnMobile(true)} className="lg:hidden p-2 -ml-2 text-gray-400 hover:text-gray-900">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" /></svg>
                </button>
                <div className="flex flex-col">
                  <h2 className="text-sm font-bold text-[#1A1A1A] tracking-tight">{currentSession.title}</h2>
                  <div className="flex items-center gap-2">
                    <span className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-pulse"></span>
                    <p className="text-[9px] font-bold text-gray-400 uppercase tracking-widest">CFA Market Analyst</p>
                  </div>
                </div>
              </div>
            </header>

            <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 lg:p-8 space-y-8 custom-scrollbar scroll-smooth">
              {currentSession.messages.map(m => (
                <div key={m.id} className={`flex w-full ${m.role === 'user' ? 'justify-end' : 'justify-start'} animate-slide-in-bottom`}>
                  <div className={`flex flex-col gap-1 max-w-[85%] lg:max-w-[70%] ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                    <div className={`
                      p-5 shadow-sm relative
                      ${m.role === 'user' 
                        ? 'bg-[#1A1A1A] text-white rounded-2xl rounded-tr-sm' 
                        : 'bg-white text-[#1A1A1A] border border-gray-100 rounded-2xl rounded-tl-sm shadow-md shadow-gray-100/50'
                      }
                    `}>
                      {m.role === 'model' && (
                        <div className="absolute -top-3 -left-3 w-6 h-6 bg-blue-100 rounded-lg flex items-center justify-center border border-blue-200">
                          <svg className="w-3 h-3 text-blue-700" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" /></svg>
                        </div>
                      )}
                      {m.image && (
                        <div className="mb-4 rounded-xl overflow-hidden border border-gray-100/10">
                          <img src={`data:${m.image.mimeType};base64,${m.image.data}`} className="max-w-full h-auto object-cover" alt="Anexo" />
                        </div>
                      )}
                      <div className="text-[13px] leading-7 font-medium whitespace-pre-wrap">{m.content}</div>
                    </div>
                    <span className="text-[9px] font-bold text-gray-300 uppercase tracking-widest px-1">
                      {m.role === 'user' ? 'Você' : 'Analista CFA'} • {m.timestamp.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                    </span>
                  </div>
                </div>
              ))}
              {isLoading && (
                <div className="flex justify-start w-full">
                  <div className="max-w-[70%] p-6 bg-white border border-gray-100 rounded-2xl rounded-tl-sm shadow-sm">
                    <div className="flex items-center gap-3 mb-2">
                       <div className="w-4 h-4 border-2 border-blue-500 border-t-transparent rounded-full animate-spin"></div>
                       <span className="text-[10px] font-bold text-blue-600 uppercase tracking-widest">Analisando Mercado</span>
                    </div>
                    <div className="text-[13px] font-medium text-gray-400 animate-pulse">
                      {streamingText || "Computando indicadores técnicos..."}
                    </div>
                  </div>
                </div>
              )}
            </div>

            <div className="p-4 lg:p-6 bg-gradient-to-t from-white via-white to-transparent">
              <div className="max-w-4xl mx-auto bg-white rounded-[2rem] shadow-2xl shadow-blue-900/5 p-2 flex flex-col gap-2 border border-gray-100">
                {imageAttachment && (
                  <div className="p-3 bg-gray-50 rounded-2xl flex items-center justify-between border border-gray-100 mx-2 mt-1">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 rounded-lg overflow-hidden border border-gray-200">
                        <img src={`data:${imageAttachment.mimeType};base64,${imageAttachment.data}`} className="w-full h-full object-cover" alt="Preview" />
                      </div>
                      <span className="text-[10px] font-bold uppercase text-gray-500">Imagem Anexada</span>
                    </div>
                    <button onClick={() => setImageAttachment(null)} className="p-2 hover:bg-gray-200 rounded-lg text-gray-400">
                      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                  </div>
                )}

                <div className="flex items-end gap-2 px-2 pb-2">
                  <button 
                    onClick={() => fileInputRef.current?.click()}
                    className="p-3 text-gray-400 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all"
                  >
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" /></svg>
                  </button>
                  <input ref={fileInputRef} type="file" accept="image/*" onChange={handleImageSelect} className="hidden" />

                  <textarea
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                    placeholder="Envie gráficos de ações ou pergunte sobre tendências..."
                    className="flex-1 bg-transparent py-4 px-2 text-[13px] font-medium text-[#1A1A1A] placeholder-gray-400 outline-none resize-none h-[56px] min-h-[56px] max-h-32 custom-scrollbar"
