  const createNewSession = () => {
    const newSession: ChatSession = {
      id: Date.now().toString(),
      title: 'Nova Aula de Finanças',
      messages: [{ id: 'init', role: 'model', content: 'Olá! Sou seu Tutor de Finanças. Qual tema você quer dominar hoje? (Débito/Crédito, IFRS, Valuation...)', timestamp: new Date() }],
      lastUpdate: new Date(),
      updatedAt: new Date().toISOString(),
      version: 1
    };
    StorageService.saveStudentSession(newSession);
    setSessions([newSession, ...sessions]);
    setCurrentSessionId(newSession.id);
    setShowListOnMobile(false);
  };

  const handleSelectSession = (id: string) => {
    setCurrentSessionId(id);
    setShowListOnMobile(false);
  };

  const handleSend = async () => {
    if (!input.trim() || !currentSessionId || isLoading) return;

    const currentSession = sessions.find(s => s.id === currentSessionId);
    if (!currentSession) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      timestamp: new Date()
    };

    const updatedSession = { ...currentSession, messages: [...currentSession.messages, userMsg], lastUpdate: new Date() };
    setSessions(prev => prev.map(s => s.id === currentSessionId ? updatedSession : s));

    const textToSend = input;
    setInput('');
    setIsLoading(true);

    try {
      const response = await GeminiService.generateStudentResponseStream(
        textToSend,
        updatedSession.messages,
        (chunk) => setStreamingText(chunk)
      );

      const modelMsg: Message = { id: (Date.now() + 1).toString(), role: 'model', content: response, timestamp: new Date() };
      const finalSession = { ...updatedSession, messages: [...updatedSession.messages, modelMsg] };
      StorageService.saveStudentSession(finalSession);
      setSessions(prev => prev.map(s => s.id === currentSessionId ? finalSession : s));

      if (finalSession.messages.length <= 3) {
        const title = await GeminiService.generateTitle(textToSend || "Aula de Contabilidade");
        const titledSession = { ...finalSession, title };
        StorageService.saveStudentSession(titledSession);
        setSessions(prev => prev.map(s => s.id === currentSessionId ? titledSession : s));
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsLoading(false);
      setStreamingText('');
    }
  };

  const currentSession = sessions.find(s => s.id === currentSessionId);

  return (
    <div className="flex h-full bg-[#F2EFEA] overflow-hidden">
      {/* Session Sidebar */}
      <div className={`
        ${showListOnMobile ? 'flex' : 'hidden'} lg:flex
        w-full lg:w-80 border-r border-gray-100 flex-col bg-white shrink-0
      `}>
        <div className="p-6">
          {/* Mobile Menu Header for List View */}
          <div className="flex items-center justify-between mb-4 lg:hidden">
            <button 
              onClick={onOpenMenu}
              className="p-2 -ml-2 text-gray-400 hover:text-gray-900 transition-colors"
            >
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M4 6h16M4 12h16M4 18h16" />
              </svg>
            </button>
            <span className="text-xs font-bold text-gray-500 uppercase tracking-widest">Área do Aluno</span>
            <div className="w-8"></div>
          </div>

          <button onClick={createNewSession} className="modern-button w-full shadow-lg shadow-black/10">+ Nova Aula</button>
        </div>
        <div className="flex-1 overflow-y-auto p-4 custom-scrollbar bg-gray-50/30">
          <h3 className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em] mb-4 px-2">Suas Trilhas de Estudo</h3>
          {sessions.length === 0 ? (
            <div className="p-10 text-center opacity-30 text-[10px] font-bold uppercase tracking-widest">Nenhuma aula iniciada</div>
          ) : (
            sessions.map(s => (
              <ChatListItem 
                key={s.id} session={s} isActive={s.id === currentSessionId} 
                onClick={() => handleSelectSession(s.id)} 
                onTogglePin={(e, id) => { e.stopPropagation(); StorageService.toggleStudentPin(id); setSessions(StorageService.getStudentSessions()); }} 
                onDelete={(e, id) => { e.stopPropagation(); if(confirm('Excluir?')){ StorageService.deleteStudentSession(id); setSessions(StorageService.getStudentSessions()); } }} 
              />
            ))
          )}
        </div>
      </div>

      {/* Main Content Area */}
      <div className={`
        ${!showListOnMobile ? 'flex' : 'hidden'} lg:flex
        flex-1 flex-col bg-[#F2EFEA] overflow-hidden relative
      `}>
        {currentSession ? (
          <>
            {/* Header */}
            <header className="p-6 bg-white border-b border-gray-100 flex items-center justify-between">
              <div className="flex items-center gap-4">
                <button onClick={() => setShowListOnMobile(true)} className="lg:hidden p-2 -ml-2 text-gray-400 hover:text-gray-900">
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M15 19l-7-7 7-7" /></svg>
                </button>
                <div>
                  <h2 className="text-sm font-bold text-[#1A1A1A] tracking-tight">{currentSession.title}</h2>
                  <p className="text-[10px] font-medium text-amber-600 uppercase tracking-widest flex items-center gap-1.5 mt-0.5">
                    <span className="w-1 h-1 bg-amber-600 rounded-full"></span> Tutor IA Ativo
                  </p>
                </div>
              </div>
            </header>

            {/* Conversation Flow */}
            <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-8 custom-scrollbar">
              {currentSession.messages.map(m => (
                <div key={m.id} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`
                    max-w-[85%] lg:max-w-[70%] p-5 shadow-sm
                    ${m.role === 'user' 
                      ? 'bg-[#1A1A1A] text-white rounded-[1.5rem] rounded-tr-none' 
                      : 'bg-white text-[#1A1A1A] border border-gray-100 rounded-[1.5rem] rounded-tl-none'
                    }
                  `}>
                    <div className="text-[13px] font-medium leading-relaxed whitespace-pre-wrap">{m.content}</div>
                  </div>
                </div>
              ))}
              {isLoading && (
                <div className="flex justify-start">
                  <div className="max-w-[70%] p-6 bg-white border border-gray-100 rounded-[1.5rem] rounded-tl-none shadow-sm animate-pulse">
                    <div className="text-[13px] font-medium text-gray-400">
                      {streamingText || "Elaborando explicação técnica..."}
                    </div>
                  </div>
                </div>
              )}
            </div>

            {/* Input Bar */}
            <div className="p-8">
              <div className="max-w-4xl mx-auto bg-white rounded-[2rem] shadow-xl shadow-black/5 p-2 flex flex-col gap-2">
                <div className="flex items-end gap-2 px-2 pb-2">
                  <textarea
                    value={input} onChange={(e) => setInput(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                    placeholder="Dúvida técnica ou conceito contábil..."
                    className="flex-1 bg-transparent py-4 px-2 text-[13px] font-medium outline-none resize-none h-[56px] min-h-[56px] max-h-32"
                  />
                  <button 
                    onClick={handleSend} 
                    disabled={isLoading || !input.trim()} 
                    className={`p-4 rounded-2xl transition-all ${isLoading || !input.trim() ? 'bg-gray-100 text-gray-300' : 'bg-[#1A1A1A] text-white shadow-lg shadow-black/10'}`}
                  >
                     <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" /></svg>
                  </button>
                </div>
              </div>
            </div>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center p-12 text-center">
             <div className="w-24 h-24 bg-white rounded-[2rem] shadow-sm flex items-center justify-center text-4xl mb-8 border border-gray-50">🎓</div>
             <h3 className="text-xl font-bold text-[#1A1A1A] mb-2 tracking-tight">Sala de Aula Virtual</h3>
             <p className="text-sm font-medium text-gray-400 max-w-xs leading-relaxed">Selecione uma aula no histórico ou inicie um novo tema agora.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default StudentArea;

import React, { useState, useRef, useEffect } from 'react';
import { Message, ChatSession } from '../types.ts';
import { GeminiService } from '../services/geminiService.ts';
import { StorageService } from '../services/storage.ts';

interface ChatInterfaceProps {
  onOpenMenu?: () => void;
}

const ChatListItem: React.FC<{
  session: ChatSession;
  isActive: boolean;
  onClick: () => void;
  onTogglePin: (e: React.MouseEvent, id: string) => void;
  onDelete: (e: React.MouseEvent, id: string) => void;
}> = ({ session, isActive, onClick, onTogglePin, onDelete }) => (
  <div 
    onClick={onClick}
    className={`
      group relative flex items-center gap-3 p-3 cursor-pointer transition-all duration-200 rounded-lg mx-2
      ${isActive 
        ? 'bg-[#212121] text-white' 
        : 'text-gray-400 hover:bg-[#212121] hover:text-white'
      }
    `}
  >
    <div className="flex-1 min-w-0">
      <div className="flex justify-between items-center">
        <h4 className="text-sm font-medium truncate text-gray-200">
          {session.title || 'Nova Auditoria'}
        </h4>
      </div>
      <p className="text-[11px] text-gray-500 mt-0.5 truncate">
        {session.messages[session.messages.length - 1]?.content.substring(0, 30) || 'Sem mensagens'}
      </p>
    </div>
    {session.isPinned && <span className="text-[10px] text-gray-500">★</span>}
