            sessions.map(s => (
              <ChatListItem 
                key={s.id} session={s} isActive={s.id === currentSessionId} 
                onClick={() => handleSelectSession(s.id)} 
                onTogglePin={(e, id) => { e.stopPropagation(); StorageService.togglePin(id); setSessions(StorageService.getChatSessions()); }} 
                onDelete={(e, id) => { e.stopPropagation(); if(confirm('Excluir?')){ StorageService.deleteChatSession(id); setSessions(StorageService.getChatSessions()); } }} 
              />
