                   <div className="flex flex-col items-center justify-center h-[50vh] px-4 text-center">
                      <div className="w-12 h-12 bg-white rounded-full flex items-center justify-center mb-6">
                        <svg className="w-6 h-6 text-black" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" /></svg>
                      </div>
                      <h2 className="text-white text-2xl font-semibold mb-2">Como posso ajudar na auditoria?</h2>
                   </div>
                 )}
                 {currentSession.messages.map(m => (
                    <div key={m.id} className={`flex w-full ${m.role === 'user' ? 'justify-end' : 'justify-start'} mb-6`}>
                       <div className={`max-w-[85%] lg:max-w-[75%] flex gap-4 ${m.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>
                          {/* Avatar */}
                          <div className="w-8 h-8 rounded-full flex items-center justify-center shrink-0 border border-white/10 overflow-hidden">
                             {m.role === 'user' 
                               ? <div className="w-full h-full bg-[#555]"></div> 
