                               {m.image && (
                                  <img src={`data:${m.image.mimeType};base64,${m.image.data}`} className="max-w-[300px] rounded-xl mb-3 border border-gray-700" alt="attachment" />
                               )}
                               <div className="whitespace-pre-wrap">{m.content}</div>
                            </div>
                          </div>
                       </div>
                    </div>
                 ))}
                 {isLoading && (
                    <div className="flex w-full justify-start mb-6">
