                  <div className="bg-[#2F2F2F] rounded-[26px] p-2 pl-3 flex items-end gap-2 shadow-lg ring-1 ring-white/5">
                     <button 
                        onClick={() => fileInputRef.current?.click()}
                        className="w-8 h-8 rounded-full bg-transparent hover:bg-[#3F3F3F] text-gray-400 hover:text-white flex items-center justify-center shrink-0 mb-0.5 transition-colors"
                     >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 6v6m0 0v6m0-6h6m-6 0H6" /></svg>
                     </button>
                     <input ref={fileInputRef} type="file" accept="image/*" onChange={handleImageSelect} className="hidden" />

                     <textarea
                        ref={textareaRef}
                        value={input}
                        onChange={(e) => setInput(e.target.value)}
                        onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), handleSend())}
                        placeholder="Pergunte ao Chat..."
                        rows={1}
                        className="flex-1 bg-transparent text-white text-[15px] placeholder-gray-500 outline-none resize-none py-3 max-h-[150px] custom-scrollbar"
                     />

                     <button 
                        onClick={handleSend}
                        disabled={!input.trim() && !imageAttachment}
                        className={`
                           w-8 h-8 rounded-full flex items-center justify-center shrink-0 mb-0.5 transition-all
                           ${(input.trim() || imageAttachment) 
                              ? 'bg-white text-black hover:bg-gray-200' 
                              : 'bg-[#676767] text-[#2F2F2F]'
                           }
                        `}
                     >
                        {input.trim() || imageAttachment ? (
                           <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 10l7-7m0 0l7 7m-7-7v18" /></svg>
                        ) : (
                           <svg className="w-4 h-4 text-white" fill="currentColor" viewBox="0 0 24 24"><path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3z"/><path d="M17 11c0 2.76-2.24 5-5 5s-5-2.24-5-5H5c0 3.53 2.61 6.43 6 6.92V21h2v-3.08c3.39-.49 6-3.39 6-6.92h-2z"/></svg>
                        )}
                     </button>
                  </div>
                  <p className="text-center text-[10px] text-gray-500 mt-3 font-medium">O FinAIGPT pode cometer erros. Verifique informações importantes.</p>
               </div>
            </div>
          </>
        ) : (
          <div className="flex-1 flex flex-col items-center justify-center p-12 text-center opacity-60">
            <div className="w-16 h-16 bg-[#212121] text-white rounded-[20px] flex items-center justify-center text-2xl mb-6 shadow-2xl">A</div>
            <h3 className="text-xl font-bold text-white mb-2">Auditor Virtual</h3>
            <p className="text-sm text-gray-400 max-w-xs leading-relaxed">Selecione uma auditoria no histórico ou inicie uma nova consulta.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default ChatInterface;

import React, { useState, useRef, useEffect } from 'react';
import { Message, ChatSession } from '../types.ts';
import { GeminiService } from '../services/geminiService.ts';
import { StorageService } from '../services/storage.ts';

interface ChatInterfaceProps {
  onOpenMenu?: () => void;
}

const ChatListItem: React.FC<{
  session: ChatSession;
  isActive: boolean;
  onClick: () => void;
  onTogglePin: (e: React.MouseEvent, id: string) => void;
  onDelete: (e: React.MouseEvent, id: string) => void;
}> = ({ session, isActive, onClick, onTogglePin, onDelete }) => (
  <div 
    onClick={onClick}
    className={`
      group relative flex items-center gap-3 p-3 cursor-pointer transition-all duration-200 rounded-lg mx-2
      ${isActive 
        ? 'bg-[#212121] text-white' 
        : 'text-gray-400 hover:bg-[#212121] hover:text-white'
      }
    `}
  >
    <div className="flex-1 min-w-0">
      <div className="flex justify-between items-center">
        <h4 className="text-sm font-medium truncate text-gray-200">
          {session.title || 'Nova Auditoria'}
        </h4>
      </div>
      <p className="text-[11px] text-gray-500 mt-0.5 truncate">
        {session.messages[session.messages.length - 1]?.content.replace(/[*#]/g, '').substring(0, 30) || 'Sem mensagens'}
      </p>
    </div>
    {session.isPinned && <span className="text-[10px] text-gray-500">★</span>}
    <button 
      onClick={(e) => onDelete(e, session.id)} 
      className="absolute right-2 top-1/2 -translate-y-1/2 p-1.5 rounded-md text-gray-500 hover:text-red-400 hover:bg-white/5 opacity-0 group-hover:opacity-100 transition-all"
    >
      <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg>
    </button>
  </div>
);

const ChatInterface: React.FC<ChatInterfaceProps> = ({ onOpenMenu }) => {
  const [sessions, setSessions] = useState<ChatSession[]>([]);
  const [currentSessionId, setCurrentSessionId] = useState<string | null>(null);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [streamingText, setStreamingText] = useState('');
  const [imageAttachment, setImageAttachment] = useState<{data: string, mimeType: string} | null>(null);
  const [showListOnMobile, setShowListOnMobile] = useState(true);

  const scrollRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    const loaded = StorageService.getChatSessions();
    setSessions(loaded);
    if (loaded.length > 0 && !currentSessionId) {
      setCurrentSessionId(loaded[0].id);
      if (window.innerWidth >= 1024) setShowListOnMobile(false);
    }
  }, []);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [sessions, streamingText]);

  useEffect(() => {
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto';
      textareaRef.current.style.height = Math.min(textareaRef.current.scrollHeight, 150) + 'px';
    }
  }, [input]);

  const cleanText = (text: string) => text.replace(/[*#]/g, '');

  const createNewSession = () => {
    const newSession: ChatSession = {
      id: Date.now().toString(),
      title: 'Nova Auditoria',
      messages: [],
      lastUpdate: new Date(),
      updatedAt: new Date().toISOString(),
      version: 1
    };
    StorageService.saveChatSession(newSession);
    setSessions([newSession, ...sessions]);
    setCurrentSessionId(newSession.id);
    setShowListOnMobile(false);
  };

  const handleSelectSession = (id: string) => {
    setCurrentSessionId(id);
    setShowListOnMobile(false);
  };

  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (re) => {
        const base64 = (re.target?.result as string).split(',')[1];
        setImageAttachment({ data: base64, mimeType: file.type });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSend = async () => {
    if ((!input.trim() && !imageAttachment) || !currentSessionId || isLoading) return;

    const currentSession = sessions.find(s => s.id === currentSessionId);
    if (!currentSession) return;

    const userMsg: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: input,
      image: imageAttachment || undefined,
      timestamp: new Date()
    };

    const updatedSession = { ...currentSession, messages: [...currentSession.messages, userMsg], lastUpdate: new Date() };
    setSessions(prev => prev.map(s => s.id === currentSessionId ? updatedSession : s));

    const textToSend = input;
    const imgToSend = imageAttachment;
    setInput('');
    setImageAttachment(null);
    setIsLoading(true);
    if(textareaRef.current) textareaRef.current.style.height = 'auto';

    try {
      const response = await GeminiService.generateChatResponseStream(
        textToSend,
        currentSession.messages,
        (chunk) => setStreamingText(cleanText(chunk)),
        imgToSend || undefined
      );

      const modelMsg: Message = { id: (Date.now() + 1).toString(), role: 'model', content: cleanText(response), timestamp: new Date() };
      const finalSession = { ...updatedSession, messages: [...updatedSession.messages, modelMsg] };
      StorageService.saveChatSession(finalSession);
      setSessions(prev => prev.map(s => s.id === currentSessionId ? finalSession : s));

      if (finalSession.messages.length <= 1) { 
        const title = await GeminiService.generateTitle(textToSend || "Auditoria");
        const titledSession = { ...finalSession, title };
        StorageService.saveChatSession(titledSession);
        setSessions(prev => prev.map(s => s.id === currentSessionId ? titledSession : s));
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsLoading(false);
      setStreamingText('');
    }
  };

  const currentSession = sessions.find(s => s.id === currentSessionId);

  return (
    <div className="flex h-full bg-black text-white overflow-hidden font-sans">
      {/* Sidebar (Dark Mode) */}
      <div className={`
        ${showListOnMobile ? 'flex' : 'hidden'} lg:flex
        w-full lg:w-[260px] border-r border-[#333] flex-col bg-black shrink-0
      `}>
        <div className="p-3">
          <div className="flex items-center justify-between mb-2 lg:hidden px-2 pt-2">
             <button onClick={onOpenMenu} className="text-gray-400 hover:text-white">
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg>
             </button>
             <span className="font-bold">Auditor IA</span>
             <div className="w-6"></div>
          </div>
          <button 
            onClick={createNewSession} 
            className="w-full py-2.5 px-3 hover:bg-[#212121] rounded-lg text-sm font-medium transition-all flex items-center justify-between group text-gray-200"
          >
            <div className="flex items-center gap-2">
              <div className="bg-white text-black p-1 rounded-full">
                <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 4v16m8-8H4"/></svg>
              </div>
              <span>Nova Auditoria</span>
            </div>
            <svg className="w-4 h-4 text-gray-500 group-hover:text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" /></svg>
          </button>
        </div>
        <div className="flex-1 overflow-y-auto px-2 pb-4 space-y-1 custom-scrollbar">
          <h3 className="text-[11px] font-bold text-gray-500 px-4 py-2 mt-2 uppercase tracking-wider">Histórico</h3>
          {sessions.length === 0 ? (
            <div className="p-4 text-center text-xs text-gray-600">Nenhum chat recente</div>
          ) : (
            sessions.map(s => (
              <ChatListItem 
                key={s.id} session={s} isActive={s.id === currentSessionId} 
                onClick={() => handleSelectSession(s.id)} 
                onTogglePin={(e, id) => { e.stopPropagation(); StorageService.togglePin(id); setSessions(StorageService.getChatSessions()); }} 
                onDelete={(e, id) => { e.stopPropagation(); if(confirm('Excluir?')){ StorageService.deleteChatSession(id); setSessions(StorageService.getChatSessions()); } }} 
              />
            ))
          )}
        </div>
      </div>

      {/* Main Chat Area */}
      <div className={`
        ${!showListOnMobile ? 'flex' : 'hidden'} lg:flex
        flex-1 flex-col bg-black relative w-full
      `}>
        {currentSession ? (
