                                <div className="w-2 h-2 bg-gray-500 rounded-full animate-bounce" style={{animationDelay: '0.2s'}}></div>
                                <div className="w-2 h-2 bg-gray-500 rounded-full animate-bounce" style={{animationDelay: '0.4s'}}></div>
                             </div>
                             {streamingText && <div className="mt-2 text-gray-100 font-serif text-[17px] leading-8 whitespace-pre-wrap">{cleanText(streamingText)}</div>}
                          </div>
                       </div>
                    </div>
                 )}
              </div>
            </div>

            {/* Input Bar */}
            <div className="absolute bottom-0 left-0 w-full bg-gradient-to-t from-black via-black to-transparent pt-10 pb-6 px-4">
               <div className="max-w-3xl mx-auto w-full relative">
