                        <img src={`data:${imageAttachment.mimeType};base64,${imageAttachment.data}`} className="w-10 h-10 object-cover rounded-lg" alt="preview" />
                        <button onClick={() => setImageAttachment(null)} className="text-gray-400 hover:text-white">✕</button>
